(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,88507,(e,t,s)=>{t.exports=JSON.parse('{"meta":{"source":"SYSCOHADA Révisé 2017 — Fonctionnement des comptes","generatedAt":"2026-06-06T17:24:31.853Z","nbComptes":115,"classes":{"1":"Comptes de ressources durables","2":"Comptes d\'actif immobilisé","3":"Comptes de stocks","4":"Comptes de tiers","5":"Comptes de trésorerie","6":"Comptes de charges des activités ordinaires","7":"Comptes de produits des activités ordinaires","8":"Comptes des autres charges et produits (HAO)","9":"Comptes des engagements hors bilan et comptabilité analytique"},"groupes":{"A":{"label":"Comptes de bilan","classes":[1,2,3,4,5]},"B":{"label":"Comptes de gestion","classes":[6,7,8]},"C":{"label":"Comptes spéciaux (CAGE)","classes":[9]}}},"comptes":[{"numero":"10","intitule":"Capital","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"Le compte 10 – CAPITAL enregistre les apports faits à l\'entité par ceux qui la financent en propre, par opposition aux dettes envers des tiers. C\'est la première rubrique des capitaux propres.\\n\\nLa notion est commune à des structures juridiques différentes. Pour une société, il s\'agit du capital social (compte 101), dont la comptabilité suit les phases successives de souscription, d\'appel et de libération. Pour un établissement public ou une entité dotée par l\'État, il s\'agit du capital par dotation (compte 102). Pour une entreprise individuelle, il s\'agit du capital personnel de l\'exploitant (compte 103), dont les mouvements de l\'exercice transitent par le compte de l\'exploitant (compte 104).","subdivisions":[{"numero":"101","intitule":"Capital social"},{"numero":"102","intitule":"Capital par dotation"},{"numero":"103","intitule":"Capital personnel"},{"numero":"104","intitule":"Compte de l\'exploitant"},{"numero":"105","intitule":"Primes liées aux capitaux propres"},{"numero":"106","intitule":"Ecarts de réévaluation"},{"numero":"109","intitule":"Apporteurs, capital souscrit, non appelé"}],"fonctionnement":"Le compte 10 – CAPITAL est crédité du montant des apports\\n- par le débit des comptes d\'immobilisations, pour les apports en nature ;\\n- par le débit du compte 46 – Apporteurs, Associés et Groupe, puis des comptes de trésorerie lors de la libération, pour les apports en numéraire ;\\n- par le débit du compte 106 – Écarts de réévaluation, en cas d\'incorporation directe au capital.\\n\\nLe compte 10 – CAPITAL est débité des réductions de capital\\n- par le crédit des comptes de tiers ou de trésorerie concernés, en cas de remboursement aux associés ;\\n- par le crédit du compte 12 – Report à nouveau, en cas d\'apurement de pertes antérieures.\\n\\nLe solde est créditeur et figure au passif du bilan, en tête des capitaux propres.","commentaires":"Le capital n\'est pas un compte de trésorerie : il n\'indique pas ce que l\'entité possède, mais l\'origine d\'une partie de son financement. Une société peut avoir un capital de dix millions et une caisse vide.\\n\\nAttention à la distinction entre capital SOUSCRIT et capital LIBÉRÉ. Tant que les associés n\'ont pas versé, la fraction non appelée reste inscrite au compte 109 – Apporteurs, capital souscrit non appelé, qui vient en déduction au bilan.\\n\\nPour une entreprise individuelle, le capital personnel (103) et le compte de l\'exploitant (104) fonctionnent ensemble : les prélèvements et apports de l\'année passent par le 104, qui est viré au 103 à la clôture.","exclusions":"Le compte 10 – CAPITAL ne doit pas servir à enregistrer :\\n- les bénéfices conservés dans l\'entité, qui relèvent du compte 11 – Réserves ou du compte 12 – Report à nouveau ;\\n- les subventions reçues pour financer un investissement, qui relèvent du compte 14 – Subventions d\'investissement ;\\n- les sommes mises à disposition par les associés à titre de prêt, qui sont des dettes et relèvent du compte 46.","controle":"Le compte 10 – CAPITAL peut être contrôlé à partir des statuts et de leurs modifications, des procès-verbaux d\'assemblée décidant une augmentation ou une réduction, des bulletins de souscription, et de l\'inscription au registre du commerce. Son solde ne bouge qu\'en vertu d\'une décision formelle : tout mouvement sans pièce juridique correspondante doit être justifié.","motsCles":["capital","apports","capitaux propres","associés","société"]},{"numero":"101","intitule":"Capital social","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"Le Capital social traduit le montant des valeurs apportées par les associés.\\nDans les sociétés, le capital initial correspond à la valeur des apports (nature ou\\nespèces) effectués par les associés à la création de l\'entité tels qu\'ils figurent dans\\n- les statuts.\\nIl est divisé en actions ou parts d\'une même valeur nominale.\\nAu cours de la vie sociale, le capital peut, sur décision des organes compétents, être\\naugmenté ou diminué pour diverses raisons, notamment : apports et/ou retraits de\\ncapital, affectation de résultats et incorporation de réserves.\\nPour certaines sociétés, la loi prévoit la limitation de la responsabilité des associés à\\n- l\'égard des créanciers sociaux en fixant le montant minimum du capital social.","subdivisions":[{"numero":"1011","intitule":"Capital souscrit, non appelé"},{"numero":"1012","intitule":"Capital souscrit, appelé, non versé"},{"numero":"1013","intitule":"Capital souscrit, appelé, versé, non amorti"},{"numero":"1014","intitule":"Capital souscrit, appelé, versé, amorti"},{"numero":"1018","intitule":"Capital souscrit, soumis à des conditions particulières"}],"fonctionnement":"Le compte 101 – CAPITAL SOCIAL est crédité du montant : – des apports initiaux ; –\\ndes augmentations de capital en espèces, en nature ou en réserves (déduction faite\\ndes primes liées au capital social)\\n- par le débit du compte 46 – Apporteurs Associés et Groupe, pour les apports\\nen espèces ou en nature, pour les sociétés de personnes et GIE ;\\n- ou par le débit du compte 109 Apporteurs capital souscrit, non appelé, pour les\\nsociétés de capitaux ;\\n- ou par le débit du compte 11 – Réserves, pour l\'incorporation de ce poste au\\ncapital ;\\n- ou par le débit du compte 12 – Report à nouveau, pour l\'incorporation de ce\\nposte au capital\\n- ou par le débit du compte 13 – Résultat net de l\'exercice, pour l\'incorporation de\\nce poste au capital.\\nLe compte 101 – CAPITAL SOCIAL est débité des réductions de capital décidées par\\n- les Assemblées générales d\'associés\\n- par le crédit du compte 12 – Report à nouveau, pour l\'absorption des pertes\\nantérieures reportées ;\\n- ou par le crédit du compte 109 Apporteurs, capital souscrit non appelé dans le\\ncas de renonciation d\'une partie du capital non libéré\\n- ou par le crédit du compte 46 – Apporteurs, Associés et Groupe, dans le cas du\\nremboursement d\'une partie du capital.","commentaires":"- le capital social représente la valeur nominale des actions ou parts sociales.\\n- le compte 1011 – Capital souscrit, non appelé enregistre à son crédit les\\npromesses d\'apport en espèces ou en nature, faites par les associés, par le débit\\ndu compte 109 – Apporteurs capital souscrit, non appelé.\\nau moment de l\'appel d\'une nouvelle fraction du capital le compte 1011 est\\ndébité par le crédit du compte 1012 à concurrence du montant appelé.\\nCorrélativement, le compte 467 – Apporteurs, restant dû sur capital appelé est\\ndébité du même montant par le crédit du compte 109 – Apporteurs, capital\\nsouscrit, non appelé.\\n- le compte 1012 – Capital souscrit, appelé, non versé enregistre à son crédit la\\nfraction de capital en instance d\'être effectivement libérée par les apporteurs.\\nEn cas de libération effective par les apporteurs de la fraction de capital appelé, le\\ncompte 1012 – Capital souscrit, appelé, non versé est viré au compte 1013 –\\nCapital souscrit appelé, versé, non amorti.\\nlesorganes compétents peuvent décider de rembourser aux associés tout ou\\npartie du montant nominal de leurs actions à titre d\'avances sur le produit de la\\nliquidation future de la société. Le capital demeure inchangé, les actions\\namorties devenant des actions de jouissance. La contre-valeur des actions de\\njouissance est isolée dans le compte 1014 – Capital souscrit, appelé, versé,\\namorti. Les actions dont le capital est partiellement ou totalement amorti\\ndonnent les mêmes droits que les actions non amorties à l\'exception du premier\\ndividende (Intérêt statutaire).\\nL\'attribution gratuite d\'actions au personnel salarié de la société et aux\\ndirigeants est traitée au titre VII opérations spécifiques chapitre 18.\\n- le compte 1018 – Capital souscrit, soumis à des conditions particulières\\nenregistre à son crédit le montant du capital provenant d\'opérations\\nparticulières telles que :\\n- l\'incorporation de plus-values nettes à long terme (P.V.N.L.T.), lorsque les\\ndispositions législatives et réglementaires le prévoient ;\\n- l\'émission de certificats d\'investissement, d\'actions de préférence et d\'actions à\\ndividendes prioritaires, sans droit de vote.","exclusions":"Le compte 101 – CAPITAL SOCIAL ne doit pas servir à enregistrer :\\n- les versements et/ou retraits temporaires de fonds effectués par les associés\\n- les apports effectués par l\'exploitant individuel\\n- les apports non remboursables effectués par la puissance publique\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n46 – Apporteurs, Associés et Groupe\\n- 103 – Capital personnel\\n- 102 – Capital par dotation","controle":"Le compte 101 – CAPITAL SOCIAL peut être contrôlé à partir de recoupements issus\\n:\\ndes statuts de la société ;\\nde la déclaration notariée de souscription et de versement ;\\ndes virements bancaires et relevés de banque ;\\ndu procès-verbal de l\'Assemblée des associés.","motsCles":["capital","social"]},{"numero":"102","intitule":"Capital par dotation","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"Le Capital par dotation représente la contrepartie de l\'intégration au patrimoine\\ndes entités publiques, des immobilisations et fonds affectés, sur décision de\\n- l\'Autorité publique, au fonctionnement de ces entités.\\nCette dotation peut aussi se réaliser par transformation de dettes.","subdivisions":[{"numero":"1021","intitule":"Dotation initiale"},{"numero":"1022","intitule":"Dotations complémentaires"},{"numero":"1028","intitule":"Autres dotations"}],"fonctionnement":"Le compte 102 – CAPITAL PAR DOTATION est crédité des dotations en numéraire et\\nen nature accordées par une collectivité publique\\n- par le débit du compte 4493 – Etat, fonds de dotation à recevoir ;\\n- ou par le débit du compte 45 – Organismes internationaux ;\\n- ou par le débit du compte 47 – Débiteurs et créditeurs divers ;\\nou encore par le débit des comptes d\'actifs concernés, immobilisations, stocks,\\ncréances.\\nLe compte 102 – CAPITAL PAR DOTATION est débité, en cas de reprise contractuelle\\nde dettes\\n- par le crédit des comptes de passif concernés.","commentaires":"- le compte 102 – Capital par dotation ne saurait être utilisé que dans les entités\\npubliques. Il reçoit en effet les fonds de dotation des collectivités publiques. Il\\nenregistre la contre-valeur des biens affectés de manière irrévocable à ces\\nentités.\\nil n\'en demeure pas moins vrai que certaines subventions d\'investissement,\\naccordées par les collectivités auxquelles les entités sont rattachées, peuvent\\nêtre considérées comme étant des fonds de dotation. Ce sera notamment le cas\\nd\'espèce d\'organismes subventionneurs et d\'entité subventionnée émanant de la\\nmême personne morale publique. Dans ce cas, il faut se référer à la décision\\nd\'octroi pour leur qualification.","exclusions":"Le compte 102 – CAPITAL PAR DOTATION ne doit pas servir à enregistrer :\\n- les sommes reçues à titre de prêts ou d\'avances remboursables par les entités\\npubliques\\n- les sommes reçues à titre de prêts ou d\'avances remboursables assorties de\\nconditions particulières\\n- les sommes reçues à titre de subventions d\'investissement dans la mesure où\\nelles ne sont pas transformées en capital par dotation\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n- 163 – Avances reçues de l\'Etat\\n- 167 – Avances assorties de conditions particulières\\n14 – Subventions d\'investissement","controle":"Le compte 102 – CAPITAL PAR DOTATION peut être contrôlé à partir de\\nrecoupements issus :\\nde décret, arrêté ou lettre officielle d\'octroi ou de déblocage des fonds ;\\nde procès-verbal de remise d\'un bien cédé en guise d\'apport en nature ;\\nde pièces justificatives de virements correspondants","motsCles":["capital","dotation"]},{"numero":"103","intitule":"Capital personnel","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"A la création de l\'entité exploitée sous la forme individuelle, le capital initial\\nreprésente le montant des apports en nature ou en espèces effectués par\\n- l\'entrepreneur à titre définitif et des dettes qu\'il décide d\'inscrire au bilan.\\nCe capital initial est modifié ultérieurement par les apports et les retraits de capital\\nainsi que par l\'affectation des résultats.","subdivisions":[],"fonctionnement":"Le compte 103 – CAPITAL PERSONNEL est crédité des apports effectués par\\n- l\'exploitant à titre définitif, en début ou en cours d\'activité\\n- par le débit des comptes d\'actifs concernés : immobilisations, stocks,\\ntrésorerie ; à la clôture de l\'exercice, de l\'apport net issu du solde du Compte\\nde l\'exploitant\\n- par le débit du compte 104 – Compte de l\'exploitant.\\nLe compte 103 – CAPITAL PERSONNEL est crédité, à l\'ouverture de l\'exercice, du\\nmontant de l\'affectation du résultat de l\'exercice précédent\\n- par le débit du compte 131 – Résultat net : Bénéfice.\\nLe compte 103 – CAPITAL PERSONNEL est débité, à l\'ouverture de l\'exercice, du\\nmontant de l\'affectation du résultat de l\'exercice précédent\\n- par le crédit du compte 139 – Résultat net : Perte.\\nLe compte 103 – CAPITAL PERSONNEL est débité, à la clôture de l\'exercice, du solde\\ndu compte de l\'exploitant (retraits nets)\\n- par le crédit du compte 104 – Compte de l\'exploitant.","commentaires":"Ce compte ne doit pas être confondu avec le compte de l\'exploitant. Lorsque le solde\\nde ce compte est débiteur, il reste au passif, mais précédé du signe moins.","exclusions":"Le compte 103 – CAPITAL PERSONNEL ne doit pas servir à enregistrer :\\n- les prélèvements et versements effectués dans les entités non individuelles\\n- les prélèvements et apports effectués par l\'exploitant à titre temporaire\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n- 462 – Apporteurs, Associés, comptes courants\\n- 104 – Compte de l\'exploitant","controle":"Le compte 103 – CAPITAL PERSONNEL peut être contrôlé à partir de recoupements\\nissus :\\ndu compte de résultat de l\'exercice précédent ;\\ndes virements ;\\ndes fiches de caisse ;\\ndes relevés de banque.","motsCles":["capital","personnel"]},{"numero":"104","intitule":"Compte de l\'exploitant","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"Ce compte sert à établir la situation de l\'entrepreneur en ce qui concerne :\\n- les apports et compléments d\'apports financiers et/ou de biens et services\\neffectués à titre temporaire en cours d\'exercice. Ces apports et compléments\\nd\'apports financiers peuvent consister en des versements dans la caisse ou sur\\nun compte bancaire de l\'entité ou en des règlements de dépenses de l\'entité sur\\nla trésorerie privée de l\'exploitant ;\\n- les retraits effectués au cours de l\'exercice pour son usage personnel ou celui de\\nsa famille et dans le cadre de l\'exploitation. Ceux-ci consistent en des :\\nprélèvements en nature de biens et services, objets de l\'activité, qui\\nconcourent à la détermination du résultat ;\\nprélèvements financiers opérés sur un compte de trésorerie affecté à\\n- l\'activité, qu\'il s\'agisse de prélèvements directs (retraits de fonds) ou indirects\\n(paiement d\'une dépense privée).","subdivisions":[{"numero":"1041","intitule":"Apports temporaires"},{"numero":"1042","intitule":"Opérations courantes"},{"numero":"1043","intitule":"Rémunérations, impôts, et autres charges personnelles"},{"numero":"1047","intitule":"Prélèvements d\'autoconsommation"},{"numero":"1048","intitule":"Autres prélèvements"}],"fonctionnement":"Le compte 104 – COMPTE DE L\'EXPLOITANT est crédité, en cours d\'exercice, des\\napports et compléments d\'apports financiers et/ou de biens et services effectués par\\n- l\'exploitant à titre temporaire\\n- par le débit d\'un compte de trésorerie ou des comptes d\'actifs\\ncorrespondants.\\nLe compte 104 – COMPTE DE L\'EXPLOITANT est crédité, à la clôture de l\'exercice,\\ndu montant débiteur de son solde\\n- par le débit du compte 103 – Capital personnel\\nLe compte 104 – COMPTE DE L\'EXPLOITANT est débité, en cours d\'exercice, des\\nretraits de fonds ou des prélèvements de biens et services effectués par l\'exploitant,\\npour son usage personnel ou celui de sa famille et de l\'exploitation\\n- par le crédit des comptes d\'actifs correspondants.\\nLe compte 104 – COMPTE DE L\'EXPLOITANT est débité, à la clôture de l\'exercice, du\\nmontant de son solde créditeur\\n- par le crédit du compte 103 – Capital personnel.","commentaires":"Le compte 104 – Compte de l\'exploitant est en fait un démembrement du compte\\n- 103 – Capital personnel. A ce titre, il est systématiquement soldé à la clôture de\\n- l\'exercice.","exclusions":"Le compte 104 – COMPTE DE L\'EXPLOITANT ne doit pas servir à enregistrer :\\n- les prélèvements et versements effectués dans des entités non individuelles\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n- 462 – Apporteurs, Associés, comptes courants","controle":"Le compte 104 – COMPTE DE L\'EXPLOITANT peut être contrôlé à partir de\\nrecoupements issus :\\ndes virements ;\\ndes fiches de caisse ;\\ndes relevés de banque.","motsCles":["compte","exploitant"]},{"numero":"105","intitule":"Primes liées aux capitaux propres","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"La prime peut être analysée comme étant un droit d\'entrée demandé au nouvel\\nactionnaire ou associé d\'autant que l\'action ou la part sociale vaut, avant\\naugmentation du capital, beaucoup plus que sa valeur nominale. Elle représente\\nune partie des apports purs et simples non comprise dans le capital social.\\nLes primes liées aux capitaux propres doivent figurer distinctement au passif du\\nbilan dans les rubriques appropriées. Selon la nature des opérations\\nd\'augmentation de capital, en nature ou en espèces, il y a lieu de distinguer quatre\\n(4) catégories de primes, d\'émission, de fusion, d\'apport et de conversion.","subdivisions":[{"numero":"1051","intitule":"Primes d\'émission"},{"numero":"1052","intitule":"Primes d\'apport"},{"numero":"1053","intitule":"Primes de fusion"},{"numero":"1054","intitule":"Primes de conversion"},{"numero":"1058","intitule":"Autres primes"}],"fonctionnement":"Le compte 105 – PRIMES LIEES AUX CAPITAUX PROPRES est crédité lors des\\naugmentations de capital\\n- par le débit des comptes d\'associés, de comptes de tiers ou de comptes de\\ntrésorerie.\\nLe compte 105 – PRIMES LIEES AUX CAPITAUX PROPRES est débité en cas\\nd\'incorporation des primes au capital\\n- par le crédit du compte 101 – Capital social\\nLe compte 105 – PRIMES LIEES AUX CAPITAUX PROPRES est débité en cas\\nd\'absorption de pertes\\n- par le crédit du compte 12 – Report à nouveau ou 139 – Résultat net :\\npertes.\\nLe compte 105 – PRIMES LIEES AUX CAPITAUX PROPRES est débité en cas de\\nremboursement du capital\\n- par le crédit du compte 462 – Apporteurs, Associés, comptes courants.\\nLe compte 105 – PRIMES LIEES AUX CAPITAUX PROPRES est débité, en cas\\nd\'augmentation du capital, du montant des frais de cette augmentation\\n- par le crédit du compte 78 – Transferts de charges, en cas d\'imputation des\\nfrais d\'augmentation du capital.","commentaires":"la prime d\'émission est égale à l\'excédent du prix d\'émission en numéraire (c\'est-\\nà-dire le prix payé par le souscripteur) sur la valeur nominale des actions ou\\nparts sociales.\\nla prime de fusion représente la différence entre la valeur réelle de l\'entité\\nabsorbée et la valeur nominale des actions ou parts sociales rémunérant\\n- l\'apport.\\nla prime d\'apport représente la différence entre la valeur du ou des biens\\napportés et la valeur nominale des actions ou des parts sociales rémunérant\\n- l\'apport.\\nla prime de conversion représente la différence entre la valeur de conversion du\\nou des titres de créances et la valeur nominale des actions ou des parts sociales\\nrémunérant l\'apport.","exclusions":"Le compte 105 – PRIMES LIEES AUX CAPITAUX PROPRES ne doit pas servir à\\nenregistrer certaines sommes qualifiées de primes, exemples : primes de\\nremboursement des obligations, primes d\'assurance, primes de création d\'emplois,\\nprimes de développement\\nIl convient dans les cas d\'espèce d\'utiliser des comptes tels que :\\n- 6714 – Primes de remboursement des obligations\\n- 625 – Primes d\'assurance\\n- 7078 – Autres produits accessoires\\netc.","controle":"Le compte 105 – PRIMES LIEES AUX CAPITAUX PROPRES peut être contrôlé à partir\\nde recoupements issus :\\ndes décisions de l\'Assemblée des associés portant augmentation du capital social\\n;\\ndes textes relatifs au protocole de fusion ;\\ndes textes relatifs au protocole d\'apport ;\\ndes factures de frais ou du calcul analytique des frais d\'augmentation de capital.","motsCles":["primes","liees","capitaux","propres"]},{"numero":"106","intitule":"Ecarts de réévaluation","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"L\'écart de réévaluation représente la contrepartie au passif du bilan des\\naugmentations de valeur d\'éléments actifs soit dans le cadre d\'une réévaluation\\nlégale, soit dans celui d\'une réévaluation libre.\\nLa différence entre les valeurs réévaluées et les valeurs nettes précédemment\\ncomptabilisées constitue l\'écart de réévaluation.\\nL\'écart de réévaluation s\'inscrit distinctement au passif du bilan dans les capitaux\\npropres.","subdivisions":[{"numero":"1061","intitule":"Ecarts de réévaluation légale"},{"numero":"1062","intitule":"Ecarts de réévaluation libre"}],"fonctionnement":"Le compte 106 – ECARTS DE REEVALUATION est crédité du montant de la\\nréévaluation des éléments d\'actif réévalués\\n- par le débit des comptes d\'actifs concernés.\\nLe compte 106 – ECARTS DE REEVALUATION est débité des incorporations directes\\nau capital\\n- par le crédit du compte 10 – Capital.","commentaires":"L\'écart de réévaluation n\'a pas la nature d\'un résultat et ne peut être utilisé à\\ncompenser les pertes de l\'exercice de réévaluation. Il n\'est pas distribuable ; il peut\\nêtre incorporé en tout ou partie au capital.","exclusions":"","controle":"Le compte 106 – ECARTS DE REEVALUATION peut être contrôlé à partir de\\nrecoupements issus :\\ndes décisions des organes de gestion;\\ndes décisions de l\'Assemblée générale des actionnaires portant augmentation de\\ncapital par incorporation de tout ou partie de l\'écart de réévaluation.\\nde la comparaison des actifs de l\'exercice précèdent avec ceux de l\'exercice en\\ncours.","motsCles":["ecarts","reevaluation"]},{"numero":"109","intitule":"Apporteurs, capital souscrit, non appelé","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"Ce compte retrace la créance de la société sur les actionnaires ou les associés, pour\\nla fraction du capital non encore appelé par les organes compétents en cas de\\nlibération partielle. Celle-ci peut être consécutive aux opérations de constitution\\nd\'une société ou d\'augmentation de capital.","subdivisions":[],"fonctionnement":"Le compte 109 – APPORTEURS, CAPITAL SOUSCRIT NON APPELE est débité, lors de\\nla création d\'une société ou lors d\'une augmentation de capital, du montant non\\nappelé immédiatement\\n- par le crédit du compte 101 – Capital social.\\nLe compte 109 – APPORTEURS, CAPITAL SOUSCRIT NON APPELE est crédité lors\\ndes appels successifs du capital\\n- par le débit du compte 467 – Apporteurs, restant dû sur capital appelé.","commentaires":"Le montant inscrit au compte 109 représente en fait la créance globale de la société\\nsur les actionnaires et les associés.\\nElle devra être personnalisée pour chacun d\'eux au moment des appels effectifs de\\nfonds et portée au débit du compte 467 – Apporteurs, restant dû sur capital appelé.\\nLe compte 109 figure en seconde ligne au passif du bilan, en moins parmi les\\ncapitaux propres.","exclusions":"","controle":"Le compte 109 – Apporteurs, capital souscrit, non appelé peut être contrôlé à partir\\nde recoupements issus :\\ndes statuts ;\\ndes décisions des Assemblées générales ordinaires et extraordinaires ;\\ndes décisions du conseil d\'administration ou de la gérance pour les appels de\\nfonds ;\\ndu compte 1011 – Capital souscrit, non appelé, de solde opposé et de montant\\nidentique.","motsCles":["apporteurs","capital","souscrit","non","appele"]},{"numero":"11","intitule":"Réserves","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"Les réserves correspondent à des bénéfices laissés à la disposition de l\'entité et non\\nincorporés au capital.\\nL\'obligation de constituer des réserves résulte des dispositions statutaires ou\\nréglementaires et des décisions des organes compétents.","subdivisions":[{"numero":"111","intitule":"RESERVE LEGALE"},{"numero":"112","intitule":"RESERVES STATUTAIRES OU CONTRACTUELLES"},{"numero":"113","intitule":"RESERVES REGLEMENTEES"},{"numero":"1131","intitule":"Réserves de plus-values nettes à long terme"},{"numero":"1132","intitule":"Réserves d\'attribution gratuite d\'actions au personnel salarié et aux dirigeants"},{"numero":"1133","intitule":"Réserves consécutives à l\'octroi de subventions d\'investissement"},{"numero":"1134","intitule":"Réserves de valeurs mobilières donnant accès au capital"},{"numero":"1138","intitule":"Autres réserves réglementées"},{"numero":"118","intitule":"AUTRES RESERVES"},{"numero":"1181","intitule":"Réserves facultatives"},{"numero":"1188","intitule":"Réserves diverses"}],"fonctionnement":"Le compte 11 – RESERVES est crédité du montant affecté aux réserves\\n- par le débit du compte 131 – Résultat net : Bénéfice ou le débit du compte\\n- 1301 – Résultat en instance d\'affectation : Bénéfice.\\nLe compte 11 – RÉSERVES est débité des incorporations directes au capital\\n- par le crédit du compte 101 – Capital social.\\nLe compte 11 – RÉSERVES est débité des distributions aux associés\\n- par le crédit du compte 465 – Associés, dividendes à payer.\\nLe compte 11 – RÉSERVES est débité des prélèvements pour l\'amortissement des\\npertes\\n- par le crédit des comptes 129 – Report à nouveau débiteur ou 139 –\\nRésultat net : Perte.","commentaires":"Les réserves accroissent les capitaux propres et comprennent les réserves\\nindisponibles : légales, réglementées et statutaires ainsi que les réserves libres ou\\nfacultatives.\\n- le compte 111 – Réserve légale est destiné à constater l\'obligation annuelle\\nd\'alimentation ou de constitution d\'un fonds de réserves, en application de\\ndispositions juridiques régissant certains types de sociétés (SA et SARL,\\nnotamment) : la dotation est égale à 10% au moins prélevée sur le bénéfice de\\n- l\'exercice diminué le cas échéant des pertes antérieures.\\nLa réserve légale, qui peut également être constituée par prélèvement sur toute\\nréserve disponible (notamment primes liées au capital), cesse d\'être obligatoire\\nlorsque son montant atteint 20 % du montant du capital.\\n- le compte 113 – Réserves réglementées comprend des subdivisions telles que :\\n- 1131 – Réserve de plus-values nettes à long terme. Lorsque la législation\\nfiscale le prévoit, ce compte enregistre la plus-value nette à long terme, pour\\nson montant net d\'impôt.\\n- 1132 – Réserves d\'attribution gratuite d\'actions au personnel salarié et aux\\ndirigeants, le paiement ou la libération des actions acquises en vue d\'une\\nattribution gratuite est réalisée par un prélèvement obligatoire, à\\nconcurrence des actions à attribuer, sur la part des bénéfices d\'un ou de\\nplusieurs exercices ainsi que des réserves, à l\'exception de la réserve légale\\n(voir Titre VIII Opérations spécifiques Chapitre 19).\\n- 1133 – Réserves consécutives à l\'octroi de subventions d\'investissement.\\nCe compte est ouvert lorsque la convention de subvention prévoit :\\n- 1134 – Réserves de valeurs mobilières donnant accès au capital, lorsqu\'il\\nexiste des valeurs mobilières donnant accès au capital, la société qui procède\\nà l\'attribution gratuite d\'actions vire à un compte de réserve indisponible la\\nsomme nécessaire pour attribuer lesdites actions aux titulaires des droits\\nattachés aux valeurs mobilières donnant accès au capital qui exerceraient\\nleur droit ultérieurement en nombre égal à celui qu\'ils auraient reçu s\'ils\\navaient été actionnaires au moment de l\'attribution principale.\\nla constitution par l\'entité subventionnée d\'une réserve de montant déterminé\\neu égard à la subvention ;\\n- le maintien d\'une telle réserve au passif du bilan pendant une période\\ndéterminée.","exclusions":"Le compte 11 – RESERVES ne doit pas servir à enregistrer :\\n- les provisions pour pertes et charges\\n- les dépréciations des immobilisations\\n- les dépréciations des comptes de stocks\\n- les dépréciations des comptes clients\\n- les dépréciations des comptes de trésorerie\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n19 – Provisions financières pour risques et charges\\n29 –Dépréciations\\n39 – Dépréciations des stocks\\n49 – Dépréciations et provisions pour risques à court terme (Tiers)\\n59–Dépréciations et provisions pour risques à court terme (Trésorerie)","controle":"Le compte 11 – RESERVES peut être contrôlé à partir de recoupements issus :\\nde dispositions législatives, statutaires ou contractuelles obligatoires concernant\\nla répartition des résultats ;\\ndes décisions de l\'Assemblée générale des actionnaires portant répartition des\\nrésultats.","motsCles":["reserves"]},{"numero":"12","intitule":"Report à nouveau","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"Le report à nouveau correspond au montant soit des bénéfices d\'exercices\\nantérieurs dont l\'affectation a été reportée sur les exercices ultérieurs, soit des\\npertes constatées à la clôture d\'exercices antérieurs qui n\'ont pas été compensées\\npar des prélèvements opérés sur les bénéfices, les réserves ou le capital.\\nLe report à nouveau est inscrit au passif du bilan où il doit figurer sur une ligne\\ndistincte : en moins si son solde est débiteur, et en plus si son solde est créditeur. Il\\nconstitue un élément des capitaux propres.","subdivisions":[{"numero":"121","intitule":"REPORT A NOUVEAU CREDITEUR"},{"numero":"129","intitule":"REPORT A NOUVEAU DEBITEUR"},{"numero":"1291","intitule":"Perte nette à reporter"},{"numero":"1292","intitule":"Perte-Amortissements réputés différés"}],"fonctionnement":"Le compte 12 – REPORT A NOUVEAU est crédité lors de la répartition des bénéfices\\n- par le débit du compte 131 – Résultat net : Bénéfice, pour la partie non\\ndistribuée, ou non affectée à un compte de réserves.\\nLe compte 12 – REPORT A NOUVEAU est débité lors de l\'affectation du résultat\\n- par le crédit du compte 139 – Résultat net : Perte, pour le montant des\\npertes non compensées par des prélèvements opérés sur des réserves ou sur\\n- le capital ;\\n- ou par le crédit du compte 465 – Associés, dividendes à payer, pour le report à\\nnouveau mis en distribution.\\nLorsque la législation fiscale prévoit un traitement des amortissements différés,\\ndifférent de celui des pertes ordinaires, l\'entité substituera les sous-comptes 1291\\net 1292 au compte 129 – Report à nouveau débiteur.","commentaires":"Le report à nouveau est constitué par :\\n- les sommes non affectées et laissées à la disposition de l\'entité;\\n- les pertes non compensées par des réserves ou par une diminution du capital ;\\n- les sommes venant des arrondis des dividendes distribués.\\nLe fonctionnement de ce compte est subordonné à la décision de l\'Assemblée\\ngénérale statuant sur l\'affectation du bénéfice de l\'exercice précédent ou sur le sort\\ndes pertes constatées à la clôture de l\'exercice précédent.","exclusions":"Le compte 12 – REPORT A NOUVEAU ne doit pas servir à enregistrer :\\n- les sommes à porter en réserves par décision de l\'Assemblée générale ordinaire\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n11 – Réserves","controle":"Le compte 12 – REPORT À NOUVEAU peut être contrôlé à partir de recoupements\\nissus des décisions des assemblées sur la répartition des résultats.","motsCles":["report","nouveau"]},{"numero":"13","intitule":"Résultat net de l\'exercice","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"Le résultat net de l\'exercice peut être défini de deux façons : 1. différence entre les\\nproduits (reçus ou à recevoir) et les charges (payées ou à payer) de la période ; 2.\\nvariation des capitaux propres entre le début et la clôture de l\'exercice, hors\\nnouveaux apports et retraits d\'apports et hors réévaluation.\\nQuel que soit son signe, le résultat net de l\'exercice est inscrit au passif du bilan sur\\nla ligne correspondante, parmi les capitaux propres.","subdivisions":[{"numero":"130","intitule":"RESULTAT EN INSTANCE D\'AFFECTATION"},{"numero":"1301","intitule":"Résultat en instance d\'affectation : Bénéfice"},{"numero":"1309","intitule":"Résultat en instance d\'affectation : Perte"},{"numero":"131","intitule":"RESULTAT NET : BENEFICE"},{"numero":"132","intitule":"MARGE COMMERCIALE (M.C.)"},{"numero":"133","intitule":"VALEUR AJOUTEE (V.A.)"},{"numero":"134","intitule":"EXCEDENT BRUT D\'EXPLOITATION (E.B.E.)"},{"numero":"135","intitule":"RESULTAT D\'EXPLOITATION (R.E.)"},{"numero":"136","intitule":"RESULTAT FINANCIER (R.F.)"},{"numero":"137","intitule":"RESULTAT DES ACTIVITES ORDINAIRES (R.A.O.)"},{"numero":"138","intitule":"RESULTAT HORS ACTIVITES ORDINAIRES (R.H.A.O.)"},{"numero":"1381","intitule":"Résultat de fusion,"},{"numero":"1382","intitule":"Résultat d\'apport partiel d\'actif"},{"numero":"1383","intitule":"Résultat de scission"},{"numero":"1384","intitule":"Résultat de liquidation"},{"numero":"139","intitule":"RESULTAT NET : PERTE"}],"fonctionnement":"Le compte 13 – RESULTAT NET DE L\'EXERCICE est crédité, à la clôture de l\'exercice\\n- par le débit des comptes de la classe 7 et des comptes créditeurs de la classe\\n8 pour solde.\\nLe compte 13 – RESULTAT NET DE L\'EXERCICE est crédité, après la clôture de\\n- l\'exercice et décision d\'imputation des pertes, du montant du résultat déficitaire\\n- par le débit des comptes : 12 – Report à nouveau, ou 11 – Réserves, ou 101 –\\nCapital social, ou 103 – Capital personnel.\\nLe compte 13 – RESULTAT NET DE L\'EXERCICE est débité à la clôture de l\'exercice\\ndu montant des charges de l\'exercice\\n- par le crédit des comptes de la classe 6 et des comptes débiteurs de la classe\\n8 pour solde.\\nLe compte 13 – RESULTAT NET DE L\'EXERCICE est débité après la clôture de\\n- l\'exercice et décision d\'affectation des résultats du montant du résultat déficitaire\\n- par le crédit des comptes 12 – Report à nouveau ou 11 – Réserves ou 101 –\\nCapital social ou 103 – Capital personnel ou 465 – Associés, dividendes à\\npayer.","commentaires":"Le compte 13 – Résultat net de l\'exercice permet de calculer, à la clôture de\\n- l\'exercice, le résultat net à affecter, après déduction de l\'impôt sur les bénéfices et\\nautres prélèvements obligatoires.\\nLe solde du compte 13 représente un bénéfice si les produits l\'emportent sur les\\ncharges (solde créditeur) ou une perte si les charges l\'emportent sur les produits\\n(solde débiteur).\\nL\'affectation du résultat d\'un exercice est décidée par les organes compétents au\\ncours de l\'exercice suivant. Le compte 13 est donc soldé lors de la comptabilisation\\nde cette affectation.\\nEn fin d\'exercice, le résultat de l\'exercice précédent non affecté à un compte de\\nréserves et non distribué sera viré au compte de report à nouveau.\\nA la réouverture des comptes de l\'exercice suivant, les entités ont la possibilité\\nd\'utiliser un compte spécial \\"Résultat en instance d\'affectation\\".\\nDans les entités individuelles, le solde du compte 13 – Résultat net de l\'exercice est\\nviré au compte 103 – Capital personnel.","exclusions":"Le compte 13 – RESULTAT NET DE L\'EXERCICE ne doit pas servir à enregistrer :\\n- les charges ou produits qui n\'auraient pas au préalable transité par les comptes\\nde gestion\\nIl convient dans le cas d\'espèce d\'utiliser les comptes ci-après :\\nclasses 6, 7 et 8","controle":"Le compte 13 – RESULTAT NET DE L\'EXERCICE peut être contrôlé à partir de\\nrecoupements issus des soldes des comptes de gestion.","motsCles":["resultat","net","exercice"]},{"numero":"14","intitule":"Subventions d\'investissement","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"Les subventions d\'investissement sont des aides financières non remboursables\\naccordées aux entités (publiques ou privées), pour différentes raisons : acquisition,\\ncréation de valeurs immobilisées (subventions d\'équipement) ou financement\\nd\'activités à long terme, afin de pourvoir au remplacement ou à la remise en état\\ndes immobilisations. Elles peuvent également consister en l\'octroi de biens et\\nservices (voir Titre VII Opérations spécifiques, Chapitre 16).","subdivisions":[{"numero":"141","intitule":"SUBVENTIONS D\'EQUIPEMENT"},{"numero":"1411","intitule":"Etat"},{"numero":"1412","intitule":"Régions"},{"numero":"1413","intitule":"Départements"},{"numero":"1414","intitule":"Communes et collectivités publiques décentralisées"},{"numero":"1415","intitule":"Entité publiques ou mixtes"},{"numero":"1416","intitule":"Entreprises et organismes privés"},{"numero":"1417","intitule":"Organismes internationaux"},{"numero":"1418","intitule":"Autres"},{"numero":"148","intitule":"AUTRES SUBVENTIONS D\'INVESTISSEMENT"}],"fonctionnement":"Le compte 14 – SUBVENTIONS D\'INVESTISSEMENT est crédité du montant de l\'aide\\nobtenue\\n- par le débit du compte approprié de la classe 2, sur la base de l\'évaluation\\ndes immobilisations transférées gratuitement à l\'entité.\\nLe compte 14 – SUBVENTIONS D\'INVESTISSEMENT est crédité du montant de la\\nsubvention\\n- par le débit du compte approprié de la classe 4 tel que 4494 – Etat,\\nsubventions d\'équipement à recevoir ou 4582 – Organismes\\ninternationaux, subventions à recevoir.\\nLe compte 14 – SUBVENTIONS D\'INVESTISSEMENT est débité à la clôture de\\n- l\'exercice\\n- par le crédit des comptes 799– Reprises de subventions d\'investissement,\\npour la partie de la subvention rapportée au résultat de la période.\\nLe compte 14 – SUBVENTIONS D\'INVESTISSEMENT est débité à la date de cession de\\n- l\'actif acquis à l\'aide de la subvention\\n- par le crédit du compte 799 – Reprises de subventions d\'investissement,\\npour la partie de la subvention non encore rapportée au résultat.","commentaires":"Les subventions d\'investissement sont accordées par l\'Etat, les collectivités\\npubliques, les organismes internationaux ou les tiers, éventuellement, en vue\\nd\'acquérir ou de créer des immobilisations et de financer des activités à long terme.\\nDans certains cas, l\'entité reçoit ladite subvention d\'investissement sous la forme\\nd\'un transfert direct d\'immobilisations, à titre gratuit.\\nLes subventions d\'investissement figurent pour leur montant net au passif du bilan,\\nparmi les capitaux propres, jusqu\'à ce qu\'elles aient rempli leur objet.\\nLe compte 14 permet aux entités subventionnées d\'échelonner sur plusieurs\\nexercices l\'enrichissement provenant de ces subventions.\\nLa quote-part de subvention reprise dans le résultat de l\'exercice est égale :\\nsoit au montant de la dotation de l\'exercice aux comptes d\'amortissements des\\nimmobilisations amortissables acquises ou créées au moyen de la subvention ;\\nsoit à un montant déterminé en fonction du nombre d\'années pendant lesquelles\\n- les immobilisations non amortissables acquises ou créées au moyen de la\\nsubvention sont inaliénables aux termes du contrat, ou à défaut d\'une clause\\nd\'inaliénabilité dans le contrat, d\'une somme égale au dixième du montant de la\\nsubvention.\\nDes dérogations à ces règles générales pourront être admises lorsqu\'une telle\\nmesure sera justifiée par des circonstances particulières, notamment par le régime\\njuridique des entités, l\'objet de leur activité, les conditions posées ou les\\nengagements demandés par les autorités ou organismes ayant alloué ces\\nsubventions.","exclusions":"Le compte 14 – SUBVENTIONS D\'INVESTISSEMENT ne doit pas servir à enregistrer :\\n- les subventions d\'exploitation reçues\\n- les subventions d\'équilibre reçues\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n71 – Subventions d\'exploitation\\n88 – Subventions d\'équilibre","controle":"Le compte 14 – SUBVENTIONS D\'INVESTISSEMENT peut être contrôlé à partir de\\nrecoupements issus :\\ndes décisions d\'octroi de la subvention ou d\'affectation à l\'entité d\'un bien de\\nfaçon définitive et à titre gratuit ;\\ndu tableau d\'amortissement des biens acquis ou créés à l\'aide de la subvention\\npour vérification de la reprise au résultat de la subvention selon le même\\nrythme que les amortissements. Pour les biens non amortissables, l\'entité a la\\nfaculté de décider en l\'absence d\'instruction du pourvoyeur de la subvention, du\\nrythme de reprise de la subvention au résultat.","motsCles":["subventions","investissement"]},{"numero":"15","intitule":"Provisions réglementées et fonds assimilés","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"Les provisions réglementées sont des provisions à caractère purement fiscal ou\\nréglementaire, comptabilisées non pas en application de principes comptables,\\nmais suivant des dispositions légales et réglementaires (lois de finances, par\\nexemple).\\nPeuvent être classées dans cette catégorie, les provisions :\\nautorisées spécialement pour certaines professions (reconstitution de gisements\\nminiers et pétroliers) ;\\npour hausse des prix et fluctuation des cours ;\\npour investissement.\\nOnt notamment le caractère de fonds assimilés, lorsqu\'ils sont prévus par la\\nlégislation fiscale :\\n- les amortissements dérogatoires ;\\n- les plus-values de cession à réinvestir ;\\n- les fonds réglementés ;\\nla provision spéciale de réévaluation, lorsque la législation fiscale n\'autorisant\\npas la déductibilité du supplément d\'amortissement (concept dit de \\"neutralité\\nfiscale\\") impose la comptabilisation sous cette forme.","subdivisions":[{"numero":"151","intitule":"AMORTISSEMENTS DEROGATOIRES"},{"numero":"152","intitule":"PLUS-VALUES DE CESSION A REINVESTIR"},{"numero":"153","intitule":"FONDS REGLEMENTES"},{"numero":"1531","intitule":"Fonds national"},{"numero":"1532","intitule":"Prélèvement pour le Budget"},{"numero":"154","intitule":"PROVISION SPECIALE DE REEVALUATION"},{"numero":"155","intitule":"PROVISIONS REGLEMENTEES RELATIVES AUX IMMOBILISATIONS"},{"numero":"1551","intitule":"Reconstitution des gisements miniers et pétroliers"},{"numero":"156","intitule":"PROVISIONS REGLEMENTEES RELATIVES AUX STOCKS"},{"numero":"1561","intitule":"Hausse de prix"},{"numero":"1562","intitule":"Fluctuation des cours"},{"numero":"157","intitule":"PROVISIONS POUR INVESTISSEMENT"},{"numero":"158","intitule":"AUTRES PROVISIONS ET FONDS REGLEMENTES"}],"fonctionnement":"Le compte 15 – PROVISIONS REGLEMENTEES ET FONDS ASSIMILES est crédité de\\nla création ou de la variation en augmentation des provisions réglementées\\n- par le débit du compte 85 – Dotations H.A.O.\\nLe compte 15 – PROVISIONS REGLEMENTEES ET FONDS ASSIMILES est débité de\\n- l\'annulation ou de la variation en diminution des provisions réglementées\\n- par le crédit du compte 86 – Reprises H.A.O.","commentaires":"Du fait de leur caractère de réserves non libérées d\'impôt sur lesquelles pèsent une\\ncharge latente ou différée d\'impôt qui n\'est pas comptabilisée, les provisions\\nréglementées et fonds assimilés sont inscrits au passif du bilan parmi les capitaux\\npropres.\\nElles sont créées ou augmentées exclusivement par \\"Dotations H.A.O.\\", et sont\\nréduites ou annulées exclusivement par \\"Reprises H.A.O.\\".\\nExemple : Schéma de comptabilisation des plus-values à réinvestir\\nCe mécanisme comptable a pour objet de répondre aux exigences fiscales dans les\\npays où s\'applique le système des plus-values à réinvestir :\\n- les plus-values de cession sur des éléments de l\'actif immobilisé de l\'exercice\\nsont constatées par différence entre : les comptes 81 – Valeurs comptables des\\ncessions d\'immobilisations et les comptes 82 – Produits des cessions\\nd\'immobilisations ;\\nà la clôture de l\'exercice, l\'engagement de réemploi de la plus-value, dans les\\nlimites autorisées par la législation fiscale, est constaté :\\nDébit 851 – Dotations aux provisions réglementées\\nCrédit 152 – Plus-values de cession à réinvestir\\nEn l\'absence de réinvestissement au cours de l\'exercice suivant, la provision doit\\nêtre reprise intégralement :\\nDébit 152 – Plus-values de cession à réinvestir\\nCrédit 861 – Reprises de provisions réglementées\\nEn cas d\'utilisation de la plus-value conformément à son objet, le bien donnera lieu\\nà un amortissement calculé dans les conditions de droit commun. En revanche,\\nannuellement, la différence entre l\'amortissement calculé globalement sur la valeur\\nd\'entrée du bien dans le patrimoine et l\'amortissement calculé sur la base de son\\n\\"coût de revient\\", diminué de la plus-value, donne lieu à reprise partielle pour ce\\nmontant de la plus-value à réinvestir :\\nDébit 152 – Plus-values de cession à réinvestir\\nCrédit 861 – Reprises de provisions réglementées","exclusions":"Le compte 15 – PROVISIONS REGLEMENTEES ET FONDS ASSIMILES ne doit pas\\nservir à enregistrer :\\n- les provisions destinées à couvrir des risques et des charges futurs (à plus d\'un\\nan)\\n- les dépréciations de l\'actif immobilisé\\n- les dépréciations de l\'actif circulant\\n- les dépréciations des comptes de trésorerie\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n19 – Provisions financières pour risques et charges\\n29 –Dépréciations\\n39 – Dépréciations des stocks\\n49 – Dépréciations et provisions pour risques à court terme (Tiers)\\n59 – Dépréciations et provisions pour risques à court terme (Trésorerie)","controle":"Le compte 15 – PROVISIONS REGLEMENTEES ET FONDS ASSIMILES peut être\\ncontrôlé à partir de recoupements issus :\\ndes écritures à la clôture de l\'exercice ;\\ndes tableaux d\'amortissements comptables et fiscaux ;\\ndes factures de cession d\'immobilisations et des opérations faisant ressortir la\\nplus ou moins-value ;\\ndes décisions des assemblées sur la répartition du résultat et la législation\\nconcernant cette affectation.","motsCles":["provisions","reglementees","fonds","assimiles"]},{"numero":"16","intitule":"Emprunts et dettes assimilées","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"Les emprunts et les dettes assimilées sont des ressources financières externes,\\ncontractées auprès d\'établissements de crédit et/ou de tiers divers, affectées de\\nfaçon durable au financement des moyens d\'exploitation ou de production.\\nLes emprunts obligataires sont traités au titre VII Opérations spécifiques, chapitre\\n19.\\nRemboursables à terme, ils participent concurremment avec les capitaux propres à\\nla couverture des besoins durables de l\'entité.","subdivisions":[{"numero":"161","intitule":"EMPRUNTS OBLIGATAIRES"},{"numero":"1611","intitule":"Emprunts obligataires ordinaires"},{"numero":"1612","intitule":"Emprunts obligataires convertibles en actions"},{"numero":"1613","intitule":"Emprunts obligataires remboursables en actions"},{"numero":"1618","intitule":"Autres emprunts obligataires"},{"numero":"162","intitule":"EMPRUNTS ET DETTES AUPRES DES ETABLISSEMENTS DE CREDIT"},{"numero":"163","intitule":"AVANCES REÇUES DE L\'ETAT"},{"numero":"164","intitule":"AVANCES REÇUES ET COMPTES COURANTS BLOQUES"},{"numero":"165","intitule":"DEPÔTS ET CAUTIONNEMENTS REÇUS"},{"numero":"1651","intitule":"Dépôts"},{"numero":"1652","intitule":"Cautionnements"},{"numero":"166","intitule":"INTERÊTS COURUS"},{"numero":"1661","intitule":"sur emprunts obligataires"},{"numero":"1662","intitule":"sur emprunts et dettes auprès des établissements de crédit"},{"numero":"1663","intitule":"sur avances reçues de l\'Etat"},{"numero":"1664","intitule":"sur avances reçues et comptes courants bloqués"},{"numero":"1665","intitule":"sur dépôts et cautionnements reçus"},{"numero":"1667","intitule":"sur avances assorties de conditions particulières"},{"numero":"1668","intitule":"sur autres emprunts et dettes"},{"numero":"167","intitule":"AVANCES ASSORTIES DE CONDITIONS PARTICULIERES"},{"numero":"1671","intitule":"Avances bloquées pour augmentation du capital"},{"numero":"1672","intitule":"Avances conditionnées par l\'Etat"},{"numero":"1673","intitule":"Avances conditionnées par les autres organismes africains"},{"numero":"1674","intitule":"Avances conditionnées par les organismes internationaux"},{"numero":"1676","intitule":"Droits du concédant exigibles en nature"},{"numero":"168","intitule":"AUTRES EMPRUNTS ET DETTES"},{"numero":"1681","intitule":"Rentes viagères capitalisées"},{"numero":"1682","intitule":"Billets de fonds"},{"numero":"1683","intitule":"Dettes consécutives à des titres empruntés"},{"numero":"1685","intitule":"Emprunts participatifs"},{"numero":"1686","intitule":"Participation des travailleurs aux bénéfices"}],"fonctionnement":"Le compte 16 – EMPRUNTS ET DETTES ASSIMILEES est crédité du montant net des\\nemprunts et avances diverses accordés\\n- par le débit des comptes de trésorerie concernés\\nLe compte 16 – EMPRUNTS ET DETTES ASSIMILEES est crédité, à la clôture de\\n- l\'exercice, des intérêts courus jusqu\'au jour de la clôture\\n- par le débit du compte 671 – Intérêts des emprunts.\\nLe compte 16 – EMPRUNTS ET DETTES ASSIMILEES est crédité du montant des\\ndépôts et cautionnements reçus\\n- par le débit des comptes de trésorerie intéressés.\\nLe compte 16 – EMPRUNTS ET DETTES ASSIMILEES est débité, à la date d\'échéance\\nde remboursement, du montant du principal remboursé\\n- par le crédit d\'un compte de tiers ou d\'un compte de trésorerie.\\nLe compte 16 – EMPRUNTS ET DETTES ASSIMILEES est débité, à l\'ouverture de\\n- l\'exercice, du montant des intérêts courus pris en compte à la clôture de l\'exercice\\nprécédent\\n- par le crédit du compte 671 – Intérêts des emprunts.\\nLe compte 16 – EMPRUNTS ET DETTES ASSIMILEES est débité du montant des\\ndépôts et cautionnements restitués\\n- par le crédit des comptes de trésorerie concernés.","commentaires":"Les emprunts et dettes assimilées ne sont pas distingués en fonction du terme\\nd\'exigibilité. Toutefois, à la clôture de l\'exercice, les fractions devenues exigibles à\\nun an au plus, à deux ans au plus, et à plus de deux ans sont isolées afin d\'être\\nportées distinctement dans le tableau des créances et dettes.\\nS\'agissant de leur position au passif du bilan, les comptes 161 – Emprunts\\nobligataires et 162 – Emprunts et dettes auprès des établissements de crédit\\ndoivent être regroupés sur une ligne distincte \\"Emprunts\\". Les comptes 163 à 168\\nfigurent en dettes financières diverses.\\nPour les emprunts assortis d\'une caution, d\'une garantie ou de gage, le montant et\\nla portée de la caution, de la garantie ou du gage doivent être indiqués dans les\\nNotes annexes.\\nSchéma de comptabilisation des emprunts obligations (voir titre VIII Opérations\\nspécifiques, chapitre 20).","exclusions":"Le compte 16 – EMPRUNTS ET DETTES ASSIMILEES ne doit pas servir à enregistrer\\n:\\n- les emprunts et dettes liées à des participations\\n- les emprunts équivalents de crédit-bail et contrats assimilés\\n- les primes de remboursement des obligations\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n- 181 – Dettes liées à des participations\\n17 – Dettes de crédit-bail et contrats assimilés\\n- 6714 – Primes de remboursement des obligations","controle":"Le compte 16 – EMPRUNTS ET DETTES ASSIMILEES peut être contrôlé à partir de\\nrecoupements issus :\\ndes contrats de prêts signés par l\'entité;\\ndes virements (réception et remboursements) ;\\ndu tableau d\'amortissement des emprunts ;\\ndu calcul des intérêts courus ;\\ndes contrats de dépôts et cautionnements ;\\ndes contrats d\'avances-engagements de l\'Etat et des organismes internationaux.","motsCles":["emprunts","dettes","assimilees"]},{"numero":"17","intitule":"Dettes de location acquisition","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"Ce compte enregistre le montant correspondant à la valeur d\'entrée du bien acquis\\npar contrats de location acquisition.\\nCette valeur est celle figurant dans le contrat ou la somme actualisée des\\nredevances de location acquisition (voir Titre VIII Opérations spécifiques, Chapitre\\n8).","subdivisions":[{"numero":"172","intitule":"DETTES DE LOCATION ACQUISITION/CREDIT- BAIL IMMOBILIER"},{"numero":"173","intitule":"DETTES DE LOCATION ACQUISITION/ CREDIT- BAIL MOBILIER"},{"numero":"174","intitule":"DETTES DE LOCATION ACQUISITION /LOCATION VENTE"},{"numero":"176","intitule":"INTERÊTS COURUS"},{"numero":"1762","intitule":"sur dettes de location acquisition/crédit-bail immobilier"},{"numero":"1763","intitule":"sur dettes de location acquisition/crédit-bail mobilier"},{"numero":"1764","intitule":"sur dettes de location acquisition/location vente"},{"numero":"1768","intitule":"sur autres dettes de location acquisition"},{"numero":"178","intitule":"DETTES D\'AUTRES CONTRATS DE LOCATION ACQUISITION"}],"fonctionnement":"Le compte 17 – DETTES DE LOCATION ACQUISITION est crédité à l\'entrée du bien\\nsous le contrôle de l\'entité du montant stipulé au contrat ou de la somme actualisée\\ndes redevances\\n- par le débit du compte d\'immobilisation concerné.\\nLe compte 17 – DETTES DE LOCATION ACQUISITION est crédité, à la clôture de\\n- l\'exercice, des intérêts courus de la dette\\n- par le débit du compte 672 – Intérêts dans loyers de location acquisition\\nLe compte 17 – DETTES DE LOCATION ACQUISITION est débité à la clôture de\\n- l\'exercice de la fraction des redevances payées, durant l\'exercice correspondant au\\nremboursement de la dette\\n- par le crédit du compte 623 – Redevances de location acquisition\\nLe compte 17 – DETTES DE LOCATION ACQUISITION est débité, à l\'ouverture de\\n- l\'exercice, du montant des intérêts courus pris en compte à la clôture de l\'exercice\\nprécédent\\n- par le crédit du compte 672 – Intérêts dans loyers de location acquisition","commentaires":"Ne sont visés par ce compte que les contrats de location acquisition (voir Titre VIII\\nOpérations spécifiques, Chapitre 8).","exclusions":"Le compte 17 – DETTES DE LOCATION ACQUISITION ne doit pas servir à\\nenregistrer :\\n- les dettes autres que celles relatives aux contrats de location acquisition\\n(répondant au critère d\'inscription à l\'actif du bilan)\\n- les redevances non retraitées\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n16 ou 18 – Selon le cas\\n- 622 – Locations et charges locatives","controle":"Le compte 17 – DETTES DE LOCATION ACQUISITION peut être contrôlé à partir :\\ndes factures de redevances ;\\ndes contrats de crédit-bail et assimilés ;\\ndes contrats de location vente et assimilés ;\\ndes échéanciers de remboursement.","motsCles":["dettes","location","acquisition"]},{"numero":"18","intitule":"Dettes liées à des participations et comptes de liaison des établissements et sociétés en participation","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"Les dettes liées à des participations sont des emprunts contractés auprès d\'entités\\nliées ou avec lesquelles elles ont un lien de participation.\\nLes dettes liées à des participations figurent au passif du bilan parmi les dettes\\nfinancières diverses.\\nLe compte de liaison des établissements et succursales est un compte de bilan\\nouvert au nom de l\'établissement. Il fonctionne comme un compte courant, de sorte\\nque toutes les opérations réalisées entre le siège et l\'établissement y soient\\nenregistrées comme s\'il s\'agissait d\'un tiers. En conséquence, il conviendra :\\nde créer, au siège, un compte de liaison au nom de chaque établissement ou\\nsuccursale ;\\nde créer, dans l\'établissement ou la succursale, un compte réfléchi au nom du\\nsiège.\\nLes opérations entre le siège et l\'établissement ou la succursale sont à enregistrer\\nde manière symétrique, dans la même période comptable et sur la base des mêmes\\npièces justificatives. Il en résulte que les comptes de liaison sont égaux et de sens\\ncontraire dans la comptabilité du siège et dans celle de l\'établissement ou la\\nsuccursale.","subdivisions":[{"numero":"181","intitule":"DETTES LIEES A DES PARTICIPATIONS"},{"numero":"1811","intitule":"Dettes liées à des participations (groupe)"},{"numero":"1812","intitule":"Dettes liées à des participations (hors groupe)"},{"numero":"182","intitule":"DETTES LIEES A DES SOCIETES EN PARTICIPATION"},{"numero":"183","intitule":"INTERÊTS COURUS SUR DETTES LIEES A DES PARTICIPATIONS"},{"numero":"184","intitule":"COMPTES PERMANENTS BLOQUES DES ETABLISSEMENTS ET SUCCURSALES"},{"numero":"185","intitule":"COMPTES PERMANENTS NON BLOQUES DES ETABLISSEMENTS ET SUCCURSALES"},{"numero":"186","intitule":"COMPTES DE LIAISON CHARGES"},{"numero":"187","intitule":"COMPTES DE LIAISON PRODUITS"},{"numero":"188","intitule":"COMPTES DE LIAISON DES SOCIETES EN PARTICIPATION"}],"fonctionnement":"Les comptes 181, 182 – DETTES LIEES A DES PARTICIPATIONS ET DETTES LIEES A\\nDES SOCIETES EN PARTICIPATION sont crédités de la valeur à rembourser des\\nemprunts contractés\\n- par le débit des comptes de trésorerie ou des comptes de tiers concernés.\\nLe compte 183 –INTERÊTS COURUS SUR DETTES LIEES A DES PARTICIPATIONS est\\ncrédité, à la clôture de l\'exercice, du montant des intérêts courus depuis la dernière\\néchéance\\n- par le débit du compte 671 – Intérêts des emprunts.\\nLes comptes 181, 182 – DETTES LIEES A DES PARTICIPATIONS et DETTES LIEES A\\nDES SOCIETES EN PARTICIPATION sont débités à la date d\'échéance des dettes\\n- par le crédit des comptes de trésorerie concernés.\\nLes comptes 184 à 187 – COMPTES DE LIAISON DES ETABLISSEMENTS ET\\nSUCCURSALES sont crédités des opérations effectuées entre le siège d\'une entité\\nentreprise et ses établissements ou succursales\\n- par le débit des comptes concernés.\\nLes comptes 184 à 187 – COMPTES DE LIAISON DES ETABLISSEMENTS ET\\nSUCCURSALES sont débités des opérations effectuées entre le siège d\'une entité\\nentreprise et ses établissements ou succursales (y compris le montant\\nantérieurement apporté à titre permanent)\\n- par le crédit des comptes concernés.","commentaires":"L\'utilisation des comptes 181, 182, 183 et\\n- 188 est exclusivement limitée aux opérations financières entre les entités liées.\\nCelle des comptes 184, 185, 186 et 187 est réservée aux opérations entre\\nétablissements d\'une même entité.\\nLe terme établissement s\'applique à toute division de l\'entité disposant d\'une\\ncomptabilité autonome (succursales, usines, ateliers).\\nIl convient d\'entendre par comptabilité autonome, toute comptabilité distincte\\nrattachée à la comptabilité du siège par un compte de liaison.","exclusions":"Le compte 18 – DETTES LIEES A DES PARTICIPATIONS ET COMPTES DE LIAISON\\nDES ETABLISSEMENTS ET SOCIETES EN PARTICIPATION ne doit pas servir à\\nenregistrer :\\n- les dettes résultant d\'opérations commerciales courantes entre les sociétés du\\ngroupe\\n- les dettes financières à l\'égard de tiers non liés à l\'entité par des liens de\\nparticipation ou celles contractées auprès d\'autres établissements de crédit mais\\nà des conditions de droit commun\\n- les comptes bloqués d\'associés\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n40 – Fournisseurs et comptes rattachés\\n16 – Emprunts et dettes assimilées\\n- 164 – Avances reçues et comptes courants bloqués","controle":"Le compte 18 – DETTES LIEES A DES PARTICIPATIONS ET COMPTES DE LIAISON\\nDES ETABLISSEMENTS ET SOCIETES EN PARTICIPATION peut être contrôlé à partir\\ndes recoupements issus :\\nde la vérification du lien de participation ;\\ndu contrat de prêt ;\\ndu tableau de remboursement ou d\'amortissement de l\'emprunt ;\\ndu calcul des intérêts courus ;\\nde la vérification des conditions d\'octroi lorsque l\'entité liée est un établissement\\nde crédit ;\\ndes virements.","motsCles":["dettes","liees","participations","comptes","liaison","etablissements","societes","participation"]},{"numero":"19","intitule":"Provisions pour risques et charges","classe":1,"classeLabel":"Comptes de ressources durables","groupe":"A","contenu":"Une provision est un passif externe (dette) dont l\'échéance ou le montant est\\nincertain.\\nLes provisions pour risques et charges sont des provisions destinées à couvrir des\\ncharges, des risques et pertes nettement précisés quant à leur objet que des\\névénements survenus ou en cours rendent probables, mais comportant un élément\\nd\'incertitude quant à leur montant ou leur réalisation prévisible à plus d\'un an.\\nLes provisions pour risques et charges sont inscrites au passif du bilan dans les\\ndettes financières et ressources assimilées.\\nLes provisions et passifs et actifs éventuels sont traités au titre VIII Opérations\\nspécifiques, chapitre 18.","subdivisions":[{"numero":"191","intitule":"PROVISIONS POUR LITIGES"},{"numero":"192","intitule":"PROVISIONS POUR GARANTIES DONNEES AUX CLIENTS"},{"numero":"193","intitule":"PROVISIONS POUR PERTES SUR MARCHES A ACHEVEMENT FUTUR"},{"numero":"194","intitule":"PROVISIONS POUR PERTES DE CHANGE"},{"numero":"195","intitule":"PROVISIONS POUR IMPÔTS"},{"numero":"196","intitule":"PROVISIONS POUR PENSIONS ET OBLIGATIONS SIMILAIRES"},{"numero":"1961","intitule":"Provisions pour pensions et obligations similaires – engagement de retraite"},{"numero":"1962","intitule":"Actif du régime de retraite"},{"numero":"197","intitule":"PROVISIONS POUR RESTRUCTURATION"},{"numero":"198","intitule":"AUTRES PROVISIONS POUR RISQUES ET CHARGES"},{"numero":"1981","intitule":"Provisions pour amendes et pénalités"},{"numero":"1983","intitule":"Provisions de propre assureur"},{"numero":"1984","intitule":"Provisions pour démantèlement et remise en état"},{"numero":"1985","intitule":"Provisions de droits à déduction (Chèques cadeau, cartes de fidélité…)"},{"numero":"1988","intitule":"Autres provisions pour risques et charges"}],"fonctionnement":"Le compte 19 – PROVISIONS POUR RISQUES ET CHARGES est crédité, à la clôture de\\n- l\'exercice, des charges et pertes prévisibles\\n- par le débit du compte 69 (compte 691 – Dotations aux provisions et aux\\ndépréciations d\'exploitation, ou 697 – Dotations aux provisions et aux\\ndépréciations financières) ;\\n- ou par le débit du compte 85 – Dotations H.A.O.\\nLe compte 19 – PROVISIONS POUR RISQUES ET CHARGES est débité, à la clôture de\\n- l\'exercice, de la reprise des provisions pour charges et pertes constatées à la clôture\\nd\'un exercice antérieur dont les raisons qui les ont motivées ont cessé d\'exister\\n- par le crédit du compte 79 – Reprises de provisions, de dépréciations et\\nautres;\\n- ou par le crédit du compte 86 – Reprises H.A.O.","commentaires":"- 191 – Provisions pour litiges : à constituer lorsque l\'entité engagée dans un procès risque\\nd\'être condamnée au versement de dommages et intérêts ou autres indemnités.\\n- 192 – Provisions pour garanties données aux clients : la régularité des comptes et la\\nsincérité du résultat d\'exploitation exigent que l\'on tienne compte des risques liés aux\\ngaranties accordées aux clients contractuellement, en liaison notamment avec des biens\\nvendus ou des prestations fournies. L\'estimation des provisions y afférentes peut être faite\\nsur des bases statistiques provenant de l\'expérience des années antérieures (voir titre VIII\\nOpérations spécifiques, Chapitre 18).\\n- 195 – Provisions pour impôt : le principe de base étant la méthode de l\'impôt exigible, les\\nimpôts différés ne sont pas mis en évidence dans les comptes.\\nToutefois, en cas d\'imposition fractionnée et pour des montants significatifs, il\\nconvient de doter le compte de provision pour impôts (exemple : étalement des\\nplus-values nettes à long terme).\\n- 196 – Provisions pour pensions et obligations similaires (voir titre VIII Opérations\\nspécifiques, Chapitre 21):\\nDans la plupart des Etats de l\'espace OHADA, il est institué une obligation légale ou\\nconventionnelle, à la charge des entités, de verser au profit de l\'employé une\\nindemnité spéciale dite de fin de carrière, le jour du départ à la retraite d\'un\\nmontant proportionnel à l\'ancienneté et à la rémunération atteinte à cette date.\\nPour respecter cet engagement, deux solutions s\'offrent aux entités :\\nverser à un organisme tiers (compagnie d\'assurances) ou à un fonds de pension\\ndes cotisations mensuelles, trimestrielles ou annuelles pendant toute la période\\nd\'activité du salarié.\\nL\'organisme prend en charge le versement des prestations à l\'échéance.\\nlorsque l\'entité n\'a pas d\'obligation juridique ou implicite de combler les\\npertes sur le contrat, elle n\'a pas l\'obligation de payer les indemnités de fin\\ncarrière aux membres du personnel, le paiement de celles-ci relevant de\\nla seule responsabilité de l\'assureur. La prime due à la compagnie\\nd\'assurance est enregistrée au débit du compte 6686 Assurances retraite\\net fonds de pension et au crédit du compte 4332 Assurance retraite ;\\nlorsque l\'entité a une obligation juridique ou implicite de combler les\\npertes sur le contrat, elle a l\'obligation de payer les indemnités de fin de\\ncarrière aux membres du personnel, le paiement de celles-ci relevant de\\nla responsabilité de l\'entité. La prime versée à la compagnie d\'assurance\\nou au fonds de pension est enregistrée au débit du compte 1962 Actif du\\nrégime retraite par le crédit d\'un compte de trésorerie. A la clôture de\\n- l\'exercice une dotation aux provisions (débit compte 6911 par le crédit du\\ncompte 196* doit être constituée pour tenir compte des engagements de\\nretraite. Cette provision sera reprise au fur et à mesure du départ à la\\nretraite.\\nverser elles-mêmes à l\'échéance les prestations acquises par les salariés. Cet\\nengagement devrait être constaté sous forme de provision (par le biais du\\ncompte 6911Dotations aux provisions pour risques et charges) et réajustée (en\\ncas de reprises par le biais du compte 7911 Reprises de provisions pour risques\\net charges).\\nLes indemnités de fin de carrière sont considérées comme des avantages à\\nprestations définies, ressortant de la catégorie des avantages postérieurs à l\'emploi\\ndont la prise en charge s\'effectue de façon linéaire pendant toute la durée\\nd\'acquisition conditionnelle des droits conférés aux bénéficiaires, tout en\\nprobabilisant les risques que le salarié quitte l\'entreprise avant son départ en\\nretraite.\\nLa comptabilisation des régimes à prestations définies est complexe parce que des\\nhypothèses actuarielles sont nécessaires pour évaluer l\'obligation et la charge et\\nque des écarts actuariels peuvent exister. De plus, les obligations sont évaluées sur\\nune base actualisée car elles peuvent être réglées de nombreuses années après que\\n- les membres du personnel aient effectué les services correspondants.\\nPar dérogation, les entités non inscrites à une bourse de valeur peuvent soit opter\\npour la méthode actuarielle, soit définir leurs propres modalités d\'évaluation des\\nengagements de retraite et avantages similaires (avec ou sans actualisation).\\nEn revanche les sociétés inscrites à une bourse de valeur sont tenues d\'appliquer la\\nméthode d\'évaluation actuarielle et faire des hypothèses actuarielles (voir Titre VIII\\nOpérations spécifiques, Chapitre 21).\\nLa première année d\'application de la comptabilisation des indemnités de fin de\\ncarrière, (à inscrire au crédit du compte « 196 : provisions pour pensions et\\nobligations similaires ») doit être considérée comme un changement de méthode\\ncomptable. Le retraitement doit être en principe rétrospectif par une imputation\\nsur les réserves. Les engagements antérieurs non comptabilisés (montant net de\\n- l\'effet d\'impôt) sont affectés directement aux postes de réserves ou report à\\nnouveau. La mise en œuvre de cette possibilité est plus délicate. En effet, elle\\nnécessite :\\n- l\'existence de réserves suffisantes ;\\n- l\'approbation de l\'Assemblée générale des actionnaires.\\nToutefois, l\'entité peut recourir à deux autres méthodes de comptabilisation qui\\nsont les suivantes :\\ncomptabilisation de la totalité de la charge à la fin du premier exercice\\nd\'application ;\\nétalement de la partie de l\'indemnité relative aux engagements antérieurs non\\ncomptabilisés de façon linéaire, sur une durée maximum de cinq ans ;\\n- 197 – Provisions pour restructuration La provision pour restructuration concerne l\'arrêt ou\\nla vente d\'une branche d\'activité, les changements apportés à la structure de direction ou\\nune réorganisation fondamentale, avant un effet significatif sur la nature et le recentrage\\nd\'une activité.\\nEn ce qui concerne la revente d\'une branche d\'activité, l\'obligation de\\nrestructuration n\'existe pas jusqu\'à un accord de vente irrévocable. Si ce fait\\ngénérateur n\'existe pas à la date de clôture, aucune provision ne sera comptabilisée.\\n(voir Titre VIII Opérations spécifiques chapitre 18).\\n- 1984 – Provisions pour démantèlement et remise en état (voir Titre VIII Opérations\\nspécifiques, Chapitre 6)\\n- 1985 – Provisions pour droits à déduction (Chèques cadeau, cartes de fidélité….)\\nLors de la vente initiale d\'un produit ou d\'un service, l\'entité peut s\'engager, de\\nmanière explicite ou implicite, à accorder à ses clients des droits se traduisant par\\nune réduction monétaire ou par la remise d\'avantages en nature ou de prestations.\\nLe droit à réduction ou l\'avantage peut être mobilisable immédiatement ou à terme,\\navec des conditions de délai ou de seuils, le cas échéant. (voir Titre VIII Opérations\\nspécifiques, Chapitre 18).\\nEn application du principe de prudence, même en cas d\'absence ou d\'insuffisance\\nde bénéfice, il doit être procédé obligatoirement aux provisions.\\nLe compte 19 est réajusté à la clôture de chaque exercice soit par dotations\\nsupplémentaires, soit par reprises des provisions antérieures.","exclusions":"Le compte 19 – PROVISIONS POUR RISQUES ET CHARGES ne doit pas servir à\\nenregistrer :\\n- les charges certaines d\'un montant déterminé, qui sont à comptabiliser dans les\\ncomptes de charges par nature avec contrepartie dans les comptes de tiers ou de\\ntrésorerie concernés\\n- les provisions qui ont pour origine une réglementation particulière, souvent\\nd\'ordre fiscal, sans charges ou pertes réellement prévisibles\\n- les provisions correspondant à des risques à moins d\'un an\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\nclasses 6 et 8 de Charges\\n15 – Provisions réglementées et fonds assimilés\\n- 499 – Provisions pour risques à court terme","controle":"Le compte 19 – PROVISIONS POUR RISQUES ET CHARGES peut être contrôlé à partir\\ndes éléments ci-après :\\nvérification du calcul des provisions ;\\nrecherche de la réalité du risque ou de l\'éventualité de la charge ; appréciation\\nde l\'échéance du risque ou de la charge.\\n\\n# CLASSE 2 : COMPTES D\'ACTIF IMMOBILISÉ\\nL\'actif immobilisé correspond aux emplois durables rendus nécessaires par l\'objet\\néconomique et financier de l\'entité que constituent ses « activités ordinaires ».\\nLes immobilisations représentent les biens et valeurs destinés à rester durablement\\ndans l\'entité: les immobilisations incorporelles, corporelles et financières.\\nL\'entité dresse à la clôture de l\'exercice un inventaire détaillé de ses\\nimmobilisations.\\nLes comptes de l\'actif immobilisé doivent comprendre toutes les immobilisations,\\ncorporelles ou incorporelles, existant dans l\'entité, qu\'elles soient affectées ou non à\\n- l\'exploitation. Les immobilisations louées par l\'entité et qui concourent à son\\nexploitation sont également inscrites au bilan.\\nLe montant d\'une immobilisation corporelle d\'une entité peut sur option être\\nventilée en ses parties significatives dès lors que :\\n- les éléments d\'actif sont dissociables ;\\n- les éléments d\'actif ont une utilisation différente ;\\nla durée d\'utilité de chaque élément est différente.\\nChaque élément de cette immobilisation peut être comptabilisé séparement dès son\\nacquisition ou son remplacement, si son coût peut être évalué de façon fiable et\\nqu\'il est significatif par rapport au coût total de l\'immobilisation.\\nAinsi, peuvent être décomposés selon le SYSCOHADA : les immeubles, les avions, les\\nbateaux, des camions des autocars, des bus, des plates formes pétrolières, certaines\\nmachines des entités industrielles, minières, et pétrolières dès lors que l\'entité\\ndispose de statistiques lui permettant de bien appréhender la durée d\'utilité de\\nchaque élément.\\nLes immobilisations entièrement amorties demeurent inscrites au bilan aussi\\nlongtemps qu\'elles subsistent dans l\'entité.\\nLes comptes d\'actif immobilisé peuvent être assortis de comptes d\'amortissements\\nou de provisions pour dépréciation.\\nLa dépréciation des immobilisations, qu\'elle résulte de l\'usure, du changement des\\ntechniques ou de toute autre cause, doit être constatée par des amortissements.\\nLes moins-values sur les immobilisations consécutives à des événements jugés non\\nirréversibles doivent faire l\'objet de provisions pour dépréciation. Toutefois, les\\nmoins-values sur immobilisations amortissables ne concernent que des\\ndépréciations exceptionnelles qui ne peuvent raisonnablement être inscrites au\\ncompte d\'amortissement en raison de leur caractère non définitif.\\nEn tout état de cause, même en cas d\'absence ou d\'insuffisance de bénéfices, l\'entité\\nprocède aux amortissements et aux provisions nécessaires pour que le bilan donne\\nune image fidèle du patrimoine, de la situation financière et du résultat de\\n- l\'exercice.\\nLors de son entrée dans le patrimoine de l\'entité, la valeur de l\'immobilisation est\\nainsi déterminée :\\n- le bien acquis à titre onéreux est comptabilisé à son coût d\'acquisition.\\nCe coût d\'acquisition est déterminé par l\'addition des éléments suivants :\\n- le prix d\'achat net de remises et rabais commerciaux et d\'escompte de\\nrèglement et de taxes récupérables,\\n- les frais accessoires après déduction des taxes récupérables (frais de\\ntransport, droits de douane, frais d\'installation et de montage, etc.) ;\\n- les frais d\'acquisition après déduction des taxes récupérables (droits de\\nmutation, d\'enregistrement, honoraires, commissions, frais d\'actes, etc.);\\n- l\'estimation initiale des coûts relatifs au démantèlement, à l\'enlèvement de\\n- l\'immobilisation et à la remise en état du site sur lequel elle est située, si cette\\nobligation incombe à l\'entité soit du fait de l\'acquisition de l\'immobilisation\\ncorporelle, soit du fait de son utilisation pendant une durée spécifique à des\\nfins autres que la production de stocks au cours de cette période. Ces coûts\\nseront comptabilisés dans un sous compte composant de l\'immobilisation\\nprincipal par le biais de 79 Reprises de provisions, de dépréciations et autres.\\nEtant entendu que la provision a été dotée au préalable (débit 6914 par le\\ncrédit de 1984).\\nCompte tenu de la simultanéité des deux écritures le SYSCOHADA autorise que le\\nsous compte composant démantèlement soit débité par le crédit du compte de\\nprovisions 1984.\\nPour la première d\'année application les coûts doivent être estimés et comptabilisés\\nen tenant compte de la provision constituée antérieurement par le biais du compte\\nprovision pour charges à répartir (voir titre VIII Opérations spécifiques, Chapitre 6).\\nLes coûts d\'emprunt pour financer l\'acquisition d\'un actif qualifié,\\nimmobilisation incorporelle ou corporelle, peuvent être inclus dans le coût\\ndu bien lorsqu\'ils concernent la période de production du bien, jusqu\'à la\\ndate d\'acquisition ou de réception définitive (voir Titre VIII Opérations\\nspécifiques chapitre 7).\\n- le bien produit par l\'entité est comptabilisé à son coût de production.\\nCe coût de production est déterminé par l\'addition des éléments suivants :\\n- le coût d\'acquisition des matières et fournitures consommées,\\n- les charges directes de production,\\n- les charges indirectes de production dans la mesure où elles peuvent être\\nraisonnablement rattachées à la production du bien ;\\nLes coûts d\'emprunt pour financer la production d\'un actif qualifié,\\nimmobilisation incorporelle ou corporelle, peuvent être inclus dans le coût\\ndu bien lorsqu\'ils concernent la période de production du bien, jusqu\'à la\\ndate de réception définitive (voir titre VIII Opérations spécifiques, Chapitre\\n7).\\n- le bien acquis à titre gratuit est comptabilisé à sa valeur vénale ;\\n- le bien acquis par voie d\'échange doit être évalué à la valeur vénale ou à la\\nvaleur comptable de l\'actif donné en échange, à défaut de marché.\\nLe bien acquis contre versement de rentes viagères est comptabilisé pour le\\nmontant stipulé dans le contrat ou à défaut la valeur actuelle à la date du contrat\\nvoir Titre VIII Opérations spécifiques, Chapitre 11).\\n- le bien reçu à titre d\'apport en nature est comptabilisé à la valeur figurant dans\\n- l\'acte d\'apport.\\nLe bien acquis en monnaies étrangères est comptabilisé en unité monétaire\\nlégale au cours du jour de l\'acquisition (voir Titre VIII Opérations spécifiques,\\nChapitre 22).\\nLes pièces de rechange principales et le stock de pièces de sécurité constituent\\ndes immobilisations corporelles si l\'entité compte les utiliser sur plus d\'un\\nexercice.\\nPour les pièces de sécurité, l\'amortissement doit démarrer dès l\'acquisition de\\n- l\'immobilisation principale.\\nPour les pièces de rechange destinées à remplacer totalement ou partiellement un\\ncomposant, l\'amortissement ne débute qu\'à la date d\'utilisation de la pièce, c\'est-à-\\ndire au moment où elle est intégrée dans l\'immobilisation principale.\\nLorsqu\'une inspection majeure est réalisée, son coût est comptabilisé dans un\\nsous compte composant de l\'immobilisation principale appelée\\nRévisions majeures. Cette révision est amortie sur la durée séparant deux révisions.\\nLorsque la révision est réalisée toute valeur comptable résiduelle du coût de la\\nprécédente inspection est décomptabilisée (voir Titre VIII Opérations spécifiques,\\nChapitre 5).\\nLes immobilisations cédées, disparues ou détruites cessent de figurer au bilan.\\nLes immobilisations mises hors service ou au rebut, sont à amortir intégralement.\\nLa concession est le contrat par lequel une personne publique, le concédant,\\nconfie à un concessionnaire, entité du secteur privé,\\nla construction et/ou l\'amélioration, l\'exploitation et/ou l\'entretien,\\nd\'infrastructures servant à fournir un service public, pour une durée\\ndéterminée, et moyennant le droit de percevoir des redevances des usagers\\ndu service public.\\nLe SYSCOHADA a retenu le mode comptabilisation suivant :\\nDroit exclusif d\'utilisation ou d\'exploitation : en l\'absence de flux\\ncorrespondant, ce droit n\'est pas comptabilisé, mais il doit être mentionné\\ndans les Notes annexes avec la durée résiduelle du contrat ;\\nTraitement des infrastructures si elles sont réalisées par l\'opérateur privé\\n(voir Titre VIII Opérations spécifiques chapitre 25).","motsCles":["provisions","risques","charges"]},{"numero":"21","intitule":"Immobilisations incorporelles","classe":2,"classeLabel":"Comptes d\'actif immobilisé","groupe":"A","contenu":"Les immobilisations incorporelles sont des actifs non monétaires identifiables sans\\nsubstance physique, contrôlés par l\'entité qui a le pouvoir d\'obtenir des avantages\\néconomiques futurs et peut restreindre l\'accès des tiers à ces avantages.\\nUn actif est identifiable s\'il\\nest séparable, c\'est-à-dire qu\'il peut être séparé de l\'entité et être vendu,\\ntransféré, concédé par licence, loué ou échangé, soit de façon individuelle, soit\\ndans le cadre d\'un contrat, avec un actif ou un passif liés; ou\\nrésulte de droits contractuels ou d\'autres droits légaux, que ces droits soient ou\\nnon cessibles ou séparables de l\'entité ou d\'autres droits et obligations.\\nUne entité contrôle ses avantages si ces connaissances sont protégées par des droits\\nlégaux.\\nLes avantages économiques futurs résultent des produits découlant de la vente de\\nbiens ou services, des économies de coûts ou d\'autres avantages résultant de\\n- l\'utilisation de l\'actif par l\'entité.\\nElles ont la nature de biens acquis ou créés par l\'entité, non pour être vendus ou\\ntransformés, mais pour être utilisés de manière durable, directement ou\\nindirectement, pour la réalisation des opérations professionnelles ou non.","subdivisions":[{"numero":"211","intitule":"FRAIS DE DEVELOPPEMENT"},{"numero":"212","intitule":"BREVETS, LICENCES, CONCESSIONS ET DROITS SIMILAIRES"},{"numero":"2121","intitule":"Brevets"},{"numero":"2122","intitule":"Licences"},{"numero":"2123","intitule":"Concessions de service public"},{"numero":"2128","intitule":"Autres concessions et droits similaires"},{"numero":"213","intitule":"LOGICIELS ET SITES INTERNET"},{"numero":"2131","intitule":"Logiciels"},{"numero":"2132","intitule":"Sites internet"},{"numero":"214","intitule":"MARQUES"},{"numero":"215","intitule":"FONDS COMMERCIAL"},{"numero":"216","intitule":"DROIT AU BAIL"},{"numero":"217","intitule":"INVESTISSEMENTS DE CREATION"},{"numero":"218","intitule":"AUTRES DROITS ET VALEURS INCORPORELS"},{"numero":"2181","intitule":"Frais de prospection et d\'évaluation de ressources minérales"},{"numero":"2182","intitule":"Coûts d\'obtention du contrat"},{"numero":"2183","intitule":"Fichiers clients, notices, titres de journaux et magazines"},{"numero":"2188","intitule":"Divers droits et valeurs incorporelles"},{"numero":"219","intitule":"IMMOBILISATIONS INCORPORELLES EN COURS"},{"numero":"2191","intitule":"Frais de développement"},{"numero":"2193","intitule":"Logiciels"},{"numero":"2198","intitule":"Autres droits et valeurs incorporels"}],"fonctionnement":"Le compte 21 – IMMOBILISATIONS INCORPORELLES est débité de la valeur\\nd\'apport, d\'acquisition ou de création par l\'entité de l\'immobilisation incorporelle\\n- par le crédit du compte 10 – Capital ;\\n- ou par le crédit du compte 46 – Apporteurs, Associés et\\nGroupe ;\\n- ou par le crédit des comptes de tiers ;\\n- ou par le crédit des comptes de trésorerie ;\\n- ou par le crédit du compte 72 – Production immobilisée.\\nLe compte 21 – IMMOBILISATIONS INCORPORELLES est crédité en cas de cession,\\ndisparition, destruction ou mise au rebut\\n- par le débit du compte 81 – Valeurs comptables des cessions\\nd\'immobilisations (ou du compte 654 – Valeurs comptables des cessions\\ncourantes d\'immobilisations) ; et/ou par le débit du compte 281 –\\nAmortissements des immobilisations incorporelles (pour solde de ce\\ncompte).","commentaires":"Le compte 211 enregistre les dépenses résultant du développement (ou de la phase\\nde développement d\'un projet interne) si et seulement si l\'entité peut démontrer\\nqu\'elle satisfait aux 6 critères suivants :\\nla faisabilité technique nécessaire à l\'achèvement de l\'immobilisation\\nincorporelle en vue de sa mise en service ou de sa vente : faisabilité technique\\ndémontrée ;\\nson intention d\'achever l\'immobilisation incorporelle et de la mettre en service\\nou de la vendre : intention de produire et de commercialiser ;\\nsa capacité à mettre en service ou à vendre l\'immobilisation incorporelle :\\ncapacité de produire et de commercialiser ;\\nla façon dont l\'immobilisation incorporelle générera des avantages économiques\\nfuturs probables.\\nL\'entité doit démontrer, entre autres choses, l\'existence d\'un marché pour la\\nproduction issue de l\'immobilisation incorporelle ou pour l\'immobilisation\\nincorporelle elle- même ou, si celle-ci doit être utilisée en interne, son utilité :\\nexistence d\'un marché potentiel;\\nla disponibilité de ressources techniques, financières et autres, appropriées pour\\nachever le développement et mettre en service ou vendre l\'immobilisation\\nincorporelle : ressources suffisantes pour terminer le projet;\\nsa capacité à évaluer de façon fiable les dépenses attribuables à l\'immobilisation\\nincorporelle au cours de son développement : capacité d\'évaluation fiable des\\ndépenses à immobiliser.\\nCette immobilisation incorporelle est amortie en fonction de sa durée d\'utilité.\\nLes dépenses pour la recherche sont comptabilisées en charge lorsqu\'elles sont\\nencourues et non en immobilisations incorporelles.\\nSi la distinction n\'est pas possible entre la phase de recherche et la phase de\\ndéveloppement, toutes les dépenses seront considérés comme de la recherche, donc\\ninscrites dans les charges (voir Titre VIII Opérations spécifiques, Chapitre 1).\\nCompte 212 Brevets, licences, concessions et droits assimilés (voir titre VIII\\nOpérations spécifiques, chapitre 2). Il enregistre les dépenses engagées pour obtenir\\nla protection accordée sous certaines conditions aux inventeurs, auteurs ou\\nbénéficiaires du droit d\'exploitation des brevets, modèles, dessins, procédés,\\npropriétés littéraire et artistique sous forme directe ou sous forme de licences ou de\\nconcessions.\\nLes éléments du compte 212 sont amortissables sur leur durée de vie économique\\nau maximum égale à la durée de la protection juridique.\\nLes Marques enregistrent le coût d\'acquisition des marques commerciales ou\\nindustrielles. Dans le cas où ces marques ne semblent pas avoir une valeur\\npérenne, elles sont à amortir.\\nCompte 213 logiciels et sites internet (voir Titre VIII Opérations spécifiques,\\nChapitre 2). Ce compte Logiciels enregistre les dépenses faites en vue d\'acquérir le\\ndroit d\'usage, d\'adaptation, ou encore de reproduction d\'un logiciel acquis, de\\nmême que le coût de production d\'un logiciel créé ou développé pour les besoins\\ninternes de l\'entité.\\nLe logiciel est un ensemble de programmes, procédés, et règles assortis ou non de\\ndocumentation, acquis ou créés par l\'entité en vue du traitement automatique des\\ndonnées.\\nCompte 215 – Fonds commercial (voir titre VIII Opérations spécifiques, Chapitre 2).\\nCe compte est constitué par les éléments incorporels qui ne font pas l\'objet d\'une\\névaluation et d\'une comptabilisation séparées au bilan et qui concourent au\\nmaintien ou au développement du potentiel d\'activité de l\'entité, de la clientèle, de\\n- l\'achalandage, du droit au bail, du nom commercial et de l\'enseigne.\\nLa clientèle et l\'achalandage correspondent au potentiel de bénéfice représenté par\\n- l\'existence d\'une clientèle déterminée ou justifié par l\'emplacement de l\'entité.\\nLes éléments composant le fonds commercial ne bénéficient pas toujours d\'une\\nprotection juridique leur donnant une valeur pérenne. Seul est inscrit à ce compte\\n- le fonds commercial acquis.\\nCompte 216 – Droit au bail et pas de porte (voir titre VIII Opérations spécifiques,\\nchapitre 2). Ce compte est constitué par le montant versé ou dû au locataire\\nprécédent en considération du transfert des droits résultant tant des conventions\\nque de la législation sur la propriété commerciale.\\nLe compte 217 – Investissements de création se rapporte aux fabricants,\\nproducteurs, éditeurs et distributeurs de phonogrammes, aux entités de spectacle,\\naux établissements exerçant des activités culturelles et aux industries textiles\\n(créateurs de mode).\\nSont donc portés au compte 217 les dépenses particulièrement élevées que les\\néditeurs engagent pour l\'étude et la production de certains ouvrages et de certaines\\néditions (ouvrages de grandes collections, ouvrages d\'art et encyclopédies) ainsi que\\n- les frais de collection exposés dans l\'industrie textile.\\nCompte 2181 Frais de prospection et d\'évaluation de ressources minérales (voir\\ntitre VIII Opérations spécifiques, chapitre 3). Ce compte enregistre des dépenses\\nd\'exploration et d\'évaluation des ressources minérales après obtention des droits\\nd\'exploitation. Ces dépenses peuvent être enregistrées soit en charges, soit en\\nimmobilisations incorporelles.\\nLa méthode retenue doit être cohérente et permanente pour tous les exercices et les\\nactivités ou éléments similaires.\\nL\'entité peut prendre en compte toutes les dépenses qui peuvent être associées à la\\ndécouverte de ressources minérales spécifiques par exemple :\\nacquisition de droits de prospecter ;\\nétudes topographiques, géologiques ; géochimiques et géophysiques ;\\nforage d\'exploration ;\\ncreusement de tranchées ;\\néchantillonnage ;\\net activités en liaison avec l\'évaluation de la faisabilité technique et de la\\nviabilité commerciale de l\'extraction d\'une ressource minérale.\\nLes actifs de prospection et d\'évaluation doivent être soumis à un test de\\ndépréciation.\\nCompte 2182 Coûts d\'obtention du contrat (voir titre VIII Opérations spécifiques,\\nchapitre 2). Le SYSCOHADA préconise l\'activation sur option des coûts d\'obtention\\ndu contrat lorsque les conditions suivantes sont remplies :\\nces coûts sont marginaux, c\'est-à-dire que l\'entité ne les aurait pas encourus si\\nelle n\'avait pas obtenu le contrat ;\\n- l\'entité s\'attend à les recouvrer ;\\n- les coûts d\'obtention du contrat sont significatifs ;\\nen cas d\'activation, la durée d\'amortissement de ces coûts d\'obtention aurait été\\nsupérieure à 12 mois.\\nLes coûts d\'obtention du contrat qui auraient été supportés en tout état de cause\\nsont enregistrés en charge lorsqu\'ils sont encourus ; toutefois, même si le contrat\\nn\'est pas obtenu, ces coûts sont inscrits à l\'actif lorsqu\'ils peuvent être facturés au\\nclient.\\nPar contre, les coûts suivants sont exclus du coût d\'obtention du contrat :\\n- les frais encourus pour répondre à des appels d\'offre ;\\n- les frais marketing que l\'entité encourt, qu\'elle obtienne ou non le contrat.\\nCompte 2183 Fichiers clients, notices, titres de journaux et magazines (voir titre\\nVIII Opérations spécifiques, chapitre 2).\\nCe compte enregistre lorsqu\'ils sont acquis, les fichiers clients (listes et autres bases\\nde données reflétant des relations contractuelles antérieures, listes de clients ou\\nd\'abonnés fréquemment concédées par licence), notices, titres de journaux, et\\nmagazines.\\nLes dépenses pour générer en interne les marques, les notices, les titres de\\njournaux et de magazines, les listes de clients et autres éléments similaires en\\nsubstance ne peuvent pas être distinguées du coût de développement de l\'activité\\ndans son ensemble. Par conséquent, ces éléments ne sont pas comptabilisés en tant\\nqu\'immobilisations incorporelles!\\nImmobilisations incorporelles en cours : le compte 219 enregistre le coût de\\nproduction des brevets, investissements de création et logiciels élaborés par l\'entité\\nelle-même, dont les éléments transitent pour la plupart par le compte 211 – Frais\\nde développement.","exclusions":"Le compte 21 – IMMOBILISATIONS INCORPORELLES ne doit pas servir à\\nenregistrer :\\n- les frais d\'établissement\\n- les frais de recherche\\n- les frais de pré exploitation portés en classe 6\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\ncharges de la classe 6","controle":"Le compte 21 – IMMOBILISATIONS INCORPORELLES peut être contrôlé à partir :\\ndes factures ;\\ndes promesses d\'apport ;\\ndes actes d\'acquisition ;\\ndes récépissés de dépôt de brevets, de marques ;\\ndes contrats de concession ...","motsCles":["immobilisations","incorporelles"]},{"numero":"22","intitule":"Terrains","classe":2,"classeLabel":"Comptes d\'actif immobilisé","groupe":"A","contenu":"Ce compte enregistre la valeur des terrains dont l\'entité est propriétaire et de ceux\\nqui sont mis à sa disposition par des tiers.","subdivisions":[{"numero":"221","intitule":"TERRAINS AGRICOLES ET FORESTIERS"},{"numero":"2211","intitule":"Terrains d\'exploitation agricole"},{"numero":"2212","intitule":"Terrains d\'exploitation forestière"},{"numero":"2218","intitule":"Autres terrains"},{"numero":"222","intitule":"TERRAINS NUS"},{"numero":"2221","intitule":"Terrains à bâtir"},{"numero":"2228","intitule":"Autres terrains nus"},{"numero":"223","intitule":"TERRAINS BÂTIS"},{"numero":"2231","intitule":"pour bâtiments industriels et agricoles"},{"numero":"2232","intitule":"pour bâtiments administratifs et commerciaux"},{"numero":"2234","intitule":"pour bâtiments affectés aux autres opérations professionnelles"},{"numero":"2235","intitule":"pour bâtiments affectés aux autres opérations non professionnelles"},{"numero":"2238","intitule":"Autres terrains bâtis"},{"numero":"224","intitule":"TRAVAUX DE MISE EN VALEUR DES TERRAINS"},{"numero":"2241","intitule":"Plantations d\'arbres et d\'arbustes"},{"numero":"2245","intitule":"Améliorations du fonds"},{"numero":"2248","intitule":"Autres travaux"},{"numero":"225","intitule":"TERRAINS CARRIERES TREFONDS"},{"numero":"2251","intitule":"Carrières"},{"numero":"226","intitule":"TERRAINS AMENAGES"},{"numero":"2261","intitule":"Parkings"},{"numero":"227","intitule":"TERRAINS MIS EN CONCESSION"},{"numero":"228","intitule":"AUTRES TERRAINS"},{"numero":"2281","intitule":"Terrains des immeubles de placement"},{"numero":"2285","intitule":"Terrains des logements affectés au personnel"},{"numero":"2286","intitule":"Terrain location-acquisition"},{"numero":"2288","intitule":"Autres"},{"numero":"229","intitule":"AMENAGEMENTS DE TERRAINS EN COURS"},{"numero":"2291","intitule":"Terrains agricoles et forestiers"},{"numero":"2292","intitule":"Terrains nus"},{"numero":"2295","intitule":"Terrains de carrières – tréfonds"},{"numero":"2298","intitule":"Autres terrains"}],"fonctionnement":"Le compte 22 – TERRAINS est débité de la valeur d\'apport ou d\'acquisition des\\nterrains\\n- par le crédit du compte 10 – Capital ;\\n- par le crédit du compte 46 – Apporteurs, Associés et Groupe ;\\n- ou par le crédit des comptes de tiers et des comptes de trésorerie concernés.\\nLe compte 22 – TERRAINS est crédité en cas de cession\\n- par le débit du compte 81 – Valeurs comptables des cessions\\nd\'immobilisations ; et le débit du compte 282 – Amortissements des\\nterrains, pour le montant des amortissements pratiqués sur les terrains\\nagricoles ou forestiers et sur les travaux de mise en valeur des terrains.","commentaires":"Les terrains nus sont des terrains pouvant constituer le sol de bâtiments ou\\nd\'ouvrages. Ils sont par conséquent sans construction.\\nLes terrains bâtis sont ceux sur lesquels des constructions sont édifiées ; la valeur\\nd\'entrée de ces terrains doit toujours être distinguée de celle du bâtiment\\ncorrespondant. A défaut de pièces justificatives indiquant séparément la valeur des\\nterrains et celle des constructions, la ventilation du prix global d\'acquisition peut\\nêtre effectuée par tous moyens à la disposition de l\'entité.\\nLe compte 2288 – Autres correspond aux terrains non évoqués dans les rubriques\\nprécédentes, tels que, notamment, les sous- sols et les sur-sols au cas où l\'entité ne\\nserait pas propriétaire des trois éléments rattachés à une même parcelle de terrain,\\nà savoir le sous-sol, le sol et le sur-sol.\\nLes terrains de gisement sont des terrains d\'extraction de matières destinées soit\\naux besoins de l\'entité, soit à être revendues en l\'état ou après transformation.\\nLes travaux de mise en valeur des terrains, dont la valeur peut être enregistrée par\\n- le compte 224 (voir titre VIII Opérations spécifiques, chapitre 37),sont\\nessentiellement des travaux de défrichage, drainage, irrigation, nivellement,\\ndéfonçage, plantation d\'arbres et d\'arbustes, à l\'exclusion de tout travail de\\nconstruction et de fondation qui feraient partie intégrante du coût des bâtiments.\\nCes travaux ne peuvent être isolés dans un compte et donner lieu à amortissement\\nque s\'ils ont été effectués par l\'entité ou sous ses ordres et, en aucun cas, pour les\\nterrains acquis.","exclusions":"Le compte 22 – TERRAINS ne doit pas servir à enregistrer :\\n- les dépenses de construction qui constituent des composantes du coût des\\nbâtiments\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n23 – Bâtiments, installations techniques et agencements","controle":"Le compte 22 – TERRAINS peut être contrôlé à partir :\\ndes actes d\'acquisition ;\\ndes titres de propriété.","motsCles":["terrains"]},{"numero":"23","intitule":"Bâtiments, installations techniques et agencements","classe":2,"classeLabel":"Comptes d\'actif immobilisé","groupe":"A","contenu":"Ce compte enregistre le montant des opérations ayant trait aux apports effectués\\npar les associés ou à l\'acquisition et à la création par l\'entité de bâtiments,\\ninstallations et agencements, de même que leur cession, disparition et mise au\\nrebut.","subdivisions":[{"numero":"231","intitule":"BÂTIMENTS INDUSTRIELS, AGRICOLES, ADMINISTRATIFS ET COMMERCIAUX SUR SOL PROPRE"},{"numero":"2311","intitule":"Bâtiments industriels"},{"numero":"2312","intitule":"Bâtiments agricoles"},{"numero":"2313","intitule":"Bâtiments administratifs et commerciaux"},{"numero":"2314","intitule":"Bâtiments affectés au logement du personnel"},{"numero":"2315","intitule":"Immeubles de placement"},{"numero":"2316","intitule":"Bâtiments de location acquisition"},{"numero":"232","intitule":"BÂTIMENTS INDUSTRIELS, AGRICOLES, ADMINISTRATIFS ET COMMERCIAUX SUR SOL D\'AUTRUI"},{"numero":"2321","intitule":"Bâtiments industriels"},{"numero":"2322","intitule":"Bâtiments agricoles"},{"numero":"2323","intitule":"Bâtiments administratifs et commerciaux"},{"numero":"2324","intitule":"Bâtiments affectés au logement du personnel"},{"numero":"2325","intitule":"Immeubles de placement"},{"numero":"2326","intitule":"Bâtiment de location-acquisition"},{"numero":"233","intitule":"OUVRAGES D\'INFRASTRUCTURE"},{"numero":"2331","intitule":"Voies de terre"},{"numero":"2332","intitule":"Voies de fer"},{"numero":"2333","intitule":"Voies d\'eau"},{"numero":"2334","intitule":"Barrages, Digues"},{"numero":"2335","intitule":"Pistes d\'aérodrome"},{"numero":"2338","intitule":"Autres"},{"numero":"234","intitule":"INSTALLATIONS TECHNIQUES"},{"numero":"2341","intitule":"Installations complexes spécialisées sur sol propre"},{"numero":"2342","intitule":"Installations complexes spécialisées sur sol d\'autrui"},{"numero":"2343","intitule":"Installations à caractère spécifique sur sol propre"},{"numero":"2344","intitule":"Installations à caractère spécifique sur sol d\'autrui"},{"numero":"2345","intitule":"Aménagements et agencements des bâtiments"},{"numero":"235","intitule":"AMENAGEMENTS DE BUREAUX"},{"numero":"2351","intitule":"Installations générales"},{"numero":"2358","intitule":"Autres"},{"numero":"237","intitule":"BÂTIMENTS INDUSTRIELS, AGRICOLES ET COMMERCIAUX MIS EN CONCESSION"},{"numero":"238","intitule":"AUTRES INSTALLATIONS ET AGENCEMENTS"},{"numero":"239","intitule":"BÂTIMENTS ET INSTALLATIONS EN COURS"},{"numero":"2391","intitule":"Bâtiments en cours"},{"numero":"2392","intitule":"Installations en cours"},{"numero":"2393","intitule":"Aménagements et agencements"}],"fonctionnement":"Le compte 23 – BÂTIMENTS, INSTALLATIONS TECHNIQUES ET AGENCEMENTS est\\ndébité de la valeur d\'apport, d\'acquisition ou de création par l\'entité des bâtiments,\\ninstallations et agencements\\n- par le crédit du compte 10 – Capital ;\\n- par le crédit du compte 46 – Apporteurs, Associés et Groupe ;\\n- ou par le crédit des comptes de tiers et des comptes de trésorerie concernés ;\\n- par le crédit du compte 72 – Production immobilisée ;\\n- ou par le crédit du compte 239, lorsque les éléments des comptes 231 à 238\\nayant trait à des travaux en cours sont terminés.\\nLe compte 23 – BÂTIMENTS, INSTALLATIONS TECHNIQUES ET AGENCEMENTS est\\ncrédité en cas de cession, disparition, mise au rebut\\n- par le débit du compte 81 – Valeurs comptables des cessions\\nd\'immobilisations ;\\n- ou par le débit du compte 283 – Amortissements des bâtiments, installations\\ntechniques et agencements, à concurrence du montant des amortissements\\npratiqués sur les éléments cédés ou disparus.","commentaires":"La valeur des terrains n\'est pas comprise dans celle des bâtiments. Les terrains et\\n- les bâtiments doivent faire l\'objet d\'évaluations distinctes.\\nIl faut en revanche inclure dans la valeur des bâtiments les éléments ci-après qui\\npeuvent être ventilés dans des sous comptes spécifiques du bâtiment concerné et\\namortis sur leur durée d\'utilité et non celle du bâtiment :\\n- le coût de la peinture extérieure et intérieure des constructions neuves ;\\n- le coût de tous les aménagements permanents tels que appareils de chauffage,\\nde conditionnement d\'air et de climatisation, conduites d\'eau, de gaz,\\nd\'électricité, de réception d\'images ;\\n- le coût du matériel normalement installé avant que le bâtiment soit occupé.\\nToute construction sur un terrain d\'autrui, bien qu\'elle revienne en fin de bail au\\nbailleur, doit être constatée dans les livres du locataire par le compte 232 en\\ntenant compte de toutes les dépenses engagées pour réaliser la construction.\\nEn revanche, Le bailleur ne doit faire figurer dans ses livres que la valeur des\\nterrains pendant toute la durée du bail.\\nLe locataire est tenu d\'amortir les constructions sur la durée la plus courte entre la\\ndurée d\'utilité du bien et la durée du bail.\\nEn fin de bail, le locataire rétrocède les constructions en soldant le compte 232 et le\\ncompte 2832 par le compte 812. Si le transfert se fait contre indemnité du bailleur,\\ncelle-ci sera constatée par le compte 822.\\nChez le bailleur, la construction reçue gratuitement sera constatée en retenant la\\nvaleur actuelle du jour de transfert en contrepartie du compte 841 produits HAO\\nconstatés. L\'indemnité d\'éviction est comptabilisée au débit du compte\\n- 231 (voir titre VIII Opérations spécifiques, chapitre 11).\\nLes agencements et les installations permanents effectués par le locataire ayant une\\ndurée d\'utilité supérieure à un an peuvent être immobilisés et amortis sur la durée\\ndu bail. Toutefois si le bail prévoit une remise en état à la fin du contrat une\\nestimation doit être effectuée et enregistrée comme un composant des agencements\\net des installations.\\nLes bâtiments et installations en cours sont ceux qui ne sont pas encore terminés à\\nla clôture de l\'exercice, mais qui appartiennent cependant à l\'entité. Après\\nachèvement, ces derniers seront portés au débit des comptes 231 à 238 par le\\ncrédit du compte 239 – Bâtiments et installations en cours. En principe,\\n- l\'amortissement des bâtiments ou installations en cours ne peut avoir lieu qu\'à\\npartir de leur mise en service effective.","exclusions":"Le compte 23 – BÂTIMENTS, INSTALLATIONS TECHNIQUES ET AGENCEMENTS ne\\ndoit pas servir à enregistrer :\\n- les biens corporels disparaissant par le premier usage ou dont la durée\\nd\'utilisation est inférieure à un an (petit outillage)\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\ncompte approprié de la classe 6","controle":"Le compte 23 – BÂTIMENTS, INSTALLATIONS TECHNIQUES ET AGENCEMENTS peut\\nêtre contrôlé à partir des :\\nactes d\'acquisition,\\ntitres de propriété (titres fonciers),\\nfactures ...","motsCles":["batiments","installations","techniques","agencements"]},{"numero":"24","intitule":"Matériel, Mobilier et Actifs biologiques","classe":2,"classeLabel":"Comptes d\'actif immobilisé","groupe":"A","contenu":"Le matériel est constitué par l\'ensemble des objets et instruments avec (et ou par)\\nlesquels :\\nsont extraits, transformés ou façonnés les matières ou fournitures ;\\nsont fournis les services qui sont l\'objet même de la profession exercée.\\nLe mobilier est constitué de meubles et objets utilisés sur une période supérieure à\\nun an dans l\'entreprise, comme les tables, les chaises, les classeurs.\\nL\'actif biologique est constitué d\'animaux vivants, de plantes vivantes et\\nsecondairement, des améliorations foncières, de l\'autoconsommation prélevée, de\\ncertains contrats ou partenariats spécifiques.","subdivisions":[{"numero":"241","intitule":"MATERIEL ET OUTILLAGE INDUSTRIEL ET COMMERCIAL"},{"numero":"2411","intitule":"Matériel industriel"},{"numero":"2412","intitule":"Outillage industriel"},{"numero":"2413","intitule":"Matériel commercial"},{"numero":"2414","intitule":"Outillage commercial"},{"numero":"2416","intitule":"Matériel et outillage de location acquisition"},{"numero":"242","intitule":"MATERIEL ET OUTILLAGE AGRICOLE"},{"numero":"2421","intitule":"Matériel agricole"},{"numero":"2422","intitule":"Outillage agricole"},{"numero":"2426","intitule":"Matériel et outillage agricole de location – acquisition"},{"numero":"243","intitule":"MATERIEL D\'EMBALLAGE RECUPERABLE ET IDENTIFIABLE"},{"numero":"244","intitule":"MATERIEL ET MOBILIER"},{"numero":"2441","intitule":"Matériel de bureau"},{"numero":"2442","intitule":"Matériel informatique"},{"numero":"2443","intitule":"Matériel bureautique"},{"numero":"2444","intitule":"Mobilier de bureau"},{"numero":"2446","intitule":"Matériel et mobilier de location- acquisition"},{"numero":"2447","intitule":"Matériel et mobilier des logements affectés au personnel"},{"numero":"245","intitule":"MATERIEL DE TRANSPORT"},{"numero":"2451","intitule":"Matériel automobile"},{"numero":"2452","intitule":"Matériel ferroviaire"},{"numero":"2453","intitule":"Matériel fluvial, lagunaire"},{"numero":"2454","intitule":"Matériel naval"},{"numero":"2455","intitule":"Matériel aérien"},{"numero":"2456","intitule":"Matériel de transport de location-acquisition"},{"numero":"2457","intitule":"Matériel hippomobile"},{"numero":"2458","intitule":"Autres (vélo, mobylette, moto)"},{"numero":"246","intitule":"ACTIFS BIOLOGIQUES"},{"numero":"2461","intitule":"Cheptel, animaux de trait"},{"numero":"2462","intitule":"Cheptel, animaux reproducteurs"},{"numero":"2463","intitule":"Animaux de garde"},{"numero":"2465","intitule":"Plantations agricoles"},{"numero":"2468","intitule":"Autres"},{"numero":"247","intitule":"AGENCEMENTS, AMENAGEMENTS DU MATERIEL ET ACTIFS BIOLOGIQUES"},{"numero":"2471","intitule":"Agencements et aménagements du matériel"},{"numero":"2472","intitule":"Agencements et aménagements des actifs biologiques"},{"numero":"248","intitule":"AUTRES MATERIELS ET MOBILIERS"},{"numero":"2481","intitule":"Collections et œuvres d\'art"},{"numero":"249","intitule":"MATERIEL ET ACTIFS BIOLOGIQUES EN COURS"},{"numero":"2491","intitule":"Matériel et outillage industriel et commercial"},{"numero":"2492","intitule":"Matériel et outillage agricole"},{"numero":"2493","intitule":"Matériel d\'emballage récupérable et identifiable"},{"numero":"2494","intitule":"Matériel et mobilier de bureau"},{"numero":"2495","intitule":"Matériel de transport"},{"numero":"2496","intitule":"Actifs biologiques"},{"numero":"2497","intitule":"Agencements et aménagements du matériel et des actifs biologiques"},{"numero":"2498","intitule":"Autres matériels"}],"fonctionnement":"Le compte 24 – MATERIEL, MOBILIER ET ACTIFS BIOLOGIQUES est débité de la\\nvaleur d\'apport, d\'acquisition ou de création par l\'entité des matériels\\n- par le crédit du compte 10 – Capital ;\\n- par le crédit du compte 46 – Apporteurs, Associés et Groupe ;\\n- ou par le crédit des comptes de tiers et des comptes de trésorerie concernés ;\\n- par le crédit du compte 72 – Production immobilisée ;\\n- ou par le crédit du compte 249 – Matériel en cours, lorsqu\'ils ont été achevés.\\nLe compte 24 – MATERIEL, MOBILIER ET ACTIFS BIOLOGIQUES est crédité en cas\\nde cession, disparition, mise au rebut\\n- par le débit du compte 284 – Amortissements du matériel, à concurrence du\\nmontant des amortissements pratiqués jusqu\'à la date de cession, de\\ndisparition, de mise au rebut ;\\n- ou par le débit du compte 81 – Valeurs comptables des cessions\\nd\'immobilisations, pour le solde (ou 654 – Valeurs comptables des cessions\\ncourantes d\'immobilisations).","commentaires":"Les matériels d\'emballages récupérables sont destinés à être utilisés d\'une manière\\ndurable, comme instrument de travail.\\nLa remise à neuf et les transformations importantes des matériels sont\\ncomptabilisées avec les matériels eux- mêmes, pour peu que ces travaux entraînent\\nune augmentation de leur durée de vie initiale, ou une meilleure adaptation aux\\nexigences de la production de biens et de services par l\'entité.\\nLe compte 245 – Matériel de transport enregistre les véhicules et appareils servant\\nau transport des biens et des personnes.\\nSont rattachés au compte Matériel de transport les opérations de transformation et\\n- les améliorations apportées à ces matériels ainsi que les frais annexes entraînés par\\n- l\'achat de ces matériels d\'occasion.\\nLes Actifs biologiques sont traités au titre VIII Opérations spécifiques, chapitre 37\\nLe matériel bureautique est constitué notamment par tout le matériel :\\nde substitution au support papier tels les ardoises électroniques, les écrans et\\nprogiciels ;\\nutilisé pour rationaliser le support vocal, en vue de téléconférences, messagerie\\nvocale, reconnaissance de la parole ;\\nservant à regrouper des informations sous la forme de chronos, échéanciers,\\ndossiers électroniques ;\\nde télétransmission, notamment à l\'aide de modems de communication.","exclusions":"Le compte 24 – MATERIEL, MOBILIER ET ACTIFS BIOLOGIQUES ne doit pas servir à\\nenregistrer :\\n- les biens corporels disparaissant par le premier usage ou d\'une durée de vie\\ninférieure à un an ou de très faible valeur\\nIl convient dans le cas d\'espèce d\'utiliser les comptes ci-après :\\ncomptes de la classe 6","controle":"Le compte 24 – MATERIEL, MOBILIER ET ACTIFS BIOLOGIQUES peut être contrôlé à\\npartir :\\ndes factures ;\\ndes inventaires ;\\ndes documents nécessaires à la circulation (cartes grises, livrets de bord...) ;\\nde recoupements avec les assurances payées et les taxes sur les matériels\\nroulants.","motsCles":["materiel","mobilier","actifs","biologiques"]},{"numero":"25","intitule":"Avances et acomptes versés sur immobilisations","classe":2,"classeLabel":"Comptes d\'actif immobilisé","groupe":"A","contenu":"Sommes versées par l\'entité à des tiers pour des commandes en cours\\nd\'immobilisations. Le solde de ce compte représente la créance de l\'entité sur ses\\nfournisseurs d\'immobilisations.","subdivisions":[{"numero":"251","intitule":"AVANCES ET ACOMPTES VERSÉS SUR IMMOBILISATIONS INCORPORELLES"},{"numero":"252","intitule":"AVANCES ET ACOMPTES VERSÉS SUR IMMOBILISATIONS CORPORELLES"}],"fonctionnement":"Le compte 25 – AVANCES ET ACOMPTES VERSÉS SUR IMMOBILISATIONS est débité\\ndu montant des sommes versées aux fournisseurs d\'immobilisations à la\\ncommande ou en cours d\'exécution des contrats\\n- par le crédit des comptes de trésorerie.\\nLe compte 25 – AVANCES ET ACOMPTES VERSÉS SUR IMMOBILISATIONS est crédité\\npour solde à la réception de la facture définitive du fournisseur de l\'immobilisation\\n- par le débit du compte d\'immobilisation concerné.","commentaires":"Les avances et acomptes versés par l\'entité à des tiers pour les opérations en cours\\nsont des versements effectués au profit des fournisseurs d\'immobilisations au\\nmoment des commandes ou au cours de l\'exécution des contrats. Selon que ces\\nsommes ont pour objet l\'acquisition d\'une immobilisation incorporelle ou\\ncorporelle, elles sont portées dans les comptes appropriés.","exclusions":"Le compte 25 – AVANCES ET ACOMPTES VERSÉS SUR IMMOBILISATIONS ne doit\\npas servir à enregistrer :\\n- les en-cours d\'immobilisation\\n- les avances et acomptes versés sur d\'autres biens que les immobilisations\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\ncomptes appropriés de la classe 2\\n48 – Créances et dettes H.A.O.\\n40 – Fournisseurs et comptes rattachés","controle":"Le compte 25 – AVANCES ET ACOMPTES VERSÉS SUR IMMOBILISATIONS peut être\\ncontrôlé à partir :\\ndes chèques,\\ndes relevés bancaires,\\ndes factures,\\ndes versements effectués.","motsCles":["avances","acomptes","verses","immobilisations"]},{"numero":"26","intitule":"Titres de participation","classe":2,"classeLabel":"Comptes d\'actif immobilisé","groupe":"A","contenu":"Les titres de participation sont constitués par les droits dans le capital d\'autres\\nentités, matérialisés ou non par des titres, afin de créer un lien durable avec celles-\\nci et de contribuer à l\'activité et au développement de la société détentrice.","subdivisions":[{"numero":"261","intitule":"TITRES DE PARTICIPATION DANS DES SOCIETES SOUS CONTRÔLE EXCLUSIF"},{"numero":"262","intitule":"TITRES DE PARTICIPATION DANS DES SOCIETES SOUS CONTRÔLE CONJOINT"},{"numero":"263","intitule":"TITRES DE PARTICIPATION DANS DES SOCIETES CONFERANT UNE INFLUENCE"},{"numero":"265","intitule":"PARTICIPATIONS DANS DES ORGANISMES PROFESSIONNELS"},{"numero":"266","intitule":"PARTS DANS DES GROUPEMENTS D\'INTERÊT ECONOMIQUE (G.I.E.)"},{"numero":"268","intitule":"AUTRES TITRES DE PARTICIPATION"}],"fonctionnement":"Le compte 26 – TITRES DE PARTICIPATION est débité de la valeur d\'apport ou\\nd\'acquisition\\n- par le crédit du compte 10 – Capital ;\\n- ou par le crédit des comptes de tiers et des comptes de trésorerie concernés ;\\n- par le crédit du compte 4813 – Versements restant à effectuer sur titres de\\nparticipation et titres immobilisés non libérés, pour la partie non libérée des\\ntitres.\\nLe compte 26 – TITRES DE PARTICIPATION est crédité en cas de cession de titres\\n- par le débit du compte 81 – Valeurs comptables des cessions\\nd\'immobilisations.","commentaires":"Les titres de participation sont ceux dont l\'acquisition et la possession durable\\npermettent d\'exercer une certaine influence sur la société qui les a émis (voir titre\\nVIII Opérations spécifiques, chapitre 13).\\nSont présumés être des titres de participation, les titres acquis en tout ou partie par\\noffre publique d\'achat (O.P.A.) ou par offre publique d\'échange (O.P.E.) et les titres\\nreprésentant au moins 10 % du capital social d\'une entité.\\nCette influence peut être de degrés divers allant d\'une simple prise de participation,\\nen vue d\'établir des relations commerciales privilégiées, à une véritable prise de\\ncontrôle impliquant une influence déterminante sur sa gestion.\\nUne société est considérée comme étant sous contrôle exclusif, lorsqu\'elle est\\ndétenue directement ou indirectement par une entité possédant une fraction du\\ncapital lui conférant la majorité des droits de vote dans les\\nAssemblées générales.\\nPour les comptes consolidés le contrôle est ainsi définit : Un investisseur contrôle\\nune unité faisant l\'objet d\'un investissement lorsqu\'il est exposé ou qu\'il a droit à\\ndes rendements variables en raison de ses liens avec l\'entité faisant l\'objet d\'un\\ninvestissement et qu\'il a la capacité d\'influer sur ces rendements du fait du pouvoir\\nqu\'il détient sur celle-ci.\\nUne société est présumée exercer ce contrôle lorsqu\'elle dispose, directement ou\\nindirectement, d\'une fraction des droits de vote supérieure à 40 % et qu\'aucun\\nautre associé ou actionnaire ne détient directement ou indirectement une fraction\\nsupérieure à la sienne.\\nLe contrôle conjoint est le partage du contrôle d\'une entité exploitée en commun\\npar un nombre limité d\'associés ou d\'actionnaires, de sorte que les décisions\\nrésultent de leur commun accord.\\nEst présumée conférer une influence notable dans une société la détention de titres,\\ndirecte ou indirecte, donnant à l\'entité détentrice une fraction au moins égale au\\ncinquième (20 %) des droits de vote dans ladite société.\\nLes autres titres de participation sont les titres d\'une société n\'entraînant pour leur\\npropriétaire aucun contrôle déterminant sur les décisions de l\'entité selon la\\ndéfinition donnée ci-dessus, mais lui permettant, néanmoins, d\'exercer une\\ninfluence notable.\\nEn cas de libération partielle, la part non libérée des titres de participation\\nconstitue une dette inscrite au compte 472 – Versements restant à effectuer sur\\ntitres non libérés et dont il devra être fait mention, distinctement, dans les Notes\\nannexes.\\nLorsque le type de contrôle (exclusif, sous contrôle, conjoint, influence notable)\\nvient à changer, il est opéré les transferts correspondants entre les comptes\\nconcernés.\\nLe compte 266 – Parts dans des G.I.E. enregistre les prises et les cessions de \\"parts\\nsociales\\" dans les groupements d\'intérêt économique, à l\'exclusion des avances aux\\nG.I.E. non réalisables à court terme et susceptibles d\'être consolidées par\\nincorporation au capital social. Ces avances sont suivies dans le compte 2774 –\\nAvances à des G.I.E.\\nLes apports à un G.I.E., non évalués, sont à mentionner dans les engagements\\ndonnés.\\nLes autres opérations effectuées avec un GIE doivent être portées au compte 463 –\\nAssociés, opérations faites en commun qui, pour le cas d\'espèce, pourrait donner\\nlieu à ouverture d\'un compte divisionnaire.\\nLa valeur d\'entrée est le prix d\'acquisition majoré des frais accessoires d\'achat ; les\\ntitres de participation figurent de ce fait à l\'actif (montant brut) pour leur coût\\nd\'acquisition.","exclusions":"Le compte 26 – TITRES DE PARTICIPATION ne doit pas servir à enregistrer :\\n- les titres de placement\\n- les titres immobilisés\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n50 – Titres de placement\\n- 274 – Titres immobilisés","controle":"Le compte 26 – TITRES DE PARTICIPATION peut être contrôlé à partir :\\ndes bons de souscription ;\\ndes ordres d\'achat et de vente en bourse.","motsCles":["titres","participation"]},{"numero":"27","intitule":"Autres immobilisations financières","classe":2,"classeLabel":"Comptes d\'actif immobilisé","groupe":"A","contenu":"Les autres immobilisations financières comprennent :\\n- les titres autres que les titres de participation, que l\'entité n\'a ni l\'intention, ni la\\npossibilité de revendre dans un bref délai ;\\n- les prêts nés en vertu de dispositions contractuelles ;\\n- les créances non commerciales assimilées à des prêts (dépôts et\\ncautionnements).","subdivisions":[{"numero":"271","intitule":"PRÊTS ET CREANCES"},{"numero":"2711","intitule":"Prêts participatifs"},{"numero":"2712","intitule":"Prêts aux associés"},{"numero":"2713","intitule":"Billets de fonds"},{"numero":"2714","intitule":"Créances de location financement"},{"numero":"2715","intitule":"Titres prêtés"},{"numero":"272","intitule":"PRÊTS AU PERSONNEL"},{"numero":"2721","intitule":"Prêts immobiliers"},{"numero":"2722","intitule":"Prêts mobiliers et d\'installation"},{"numero":"2728","intitule":"Autres prêts (frais d\'études)"},{"numero":"273","intitule":"CREANCES SUR L\'ETAT"},{"numero":"2731","intitule":"Retenues de garantie"},{"numero":"2733","intitule":"Fonds réglementé"},{"numero":"2734","intitule":"Créances sur le concédant"},{"numero":"2738","intitule":"Autres"},{"numero":"274","intitule":"TITRES IMMOBILISES"},{"numero":"2741","intitule":"Titres immobilisés de l\'activité de portefeuille (T.I.A.P.)"},{"numero":"2742","intitule":"Titres participatifs"},{"numero":"2743","intitule":"Certificats d\'investissement"},{"numero":"2744","intitule":"Parts de fonds commun de placement (F.C.P.)"},{"numero":"2745","intitule":"Obligations"},{"numero":"2746","intitule":"Actions ou parts propres"},{"numero":"2748","intitule":"Autres titres immobilisés"},{"numero":"275","intitule":"DEPÔTS ET CAUTIONNEMENTS VERSES"},{"numero":"2751","intitule":"Dépôts pour loyers d\'avance"},{"numero":"2752","intitule":"Dépôts pour l\'électricité"},{"numero":"2753","intitule":"Dépôts pour l\'eau"},{"numero":"2754","intitule":"Dépôts pour le gaz"},{"numero":"2755","intitule":"Dépôts pour le téléphone, le télex, la télécopie"},{"numero":"2756","intitule":"Cautionnements sur marchés publics"},{"numero":"2757","intitule":"Cautionnements sur autres opérations"},{"numero":"2758","intitule":"Autres dépôts et cautionnements"},{"numero":"276","intitule":"INTERÊTS COURUS"},{"numero":"2761","intitule":"Prêts et créances non commerciales"},{"numero":"2762","intitule":"Prêts au personnel"},{"numero":"2763","intitule":"Créances sur l\'Etat"},{"numero":"2764","intitule":"Titres immobilisés"},{"numero":"2765","intitule":"Dépôts et cautionnements versés"},{"numero":"2766","intitule":"Créances de location financement"},{"numero":"2767","intitule":"Créances rattachées à des participations"},{"numero":"2768","intitule":"Immobilisations financières diverses"},{"numero":"277","intitule":"CREANCES RATTACHEES A DES PARTICIPATIONS ET AVANCES A DES G.I.E."},{"numero":"2771","intitule":"Créances rattachées à des participations (groupe)"},{"numero":"2772","intitule":"Créances rattachées à des participations (hors groupe)"},{"numero":"2773","intitule":"Créances rattachées à des sociétés en participation"},{"numero":"2774","intitule":"Avances à des groupements d\'intérêt économique (G.I.E.)"},{"numero":"278","intitule":"IMMOBILISATIONS FINANCIERES DIVERSES"},{"numero":"2781","intitule":"Créances diverses groupe"},{"numero":"2782","intitule":"Créances diverses hors groupe"},{"numero":"2784","intitule":"Banques dépôt à terme"},{"numero":"2785","intitule":"Or et métaux précieux (1)"}],"fonctionnement":"Le compte 27 – AUTRES IMMOBILISATIONS FINANCIERES est débité de la valeur\\nd\'apport ou d\'acquisition des titres, du montant des prêts accordés, des créances\\nnées ou des dépôts et cautionnements versés et de la partie non libérée des titres\\nimmobilisés\\n- par le crédit des comptes de tiers et des comptes de trésorerie concernés ;\\n- par le crédit du compte 4813 – Versements restant à effectuer sur titres de\\nparticipation et titres immobilisés non libérés.\\nLe compte 27 – AUTRES IMMOBILISATIONS FINANCIERES est crédité lors du\\nrèglement ou en cas de cession de titres\\n- par le débit des comptes de trésorerie ou de tiers intéressés.","commentaires":"Les prêts sont ceux qui répondent aux conditions juridiques en matière de contrat.\\nLes billets de fonds à recevoir sont assimilés aux prêts.\\nLes titres immobilisés (voir titre VIII Opérations spécifiques, Chapitre 13) sont des\\ntitres autres que des titres de participation que l\'entité a l\'intention de conserver\\ndurablement. Ils sont représentatifs de placements à long terme.\\nEn cas de libération partielle, la part non libérée des titres constitue une dette\\ninscrite au compte 4813 – Versements restant à effectuer sur titres de participation\\net titres immobilisés non libérés et devra faire l\'objet d\'information dans les Notes\\nannexes. Les frais accessoires d\'achat de titres (impôts, courtages, commissions,\\nhonoraires) sont inclus dans le prix d\'achat des titres.\\nLes dépôts sont des sommes versées à certains fournisseurs (gaz, eau, électricité) ou\\nprestataires de services (téléphone, bailleur) pour leur garantir le paiement des\\nredevances ou des loyers.\\nLes cautionnements sont les sommes déposées en vue de garantir la bonne fin de\\n- l\'exécution d\'un marché ou d\'une opération.\\nElles sont remboursées lors du dénouement du marché ou de l\'opération.\\nLes créances rattachées à des participations sont des prêts ou des avances consentis\\nà une société qui est une participation de l\'entité.\\nLes prêts et créances ne sont pas distingués en fonction du terme d\'exigibilité de\\nleur remboursement. Toutefois, lorsque le délai d\'exigibilité est inférieur ou égal à\\nun an, à la clôture de l\'exercice, la partie ainsi devenue exigible est isolée afin d\'être\\nportée distinctement dans le tableau d\'échéances des créances et des dettes. De\\nmême, les prêts et créances devront être distingués selon le terme à un an au plus, à\\ndeux ans au plus, et à plus de deux ans.\\nLes prêts assortis d\'une garantie font l\'objet d\'une mention dans les Notes annexes\\n(nantissement, hypothèque, dépôt de titres, caution bancaire, gages divers).","exclusions":"Le compte 27 – AUTRES IMMOBILISATIONS FINANCIERES ne doit pas servir à\\nenregistrer :\\n- les titres de participation\\n- les titres de placement\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n26 – Titres de participation\\n50 – Titres de placement","controle":"Le compte 27 – AUTRES IMMOBILISATIONS FINANCIERES peut être contrôlé à\\npartir des recoupements provenant des :\\ncontrats de prêts, reçus des dépôts et cautionnement ;\\nsouscriptions de titres, certificats de propriété de titres ;\\nreconnaissances de dettes de la part de tiers, virements bancaires et\\nmouvements financiers.","motsCles":["immobilisations","financieres"]},{"numero":"28","intitule":"Amortissements","classe":2,"classeLabel":"Comptes d\'actif immobilisé","groupe":"A","contenu":"L\'amortissement consiste pour l\'entité à répartir le montant amortissable du bien\\nsur sa durée d\'utilité selon un plan prédéfini.\\nLe montant du bien amortissable s\'entend de la différence entre le coût d\'entrée\\nd\'un actif et sa valeur résiduelle prévisionnelle.\\nLa valeur résiduelle d\'un actif est le montant estimé qu\'une entité obtiendrait\\nactuellement de la sortie de l\'actif, après déduction des coûts de sortie estimés, si\\n- l\'actif avait déjà l\'âge et se trouvait déjà dans l\'état prévu à la fin de sa durée\\nd\'utilité.\\nDifférents modes d\'amortissement peuvent être utilisés pour répartir de façon\\nsystématique le montant amortissable d\'un actif sur sa durée d\'utilité. Ces modes\\nincluent :\\n- le mode linéaire ;\\n- le mode dégressif ;\\n- le mode des unités de production ;\\net tout autre mode mieux adapté.\\nUn mode d\'amortissement basé sur les revenus générés par l\'utilisation de l\'actif est\\ninterdit pour les immobilisations corporelles.\\nLe mode d\'amortissement retenu est appliqué de manière cohérente d\'une période\\nà l\'autre, sauf en cas de changement du rythme attendu de consommation de l\'actif.\\nLa date de début d\'amortissement est la date à laquelle l\'actif immobilisé est en\\n- l\'état et en lieu d\'utilisation prévue par l\'entité.","subdivisions":[{"numero":"281","intitule":"AMORTISSEMENTS DES IMMOBILISATIONS INCORPORELLES"},{"numero":"2811","intitule":"Amortissements des frais de développement"},{"numero":"2812","intitule":"Amortissements des brevets, licences, concessions et droits similaires"},{"numero":"2813","intitule":"Amortissements des logiciels et sites internet"},{"numero":"2814","intitule":"Amortissements des marques"},{"numero":"2815","intitule":"Amortissements du fonds commercial"},{"numero":"2816","intitule":"Amortissements du droit au bail"},{"numero":"2817","intitule":"Amortissements des investissements de création"},{"numero":"2818","intitule":"Amortissements des autres droits et valeurs incorporels"},{"numero":"282","intitule":"AMORTISSEMENTS DES TERRAINS"},{"numero":"2821","intitule":"Amortissements des terrains agricoles et forestiers"},{"numero":"2824","intitule":"Amortissements des travaux de mise en valeur des terrains"},{"numero":"2825","intitule":"Amortissements des terrains de gisement"},{"numero":"283","intitule":"AMORTISSEMENTS DES BÂTIMENTS, INSTALLATIONS TECHNIQUES ET AGENCEMENTS"},{"numero":"2831","intitule":"Amortissements des bâtiments industriels, agricoles, administratifs et commerciaux"},{"numero":"2832","intitule":"Amortissements des bâtiments industriels, agricoles, administratifs et commerciaux"},{"numero":"2833","intitule":"Amortissements des ouvrages d\'infrastructure"},{"numero":"2834","intitule":"Amortissements des aménagements, agencements et installations techniques"},{"numero":"2835","intitule":"Amortissements des aménagements de bureaux"},{"numero":"2837","intitule":"Amortissements des bâtiments industriels, agricoles et commerciaux mis en concession"},{"numero":"2838","intitule":"Amortissements des autres installations et agencements"},{"numero":"284","intitule":"AMORTISSEMENTS DU MATERIEL"},{"numero":"2841","intitule":"Amortissements du matériel et outillage industriel et commercial"},{"numero":"2842","intitule":"Amortissements du matériel et outillage agricole"},{"numero":"2843","intitule":"Amortissements du matériel d\'emballage récupérable et identifiable"},{"numero":"2844","intitule":"Amortissements du matériel et mobilier"},{"numero":"2845","intitule":"Amortissements du matériel de transport"},{"numero":"2846","intitule":"Amortissements des actifs biologiques"},{"numero":"2847","intitule":"Amortissements des agencements et aménagements du matériel et des actifs"},{"numero":"2848","intitule":"Amortissements des autres matériels"}],"fonctionnement":"Le compte 28 – AMORTISSEMENTS est crédité, en fin d\'exercice de l\'annuité\\nd\'amortissement ou en cas de cession de la dotation complémentaire aux\\namortissements\\n- par le débit du compte 681 – Dotations aux amortissements d\'exploitation ;\\n- ou par le débit du compte 85 – Dotations H.A.O.\\nLe compte 28 – AMORTISSEMENTS est débité, en cas de cession d\'immobilisation,\\nde l\'annulation des amortissements relatifs à l\'immobilisation cédée\\n- par le crédit du compte d\'immobilisation concerné (classe 2).\\nLe compte 28 – AMORTISSEMENTS est débité de la reprise des amortissements\\n- par le crédit du compte 798 – Reprises d\'amortissements, en cas de révision\\ndu plan d\'amortissement ;\\n- ou par le crédit du compte 862 – Reprises d\'amortissements H.A.O.","commentaires":"L\'amortissement est en principe calculé selon les usages de la profession, de façon à\\namortir chaque catégorie d\'immobilisations sur la durée normale d\'utilisation\\nprévue. Toutefois, les annuités d\'amortissement peuvent être adaptées aux\\nconditions d\'exploitation (calcul sur la base d\'unités de mesure de l\'utilisation :\\ntonnage, cubage, heures de fonctionnement, etc.).\\nLes annuités d\'amortissement peuvent être modifiées si les perspectives d\'avenir\\njustifient une telle mesure. Dans ce cas, la correction effectuée sur les taux\\nd\'amortissement doit être révélée et quantifiée, de même que les raisons de cette\\nmodification. En revanche, si des prévisions devaient conduire à des prix plus\\nélevés que les premières estimations, aucune correction ne devrait être pratiquée.\\nSi la durée d\'utilité du bien dans l\'entité devait être nettement inférieure à sa durée\\nprobable de vie, il doit être tenu compte d\'une valeur résiduelle raisonnablement\\nappréciée au moment de l\'établissement du plan d\'amortissement. Dans le cas\\nd\'espèce, le calcul de l\'amortissement doit être effectué sur la différence entre la\\nvaleur d\'entrée et la valeur résiduelle, déduction faite des frais estimés de la\\nrevente.\\nPour fixer le taux d\'amortissement, il est tenu compte de l\'usure correspondant aux\\nconditions d\'utilisation prévisibles, notamment :\\ndu travail en fonction du nombre d\'équipes tournantes (double ou triple\\néquipes) ;\\nde la désuétude potentielle due aux changements technologiques, c\'est-à- dire,\\ndes circonstances qui peuvent rendre prématurément caduques certaines\\nimmobilisations ;\\nde l\'obsolescence potentielle due aux variations de la demande affectant les\\narticles produits ou les services fournis par l\'utilisation.\\nLes amortissements doivent être pratiqués à la clôture de chaque exercice, même\\nen cas d\'absence ou d\'insuffisance de bénéfice","exclusions":"","controle":"Le compte 28 – AMORTISSEMENTS peut être contrôlé à partir des recoupements\\nprovenant des tableaux d\'amortissement.","motsCles":["amortissements"]},{"numero":"29","intitule":"Dépréciations","classe":2,"classeLabel":"Comptes d\'actif immobilisé","groupe":"A","contenu":"A la clôture de chaque exercice une entité doit apprécier, s\'il existe un quelconque\\nindice qu\'un actif a subi une perte de valeur. S\'il existe un tel indice, l\'entité doit\\nestimer la valeur actuelle et la comparer avec la valeur nette comptable.\\nL\'actif doit être déprécié lorsque la valeur nette comptable est supérieure à la\\nvaleur actuelle.\\nPour évaluer s\'il existe un indice quelconque de dépréciation d\'actif, une entité doit\\ntenir compte, au minimum, des indications suivantes :\\nSources externes :\\ndurant l\'exercice, la valeur de marché d\'un actif a diminué de façon plus\\nimportante que du seul effet attendu du passage du temps ou de l\'utilisation\\nnormale de l\'actif;\\nd\'importants changements, ayant un effet négatif sur l\'entité, sont survenus au\\ncours de l\'exercice ou surviendront dans un proche avenir, dans\\n- l\'environnement technologique, économique ou juridique ou du marché dans\\nlequel l\'entité opère ou dans le marché auquel l\'actif est dévolu ;\\n- les taux d\'intérêt du marché ou d\'autres taux de rendement du marché ont\\naugmenté durant l\'exercice et il est probable que ces augmentations affecteront\\n- le taux d\'actualisation utilisé dans le calcul de la valeur d\'utilité d\'un actif et\\ndiminueront de façon significative la valeur actuelle de l\'actif;\\nla valeur comptable de l\'actif net de l\'entité est supérieure à sa\\ncapitalisation boursière;\\nSources internes :\\nil existe un indice d\'obsolescence ou de dégradation physique d\'un actif;\\ndes changements importants, ayant un effet négatif sur l\'entité, sont survenus au\\ncours de l\'exercice ou sont susceptibles de survenir dans un proche avenir, dans\\n- le degré ou le mode d\'utilisation d\'un actif tel qu\'il est utilisé ou que l\'on s\'attend\\nà l\'utiliser. Ces changements incluent la mise hors service de l\'actif, les plans\\nd\'abandon ou de restructuration du secteur d\'activité auquel un actif appartient\\net les plans de sortie d\'un actif avant la date antérieurement prévue, et la\\nréestimation de la durée d\'utilité d\'un actif comme déterminée plutôt\\nqu\'indéterminée;\\nun élément probant provenant du système d\'information interne montre que la\\nperformance économique d\'un actif est ou sera moins bonne que celle attendue.\\nLes dépréciations sont inscrites distinctement à l\'actif, en diminution de la valeur\\nbrute des biens correspondants pour donner leur valeur comptable nette (V.C.N.).\\nMême en cas d\'absence ou d\'insuffisance de bénéfice au cours de l\'exercice, il doit\\nêtre procédé aux dotations nécessaires pour couvrir les dépréciations.","subdivisions":[{"numero":"291","intitule":"DEPRECIATIONS DES IMMOBILISATIONS NCORPORELLES"},{"numero":"2911","intitule":"Dépréciations des frais de développement"},{"numero":"2912","intitule":"Dépréciations des brevets, licences, marques concessions et droits similaires"},{"numero":"2913","intitule":"Dépréciations des logiciels et sites internet"},{"numero":"2914","intitule":"Dépréciations des marques"},{"numero":"2915","intitule":"Dépréciations du fonds commercial"},{"numero":"2916","intitule":"Dépréciations du droit au bail"},{"numero":"2917","intitule":"Dépréciations des investissements de création"},{"numero":"2918","intitule":"Dépréciations des autres droits et valeurs incorporels"},{"numero":"2919","intitule":"Dépréciations des immobilisations incorporelles en cours"},{"numero":"292","intitule":"DEPRECIATIONS DES TERRAINS"},{"numero":"2921","intitule":"Dépréciations des terrains agricoles et forestiers"},{"numero":"2922","intitule":"Dépréciations des terrains nus"},{"numero":"2923","intitule":"Dépréciations des terrains bâtis"},{"numero":"2924","intitule":"Dépréciations des travaux de mise en valeur des terrains"},{"numero":"2925","intitule":"Dépréciations des terrains de gisement"},{"numero":"2926","intitule":"Dépréciations des terrains aménagés"},{"numero":"2927","intitule":"Dépréciations des terrains mis en concession"},{"numero":"2928","intitule":"Dépréciations des autres terrains"},{"numero":"2929","intitule":"Dépréciations des aménagements de terrains en cours"},{"numero":"293","intitule":"DEPRECIATIONS DES BÂTIMENTS, INSTALLATIONS TECHNIQUES ET AGENCEMENTS"},{"numero":"2931","intitule":"Dépréciations des bâtiments industriels, agricoles, administratifs et commerciaux"},{"numero":"2932","intitule":"Dépréciations des bâtiments industriels, agricoles, administratifs et commerciaux"},{"numero":"2933","intitule":"Dépréciations des ouvrages d\'infrastructures"},{"numero":"2934","intitule":"Dépréciations des aménagements, agencements et installations techniques"},{"numero":"2935","intitule":"Dépréciations des aménagements de bureaux"},{"numero":"2937","intitule":"Dépréciations des bâtiments industriels, agricoles et commerciaux mis en concession"},{"numero":"2938","intitule":"Dépréciations des autres installations et agencements"},{"numero":"2939","intitule":"Dépréciations des bâtiments et installations en cours"},{"numero":"294","intitule":"DEPRECIATIONS DU MATERIEL, DU MOBILIER ET DE L\'ACTIF BIOLOGIQUE"},{"numero":"2941","intitule":"Dépréciations du matériel et outillage industriel et commercial"},{"numero":"2942","intitule":"Dépréciations du matériel et outillage agricole"},{"numero":"2943","intitule":"Dépréciations du matériel d\'emballage récupérable et identifiable"},{"numero":"2944","intitule":"Dépréciations du matériel et mobilier"},{"numero":"2945","intitule":"Dépréciations du matériel de transport"},{"numero":"2946","intitule":"Dépréciations des actifs biologiques"},{"numero":"2947","intitule":"Dépréciations des agencements et aménagements du matériel et des actifs"},{"numero":"2948","intitule":"Dépréciations des autres matériels"},{"numero":"2949","intitule":"Dépréciations du matériel en cours"},{"numero":"295","intitule":"DEPRECIATIONS DES AVANCES ET ACOMPTES VERSES SUR IMMOBILISATIONS"},{"numero":"2951","intitule":"Dépréciations des avances et acomptes versés sur immobilisations incorporelles"},{"numero":"2952","intitule":"Dépréciations des avances et acomptes versés sur immobilisations corporelles"},{"numero":"296","intitule":"DEPRECIATIONS DES TITRES DE PARTICIPATION"},{"numero":"2961","intitule":"Dépréciations des titres de participation dans des sociétés sous contrôle exclusif"},{"numero":"2962","intitule":"Dépréciations des titres de participation dans les sociétés sous contrôle conjoint"},{"numero":"2963","intitule":"Dépréciations des titres de participation dans les sociétés conférant une influence"},{"numero":"2965","intitule":"Dépréciations des participations dans des organismes professionnels"},{"numero":"2966","intitule":"Dépréciations des parts dans des G.I.E."},{"numero":"2968","intitule":"Dépréciations des autres titres de participation"},{"numero":"297","intitule":"DEPRECIATIONS DES AUTRES IMMOBILISATIONS FINANCIERES"},{"numero":"2971","intitule":"Dépréciations des prêts et créances"},{"numero":"2972","intitule":"Dépréciations des prêts au personnel"},{"numero":"2973","intitule":"Dépréciations des créances sur l\'Etat"},{"numero":"2974","intitule":"Dépréciations des titres immobilisés"},{"numero":"2975","intitule":"Dépréciations des dépôts et cautionnements versés"},{"numero":"2977","intitule":"Dépréciations des créances rattachées à des participations et avances à des G.I.E."},{"numero":"2978","intitule":"Dépréciations des créances financières diverses"}],"fonctionnement":"Le compte 29 – DÉPRÉCIATIONS est crédité de la dotation aux provisions\\n- par le débit du compte 691 – Dotations aux dépréciations d\'exploitation ;\\n- ou par le débit du compte 697 – Dotations aux dépréciations financières ;\\n- ou par le débit du compte 853 – Dotations aux dépréciations\\nH.A.O.\\nLe compte 29 – DÉPRÉCIATIONS est débité de la reprise de provision\\n- par le crédit du compte 791 – Reprises de provisions et de dépréciations\\nd\'exploitation ;\\n- par le crédit du compte 797 – Reprises de provisions et de dépréciations\\nfinancières ;\\n- ou par le crédit du compte 863 – Reprises de dépréciations\\nH.A.O.","commentaires":"L\'actif doit être déprécié lorsque sa valeur nette comptable est supérieure à sa\\nvaleur actuelle. Cette dépréciation est constatée par une dotation aux dépréciations\\n(voir Titre VIII Opérations spécifiques, Chapitre 12).\\nElles peuvent également concerner les dépréciations exceptionnelles subies par les\\nimmobilisations amortissables, lorsque ces dépréciations ne peuvent\\nraisonnablement être inscrites aux comptes d\'amortissement, en raison de leur\\ncaractère définitif.\\nA la différence des provisions pour pertes et charges, elles expriment des\\ncorrections d\'actif de sens négatif.\\nLes dépréciations dépendent des conditions d\'exploitation de chaque entité ou de\\ncirconstances économiques particulières.\\nEn ce qui concerne les titres, la dépréciation est déterminée à la fin de chaque\\npériode, conformément aux règles suivantes :\\n- les titres cotés sont évalués au cours moyen boursier du dernier mois ;\\n- les titres non cotés sont estimés à leur valeur probable de négociation.\\nLes plus-values apparaissant à la suite de cette estimation ne sont pas\\ncomptabilisées. En revanche, les moins- values sont inscrites au compte de\\ndépréciation. La dépréciation fait donc apparaître, à la clôture de chaque exercice,\\nla totalité des moins-values constatées à cette date sur les titres en baisse, aucune\\ncompensation n\'étant établie avec les plus-values des titres en hausse.\\nUne dépréciation supplémentaire peut être constituée lorsqu\'il s\'est produit un\\névénement d\'une importance exceptionnelle qui la justifie (cas de faillite, par\\nexemple).\\nLa dépréciation éventuelle doit en outre être calculée sur la base de la valeur\\nlibérée des titres.\\nLes dépréciations doivent être pratiquées à la clôture de l\'exercice, même en\\n- l\'absence de bénéfice, aussi bien sur les immobilisations acquises que sur celles en\\ncours de fabrication.","exclusions":"Le compte 29 – DÉPRÉCIATIONS ne doit pas servir à enregistrer :\\n- les dépréciations des comptes de stocks\\n- les dépréciations des comptes de tiers\\n- les dépréciations des comptes de trésorerie\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n39 – Dépréciations des stocks\\n49 – Dépréciations et provisions pour risques à court terme (Tiers)\\n59 – Dépréciations et provisions pour risques à court terme (Trésorerie)","controle":"Le compte 29 – DÉPRÉCIATIONS peut être contrôlé à partir :\\ndes rapprochements effectués entre la valeur d\'entrée des actifs dans le\\npatrimoine de l\'entité et la valeur à la date de clôture de l\'exercice ;\\nde factures ;\\nde l\'argus ;\\ndu livre d\'inventaire.\\n\\n# CLASSE 3 : COMPTES DE STOCKS\\nLes stocks ( voir titre VIII opérations spécifiques, chapitre 14) sont des actifs:\\ndétenus en vue de la vente dans le cours normal de l\'activité :\\nmarchandises et produits finis;\\nen cours de production pour une telle vente : produits en cours ou\\nintermédiaires; ou\\nsous forme de matières premières ou de fournitures devant être\\nconsommées dans le processus de production ou de prestation de services.\\nLes comptes de stocks peuvent être assortis de comptes de dépréciation.\\nLa comptabilisation des stocks repose sur la tenue soit d\'un inventaire permanent,\\nsoit d\'un inventaire intermittent.\\nToutefois, les entités qui n\'ont pas les moyens de tenir l\'inventaire permanent\\npeuvent recourir au système de l\'inventaire intermittent. Dans ce cas, en fin de\\npériode, elles doivent passer les écritures faisant apparaître les variations de stocks\\nde cette période, pour retrouver le schéma comptable demandé.\\nL\'inventaire physique est un inventaire extra-comptable c\'est-à-dire un récolement\\nmatériel des existants effectué au moins une fois pendant l\'exercice. Il comporte\\ndeux opérations :\\n- l\'établissement de la liste complète des divers éléments composant les stocks par\\ngroupe de marchandises, matières et produits correspondant à la classification\\ndes comptes ;\\n- l\'évaluation des existants réels constatés par l\'opération précédente.\\nL\'inventaire comptable permanent permet à l\'entité de connaître à chaque instant :\\n- le montant de ses stocks ;\\n- le coût d\'achat des marchandises vendues ;\\n- le coût d\'achat des matières et fournitures engagées dans le processus de\\nfabrication.\\nL\'inventaire intermittent ne permet de connaître le montant des existants qu\'à la\\nclôture de l\'exercice, au moment de l\'inventaire extra-comptable.\\nLe coût des stocks doit comprendre tous les coûts d\'acquisition, coûts de\\ntransformation et autres coûts engagés pour amener les stocks à l\'endroit et dans\\n- l\'état où ils se trouvent.\\nLes coûts d\'acquisition des stocks comprennent le prix d\'achat, les droits de douane\\net autres taxes non récupérables par l\'entité auprès des administrations fiscales),\\nainsi que les frais de transport, de manutention et autres coûts directement\\nattribuables à l\'acquisition des produits finis, des matières premières et des\\nservices. Les rabais commerciaux, remises et autres éléments similaires sont\\ndéduits pour déterminer les coûts d\'acquisition.\\nLes coûts de transformation des stocks comprennent les coûts directement liés aux\\nunités produites, tels que la main-d\'œuvre directe. Ils comprennent également\\n- l\'affectation systématique des frais généraux de production fixes et variables qui\\nsont encourus pour transformer les matières premières en produits finis. Les frais\\ngénéraux de production fixes sont les coûts indirects de production qui demeurent\\nrelativement constants indépendamment du volume de production, tels que\\n- l\'amortissement et l\'entretien des bâtiments et de l\'équipement industriels, et les\\nfrais de gestion et d\'administration de l\'usine. Les frais généraux de production\\nvariables sont les coûts indirects de production qui varient directement, ou presque\\ndirectement, en fonction du volume de production, tels que les matières premières\\nindirectes et la main-d\'œuvre indirecte.\\nLes autres coûts ne sont inclus dans le coût des stocks que dans la mesure où ils\\nsont encourus pour amener les stocks à l\'endroit et dans l\'état où ils se trouvent. Par\\nexemple, il peut être approprié d\'inclure dans le coût des stocks des frais généraux\\nautres que ceux de production ou les coûts de conception de produits à l\'usage de\\nclients spécifiques.\\nLes prestataires de services évaluent leur stock au coût de production. Ces coûts se\\ncomposent essentiellement de la main- d\'œuvre et des autres frais de personnel\\ndirectement engagés pour fournir le service, y compris le personnel d\'encadrement,\\net les frais généraux attribuables. La main-d\'œuvre et les autres coûts relatifs aux\\nventes et au personnel administratif général ne sont pas inclus mais sont\\ncomptabilisés en charges de la période au cours de laquelle ils sont encourus. Le\\ncoût des stocks d\'un prestataire de services ne comprend pas les marges\\nbénéficiaires ou les frais généraux non attribuables qui sont souvent incorporés\\ndans les prix facturés par les prestataires de services.\\nLes stocks comprenant la production agricole, récoltés par une entité à partir de ses\\nactifs biologiques, sont évalués lors de la comptabilisation initiale à la valeur\\nactuelle, moins les coûts des points de vente estimés au moment de la récolte (voir\\ntitre VIII Opérations spécifiques, Chapitre 37).\\nLes techniques d\'évaluation du coût des stocks, telles que la méthode du coût\\nstandard ou la méthode du prix de détail, peuvent être utilisées pour des raisons\\npratiques si ces méthodes donnent des résultats proches du coût.\\nLes coûts standard retiennent les niveaux normaux d\'utilisation de matières\\npremières et de fournitures, de main- d\'œuvre, d\'efficience et de capacité. Ils sont\\nrégulièrement réexaminés et, le cas échéant, révisés à la lumière des conditions\\nactuelles.\\nLa méthode du prix de détail est souvent utilisée dans l\'activité de la distribution au\\ndétail pour évaluer les stocks de grandes quantités d\'articles à rotation rapide, qui\\nont des marges similaires et pour lesquels il n\'est pas possible d\'utiliser d\'autres\\nméthodes de coûts. Le coût des stocks est déterminé en déduisant de la valeur de\\nvente des stocks le pourcentage de marge brute approprié. Le pourcentage utilisé\\nprend en considération les stocks qui ont été démarqués au-dessous de leur prix de\\nvente initial. Un pourcentage moyen pour chaque rayon est souvent utilisé.\\nA la sortie de magasin ou à l\'inventaire, les stocks sont ainsi évalués :\\n- les biens matériellement identifiés et individualisés ainsi que ceux qui ne sont\\npas interchangeables, sont évalués article par article à leur coût d\'entrée ;\\n- les biens interchangeables (fongibles), non identifiables après leur entrée en\\nmagasin sont évalués soit selon la technique du coût moyen pondéré (C.M.P.),\\nsoit selon la méthode du premier entré premier sorti (P.E.P.S.).\\nA la clôture de l\'exercice les stocks doivent être évalués au plus faible de la valeur\\nnette comptable et de la valeur nette de réalisation.\\nLa valeur nette de réalisation est le prix de vente estimé dans le cours normal de\\n- l\'activité, diminué des coûts estimés pour l\'achèvement et des coûts estimés\\nnécessaires pour réaliser la vente.\\nLes estimations de la valeur nette de réalisation sont fondées sur les éléments\\nprobants les plus fiables disponibles à la date à laquelle elles sont faites, du\\nmontant que l\'on s\'attend à réaliser des stocks. Ces estimations tiennent compte des\\nfluctuations de prix ou de coût directement liées aux événements survenant après\\nla fin de la période, dans la mesure où de tels événements confirment les conditions\\nexistant à la fin de la période.\\nLe stock doit être déprécié si la valeur nette comptable est supérieure à la valeur\\nnette de réalisation, élément par élément.\\nDans certains cas, il peut être approprié de regrouper des éléments similaires ou\\nayant des rapports entre eux.","motsCles":["depreciations"]},{"numero":"31","intitule":"Marchandises","classe":3,"classeLabel":"Comptes de stocks","groupe":"A","contenu":"Les marchandises sont les objets, matières et fournitures, acquis par l\'entité et\\ndestinés à être revendus en l\'état.","subdivisions":[{"numero":"311","intitule":"MARCHANDISES A"},{"numero":"3111","intitule":"Marchandises A1"},{"numero":"3112","intitule":"Marchandises A2"},{"numero":"312","intitule":"MARCHANDISES B"},{"numero":"3121","intitule":"Marchandises B1"},{"numero":"3122","intitule":"Marchandises B2"},{"numero":"318","intitule":"MARCHANDISES HORS ACTIVITES ORDINAIRES (H.A.O.)"}],"fonctionnement":"En cas d\'inventaire intermittent, à la clôture de l\'exercice :\\nLe compte 31 – MARCHANDISES est débité du montant du stock final (1), déterminé\\npar inventaire extra-comptable et évalué conformément aux règles précisées dans\\n- l\'évaluation des stocks : les biens matériellement identifiés et individualisés au coût\\nd\'entrée ; les biens interchangeables non identifiables suivant la (méthode P.E.P.S.\\nou du coût moyen pondéré)\\n- par le crédit du compte 6031 – Variations des stocks de marchandises.\\nLe compte 31 – MARCHANDISES est crédité du montant du stock initial (2), pour\\nsolde\\n(1) ou du montant de l\'augmentation de l\'exercice (stock final moins stock initial)\\n(2) ou du montant de la diminution de l\'exercice (stock initial moins stock final)\\n- par le débit du compte 6031 – Variations des stocks de marchandises\\nEn cas d\'inventaire permanent :\\nLe compte 31 – MARCHANDISES est débité, à chaque entrée en stock, du coût des\\nmarchandises achetées (prix d\'achat et frais accessoires d\'achat)\\n- par le crédit du compte 6031 – Variations des stocks de marchandises.\\nLe compte 31 – MARCHANDISES est débité en fin d\'exercice, après inventaire\\nphysique, pour régularisation du stock des marchandises, des différences\\nconstatées en plus, par rapport à l\'inventaire permanent\\n- par le crédit du compte 6031 – Variations des stocks de marchandises.\\nLe compte 31 – MARCHANDISES est crédité, à chaque sortie de stock, les biens\\nmatériellement identifiés et individualisés au coût d\'entrée ; les biens\\ninterchangeables non identifiables suivant la méthode du premier entré, premier\\nsorti (P.E.P.S.) ou du coût moyen pondéré (C.M.P.)\\n- par le débit du compte 6031 – Variations des stocks de marchandises.\\nLe compte 31 – MARCHANDISES est crédité à la clôture de l\'exercice, après\\ninventaire physique, pour régularisation du stock des marchandises, des\\ndifférences constatées en moins, par rapport à l\'inventaire permanent\\n- par le débit du compte 6031 – Variations des stocks de marchandises.","commentaires":"Le compte 31 est subdivisé selon les besoins de l\'entité.\\nLes marchandises hors activités ordinaires (H.A.O.) ne seront distinguées que si\\nleur montant est supérieur à 5 % du total de l\'actif circulant.","exclusions":"Le compte 31 – MARCHANDISES ne doit pas servir à enregistrer :\\n- les achats de matières premières et fournitures non destinées à être revendues\\nen l\'état\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n32 – Matières premières et fournitures liées","controle":"Le compte 31 – MARCHANDISES peut être contrôlé à partir de l\'inventaire extra-\\ncomptable et des factures (achats et frais).","motsCles":["marchandises"]},{"numero":"32","intitule":"Matières premières et fournitures liées","classe":3,"classeLabel":"Comptes de stocks","groupe":"A","contenu":"Les matières premières et fournitures liées sont les objets, matières et fournitures\\nachetés pour être incorporés aux produits fabriqués.","subdivisions":[{"numero":"321","intitule":"MATIERES A"},{"numero":"322","intitule":"MATIERES B"},{"numero":"323","intitule":"FOURNITURES (A, B)"}],"fonctionnement":"En cas d\'inventaire intermittent, à la clôture de l\'exercice :\\nLe compte 32 – MATIERES PREMIERES ET FOURNITURES LIEES FOURNITURES\\nLIEES est débité du montant du stock final(1), déterminé par inventaire extra-\\ncomptable et évalué conformément aux règles précisées dans l\'évaluation des\\nstocks : les biens matériellement identifiés et individualisés au coût d\'entrée ; les\\nbiens interchangeables non identifiables suivant la (méthode P.E.P.S. ou du coût\\nmoyen pondéré),\\n- par le crédit du compte 6032 – Variations des stocks de matières premières\\net fournitures liées.\\nLe compte 32 – MATIERES PREMIERES ET FOURNITURES LIEES est crédité du\\nmontant du stock initial(2), pour solde\\n(1) ou du montant de l\'augmentation de l\'exercice (stock final moins stock initial)\\n(2) ou du montant de la diminution de l\'exercice (stock initial moins stock final)\\n- par le débit du compte 6032 – Variations des stocks de matières premières\\net fournitures liées.\\nEn cas d\'inventaire permanent :\\nLe compte 32 – MATIERES PREMIERES ET FOURNITURES LIEES est débité, à chaque\\nentrée en stock, du coût des matières et fournitures achetées (prix d\'achat et frais\\naccessoires d\'achat)\\n- par le crédit du compte 6032 – Variations des stocks de matières premières\\net fournitures liées\\nLe compte 32 – MATIERES PREMIERES ET FOURNITURES LIEES est débité, à la\\nclôture de l\'exercice, après inventaire physique, pour régularisation du stock des\\nmatières premières et fournitures liées, des différences constatées en plus, par\\nrapport à l\'inventaire permanent\\n- par le crédit du compte 6032 – Variations des stocks de matières premières\\net fournitures liées.\\nLe compte 32 – MATIERES PREMIERES ET FOURNITURES LIEES est crédité à chaque\\nsortie de stock, les biens matériellement identifiés et individualisés au coût d\'entrée\\n; les biens interchangeables non identifiables suivant la méthode du premier entré,\\npremier sorti (P.E.P.S.) ou du coût moyen pondéré\\n- par le débit du compte 6032 – Variations des stocks de matières premières\\net fournitures liées.\\nLe compte 32 – MATIERES PREMIERES ET FOURNITURES LIEES est crédité, à la\\nclôture de l\'exercice, après inventaire physique, pour régularisation du stock des\\nmatières premières et fournitures liées, des différences constatées en moins, par\\nrapport à l\'inventaire permanent\\n- par le débit du compte 6032 – Variations des stocks de matières premières\\net fournitures liées.","commentaires":"Les matières dites consommables ne font pas partie des fournitures liées et sont\\nclassées dans le compte 33 – Autres approvisionnements.","exclusions":"Le compte 32 – MATIERES PREMIERES ET FOURNITURES LIEES ne doit pas servir à\\nenregistrer :\\n- le matériel de remplacement ou de réserve qui n\'est pas encore en service\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n24 – Matériel, mobilier et actifs biologiques","controle":"Le compte 32 – MATIERES PREMIERES ET FOURNITURES LIEES peut être contrôlé à\\npartir de l\'inventaire extra-comptable et des factures (achats et frais).","motsCles":["matieres","premieres","fournitures","liees"]},{"numero":"33","intitule":"Autres approvisionnements","classe":3,"classeLabel":"Comptes de stocks","groupe":"A","contenu":"Les autres approvisionnements sont des matières, des fournitures acquises par\\n- l\'entité et qui concourent à la fabrication ou à l\'exploitation, sans entrer dans la\\ncomposition des produits fabriqués ou traités.","subdivisions":[{"numero":"331","intitule":"MATIERES CONSOMMABLES"},{"numero":"332","intitule":"FOURNITURES D\'ATELIER ET D\'USINE"},{"numero":"333","intitule":"FOURNITURES DE MAGASIN"},{"numero":"334","intitule":"FOURNITURES DE BUREAU"},{"numero":"335","intitule":"EMBALLAGES"},{"numero":"3351","intitule":"Emballages perdus"},{"numero":"3352","intitule":"Emballages récupérables non identifiables"},{"numero":"3353","intitule":"Emballages à usage mixte"},{"numero":"3358","intitule":"Autres emballages"},{"numero":"338","intitule":"AUTRES MATIERES"}],"fonctionnement":"En cas d\'inventaire intermittent, à la clôture de l\'exercice\\nLe compte 33 – AUTRES APPROVISIONNEMENTS est débité du montant du stock\\nfinal(1), déterminé par inventaire extra-comptable et évalué conformément aux\\nrègles précisées dans l\'évaluation des stocks : les biens matériellement identifiés et\\nindividualisés au coût d\'entrée ; les biens interchangeables non identifiables\\nsuivant la (méthode P.E.P.S. ou du coût moyen pondéré),\\n- par le crédit du compte 6033 – Variations des stocks d\'autres\\napprovisionnements.\\nLe compte 33 – AUTRES APPROVISIONNEMENTS est crédité du montant du stock\\ninitial(2), pour solde\\n(1) ou du montant de l\'augmentation de l\'exercice (stock final moins stock initial).\\n(2) ou du montant de la diminution de l\'exercice (stock initial moins stock final)\\n- par le débit du compte 6033 – Variations des stocks d\'autres\\napprovisionnements.\\nEn cas d\'inventaire permanent :\\nLe compte 33 – AUTRES APPROVISIONNEMENTS est débité, à chaque entrée en\\nstocks, du coût des autres approvisionnements achetés (prix d\'achat et frais\\naccessoires d\'achat)\\n- par le crédit du compte 6033 – Variations des stocks d\'autres\\napprovisionnements.\\nLe compte 33 – AUTRES APPROVISIONNEMENTS est débité, à la clôture de\\n- l\'exercice, après inventaire physique, pour régularisation du stock d\'autres\\napprovisionnements, des différences constatées en plus, par rapport à l\'inventaire\\npermanent\\n- par le crédit du compte 6033 – Variations des stocks d\'autres\\napprovisionnements.\\nLe compte 33 – AUTRES APPROVISIONNEMENTS est crédité, à chaque sortie de\\nstock, les biens matériellement identifiés et individualisés au coût d\'entrée ; les\\nbiens interchangeables non identifiables suivant la méthode du premier entré,\\npremier sorti (P.E.P.S.) ou du coût moyen pondéré,\\n- par le débit du compte 6033 – Variations des stocks d\'autres\\napprovisionnements.\\nLe compte 33 – AUTRES APPROVISIONNEMENTS est crédité, en fin d\'exercice, après\\ninventaire physique, pour régularisation du stock d\'autres approvisionnements, des\\ndifférences constatées en moins, par rapport à l\'inventaire permanent\\n- par le débit du compte 6033 – Variations des stocks d\'autres\\napprovisionnements.","commentaires":"Le compte 33 peut comprendre des pièces de rechange, du petit outillage et, le cas\\néchéant, du matériel mobile, dont la destination définitive (immobilisation ou\\nentretien) n\'est pas exactement connue.","exclusions":"Le compte 33 – AUTRES APPROVISIONNEMENTS ne doit pas servir à enregistrer :\\n- le matériel de remplacement ou de réserve qui n\'est pas encore en service\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n24 – Matériel, Mobilier et Actifs biologiques","controle":"Le compte 33 – AUTRES APPROVISIONNE-MENTS peut être contrôlé à partir de\\n- l\'inventaire extra- comptable et des factures (achats et frais).","motsCles":["approvisionnements"]},{"numero":"34","intitule":"Produits en cours","classe":3,"classeLabel":"Comptes de stocks","groupe":"A","contenu":"Les produits en cours sont des biens et services en voie de formation ou de\\ntransformation à la clôture de l\'exercice.","subdivisions":[{"numero":"341","intitule":"PRODUITS EN COURS"},{"numero":"3411","intitule":"Produits en cours P1"},{"numero":"3412","intitule":"Produits en cours P2"},{"numero":"342","intitule":"TRAVAUX EN COURS"},{"numero":"3421","intitule":"Travaux en cours T1"},{"numero":"3422","intitule":"Travaux en cours T2"},{"numero":"343","intitule":"PRODUITS INTERMEDIAIRES EN COURS"},{"numero":"3431","intitule":"Produits intermédiaires A"},{"numero":"3432","intitule":"Produits intermédiaires B"},{"numero":"344","intitule":"PRODUITS RESIDUELS EN COURS"},{"numero":"3441","intitule":"Produits résiduels A"},{"numero":"3442","intitule":"Produits résiduels B"}],"fonctionnement":"En cas d\'inventaire intermittent :\\nLe compte 34 – PRODUITS EN COURS est débité, en fin d\'exercice, du montant\\nconstaté des en-cours(1) déterminé en comptabilité analytique de gestion ou par\\nvoie extra-comptable\\n- par le crédit du compte 734 – Variations des stocks de produits en cours\\nLe compte 34 – PRODUITS EN COURS est crédité, en fin d\'exercice, du montant\\ninitial des en-cours(2), pour solde\\n- par le débit du compte 734 – Variations des stocks de produits en cours.\\nEn cas d\'inventaire permanent :\\n(1) ou de l\'augmentation de l\'exercice (montant final moins montant initial).\\n(2) ou de la diminution de l\'exercice (montant initial moins montant final)\\nLe compte 34 – PRODUITS EN COURS est débité, à chaque incorporation des frais\\ndans les en-cours, du montant déterminé en comptabilité analytique de gestion\\n- par le crédit du compte 734 – Variations des stocks de produits en cours.\\nLe compte 34 – PRODUITS EN COURS est crédité, à chaque sortie des en-cours\\nachevés et transférés en produits finis ou intermédiaires au coût de production\\n- par le débit du compte 734 – Variations des stocks de produits en cours.","commentaires":"Les produits en cours ne sont pas inscrits à un compte de magasin.\\nLes travaux en cours concernent des biens d\'équipement lourd, immeubles,\\nconstructions, dont les délais de fabrication sont relativement longs et dont la\\npropriété n\'est pas encore transférée à l\'acheteur.","exclusions":"Le compte 34 – PRODUITS EN COURS ne doit pas servir à enregistrer :\\n- les services en cours\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n35 – Services en cours","controle":"Le compte 34 – PRODUITS EN COURS peut être contrôlé à partir de l\'inventaire\\nextra-comptable et de l\'évaluation des coûts de production.","motsCles":["produits","cours"]},{"numero":"35","intitule":"Services en cours","classe":3,"classeLabel":"Comptes de stocks","groupe":"A","contenu":"Les services en cours sont des études et prestations en cours d\'exécution, dont la\\nremise définitive à l\'acheteur ou au passeur d\'ordre n\'est pas encore intervenue.","subdivisions":[{"numero":"351","intitule":"ETUDES EN COURS"},{"numero":"3511","intitule":"Etudes en cours E1"},{"numero":"3512","intitule":"Etudes en cours E2"},{"numero":"352","intitule":"PRESTATIONS DE SERVICES EN COURS"},{"numero":"3521","intitule":"Prestations de services S1"},{"numero":"3522","intitule":"Prestations de services S2"}],"fonctionnement":"En cas d\'inventaire intermittent :\\nLe compte 35 – SERVICES EN COURS est débité, en fin d\'exercice, du montant\\nconstaté des en-cours(1) déterminé en comptabilité analytique de gestion ou par\\nvoie extra-comptable\\n- par le crédit du compte 735 – Variations des en-cours de services.\\nLe compte 35 – SERVICES EN COURS est crédité en fin d\'exercice du montant des\\nen-cours existant au début de l\'exercice(2), pour solde\\n- par le débit du compte 735 – Variations des en-cours de services.\\n(1) ou de l\'augmentation de l\'exercice (montant final moins montant initial).\\n(2) ou de la diminution de l\'exercice (montant initial moins montant final)\\nEn cas d\'inventaire permanent :\\nLe compte 35 – SERVICES EN COURS est débité, à chaque incorporation des frais\\ndans les en-cours, du montant des travaux en cours déterminé en comptabilité\\nanalytique intégrée\\n- par le crédit du compte 735 – Variations des en-cours de services.\\nLe compte 35 – SERVICES EN COURS est crédité à chaque sortie en coût de\\nproduction des \\"en-cours\\" achevés et vendus\\n- par le débit du compte 735 – Variations des en-cours de services.","commentaires":"Les montants d\'études et de prestations déjà engagées et non encore facturées (cas\\nde prestations d\'une certaine durée ; exemples : étude d\'organisation, transport\\ninternational ...) peuvent, en fonction de l\'organisation, être suivis en inventaire\\npermanent ou seulement constatés en inventaire intermittent.","exclusions":"Le compte 35 – SERVICES EN COURS ne doit pas servir à enregistrer :\\n- les produits en cours\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n34 – Produits en cours","controle":"Le compte 35 – SERVICES EN COURS peut être contrôlé à partir de l\'inventaire\\nextra-comptable et de l\'évaluation des coûts de production.","motsCles":["services","cours"]},{"numero":"36","intitule":"Produits finis","classe":3,"classeLabel":"Comptes de stocks","groupe":"A","contenu":"Les produits finis sont les produits fabriqués par l\'entité qui ont atteint le stade\\nfinal de production. Ils sont destinés à être vendus, loués ou fournis.","subdivisions":[{"numero":"361","intitule":"PRODUITS FINIS A"},{"numero":"362","intitule":"PRODUITS FINIS B"}],"fonctionnement":"En cas d\'inventaire intermittent :\\nLe compte 36 – PRODUITS FINIS est débité, à la fin de l\'exercice, du montant du\\nstock final (1), évalué : pour les corps certains, au coût réel de production ; pour les\\nbiens interchangeables, au coût de production déterminé en présumant que le\\npremier élément sorti est le premier entré (P.E.P.S.) ou au coût moyen pondéré\\n- par le crédit du compte 736 – Variations des stocks de produits finis.\\nLe compte 36 – PRODUITS FINIS est crédité, à la fin de l\'exercice, du montant du\\nstock initial(2), pour solde\\n(1) ou de l\'augmentation de l\'exercice (stock final moins stock initial).\\n(2) ou de la diminution de l\'exercice (stock initial moins stock final).\\n- par le débit du compte 736 – Variations des stocks de produits finis.\\nEn cas d\'inventaire permanent :\\nLe compte 36 – PRODUITS FINIS est débité, à chaque entrée en stock, du coût de\\nproduction des produits finis, déterminé par la comptabilité analytique de gestion\\nou autonome\\n- par le crédit du compte 736 – Variations des stocks de produits finis.\\nLe compte 36 – PRODUITS FINIS est débité, à la clôture de l\'exercice, après\\ninventaire physique, pour régularisation du stock de produits finis, des différences\\nconstatées, en plus, par rapport à l\'inventaire permanent\\n- par le crédit du compte 736 – Variations des stocks de produits finis.\\nLe compte 36 – PRODUITS FINIS est crédité, à chaque sortie des stocks : pour les\\ncorps certains, du coût réel de production ; pour les biens interchangeables, du coût\\nde production déterminé en présumant que le premier élément sorti est le premier\\nentré (P.E.P.S.) ou du coût moyen pondéré\\n- par le débit du compte 736 – Variations des stocks de produits finis.\\nLe compte 36 – PRODUITS FINIS est crédité, à la clôture de l\'exercice, après\\ninventaire physique, pour régularisation du stock de produits finis, des différences\\nconstatées, en moins, par rapport à l\'inventaire permanent\\n- par le débit du compte 736 – Variations des stocks de produits finis.","commentaires":"Lorsque l\'entité vend concurremment et indistinctement des produits achetés à\\n- l\'extérieur ou des produits fabriqués par elle-même, en tous points semblables et ne\\nse distinguant que par leur origine, elle peut n\'ouvrir qu\'un seul compte pour cette\\nmarchandise et ce produit, évalués respectivement selon le coût d\'achat et le coût\\nde production. Les sorties de stocks sont créditées par le débit du compte 6031 –\\nVariations des stocks de marchandises et du compte 736 – Variations des stocks de\\nproduits finis, selon un prorata qu\'elle détermine sous sa propre responsabilité.","exclusions":"Le compte 36 – PRODUITS FINIS ne doit pas servir à enregistrer :\\n- les produits intermédiaires fabriqués\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n37 – Produits intermédiaires et résiduels","controle":"Le compte 36 – PRODUITS FINIS peut être contrôlé à partir de l\'inventaire extra-\\ncomptable et de l\'évaluation des coûts de production.","motsCles":["produits","finis"]},{"numero":"37","intitule":"Produits intermédiaires et résiduels","classe":3,"classeLabel":"Comptes de stocks","groupe":"A","contenu":"Les produits intermédiaires sont des produits ayant atteint un stade déterminé de\\nfabrication et disponibles pour des fabrications ultérieures.","subdivisions":[{"numero":"371","intitule":"PRODUITS INTERMEDIAIRES"},{"numero":"3711","intitule":"Produits intermédiaires A"},{"numero":"3712","intitule":"Produits intermédiaires B"},{"numero":"372","intitule":"PRODUITS RESIDUELS"},{"numero":"3721","intitule":"Déchets"},{"numero":"3722","intitule":"Rebuts"},{"numero":"3723","intitule":"Matières de récupération"}],"fonctionnement":"En cas d\'inventaire intermittent, à la clôture de l\'exercice :\\nLe compte 371 – PRODUITS INTERMEDIAIRES est débité du montant du stock\\nfinal(1), évalué : pour les corps certains, au coût réel de production ; pour les biens\\ninterchangeables, au coût de production déterminé en présumant que le premier\\nélément sorti est le premier entré (P.E.P.S.) ou au coût moyen pondéré\\n- par le crédit du compte 7371 – Variations des stocks de produits\\nintermédiaires.\\nLe compte 371 – PRODUITS INTERMEDIAIRES est crédité du montant du stock\\ninitial(2), pour solde\\n- par le débit du compte 7371 – Variations des stocks de produits\\nintermédiaires\\nLe compte 372 – PRODUITS RESIDUELS est débité de la valeur estimée du stock\\nfinal de produits résiduels(3), conformément aux règles d\'évaluation\\n- par le crédit du compte 7372 – Variations des stocks de produits résiduels.\\nLe compte 372 – PRODUITS RESIDUELS est débité de la valeur des produits de la\\nrécupération (matières et matériaux) provenant de la fabrication ou de la mise hors\\nservice d\'immobilisations, dans la mesure où ils ne sont pas affectables aux\\ncomptes 31, 32 ou 33\\n- par le crédit du compte 7372 – Variations des stocks de produits résiduels.\\nLe compte 372 – PRODUITS RESIDUELS est crédité du montant du stock initial(1),\\npour solde\\n(1) ou de l\'augmentation de l\'exercice (stock final moins stock initial)\\n(2) ou de l\'augmentation de l\'exercice (stock final moins stock initial)\\n(3) ou de la diminution de l\'exercice (stock initial moins stock final)\\n- par le débit du compte 7372 – Variations des stocks de produits résiduels.\\nEn cas d\'inventaire permanent :\\nLe compte 37 – PRODUITS INTERMEDIAIRES ET RESIDUELS est débité, à chaque\\nentrée en stocks, du coût de production des produits intermédiaires et résiduels,\\ndéterminé par la comptabilité analytique intégrée ou autonome\\n- par le crédit du compte 737 – Variations des stocks de produits\\nintermédiaires et résiduels.\\nLe compte 37 – PRODUITS INTERMEDIAIRES ET RESIDUELS est débité, à la clôture\\nde l\'exercice, après inventaire physique, pour régularisation des stocks de produits\\nintermédiaires et de produits résiduels, des différences constatées en plus, par\\nrapport à l\'inventaire permanent\\n- par le crédit du compte 737 – Variations des stocks de produits\\nintermédiaires et résiduels.\\nLe compte 37 – PRODUITS INTERMEDIAIRES ET RESIDUELS est crédité, à chaque\\nsortie des stocks : pour les corps certains, du coût réel de production ; pour les biens\\ninterchangeables, du coût de production déterminé en présumant que le premier\\nélément sorti est le premier entré (P.E.P.S.) ou au coût moyen pondéré\\n- par le débit du compte 737 – Variations des stocks de produits\\nintermédiaires et résiduels.\\nLe compte 37 – PRODUITS INTERMEDIAIRES ET RESIDUELS est crédité à la clôture\\nde l\'exercice, après inventaire physique, pour régularisation des stocks, des\\ndifférences constatées en moins, par rapport à l\'inventaire permanent\\n- par le débit du compte 737 – Variations des stocks de produits\\nintermédiaires et résiduels.","commentaires":"Lorsque l\'entité utilise concurremment et indistinctement un produit intermédiaire\\nfabriqué par elle et une matière ou fourniture liée achetée à l\'extérieur, mais en\\ntous points semblables et ne se distinguant que par leur origine, elle peut n\'ouvrir\\nqu\'un seul compte pour cette matière et ce produit, mais, dans ce cas, elle crédite\\n- les sorties de stocks par le débit du compte 7371 – Variations des stocks de produits\\nintermédiaires et par celui du compte 6032 – Variations des stocks de matières\\npremières et fournitures liées, suivant un prorata qu\'elle détermine sous sa propre\\nresponsabilité.\\nLes produits résiduels sont constitués par :\\n- les déchets et rebuts : résidus de toutes natures (produits ouvrés ou semi-\\nouvrés) impropres à une utilisation ou à un écoulement normal ;\\n- les produits de la récupération : matières récupérées à la suite de la mise hors\\nservice de certaines immobilisations.\\nLe compte 372 n\'est ouvert que si les déchets et rebuts ne peuvent être\\nnormalement introduits dans la nomenclature des biens et services de l\'entité.","exclusions":"Le compte 37 – PRODUITS INTERMEDIAIRES ET RESIDUELS ne doit pas servir à\\nenregistrer :\\n- les produits en cours qui par définition ne peuvent être inscrits à un compte de\\nmagasin\\n- les produits issus d\'immobilisations démontées ou mises hors service en\\nattendant l\'affectation définitive\\n- les produits issus de la récupération affectés définitivement à d\'autres stocks\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n34 – Produits en cours\\ncompte 38\\ncomptes 31, 32, 33","controle":"Le compte 37 – PRODUITS INTERMEDIAIRES ET RESIDUELS peut être contrôlé à\\npartir de l\'inventaire extra-comptable et de l\'évaluation des coûts de production des\\nproduits concernés.","motsCles":["produits","intermediaires","residuels"]},{"numero":"38","intitule":"Stocks en cours de route, en consignation ou en dépôt","classe":3,"classeLabel":"Comptes de stocks","groupe":"A","contenu":"Ce sont des marchandises, matières, fournitures ou produits fabriqués, expédiés\\n- par le fournisseur et non encore réceptionnés par l\'entité ou détenus chez des tiers\\nmais dont l\'entité est propriétaire.","subdivisions":[{"numero":"381","intitule":"MARCHANDISES EN COURS DE ROUTE"},{"numero":"382","intitule":"MATIERES PREMIERES ET FOURNITURES LIEES EN COURS DE ROUTE"},{"numero":"383","intitule":"AUTRES APPROVISIONNEMENTS EN COURS DE ROUTE"},{"numero":"386","intitule":"PRODUITS FINIS EN COURS DE ROUTE"},{"numero":"387","intitule":"STOCK EN CONSIGNATION OU EN DEPÔT"},{"numero":"3871","intitule":"Stock en consignation"},{"numero":"3872","intitule":"Stock en dépôt"},{"numero":"388","intitule":"STOCK PROVENANT D\'IMMOBILISATIONS MISES HORS SERVICE OU AU REBUT"}],"fonctionnement":"En cas d\'inventaire intermittent :\\nLe compte 38 – STOCKS EN COURS DE ROUTE, EN CONSIGNATION OU EN DEPÔT est\\ndébité, en fin d\'exercice, des stocks en cours de route à cette date(1), pour leur coût\\napproché ou leur coût standard, le coût réel n\'étant pas, dans le cas d\'espèce, connu\\nà la date d\'établissement des états financiers annuels\\n- par le crédit des sous-comptes 603 concernés.\\nLe compte 38 – STOCKS EN COURS DE ROUTE, EN CONSIGNATION OU EN DEPÔT est\\ncrédité à la fin de l\'exercice du montant des stocks en cours de route de début\\nd\'exercice(2), pour solde\\n- par le débit des sous-comptes 603 concernés.\\nEn cas d\'inventaire permanent :\\nLe compte 38 – STOCKS EN COURS DE ROUTE, EN CONSIGNATION OU EN DEPÔT est\\ndébité du montant des marchandises, matières premières et fournitures, produits\\nfabriqués, en cours de route et non encore réceptionnés (coût approché ou coût\\nstandard)\\n- par le crédit des sous-comptes 603 concernés.\\nLe compte 38 – STOCKS EN COURS DE ROUTE, EN CONSIGNATION OU EN DEPÔT est\\ncrédité lorsque les stocks sont réceptionnés par l\'entité, le consignataire ou le\\ndépositaire\\n- par le débit des comptes de stocks de la classe 3 concernés.\\n(1) ou de l\'augmentation de l\'exercice (stock final moins stock initial)\\n(2) ou de la diminution de l\'exercice (stock initial moins stock final)","commentaires":"Dans le cadre du système d\'inventaire permanent, le compte 38 constitue un\\ncompte de passage destiné à enregistrer les stocks dont l\'entité est déjà propriétaire,\\nmais qui sont en voie d\'acheminement et non encore réceptionnés. Il peut\\négalement être utilisé pour constater l\'envoi de stocks (marchandises, matières et\\nfournitures, produits fabriqués) en dépôt ou en consignation, jusqu\'à réception par\\n- le dépositaire ou le consignataire. Il s\'agit de stocks contrôlés par l\'entité mais non\\ndétenus physiquement à la clôture de l\'exercice.\\nDès réception, les stocks comptabilisés au compte 38 sont ventilés dans les comptes\\nde stocks appropriés et classés, conformément à la nomenclature des biens et\\nservices en usage dans l\'entité.\\nLes entités qui tiennent un inventaire intermittent enregistrent les stocks en cours\\nde route dans les achats à la date de transfert de propriété et utilisent,\\nexceptionnellement, le compte 38 si ces stocks ne sont pas encore réceptionnés à la\\ndate d\'établissement des comptes annuels.\\nLes stocks provenant d\'immobilisation comprennent les éléments récupérés ou\\ndémontés d\'immobilisations corporelles.\\nCe compte est débité par le crédit du compte d\'immobilisation concerné.\\nEn fin de période, les entités doivent inscrire, dans les Notes annexes, le détail par\\ncatégorie des stocks figurant au bilan dans le compte 38.","exclusions":"Le compte 38 – STOCKS EN COURS DE ROUTE, EN CONSIGNATION OU EN DEPÔT ne\\ndoit pas servir à enregistrer :\\n- les stocks dont l\'entité a pris possession et dont elle continue d\'attendre les\\nfactures d\'achat\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\nEn cours d\'exercice : pas d\'écriture à passer.\\nA la clôture de l\'exercice : les comptes de régularisation","controle":"Le compte 38 – STOCKS EN COURS DE ROUTE, EN CONSIGNATION OU EN DEPÔT\\npeut être contrôlé à partir de l\'inventaire extra-comptable et au moyen des factures\\nd\'achat.","motsCles":["stocks","cours","route","consignation","depot"]},{"numero":"39","intitule":"Dépréciations des stocks et encours de production","classe":3,"classeLabel":"Comptes de stocks","groupe":"A","contenu":"Ce sont des dépréciations subies par des stocks de marchandises, de matières, et\\nautres approvisionnements résultant de causes diverses dont les effets ne sont pas\\njugés irréversibles.","subdivisions":[{"numero":"391","intitule":"DEPRECIATIONS DES STOCKS DE MARCHANDISES"},{"numero":"392","intitule":"DEPRECIATIONS DES STOCKS DE MATIERES PREMIERES ET FOURNITURES LIEES"},{"numero":"393","intitule":"DEPRECIATIONS DES STOCKS D\'AUTRES APPROVISIONNEMENTS"},{"numero":"394","intitule":"DEPRECIATIONS DES PRODUITS EN COURS"},{"numero":"395","intitule":"DEPRECIATIONS DES SERVICES EN COURS"},{"numero":"396","intitule":"DEPRECIATIONS DES STOCKS DE PRODUITS FINIS"},{"numero":"397","intitule":"DEPRECIATIONS DES STOCKS DE PRODUITS INTERMEDIAIRES ET RESIDUELS"},{"numero":"398","intitule":"DÉPRÉCIATIONS DES STOCKS EN COURS DE ROUTE, EN CONSIGNATION OU EN DÉPÔT"}],"fonctionnement":"En fin d\'exercice :\\nLe compte 39 – DEPRECIATIONS DES STOCKS est crédité des dépréciations\\nconstatées sur les stocks à la fin de l\'exercice(1)\\n- par le débit du compte 6593 – Charges pour dépréciations et provisions\\npour risques à court terme d\'exploitation sur stocks;\\n- ou par le débit du compte 839 – Charges pour dépréciations et provisions pour\\nrisques à court terme H.A.O.\\nLe compte 39 – DEPRECIATIONS DES STOCKS est débité des dépréciations existant\\nau début de l\'exercice sur les stocks(2), pour solde\\n- par le crédit du compte 7593 – Reprises de charges pour dépréciations et\\nprovisions pour risques à court terme d\'exploitation sur stocks ;\\n- ou par le crédit du compte 849 – Reprises de charges pour dépréciations et\\nprovisions pour risques à court terme H.A.O.","commentaires":"Les dépréciations des stocks obéissent aux mêmes règles de comptabilisation que\\n- les dépréciations constatées sur les autres éléments de l\'actif circulant (classe 4).\\nLa dépréciation doit être certaine quant à sa nature et l\'élément d\'actif en cause\\ndoit être individualisé.\\nLa dépréciation est à constituer même si la dépréciation est d\'un montant incertain.\\nLa dépréciation traduit une baisse non définitive et non irréversible de l\'évaluation\\ndes éléments d\'actif par rapport à leur valeur comptable.\\nLa dépréciation doit être constituée même en l\'absence ou en cas d\'insuffisance de\\nbénéfices, conformément au principe de prudence.\\nLorsque au jour de l\'inventaire, la valeur nette de réalisation des stocks est\\ninférieure à leur valeur comptable déterminée conformément aux dispositions\\nexposées ci-dessus, classe 3 : comptes de stocks et dans l\'Acte uniforme, les entités\\ndoivent constituer des dépréciations qui expriment les moins-values constatées sur\\nces stocks.\\nLes éléments en stock détériorés, défraîchis, démodés doivent faire l\'objet d\'une\\ndépréciation.\\nLe montant de ces dépréciations est normalement déterminé par différence entre :\\nd\'une part, la valeur nette comptable;\\nd\'autre part, la valeur nette de réalisation au jour de l\'inventaire.\\nLes dépréciations sont portées à l\'actif du bilan, en déduction de la valeur des\\npostes qu\'elles concernent, sous la forme prévue par le modèle de bil","exclusions":"Le compte 39 – DEPRECIATIONS DES STOCKS ne doit pas servir à enregistrer :\\n- les dépréciations de l\'actif immobilisé de la classe 2\\n- les dépréciations des clients et comptes rattachés\\n- les dépréciations des comptes de trésorerie\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\ncompte 29 – Dépréciations\\ncompte 49 – Dépréciations et provisions pour risques à court terme (Tiers)\\ncompte 59 – Dépréciations et provisions pour risques à court terme (Trésorerie)\\n(1) ou de l\'augmentation de l\'exercice (dépréciations finales moins dépréciations\\ninitiales)\\n(2) ou de la diminution de l\'exercice (dépréciations initiales moins dépréciations\\nfinales)","controle":"Le compte 39 – DEPRECIATIONS DES STOCKS peut être contrôlé à partir de\\n- l\'inventaire extra-comptable et par évaluation, notamment.\\n\\n# CLASSE 4 : COMPTES DE TIERS\\nLes comptes de la classe 4 retracent les relations de l\'entité avec les tiers. Ils servent\\ndonc à comptabiliser les dettes et les créances de l\'entité à l\'exclusion de celles\\ninscrites respectivement dans les comptes de ressources stables et les comptes\\nd\'actif immobilisé.\\nFigurent également dans la classe 4 les comptes de régularisation qui sont utilisés\\npour répartir les charges et les produits dans le temps, de manière à rattacher à un\\nexercice déterminé toutes les charges et tous les produits qui le concernent\\neffectivement.\\nLes abandons de créances consentis en faveur de l\'entité sont enregistrés au compte\\n- 846 Abandons de créances obtenus pour le montant hors TVA si l\'abandon est\\npassible de TVA. L\'entité qui abandonne la créance enregistre la perte dans ses\\nlivres au compte 836 Abandons de créances consentis.\\nLes abandons de créances ne peuvent être assimilés en aucun cas comme un\\nélément du prix d\'achat ou de cession des titres de participation dans le cadre d\'un\\nabandon de créances dans le cadre d\'une prise de contrôle ou de séparation d\'une\\nsociété mère et de sa filiale.\\nSi l\'abandon de créance est consenti avec une clause de retour à meilleure fortune.\\nCette clause doit être mentionnée dans les engagements hors bilan. Dès que le\\nretour à meilleure fortune est effectif, la créance est reconstituée par le biais des\\ncomptes\\n- 836 et 846.\\nA la clôture de chaque exercice une entité doit apprécier, s\'il existe un quelconque\\nindice qu\'une créance a subi une perte de valeur. S\'il existe un tel indice, l\'entité\\ndoit estimer la valeur économique réelle et la comparer avec la valeur nette\\ncomptable.\\nLa créance doit être dépréciée lorsque la valeur nette comptable est supérieure à la\\nvaleur économique réelle.","motsCles":["depreciations","stocks","encours","production"]},{"numero":"40","intitule":"Fournisseurs et comptes rattachés","classe":4,"classeLabel":"Comptes de tiers","groupe":"A","contenu":"Les fournisseurs d\'exploitation sont des tiers auxquels l\'entité a recours pour ses\\nachats de fournitures de toutes natures et de services.","subdivisions":[{"numero":"401","intitule":"FOURNISSEURS, DETTES EN COMPTE"},{"numero":"4011","intitule":"Fournisseurs"},{"numero":"4012","intitule":"Fournisseurs-Groupe"},{"numero":"4013","intitule":"Fournisseurs sous-traitants"},{"numero":"4017","intitule":"Fournisseurs, retenues de garantie"},{"numero":"402","intitule":"FOURNISSEURS, EFFETS A PAYER"},{"numero":"4021","intitule":"Fournisseurs, Effets à payer"},{"numero":"4022","intitule":"Fournisseurs-Groupe, Effets à payer"},{"numero":"4023","intitule":"Fournisseurs sous-traitants, Effets à payer"},{"numero":"408","intitule":"FOURNISSEURS, FACTURES NON PARVENUES"},{"numero":"4081","intitule":"Fournisseurs"},{"numero":"4082","intitule":"Fournisseurs-Groupe"},{"numero":"4083","intitule":"Fournisseurs sous-traitants"},{"numero":"4086","intitule":"Fournisseurs, intérêts courus"},{"numero":"409","intitule":"FOURNISSEURS DEBITEURS"},{"numero":"4091","intitule":"Fournisseurs, avances et acomptes versés"},{"numero":"4092","intitule":"Fournisseurs-Groupe, avances et acomptes versés"},{"numero":"4093","intitule":"Fournisseurs sous-traitants, avances et acomptes versés"},{"numero":"4094","intitule":"Fournisseurs, créances pour emballages et matériels à rendre"},{"numero":"4098","intitule":"Rabais, Remises, Ristournes et autres avoirs à obtenir"}],"fonctionnement":"Le compte 40 – FOURNISSEURS ET COMPTES RATTACHES est crédité du montant\\ndes factures d\'achats de biens ou de prestations de services des fournisseurs ou des\\nsous- traitants\\n- par le débit : des comptes concernés de la classe 6 pour le montant hors\\ntaxes récupérables ou, le cas échéant, de la classe 3 (inventaire permanent)\\n- par le débit : du compte 4094 – Fournisseurs, créances pour emballages et\\nmatériels à rendre\\n- par le débit : du compte 445 – Etat, T.V.A. récupérable\\nLe compte 40 – FOURNISSEURS ET COMPTES RATTACHES est débité des avances et\\nacomptes versés aux fournisseurs ainsi que des règlements effectués sur factures\\n- par le crédit des comptes de trésorerie ou d\'effets à payer ;\\n- par le crédit : du compte 4094 – Fournisseurs, créances pour emballages et\\nmatériels à rendre .\\nLe compte 40 – FOURNISSEURS ET COMPTES RATTACHES est débité pour le\\nmontant des factures d\'avoir reçues pour retour des marchandises au fournisseur\\n- par le crédit des comptes de la classe 6 et des autres comptes ayant joué lors\\nde l\'enregistrement initial des achats de biens et de services, objets du\\nretour.\\nLe compte 40 – FOURNISSEURS ET COMPTES RATTACHES est débité des rabais,\\nremises et ristournes sur achats obtenus hors factures\\n- par le crédit des comptes de la classe 6 concernés.\\nLe compte 40 – FOURNISSEURS ET COMPTES RATTACHES est débité des escomptes\\nde règlement obtenus des fournisseurs\\n- par le crédit du compte 773 – Escomptes obtenus.","commentaires":"Figurent à ce compte les dettes et avances liées à l\'acquisition de biens ou de\\nservices.\\nLes dettes d\'exploitation se caractérisent par le rattachement à ce compte de tiers\\nde toutes les opérations le concernant : effets à payer, factures à recevoir à la\\nclôture de l\'exercice, les intérêts courus à la clôture de l\'exercice, les avances et\\nacomptes versés, les retenues de garantie.\\nSi un fournisseur d\'exploitation a, en outre, avec l\'entité d\'autres relations (de client\\npar exemple), seules les opérations relatives aux achats (factures, avoirs,\\nrèglements, rabais, escomptes, etc.) doivent figurer dans le compte \\"Fournisseurs\\",\\n- les autres opérations étant imputées aux comptes particuliers qu\'elles concernent.\\nSi un tiers, fournisseur d\'exploitation, a, en outre, avec l\'entité des relations de\\nfournisseur d\'investissements, ces dernières opérations doivent être imputées au\\ncompte qu\'elles concernent (481 – Fournisseurs d\'investissements).\\nLes fournisseurs sont classés selon différents critères qui peuvent servir de base à\\nla codification des sous-comptes : 1 – Responsabilité de l\'exécution :\\nfournisseurs livrant à l\'entité des objets, matières ou fournitures dont ils sont\\nentièrement responsables (conception, matières, fabrication) ;\\nsous-traitants, tiers auxquels l\'entité a recours pour exécuter, sur ses ordres et\\nen son nom, des travaux ou services qui lui ont été confiés par ses propres\\nclients.\\nSi le sous-traitant travaille sur des objets ou des matières premières qui lui sont\\nfournis par l\'entreprise (sous réserve de l\'utilisation de matières accessoires\\nnécessitées par son travail), il est dénommé façonnier et n\'est responsable que de la\\nbonne exécution de son travail.\\n2 – Relations entre le fournisseur et l\'entité\\nFournisseurs membres du groupe (sociétés apparentées) et autres fournisseurs.\\n3 – Nature de la dette\\nIl conviendra de séparer dans des comptes distincts :\\n- les retenues de garanties effectuées sur le prix convenu ;\\n- les avances et acomptes versés sur commandes d\'exploitation ou réglés aux\\nsous-traitants ;\\n- les factures à recevoir dont le montant est définitivement arrêté, mais dont les\\npièces justificatives ne sont pas encore parvenues à l\'entité (si le montant ne\\npeut être qu\'estimé à la date de clôture des écritures, utiliser le compte 408 –\\nFournisseurs, factures non parvenues en contrepartie des comptes de la classe 6\\net du compte 4455 si la TVA est récupérable). A l\'ouverture de l\'exercice ces\\nécritures sont contre- passées pour permettre un meilleur contrôle et analyse\\ndes flux ou soldées par le compte fournisseur à la réception de la facture ;\\n- le compte 4094 emballages et matériels à rendre, reçoit à son débit, par le crédit\\ndu fournisseur consignataire, les sommes facturées à titre de consignation\\nd\'emballages ou de matériels.\\nCe compte, emballages et matériels à rendre est soldé par :\\n- le compte du fournisseur au retour de l\'emballage ;\\n- par le débit du compte (6082)\\nAchats d\'emballages récupérables ou du compte (24) matériel, mobilier et actifs\\nbiologiques en cas de conservation de l\'emballage ou du matériel ;\\n- par le débit du compte fournisseur et du compte (6224) malis sur\\nemballages en cas de reprise pour un montant inférieur à celui de la\\nconsignation.\\n4 – Identité du fournisseur\\nSelon le classement adopté par l\'entité, en principe, il est tenu un sous-compte\\nindividuel pour chaque fournisseur, en vue d\'alimenter directement le fichier\\nfournisseurs.\\n5 – Nature de l\'agent fournisseur\\nSelon la nomenclature des agents économiques proposée dans le Système\\nComptable OHADA et le code d\'activité imparti à chaque fournisseur.\\n6 – Répartition géographique des fournisseurs dans les Etats de la Région et hors\\nRégion\\nLes entités ventilent, en tant que de besoin, leurs opérations selon qu\'elles sont\\nfaites :\\ndans l\'Etat-partie ;\\ndans les autres Etats de la Région ;\\nhors Région.\\nDans la situation patrimoniale, aucune compensation ne pourrait s\'effectuer entre\\n- les comptes fournisseurs à solde débiteur et les comptes fournisseurs à solde\\ncréditeur.\\nLes premiers figurent à l\'actif du bilan et les seconds au passif du bilan. C\'est ainsi\\nque les avances et acomptes versés sur commandes d\'exploitation, subsistant à la\\nclôture de l\'exercice, figurent en clair à l\'actif du bilan.","exclusions":"Le compte 40 – FOURNISSEURS ET COMPTES RATTACHES ne doit pas servir à\\nenregistrer :\\n- les fournisseurs d\'immobilisations\\n- les avances et acomptes versés sur commande d\'immobilisations\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n- 481 – Fournisseurs d\'investissements\\n25 – Avances et acomptes versés sur immobilisations","controle":"Le compte 40 – FOURNISSEURS ET COMPTES RATTACHES peut être contrôlé à\\npartir des factures, chèques de règlement, effets ...","motsCles":["fournisseurs","comptes","rattaches"]},{"numero":"41","intitule":"Clients et comptes rattachés","classe":4,"classeLabel":"Comptes de tiers","groupe":"A","contenu":"Les clients d\'exploitation sont des tiers auxquels l\'entité vend les biens ou services,\\nobjet de son activité.","subdivisions":[{"numero":"411","intitule":"CLIENTS"},{"numero":"4111","intitule":"Clients"},{"numero":"4112","intitule":"Clients-Groupe"},{"numero":"4114","intitule":"Clients, Etat et collectivités publiques"},{"numero":"4115","intitule":"Clients, organismes internationaux"},{"numero":"4116","intitule":"Clients ventes avec réserves de propriété"},{"numero":"4117","intitule":"Clients, retenues de garantie"},{"numero":"4118","intitule":"Clients, dégrèvements de Taxes sur la Valeur Ajoutée (T.V.A.)"},{"numero":"412","intitule":"CLIENTS, EFFETS A RECEVOIR EN PORTEFEUILLE"},{"numero":"4121","intitule":"Clients, Effets à recevoir"},{"numero":"4122","intitule":"Clients-Groupe, Effets à recevoir"},{"numero":"4124","intitule":"Etat et collectivités publiques, Effets à recevoir"},{"numero":"4125","intitule":"Organismes internationaux, Effets à recevoir"},{"numero":"4126","intitule":"clients ventes avec réserves de propriété, effets à recevoir"},{"numero":"414","intitule":"CREANCES SUR CESSIONS COURANTES D\'IMMOBILISATIONS"},{"numero":"4141","intitule":"Créances en compte"},{"numero":"4142","intitule":"Effets à recevoir"},{"numero":"415","intitule":"CLIENTS, EFFETS ESCOMPTES NON ECHUS"},{"numero":"416","intitule":"CREANCES CLIENTS LITIGIEUSES OU DOUTEUSES"},{"numero":"4161","intitule":"Créances litigieuses"},{"numero":"4162","intitule":"Créances douteuses"},{"numero":"418","intitule":"CLIENTS, PRODUITS A RECEVOIR"},{"numero":"4181","intitule":"Clients, factures à établir"},{"numero":"4186","intitule":"Clients, intérêts courus"},{"numero":"419","intitule":"CLIENTS CREDITEURS"},{"numero":"4191","intitule":"Clients, avances et acomptes reçus"},{"numero":"4192","intitule":"Clients-Groupe, avances et acomptes reçus"},{"numero":"4194","intitule":"Clients, dettes pour emballages et matériels consignés"},{"numero":"4198","intitule":"Rabais, Remises, Ristournes et autres avoirs à accorder"}],"fonctionnement":"Le compte 41 – CLIENTS ET COMPTES RATTACHES est débité du montant des\\nfactures de ventes de biens ou de prestations de services\\n- par le crédit des comptes concernés de la classe 7 (montant hors taxes\\nrécupérables)\\n- par le crédit du compte 4194 – clients, dettes pour emballages et matériels\\nconsignés\\n- par le crédit du compte 443 – Etat TVA facturée\\nLe compte 41 – CLIENTS ET COMPTES RATTACHES est crédité des avances et\\nacomptes ainsi que des règlements reçus des clients\\n- par le débit des comptes de trésorerie ou effets à recevoir\\n- par le débit du compte 4194 – Clients, dettes pour emballages et matériels\\nconsignés .\\nLe compte 41 – CLIENTS ET COMPTES RATTACHES est crédité pour le montant des\\nfactures d\'avoir émises pour retour de marchandises\\n- par le débit des comptes de la classe 7 et des autres comptes ayant joué lors\\nde l\'enregistrement initial des ventes de biens et de services.\\nLe compte 41 – CLIENTS ET COMPTES RATTACHES est crédité des rabais, ristournes\\net remises accordés sur ventes hors factures\\n- par le débit des comptes 70 – Ventes.\\nLe compte 41 – CLIENTS ET COMPTES RATTACHES est crédité des créances\\nlitigieuses ou douteuses\\n- par le débit du compte 416 – Créances clients litigieuses ou douteuses.\\nLe compte 41 – CLIENTS ET COMPTES RATTACHES est crédité des escomptes de\\nrèglement accordés aux clients\\n- par le débit du compte 673 – Escomptes accordés.","commentaires":"Figurent à ce compte les créances liées à la vente de biens et de services rattachés\\nau cycle d\'exploitation de l\'entité. Les créances d\'exploitation se caractérisent par le\\nrattachement à ce compte de tiers de toutes les opérations le concernant : effets à\\nrecevoir concernant ces clients, les créances à venir se rapportant à l\'exploitation\\nde l\'exercice (factures clients non encore établies), les créances sur cession d\'actifs,\\n- les effets escomptés non échus, les créances litigieuses ou douteuses, les intérêts\\ncourus à la clôture de l\'exercice, les avances et acomptes obtenus, les retenues de\\ngarantie dans les comptes rattachés.\\nLes clients sont les tiers auxquels l\'entité vend les biens ou services, objets de son\\nactivité.\\nSi un tiers a, en outre, avec l\'entité d\'autres relations (de fournisseur ou de salarié,\\npar exemple), seules les opérations relatives aux ventes (factures, avoirs,\\nrèglements, rabais, escomptes, etc.) doivent figurer dans le compte \\"Client\\", les\\nautres opérations étant enregistrées aux comptes particuliers qu\'elles concernent\\n(fournisseurs, personnel, etc.).\\nLes clients sont classés selon les différents critères dont l\'ordre de priorité est\\ndéterminé par le degré d\'utilité qu\'ils présentent pour les parties intéressées et en\\nfonction des moyens de l\'entité.\\nSi un tiers, client d\'exploitation, a, en outre, avec l\'entité d\'autres relations (de\\nfournisseur, par exemple), seules les opérations relatives aux ventes (factures,\\navoirs, règlements, rabais, escomptes, etc.) doivent figurer dans le compte \\"Clients\\",\\n- les autres opérations étant imputées aux comptes particuliers qu\'elles concernent.\\nSi un tiers, client d\'exploitation, a, en outre, avec l\'entité des relations de client\\nd\'investissements, ces dernières opérations doivent être imputées au compte\\nqu\'elles concernent (485 – Créances sur cessions d\'immobilisations).\\nLe factoring ou l\'affacturage est une opération qui consiste en un transfert de\\ncréances commerciales de leur titulaire à un factor, qui se charge d\'en opérer le\\nrecouvrement et qui en garantit la bonne fin même en cas de défaillance\\nmomentanée ou permanente du débiteur (voir titre VIII Opérations spécifiques,\\nchapitre 15).\\nLes clients sont classés selon différents critères qui peuvent servir de base à la\\ncodification des sous-comptes : 1 – Répartition géographique des clients\\nLes entités ventilent, en tant que de besoin, leurs opérations selon qu\'elles sont\\nréalisées :\\ndans l\'Etat-partie;\\ndans les autres Etats de la Région ;\\nhors Région ;\\nsur internet. 2 – Nature du client\\nEntité, particulier, Etat, collectivité publique, institutions financières, selon la\\nnomenclature des agents économiques retenue dans le Système Comptable OHADA.\\n3 – Relations entre le client et l\'entité\\nClient membre du groupe (sociétés apparentées) et autres clients.\\n4 – Nature de la créance\\nOn séparera dans des comptes distincts :\\n- les avances et acomptes reçus sur commandes en cours ;\\n- les factures à établir dont le montant est définitivement arrêté, mais qui ne sont\\npas encore expédiées par l\'entité (si le montant ne peut qu\'être estimé à la date\\nde clôture de la période, on utilisera le compte 418 – Clients, produits à recevoir\\nen contrepartie des comptes de la classe 7 et du compte 4435 si le bien entre\\ndans le champ d\'application de la TVA). A l\'ouverture de l\'exercice ces écritures\\nsont contre-passées pour permettre un meilleur contrôle et analyse des flux ou\\nsoldées par le compte client à l\'émission de la facture.\\n- les clients qui contestent leurs dettes (créances litigieuses) ou se dérobent à leur\\npaiement (créances douteuses) ;\\n- le compte 4194 emballages et matériels consignés, reçoit à son crédit, par le\\ndébit du client consignataire, les sommes facturées par l\'entité à titre de\\nconsignation d\'emballages ou de matériels.\\nCe compte, emballages et matériels consignés est soldé par\\n- le crédit du compte client à la restitution de l\'emballage ou du matériel ;\\n- le crédit du compte (7074) bonis sur cession d\'emballages, s\'il s\'agit d\'un\\nemballage, ou du compte (82) produits des cessions d\'immobilisations, s\'il s\'agit\\nd\'un matériel, en cas de conservation de l\'emballage ou du matériel par le client\\n;\\n- le crédit du (compte 7074) bonis sur reprises d\'emballage en cas de reprise pour\\nun prix inférieur à celui de la consignation.\\n- les effets à recevoir en portefeuille qui seront transférés en cas de remise à\\n- l\'escompte dans un sous – compte distinct (compte 415 – Clients, effets\\nescomptés non échus).\\n5 – Identité du client\\nSelon le classement adopté par l\'entité, en principe, il est tenu un sous-compte\\nindividuel par client en vue d\'alimenter directement le fichier clients.\\n6 – Nature du produit ou du service vendu\\nSelon la nomenclature de biens et services en usage dans chacun des Etats-parties.\\nDans la situation patrimoniale, aucune compensation ne doit être établie entre les\\ncomptes clients à solde débiteur et les comptes clients à solde créditeur. Les\\npremiers figurent à l\'actif du bilan et les seconds au passif du bilan. C\'est ainsi que\\n- les avances et acomptes reçus sur commandes en cours, subsistant à la clôture de\\n- l\'exercice, figurent en clair au passif du bilan.","exclusions":"Le compte 41 – CLIENTS ET COMPTES RATTACHES ne doit pas servir à enregistrer :\\n- les créances sur des tiers nées des opérations autres que la vente des\\nmarchandises, biens ou services\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n- 485 – Créances sur cessions d\'immobilisations","controle":"Le compte 41 – CLIENTS ET COMPTES RATTACHES peut être contrôlé à partir des\\nfactures, chèques de règlement, effets, impayés, relances clients, dossiers\\ncontentieux.","motsCles":["clients","comptes","rattaches"]},{"numero":"42","intitule":"Personnel","classe":4,"classeLabel":"Comptes de tiers","groupe":"A","contenu":"Le compte Personnel enregistre l\'ensemble des opérations qui interviennent entre\\n- l\'entité et les personnes qui lui sont liées par un contrat de travail. Par extension,\\n- les opérations qui concernent les représentants du personnel ou les organismes\\nsimilaires lui sont rattachées.\\nLe personnel de l\'entité comprend :\\n- le personnel de direction et d\'encadrement, les employés, les ouvriers et les\\noccasionnels indépendamment de leur situation ou de leurs fonctions ;\\n- les représentants salariés ;\\n- les associés et les dirigeants de société qui exercent des fonctions techniques ;\\n- les membres de la famille de l\'exploitant exerçant un emploi salarié.","subdivisions":[{"numero":"421","intitule":"PERSONNEL, AVANCES ET ACOMPTES"},{"numero":"4211","intitule":"Personnel, avances"},{"numero":"4212","intitule":"Personnel, acomptes"},{"numero":"4213","intitule":"Frais avancés et fournitures au personnel"},{"numero":"422","intitule":"PERSONNEL, REMUNERATIONS DUES"},{"numero":"423","intitule":"PERSONNEL, OPPOSITIONS, SAISIES-ARRÊTS"},{"numero":"4231","intitule":"Personnel, oppositions"},{"numero":"4232","intitule":"Personnel, saisies-arrêts"},{"numero":"4233","intitule":"Personnel, avis à tiers détenteur"},{"numero":"424","intitule":"PERSONNEL,ŒUVRES SOCIALES INTERNES"},{"numero":"4241","intitule":"Assistance médicale"},{"numero":"4242","intitule":"Allocations familiales"},{"numero":"4245","intitule":"Organismes sociaux rattachés à l\'entité"},{"numero":"4248","intitule":"Autres œuvres sociales internes"},{"numero":"425","intitule":"REPRESENTANTS DU PERSONNEL"},{"numero":"4251","intitule":"Délégués du personnel"},{"numero":"4252","intitule":"Syndicats et Comités d\'entreprise, d\'établissement"},{"numero":"4258","intitule":"Autres représentants du personnel"},{"numero":"426","intitule":"PERSONNEL, PARTICIPATION AUX BENEFICES ET AU CAPITAL"},{"numero":"4261","intitule":"Participation aux bénéfices"},{"numero":"4264","intitule":"Participation au capital"},{"numero":"427","intitule":"PERSONNEL-DEPÔTS"},{"numero":"428","intitule":"PERSONNEL, CHARGES A PAYER ET PRODUITS A RECEVOIR"},{"numero":"4281","intitule":"Dettes provisionnées pour congés à payer"},{"numero":"4286","intitule":"Autres charges à payer"},{"numero":"4287","intitule":"Produits à recevoir"}],"fonctionnement":"Le compte 42 – PERSONNEL est crédité des rémunérations brutes à payer au\\npersonnel (ou au comité d\' entreprise)\\n- par le débit des comptes de charges intéressés 66 – Charges de personnel.\\nLe compte 42 – PERSONNEL est débité du montant des avances et acomptes faits au\\npersonnel (ou au comité d\'entreprise) ainsi que des rémunérations versées au\\npersonnel\\n- par le crédit des comptes de trésorerie.\\nLe compte 42 – PERSONNEL est débité des sommes dues par le personnel\\n- par le crédit des comptes de produits (services exploités dans l\'intérêt du\\npersonnel, etc.).\\nLe compte 42 – PERSONNEL est débité des versements effectués aux organismes\\nsociaux pour le compte du personnel (cotisations salariales)\\n- par le crédit du compte 43 – Organismes sociaux.\\nLe compte 42 – PERSONNEL est débité, en cas d\'opposition de tiers sur salaires, du\\nversement de la fraction de salaire soumise à saisie\\n- par le crédit des comptes de trésorerie.","commentaires":"Les opérations traitées par ce compte concernent, d\'une part, les rémunérations\\ndues au personnel, les avances et acomptes consentis au personnel et, d\'autre part,\\n- les versements effectués aux œuvres sociales internes et la fraction du salaire\\nsoumise à saisie, en cas d\'opposition de tiers.\\nLe compte 426 Personnel participation aux bénéfices et au capital enregistre\\n- les sommes attribués au personnel après la date d\'approbation des comptes par\\n- l\'assemblée générale ordinaire des actionnaires ou des associés ;\\n- l\'attribution gratuite d\'actions au personnel salarié et aux dirigeants par\\nprélèvement obligatoire sur la part des bénéfices ou par rachat par la société de\\nses propres actions (voir titre VIII Opérations spécifiques, Chapitre 19).\\nSi l\'attribution gratuite des actions au personnel salarié et aux dirigeants est\\nréalisée par un prélèvement sur la part des réserves. Le compte de réserves\\n(compte 1132) sera débité par le crédit du compte de capital (compte 1013). Les\\nactions attribuées au personnel salarié seront mentionnées sur le registre des titres\\nnominatifs des actions.\\nA la clôture de l\'exercice, il ne doit pas être effectué de compensation entre les\\nsommes dues au personnel et les montants qui seraient éventuellement dus par le\\npersonnel et qui n\'auraient pas été retenus sur la dernière paie de l\'exercice.","exclusions":"Le compte 42 – PERSONNEL ne doit pas servir à enregistrer :\\n- les prêts consentis au personnel\\n- les opérations en comptes courants des associés et administrateurs pour les\\nmouvements de fonds n\'intéressant pas la rémunération de leur travail\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n- 272 – Prêts au personnel\\n46 – Apporteurs, Associés et Groupe","controle":"Le compte 42 – PERSONNEL peut être contrôlé à partir :\\ndes fiches de paie ;\\ndes déclarations sociales ;\\ndes contrats de prêts ;\\ndes procès-verbaux de saisie-arrêt ;\\ndes avis à tiers détenteur.","motsCles":["personnel"]},{"numero":"43","intitule":"Organismes sociaux","classe":4,"classeLabel":"Comptes de tiers","groupe":"A","contenu":"Ce compte enregistre, d\'une part, le montant des cotisations sociales salariales et\\npatronales dues aux organismes sociaux et, d\'autre part, les règlements de\\ncotisations effectués à leur profit.","subdivisions":[{"numero":"431","intitule":"SECURITE SOCIALE"},{"numero":"4311","intitule":"Prestations familiales"},{"numero":"4312","intitule":"Accidents du travail"},{"numero":"4313","intitule":"Caisse de retraite obligatoire"},{"numero":"4314","intitule":"Caisse de retraite facultative"},{"numero":"4318","intitule":"Autres cotisations sociales"},{"numero":"432","intitule":"CAISSES DE RETRAITE COMPLEMENTAIRE"},{"numero":"433","intitule":"AUTRES ORGANISMES SOCIAUX"},{"numero":"4331","intitule":"Mutuelle"},{"numero":"4332","intitule":"Assurances retraite"},{"numero":"4333","intitule":"Assurances et organismes de santé"},{"numero":"438","intitule":"ORGANISMES SOCIAUX, CHARGES A PAYER ET PRODUITS A RECEVOIR"},{"numero":"4381","intitule":"Charges sociales sur gratifications à payer"},{"numero":"4382","intitule":"Charges sociales sur congés à payer"},{"numero":"4386","intitule":"Autres charges à payer"},{"numero":"4387","intitule":"Produits à recevoir"}],"fonctionnement":"Le compte 43 – ORGANISMES SOCIAUX est crédité du montant des cotisations\\nsociales, salariales et patronales dues aux organismes sociaux\\n- par le débit du compte 664 – Charges sociales, pour la part patronale ;\\net par le débit du compte 422 – Personnel, rémunérations dues, pour la part\\nsalariale.\\nLe compte 43 – ORGANISMES SOCIAUX est débité des règlements de cotisations\\neffectués aux organismes sociaux\\n- par le crédit des comptes de trésorerie concernés.","commentaires":"Les obligations de l\'entité vis-à-vis des organismes sociaux sont remplies à partir\\ndes procédures comptables définies dans le\\nSystème Comptable OHADA.","exclusions":"Le compte 43 – ORGANISMES SOCIAUX ne doit pas servir à enregistrer :\\n- les opérations faites avec les organismes sociaux en tant que clients\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n41 – Clients et comptes rattachés","controle":"Le compte 43 – ORGANISMES SOCIAUX peut être contrôlé à partir :\\ndes fiches de paie ;\\ndes bordereaux de déclarations sociales ;\\ndes livres de paie.","motsCles":["organismes","sociaux"]},{"numero":"44","intitule":"Etat et Collectivités publiques","classe":4,"classeLabel":"Comptes de tiers","groupe":"A","contenu":"Les opérations à inscrire à ce compte concernent d\'une manière générale les\\nopérations qui sont faites avec l\'Etat et avec les diverses collectivités publiques en\\ntant que pouvoirs publics.","subdivisions":[{"numero":"441","intitule":"ETAT, IMPÔT SUR LES BENEFICES"},{"numero":"442","intitule":"ETAT, AUTRES IMPÔTS ET TAXES"},{"numero":"4421","intitule":"Impôts et taxes d\'Etat"},{"numero":"4422","intitule":"Impôts et taxes pour les collectivités publiques"},{"numero":"4423","intitule":"Impôts et taxes recouvrables sur des obligataires"},{"numero":"4424","intitule":"Impôts et taxes recouvrables sur des associés"},{"numero":"4426","intitule":"Droits de douane"},{"numero":"4428","intitule":"Autres impôts et taxes"},{"numero":"443","intitule":"ETAT, T.V.A. FACTUREE"},{"numero":"4431","intitule":"T.V.A. facturée sur ventes"},{"numero":"4432","intitule":"T.V.A. facturée sur prestations de services"},{"numero":"4433","intitule":"T.V.A. facturée sur travaux"},{"numero":"4434","intitule":"T.V.A. facturée sur production livrée à soi-même"},{"numero":"4435","intitule":"T.V.A. sur factures à établir"},{"numero":"444","intitule":"ETAT, T.V.A. DUE OU CREDIT DE T.V.A."},{"numero":"4441","intitule":"Etat, T.V.A. due"},{"numero":"4449","intitule":"Etat, crédit de T.V.A. à reporter"},{"numero":"445","intitule":"ETAT, T.V.A. RECUPERABLE"},{"numero":"4451","intitule":"T.V.A. récupérable sur immobilisations"},{"numero":"4452","intitule":"T.V.A. récupérable sur achats"},{"numero":"4453","intitule":"T.V.A. récupérable sur transport"},{"numero":"4454","intitule":"T.V.A. récupérable sur services extérieurs et autres charges"},{"numero":"4455","intitule":"T.V.A. récupérable sur factures non parvenues"},{"numero":"4456","intitule":"T.V.A. transférée par d\'autres entités"},{"numero":"446","intitule":"ETAT, AUTRES TAXES SUR LE CHIFFRE D\'AFFAIRES"},{"numero":"447","intitule":"ETAT, IMPÔTS RETENUS A LA SOURCE"},{"numero":"4471","intitule":"Impôt général sur le revenu"},{"numero":"4472","intitule":"Impôts sur salaires"},{"numero":"4473","intitule":"Contribution nationale"},{"numero":"4474","intitule":"Contribution nationale de solidarité"},{"numero":"4478","intitule":"Autres impôts et contributions"},{"numero":"448","intitule":"ETAT, CHARGES A PAYER ET PRODUITS A RECEVOIR"},{"numero":"4486","intitule":"Charges à payer"},{"numero":"4487","intitule":"Produits à recevoir"},{"numero":"449","intitule":"ETAT, CREANCES ET DETTES DIVERSES"},{"numero":"4491","intitule":"Etat, obligations cautionnées"},{"numero":"4492","intitule":"Etat, avances et acomptes versés sur impôts"},{"numero":"4493","intitule":"Etat, fonds de dotation à recevoir"},{"numero":"4494","intitule":"Etat, subventions d\'équipement à recevoir"},{"numero":"4495","intitule":"Etat, subventions d\'exploitation à recevoir"},{"numero":"4496","intitule":"Etat, subventions d\'équilibre à recevoir"},{"numero":"4497","intitule":"Etat avances sur subventions"},{"numero":"4499","intitule":"Etat, fonds réglementé provisionné"}],"fonctionnement":"Le compte 44 – ETAT ET COLLECTIVITÉS PUBLIQUES est crédité lors de la\\nconstatation par l\'entité des dettes d\'impôts dont elle est redevable envers l\'Etat\\n- par le débit des comptes de charges intéressés.\\nLe compte 44 – ETAT ET COLLECTIVITÉS PUBLIQUES est crédité lors du règlement\\npar l\'Etat des sommes dues à l\'entité\\n- par le débit des comptes de trésorerie.\\nLe compte 44 – ETAT ET COLLECTIVITÉS PUBLIQUES est débité des sommes versées\\nlors du règlement par l\'entité à l\'Etat\\n- par le crédit des comptes de trésorerie concernés.\\nLe compte 44 – ETAT ET COLLECTIVITÉS PUBLIQUES est débité lors de la\\nconstatation de la dette de l\'Etat envers l\'entité (fonds de dotation, subventions, etc.)\\n- par le crédit des comptes concernés des classes 1 et 4 ou des classes 7 et 8,\\nselon la qualification des fonds alloués.","commentaires":"Les opérations d\'achats et de ventes de biens ou de services avec l\'Etat et les\\ncollectivités publiques s\'inscrivent aux comptes 40 – Fournisseurs et comptes\\nrattachés et 41 – Clients et comptes rattachés, au même titre que les opérations\\nfaites avec les autres fournisseurs et les autres clients.\\nLes dettes du compte 442 – Etat, autres impôts et taxes comprennent non\\nseulement les impôts et taxes d\'Etat proprement dits tels que droits de douane à\\n- l\'exportation, mais, aussi, les impôts et taxes perçus pour le compte des collectivités\\nlocales.","exclusions":"Le compte 44 – ETAT ET COLLECTIVITÉS PUBLIQUES ne doit pas servir à\\nenregistrer :\\n- les opérations faites avec l\'Etat en tant que fournisseur\\n- les opérations faites avec l\'Etat en tant que client\\n- les droits de douane acquittés à l\'entrée des biens sur le territoire national\\nfaisant partie du prix d\'achat du bien\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n40 – Fournisseurs et comptes rattachés\\n41 – Clients et comptes rattachés\\ncomptes de la classe 2 ou 6 concernés","controle":"Le compte 44 – ETAT ET COLLECTIVITÉS PUBLIQUES peut être contrôlé à partir :\\ndes avis d\'imposition ;\\ndes déclarations fiscales ;\\ndes relevés bancaires.","motsCles":["etat","collectivites","publiques"]},{"numero":"45","intitule":"Organismes internationaux","classe":4,"classeLabel":"Comptes de tiers","groupe":"A","contenu":"Les opérations à inscrire à ce compte concernent les dettes et créances autres que\\ncelles liées à l\'activité de l\'entité.\\nElles concernent exclusivement le montant des dépenses dont l\'entité doit assumer\\nla charge, les dettes des organismes internationaux vis-à-vis de l\'entité et, d\'autre\\npart, les dettes de l\'entité vis-à-vis des organismes internationaux et le règlement\\npar ces derniers des sommes dues à l\'entité.","subdivisions":[{"numero":"451","intitule":"OPERATIONS AVEC LES ORGANISMES AFRICAINS"},{"numero":"452","intitule":"OPERATIONS AVEC LES AUTRES ORGANISMES INTERNATIONAUX"},{"numero":"458","intitule":"ORGANISMES INTERNATIONAUX, FONDS DE DOTATION ET SUBVENTIONS À RECEVOIR"},{"numero":"4581","intitule":"Organismes internationaux, fonds de dotation à recevoir"},{"numero":"4582","intitule":"Organismes internationaux, subventions à recevoir"}],"fonctionnement":"Le compte 45 – ORGANISMES INTERNATIONAUX est crédité lors de la constatation\\npar l\'entité des dettes dont elle est redevable envers les organismes internationaux\\n- par le débit des comptes de charges concernés.\\nou d\'immobilisations\\nLe compte 45 – ORGANISMES INTERNATIONAUX est crédité lors du règlement par\\n- les organismes internationaux de sommes dues à l\'entité\\n- par le débit des comptes de trésorerie.\\nLe compte 45 – ORGANISMES INTERNATIONAUX est débité des dépenses dont\\n- l\'entité doit assumer la charge\\n- par le crédit des comptes de trésorerie concernés lors du règlement par\\n- l\'entité aux organismes internationaux.\\nLe compte 45 – ORGANISMES INTERNATIONAUX est débité lors de la constatation\\nde la dette des organismes internationaux envers l\'entité (fonds de dotation,\\nsubventions, etc.)\\n- par le crédit des comptes concernés des classes 1 et 4 ou des classes 7 et 8,\\nselon la qualification des fonds alloués.","commentaires":"","exclusions":"Le compte 45 – ORGANISMES INTERNATIONAUX ne doit pas servir à enregistrer :\\n- les opérations faites avec les organismes internationaux en tant que\\nfournisseurs\\n- les opérations faites avec les organismes internationaux en tant que clients\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n40 – Fournisseurs et comptes rattachés\\n41 – Clients et comptes rattachés","controle":"Le compte 45 – ORGANISMES INTERNATIONAUX peut être contrôlé à partir :\\ndes relevés bancaires ;\\ndes avis de versement ;\\ndes avis d\'octroi de subventions.","motsCles":["organismes","internationaux"]},{"numero":"46","intitule":"Apporteurs, Associés et Groupe","classe":4,"classeLabel":"Comptes de tiers","groupe":"A","contenu":"Le compte 46 enregistre :\\nd\'une part les créances/dettes envers les associés résultant des divers\\nmouvements du capital social ;\\nd\'autre part les créances/dettes temporaires en comptes courants.\\nEn ce qui concerne ces derniers, le plan de comptes distingue les associés\\nordinaires et, dans le cas d\'appartenance à un groupe, les autres sociétés du groupe","subdivisions":[{"numero":"461","intitule":"APPORTEURS, OPERATIONS SUR LE CAPITAL"},{"numero":"4611","intitule":"Apporteurs, apports en nature"},{"numero":"4612","intitule":"Apporteurs, apports en numéraire"},{"numero":"4613","intitule":"Apporteurs, capital souscrit appelé non versé"},{"numero":"4614","intitule":"Apporteurs, capital appelé non versé"},{"numero":"4615","intitule":"Apporteurs, versements reçus sur augmentation de capital"},{"numero":"4616","intitule":"Apporteurs, versements anticipés"},{"numero":"4617","intitule":"Apporteurs défaillants"},{"numero":"4618","intitule":"Apporteurs, autres apports"},{"numero":"4619","intitule":"Apporteurs, capital à rembourser"},{"numero":"462","intitule":"ASSOCIES(1), COMPTES COURANTS"},{"numero":"4621","intitule":"Principal"},{"numero":"4626","intitule":"Intérêts courus"},{"numero":"463","intitule":"ASSOCIES(1), OPERATIONS FAITES EN COMMUN"},{"numero":"465","intitule":"ASSOCIES(1), DIVIDENDES A PAYER"},{"numero":"466","intitule":"GROUPE, COMPTES COURANTS"},{"numero":"467","intitule":"APPORTEURS, RESTANT DÛ SUR CAPITAL APPELE"}],"fonctionnement":"Le compte 46 – APPORTEURS, ASSOCIES ET GROUPE est crédité des sommes dues à\\ntitre de dividendes\\n- par le débit des comptes Résultat, Réserves, Report à nouveau.\\nLe compte 46 – APPORTEURS ASSOCIES ET GROUPE est crédité des fonds mis ou\\nlaissés temporairement à la disposition de la société\\n- par le débit des comptes de trésorerie (ou de charges, s\'il s\'agit de frais\\nréglés pour le compte de l\'entité).\\nLe compte 46 – APPORTEURS ASSOCIES ET GROUPE est débité des sommes réglées\\nau titre des dividendes\\n- par le crédit des comptes de trésorerie (ou des comptes courants).\\nLe compte 46 – APPORTEURS ASSOCIES ET GROUPE est débité des fonds prélevés\\npar les associés ou des règlements effectués pour leur compte par l\'entité\\n- par le crédit des comptes de trésorerie (ou des comptes de charges).","commentaires":"Sont réputés associés les membres des sociétés de capitaux, des sociétés de\\npersonnes, des sociétés de fait et des sociétés en participation. La SARL a la\\npossibilité de libérer le capital sur une durée de deux années à compter de son\\nimmatriculation au registre du commerce depuis la révision de l\'Acte uniforme\\nrelatif au droit des sociétés commerciales et GIE.\\nIl y a lieu de comptabiliser dans des sous- comptes particuliers les opérations\\nsuivantes concernant le capital :\\nla dette contractée par les associés, lors de la souscription du capital ;\\n- le règlement de cette dette par les associés ;\\n- le restant dû sur le capital appelé ;\\n- les fonds laissés ou mis temporairement à la disposition de l\'entité par les\\nassociés ;\\n- les versements reçus par la société sur augmentation de capital ;\\n- les sommes dues et réglées par la société au titre des dividendes.\\nLes mouvements du compte 461 – Apporteurs, opérations sur le capital concernent\\ntous les associés, y compris les autres sociétés du groupe, associées de l\'entité.\\nLes créances/dettes envers les sociétés du groupe, autres que celles enregistrées\\ndans le compte 466 – Groupe, comptes courants, sont comptabilisées : – dans les\\ncomptes de tiers 40 – Fournisseurs et 41 – Clients en ce qui concerne les opérations\\ncommerciales ; – dans les comptes 16, 18 et 27 en ce qui concerne les opérations\\nfinancières.","exclusions":"Le compte 46 – APPORTEURS ASSOCIES ET GROUPE ne doit pas servir à enregistrer\\n:\\n- les dettes et créances des associés contractées ou consenties\\n- les emprunts et les prêts des associés\\nla dette des associés, représentative du capital souscrit non appelé\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n16 – Emprunts et dettes assimilées\\n27 – Autres immobilisations financières\\n- 109 – Apporteurs, capital souscrit, non appelé","controle":"Le compte 46 – APPORTEURS, ASSOCIES ET GROUPE peut être contrôlé à partir des\\ndécisions des\\nAssemblées d\'actionnaires.","motsCles":["apporteurs","associes","groupe"]},{"numero":"47","intitule":"Débiteurs et créditeurs divers","classe":4,"classeLabel":"Comptes de tiers","groupe":"A","contenu":"Ce compte enregistre les opérations en instance de régularisation et relatives aux\\ncréances et dettes liées à l\'acquisition de titres, des charges non consommées, des\\nproduits constatés d\'avance, des écarts sur opérations libellées en monnaies\\nétrangères, et des créances sur travaux non encore facturables.","subdivisions":[{"numero":"471","intitule":"DEBITEURS ET CREDITEURS DIVERS"},{"numero":"4711","intitule":"Débiteurs divers"},{"numero":"4712","intitule":"Créditeurs divers"},{"numero":"4713","intitule":"Obligataires"},{"numero":"4714","intitule":"Créances sur cessions de titres de placement"},{"numero":"4715","intitule":"Rémunérations d\'administrateurs"},{"numero":"4716","intitule":"Compte du factor"},{"numero":"4717","intitule":"Débiteurs divers- retenues de garantie"},{"numero":"4718","intitule":"Apport, compte de restructuration"},{"numero":"4719","intitule":"Bons de souscription d\'actions et d\'obligations"},{"numero":"472","intitule":"VERSEMENTS RESTANT A EFFECTUER SUR TITRES DE PLACEMENT NON LIBERES"},{"numero":"473","intitule":"INTERMEDIAIRES – OPERATIONS FAITES POUR LE COMPTE DE TIERS"},{"numero":"4731","intitule":"Mandants"},{"numero":"4732","intitule":"Mandataires"},{"numero":"4733","intitule":"Commettants"},{"numero":"4734","intitule":"Commissionnaires"},{"numero":"474","intitule":"REPARTITION PERIODIQUE DES CHARGES ET DES PRODUITS"},{"numero":"4746","intitule":"Charges"},{"numero":"4747","intitule":"Produits"},{"numero":"475","intitule":"COMPTE TRANSITOIRE, AJUSTEMENT SPECIAL LIE A LA REVISION SYSCOHADA"},{"numero":"4751","intitule":"Compte actif"},{"numero":"4752","intitule":"Compte passif"},{"numero":"476","intitule":"CHARGES CONSTATEES D\'AVANCE"},{"numero":"477","intitule":"PRODUITS CONSTATES D\'AVANCE"},{"numero":"478","intitule":"ECARTS DE CONVERSION-ACTIF"},{"numero":"4781","intitule":"Diminution des créances"},{"numero":"4782","intitule":"Augmentation des dettes"},{"numero":"4788","intitule":"Différences compensées par couverture de change"},{"numero":"479","intitule":"ECARTS DE CONVERSION- PASSIF"},{"numero":"4791","intitule":"Augmentation des créances"},{"numero":"4792","intitule":"Diminution des dettes"},{"numero":"4798","intitule":"Différences compensées par couverture de change"}],"fonctionnement":"Le compte 47 – DEBITEURS ET CREDITEURS DIVERS est crédité des dettes\\ncontractées ou des remboursements de créances\\n- par le débit des comptes de trésorerie concernés.\\nLe compte 47 – DEBITEURS ET CREDITEURS DIVERS est crédité des apports\\neffectués par l\'exploitant en cours d\'exercice\\n- par le débit des comptes de trésorerie concernés.\\nLe compte 47 – DEBITEURS ET CREDITEURS DIVERS est crédité des virements\\nrestant à effectuer sur des titres non encore totalement libérés\\n- par le débit du compte 26 – Titres de participation ; ou du compte 274 –\\nTitres immobilisés ; ou du compte 50 – Titres de placement.\\nLe compte 47 – DEBITEURS ET CREDITEURS DIVERS est crédité, à la clôture de\\n- l\'exercice, des produits perçus pendant l\'exercice et se rattachant à l\'exercice à\\nvenir (produits constatés d\'avance)\\n- par le débit des comptes de produits concernés.\\nLe compte 47 – DEBITEURS ET CREDITEURS DIVERS est débité des créances sur les\\ntiers ou du remboursement des dettes contractées\\n- par le crédit d\'un compte de tiers ou des comptes de trésorerie concernés.\\nLe compte 47 – DEBITEURS ET CREDITEURS DIVERS est débité des retraits effectués\\npar l\'exploitant en cours d\'exercice\\n- par le crédit d\'un compte de trésorerie.\\nLe compte 47 – DEBITEURS ET CREDITEURS DIVERS est débité, à la clôture de\\n- l\'exercice, des charges payées pendant l\'exercice et se rattachant à l\'exercice à venir\\n(charges payées d\'avance)\\n- par le crédit des comptes de charges concernés.","commentaires":"Aucune compensation n\'est en principe admise entre les dettes et les créances dont\\n- les soldes créditeurs et débiteurs doivent être inscrits au bilan dans les rubriques\\nAutres créances à l\'actif et Autres dettes au passif.\\nLors de l\'acquisition de titres de placement non libérés entièrement par l\'entité, la\\nvaleur globale est portée au compte d\'actif immobilisé concerné, y compris les\\nmontants non encore appelés. Ces derniers figurent au compte 472 – Versements\\nrestant à effectuer sur titres de placement non encore libérés.\\nLe compte 474 répartition périodique des charges et des produits est traité au Titre\\nVIII Opérations spécifiques, Chapitre 24.\\nLe compte 475 compte transitoire, ajustement spécial lié à la révision du\\nSYSCOHADA ne doit servir à enregistrer que les comptes d\'actifs et du passif\\nsupprimés ou traités autrement par le SYSCOHADA révisé.\\nLes comptes 478 – Ecarts de conversion – Actif et 479 – Ecarts de conversion –\\nPassif (prévus pour l\'enregistrement des pertes et gains latents) permettent de\\nconstater, à la clôture de l\'exercice, les écarts entre créances et dettes en devises\\nconverties en unités monétaires légales du pays, telles qu\'elles figurent en\\ncomptabilité, et leur évaluation en unités monétaires légales du pays à la date de\\nclôture de l\'exercice.","exclusions":"Le compte 47 – DEBITEURS ET CREDITEURS DIVERS ne doit pas servir à enregistrer\\n:\\n- les charges imputables au compte\\nFournisseurs\\n- les produits imputables au compte Clients\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n40 – Fournisseurs et comptes rattachés\\n41 – Clients et comptes rattachés","controle":"Le compte 47 – DEBITEURS ET CREDITEURS DIVERS peut être contrôlé à partir :\\ndes contrats ;\\ndes conventions ;\\ndes décomptes de régularisation ;\\ndes chèques ;\\ndes relevés de banque.","motsCles":["debiteurs","crediteurs","divers"]},{"numero":"48","intitule":"Créances et dettes hors activités ordinaires","classe":4,"classeLabel":"Comptes de tiers","groupe":"A","contenu":"Ce sont des créances et des dettes consécutives à des opérations effectuées par\\n- l\'entité mais n\'ayant pas de lien direct avec l\'activité ordinaire de l\'entité.","subdivisions":[{"numero":"481","intitule":"FOURNISSEURS D\'INVESTISSEMENTS"},{"numero":"4811","intitule":"Immobilisations incorporelles"},{"numero":"4812","intitule":"Immobilisations corporelles"},{"numero":"4813","intitule":"Versements restant à effectuer sur titres de participation et titres immobilisés non"},{"numero":"4817","intitule":"Retenues de garantie"},{"numero":"4818","intitule":"Factures non parvenues"},{"numero":"482","intitule":"FOURNISSEURS D\'INVESTISSEMENTS EFFETS A PAYER"},{"numero":"484","intitule":"AUTRES DETTES HORS ACTIVITES ORDINAIRES (H.A.O.)"},{"numero":"485","intitule":"CREANCES SUR CESSIONS D\'IMMOBILISATIONS"},{"numero":"4851","intitule":"en compte"},{"numero":"4852","intitule":"Effets à recevoir"},{"numero":"4857","intitule":"Retenues de garantie"},{"numero":"4858","intitule":"Factures à établir"},{"numero":"488","intitule":"AUTRES CREANCES HORS ACTIVITES ORDINAIRES (H.A.O.)"}],"fonctionnement":"Le compte 48 – CREANCES ET DETTES HORS ACTIVITES ORDINAIRES est crédité\\ndes dettes H.A.O.\\ncontractées ou des remboursements de créances H.A.O.\\n- par le débit des comptes de trésorerie concernés ou des comptes de la classe\\n8.\\nLe compte 48 – CREANCES ET DETTES HORS ACTIVITES ORDINAIRES est débité des\\ncréances H.A.O. sur les tiers ou des remboursements de dettes H.A.O.\\n- par le crédit des comptes de trésorerie concernés ou des comptes de la\\nclasse 8.","commentaires":"La mise en évidence au bilan des créances et des dettes hors activités ordinaires par\\n- l\'intermédiaire du compte 48 permet de mesurer directement le besoin ou la\\nressource de financement H.A.O., en parallèle avec le besoin ou la ressource de\\nfinancement de l\'exploitation.\\nLes créances sur cessions d\'immobilisations sont considérées comme\\nH.A.O. dans tous les cas où elles concernent des opérations n\'entrant pas dans\\n- l\'activité normale et courante de l\'entité. Dans le cas contraire, elles constituent des\\ncréances rattachées au compte Client (compte 414) et sont débitées par le crédit du\\ncompte 754 – Produits des cessions courantes d\'immobilisations.","exclusions":"Le compte 48 – CREANCES ET DETTES HORS ACTIVITES ORDINAIRES ne doit pas\\nservir à enregistrer les dettes ou les créances ayant pour origine les activités\\nordinaires de l\'entité\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n40 – Fournisseurs et comptes rattachés\\n41 – Clients et comptes rattachés","controle":"Le compte 48 – CREANCES ET DETTES HORS ACTIVITES ORDINAIRES peut être\\ncontrôlé à partir :\\ndes chèques ;\\ndes effets de commerce ;\\ndes contrats d\'acquisition d\'immobilisations ;\\ndes factures ;\\ndes ordres de mouvements en Bourse.","motsCles":["creances","dettes","hors","activites","ordinaires"]},{"numero":"49","intitule":"Dépréciations et provisions pour risques à court terme (Tiers)","classe":4,"classeLabel":"Comptes de tiers","groupe":"A","contenu":"Ce sont des dépréciations subies par des comptes de tiers résultant de causes\\ndiverses dont les effets ne sont pas jugés irréversibles.","subdivisions":[{"numero":"490","intitule":"DÉPRÉCIATIONS DES COMPTES FOURNISSEURS"},{"numero":"491","intitule":"DEPRECIATIONS DES COMPTES CLIENTS"},{"numero":"4911","intitule":"Créances litigieuses"},{"numero":"4912","intitule":"Créances douteuses"},{"numero":"492","intitule":"DEPRECIATIONS DES COMPTES PERSONNEL"},{"numero":"493","intitule":"DEPRECIATIONS DES COMPTES ORGANISMES SOCIAUX"},{"numero":"494","intitule":"DÉPRÉCIATIONS DES COMPTES ÉTAT ET COLLECTIVITÉS PUBLIQUES"},{"numero":"495","intitule":"DEPRECIATIONS DES COMPTES ORGANISMES INTERNATIONAUX"},{"numero":"496","intitule":"DEPRECIATIONS DES COMPTES APPORTEURS ASSOCIES ET GROUPE"},{"numero":"4962","intitule":"Associés, comptes courants"},{"numero":"4963","intitule":"Associés, opérations faites en commun"},{"numero":"4966","intitule":"Groupe, comptes courants"},{"numero":"497","intitule":"DEPRECIATIONS DES COMPTES DEBITEURS DIVERS"},{"numero":"498","intitule":"DEPRECIATIONS DES COMPTES DE CREANCES H.A.O."},{"numero":"4981","intitule":"Créances sur cessions d\'immobilisations"},{"numero":"4982","intitule":"Créances sur cessions de titres de placement"},{"numero":"4983","intitule":"Autres créances H.A.O."},{"numero":"499","intitule":"PROVISIONS POUR RISQUES A COURT TERME"},{"numero":"4991","intitule":"sur opérations d\'exploitation"},{"numero":"4998","intitule":"sur opérations H.A.O."}],"fonctionnement":"Le compte 49 – DEPRECIATIONS ET PROVISIONS POUR RISQUES A COURT TERME\\n(TIERS) est crédité à la clôture de l\'exercice des dépréciations constatées sur les\\néléments d\'actif de la classe 4 (comptes 41 à 48) ou des provisions pour risques à\\ncourt terme, compte 499\\n- par le débit du compte 659 – Charges pour dépréciations et provisions pour\\nrisques à court terme d\'exploitation\\n- ou par le débit du compte 839 – Charges pour dépréciations et provisions pour\\nrisques à court terme H.A.O.\\nLe compte 49 – DEPRECIATIONS ET PROVISIONS POUR RISQUES A COURT TERME\\n(TIERS) est débité à la clôture de l\'exercice de la reprise des dépréciations\\nconstatées à la clôture d\'un exercice antérieur sur les éléments d\'actif de la classe 4\\n(comptes 41 à 48) ou des provisions pour risques à court terme (compte 499) dont\\n- les raisons qui les ont motivées ont cessé d\'exister\\n- par le crédit du compte 759 – Reprises de charges pour dépréciations et de\\nprovisions pour risques à court terme d\'exploitation ;\\n- ou par le crédit du compte 849 – Reprises de charges pour dépréciations et\\nprovisions pour risques à court terme charges\\nH.A.O.","commentaires":"Les dépréciations des comptes de tiers obéissent aux mêmes règles de\\ncomptabilisation que les dépréciations constatées sur les stocks et les comptes de\\ntrésorerie.\\nLa dépréciation doit être certaine quant à sa nature et l\'élément d\'actif en cause\\ndoit être individualisé. En l\'occurrence, les entités désireuses de constituer des\\ndépréciations doivent être en mesure :\\nde préciser exactement la nature et l\'objet des créances à déprécier ;\\nde justifier les motifs qui rendent les créances douteuses et litigieuses.\\nLa dotation est à constituer même si la dépréciation est d\'un montant incertain.\\nLa dépréciation traduit une baisse non définitive et non irréversible de l\'évaluation\\ndes éléments d\'actif par rapport à leur valeur comptable.\\nLes événements générateurs de dépréciations survenus après la clôture de\\n- l\'exercice ne sont pas pris en compte dans ledit exercice ; les dotations ne doivent\\nêtre constituées que pour des dépréciations subies au cours de l\'exercice, et à la\\nclôture de l\'exercice.\\nLa dépréciation doit être constituée même en l\'absence ou en cas d\'insuffisance de\\nbénéfices, conformément au principe de prudence.\\nLorsque, au jour de l\'inventaire, la valeur économique réelle des créances est\\ninférieure à leur valeur comptable déterminée conformément aux dispositions\\nprécédemment exposées, les entités doivent constituer des dépréciations qui\\nexpriment les moins-values constatées sur ces comptes de tiers.\\nCes dépréciations sont portées à l\'actif du bilan, en déduction de la valeur des\\npostes qu\'elles concernent, sous la forme prévue par le modèle de bilan.\\nLes provisions pour risques à court terme sont liées au mécanisme des charges et\\nreprésentent une dette probable à moins d\'un an.\\nLes dépréciations et les provisions pour risques à court terme correspondent à des\\ncharges d\'exploitation ou H.A.O. selon leur nature.","exclusions":"Le compte 49 – DEPRECIATIONS ET PROVISIONS POUR RISQUES À COURT TERME\\n(TIERS) ne doit pas servir à enregistrer :\\n- les provisions pour risques et charges à plus d\'un an\\n- les dépréciations des éléments (classe 2) de l\'actif immobilisé\\n- les dépréciations des comptes de trésorerie (classe 5)\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\ncompte 19 – Provisions financières pour risques et charges\\ncompte 29 – Dépréciations\\ncompte 59 – Dépréciations et provisions pour risques à court terme (Trésorerie)","controle":"Le compte 49 – DEPRECIATIONS ET PROVISIONS POUR RISQUES A COURT TERME\\n(TIERS) peut être contrôlé à partir de tous documents à même de justifier les motifs\\nqui rendent la créance douteuse ou litigieuse (courriers et autres protêts,\\njustificatifs du caractère douteux ou litigieux de la créance).\\n\\n# CLASSE 5 : COMPTES DE TRÉSORERIE\\nLes comptes de la classe 5 enregistrent les opérations relatives aux valeurs en\\nespèces, aux chèques, aux monnaies électroniques aux effets de commerce, aux\\ntitres de placement, aux coupons ainsi qu\'aux opérations faites avec les\\nétablissements de crédit.\\nAucune compensation ne doit être effectuée au bilan entre les soldes débiteurs et\\n- les soldes créditeurs des comptes de la classe 5.\\nLes comptes de la classe 5 peuvent être assortis de comptes de provisions pour\\ndépréciation, notamment les provisions pour dépréciation des titres de placement ;\\nces dernières provisions doivent résulter de l\'évaluation comptable des moins-\\nvalues constatées sur les éléments d\'actif considérés.","motsCles":["depreciations","provisions","risques","court","terme","tiers"]},{"numero":"50","intitule":"Titres de placement","classe":5,"classeLabel":"Comptes de trésorerie","groupe":"A","contenu":"Ce sont des titres cessibles, acquis en vue d\'en retirer un revenu direct ou une plus-\\nvalue à brève échéance.","subdivisions":[{"numero":"501","intitule":"TITRES DU TRESOR ET BONS DE CAISSE A COURT TERME"},{"numero":"5011","intitule":"Titres du Trésor à court terme"},{"numero":"5012","intitule":"Titres d\'organismes financiers"},{"numero":"5013","intitule":"Bons de caisse à court terme"},{"numero":"5016","intitule":"Frais d\'acquisition des titres du trésor et bons de caisse"},{"numero":"502","intitule":"ACTIONS"},{"numero":"5021","intitule":"Actions ou parts propres"},{"numero":"5022","intitule":"Actions cotées"},{"numero":"5023","intitule":"Actions non cotées"},{"numero":"5024","intitule":"Actions démembrées (certificats d\'investissement ; droits de vote)"},{"numero":"5025","intitule":"Autres actions"},{"numero":"5026","intitule":"Frais d\'acquisition des actions"},{"numero":"503","intitule":"OBLIGATIONS"},{"numero":"5031","intitule":"Obligations émises par la société et rachetées par elle"},{"numero":"5032","intitule":"Obligations cotées"},{"numero":"5033","intitule":"Obligations non cotées"},{"numero":"5035","intitule":"Autres obligations"},{"numero":"5036","intitule":"Frais d\'acquisition des obligations"},{"numero":"504","intitule":"BONS DE SOUSCRIPTION"},{"numero":"5042","intitule":"Bons de souscription d\'actions"},{"numero":"5043","intitule":"Bons de souscription d\'obligations"},{"numero":"505","intitule":"TITRES NEGOCIABLES HORS REGION"},{"numero":"506","intitule":"INTERÊTS COURUS"},{"numero":"5061","intitule":"Titres du Trésor et bons de caisse à court terme"},{"numero":"5062","intitule":"Actions"},{"numero":"5063","intitule":"Obligations"},{"numero":"508","intitule":"AUTRES VALEURS ASSIMILEES"}],"fonctionnement":"Le compte 50 – TITRES DE PLACEMENT est débité de la valeur d\'apport ou\\nd\'acquisition des titres\\n- par le crédit des comptes de tiers ou de trésorerie concernés.\\nLe compte 50 – TITRES DE PLACEMENT est crédité, en cas de cession des titres, de\\nla valeur d\'entrée\\n- par le débit d\'un compte de tiers ou de trésorerie, pour le prix de cession ;\\n- par le débit du compte 6771 – Pertes sur cessions de titres de placement\\n(cas de cession avec perte) ;\\n- ou par le crédit du compte 777 – Gains sur cessions de titres de placement (cas\\nde cession avec bénéfice).","commentaires":"Les titres de placement comprennent les actions et parts sociales, les obligations et\\n- les bons aisément négociables sur un marché réglementé.\\nReprésentatifs de créances souscrites, ils sont réalisables immédiatement, en cas de\\nnécessité. Productifs d\'intérêts, ils constituent des placements financiers.\\nA leur entrée les titres de placement sont comptabilisés au prix d\'achat, frais\\nd\'achat inclus. Les frais d\'acquisition peuvent être enregistrés dans un sous compte\\nspécifique; à l\'inventaire, ils sont évalués au cours en Bourse, ou, pour les titres non\\ncotés, à leur valeur probable de négociation. Cette valeur est comparée à la valeur\\nd\'achat, frais d\'acquisition inclus pour apprécier la perte de valeur éventuelle ou la\\nplus value générée.\\nLa sortie des titres du patrimoine se fait selon la méthode du premier bien entré est\\n- le premier bien sorti (P.E.P.S.). En cas de cession, la différence entre le prix de\\ncession et la valeur d\'entrée des titres est enregistrée, selon le cas : – au débit du\\ncompte 6771 – Pertes sur cessions de titres de placement ; – au crédit du compte\\n- 777 – Gains sur cessions de titres de placement.","exclusions":"Le compte 50 – TITRES DE PLACEMENT ne doit pas servir à enregistrer :\\n- les titres dont la cession n\'est pas facilement réalisable\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n26 – Titres de participation\\n- 274 – Titres immobilisés","controle":"Le compte 50 – TITRES DE PLACEMENT peut être contrôlé à partir :\\ndes ordres d\'achat ;\\ndes ordres de vente des titres ;\\ndes bordereaux de banque ;\\ndes contrats ;\\ndes relevés de titres en portefeuille.","motsCles":["titres","placement"]},{"numero":"51","intitule":"Valeurs à encaisser","classe":5,"classeLabel":"Comptes de trésorerie","groupe":"A","contenu":"Les valeurs à encaisser sont les effets, chèques et autres valeurs transmis à la\\nbanque et dont l\'entité attend l\'encaissement à l\'échéance.","subdivisions":[{"numero":"511","intitule":"EFFETS A ENCAISSER"},{"numero":"512","intitule":"EFFETS A L\'ENCAISSEMENT"},{"numero":"513","intitule":"CHEQUES A ENCAISSER"},{"numero":"514","intitule":"CHEQUES A L\'ENCAISSEMENT"},{"numero":"515","intitule":"CARTES DE CREDIT A ENCAISSER"},{"numero":"518","intitule":"AUTRES VALEURS A L\'ENCAISSEMENT"},{"numero":"5181","intitule":"Warrants"},{"numero":"5182","intitule":"Billets de fonds"},{"numero":"5185","intitule":"Chèques de voyage"},{"numero":"5186","intitule":"Coupons échus"},{"numero":"5187","intitule":"Intérêts échus des obligations"}],"fonctionnement":"Le compte 51 – VALEURS A ENCAISSER est débité, lors de la réception de l\'effet\\n- par le crédit des comptes de tiers concernés.\\nLe compte 51 – VALEURS A ENCAISSER est crédité du montant des effets, pour solde\\n- par le débit des comptes de trésorerie concernés.","commentaires":"Il est conseillé d\'ouvrir un compte d\'effets à encaisser par échéance, ce qui permet,\\néventuellement, d\'approvisionner les comptes bancaires en fonction des\\nmouvements attendus.\\nLes effets à encaisser sont les effets en portefeuille autres que ceux concernant les\\nclients et enregistrés au compte 412.\\nLes effets à l\'encaissement sont les effets transmis à la banque en vue de\\n- l\'encaissement à l\'échéance.\\nLes chèques à encaisser sont les chèques que l\'entité a reçu de ses clients et qu\'elle\\nn\'a pas encore transmis en banque.\\nLes chèques à l\'encaissement sont les chèques transmis à la banque qui n\'ont pas\\nencore été crédités par cette dernière.\\nLes cartes de crédit à encaisser enregistrent les paiements effectués par cartes de\\ncrédit jusqu\'à l\'avis de crédit de la banque.\\nLes commissions prélevées par la banque pour de tels paiements sont enregistrées\\nen services bancaires.\\nLes autres valeurs à l\'encaissement sont les intérêts des obligations ou les\\ndividendes des actions, échus et non encore encaissés.\\nEn cours d\'exercice, les entités ne sont pas tenues d\'utiliser le compte 51. Par\\ncontre, à la clôture de l\'exercice, il est obligatoire d\'inscrire au débit du compte 51,\\nd\'une part, le montant des chèques non encore remis en banque et qui ne sauraient\\nêtre de ce fait inclus dans l\'avoir disponible chez les banquiers, d\'autre part, les\\ncoupons échus détenus par l\'entité.","exclusions":"Le compte 51 – VALEURS A ENCAISSER ne doit pas servir à enregistrer :\\n- les effets à payer à plus d\'un an d\'échéance\\n- les effets remis à l\'escompte\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n16 – Emprunts et dettes assimilées\\n56 – Banques, crédits de trésorerie et d\'escompte","controle":"Le compte 51 – VALEURS A ENCAISSER peut être contrôlé à partir :\\ndes effets ;\\ndes chèques ;\\ndes bordereaux de remise d\'effets ou de chèques ;\\ndes relevés de banque.","motsCles":["valeurs","encaisser"]},{"numero":"52","intitule":"Banques","classe":5,"classeLabel":"Comptes de trésorerie","groupe":"A","contenu":"Ce compte enregistre les opérations financières effectuées entre l\'entité, les\\nbanques agréées dans un Etat-partie et les autres banques. La liste des banques\\nagréées est tenue par l\'organisme chargé de la surveillance bancaire.","subdivisions":[{"numero":"521","intitule":"BANQUES LOCALES"},{"numero":"5211","intitule":"Banques en monnaie nationale"},{"numero":"5215","intitule":"Banques en devises"},{"numero":"522","intitule":"BANQUES AUTRES ETATS REGION"},{"numero":"523","intitule":"BANQUES AUTRES ETATS ZONE MONETAIRE"},{"numero":"524","intitule":"BANQUES HORS ZONE MONETAIRE"},{"numero":"525","intitule":"BANQUES DEPOT A TERME"},{"numero":"526","intitule":"BANQUES, INTERET COURUS"},{"numero":"5261","intitule":"Banques, intérêts courus, charges à payer"},{"numero":"5267","intitule":"Banques, intérêts courus, produits à recevoir"}],"fonctionnement":"Le compte 52 – BANQUES est débité des mouvements de fonds en faveur des\\ncomptes \\"Banques\\"\\n- par le crédit des comptes concernés.\\nLe compte 52 – BANQUES est crédité des mouvements de fonds en diminution des\\ncomptes \\"Banques\\"\\n- par le débit des comptes concernés.","commentaires":"Il y a lieu de distinguer pour les banques locales, les avoirs en unité monétaire\\nlégale du pays des avoirs en devises. Parmi les premiers, il faudra séparer les avoirs\\nliquides des avoirs soumis à restriction.\\nLe solde qui ressort des livres comptables doit être rapproché du solde du compte\\ntenu par la banque et envoyé périodiquement à l\'entité. Les différences éventuelles\\ndoivent être recherchées et faire l\'objet d\'écritures de redressement lorsqu\'elles\\nn\'ont pas pour origine un chevauchement de dates.\\nLe dépôt bancaire à terme que l\'entité peut débloquer à tout moment doit être\\nconstaté par le débit du compte 525 Banques, dépôts à terme En revanche si l\'entité\\nne peut débloquer le dépôt sur une durée supérieure à un an le compte 2784\\nBanques dépôts à terme sera plus approprié.\\nA la clôture de l\'exercice, les avoirs en monnaies étrangères sont évalués au dernier\\ncours officiel de change connu à cette date.\\nLes comptes bancaires dont le solde apparaît créditeur en fin de période comptable\\nsont inscrits au passif du bilan sous le poste \\"banques, découverts\\", sans\\ncompensation possible avec ceux des comptes bancaires présentant un solde\\ndébiteur.","exclusions":"Le compte 52 – BANQUES ne doit pas servir à enregistrer les mouvements de fonds\\nrelatifs aux opérations avec :\\n- les Chèques postaux et le Trésor\\n- les représentations locales d\'institutions financières internationales ou\\nétrangères\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n53 – Etablissements financiers et assimilés\\n- 538 – Autres organismes financiers","controle":"Le compte 52 – BANQUES peut être contrôlé à partir :\\ndes relevés bancaires ;\\ndes états de rapprochement bancaire.","motsCles":["banques"]},{"numero":"53","intitule":"Etablissements financiers et assimilés","classe":5,"classeLabel":"Comptes de trésorerie","groupe":"A","contenu":"Ce compte enregistre les opérations entre l\'entité et les Chèques postaux et le Trésor\\ndans un Etat de la Région et les autres établissements financiers.","subdivisions":[{"numero":"531","intitule":"CHEQUES POSTAUX"},{"numero":"532","intitule":"TRESOR"},{"numero":"533","intitule":"SOCIETES DE GESTION ET D\'INTERMEDIATION (S.G.I.)"},{"numero":"536","intitule":"ETABLISSEMENTS FINANCIERS, INTERETS COURUS"},{"numero":"5361","intitule":"Etablissements financiers, intérêts courus, charges à payer"},{"numero":"5367","intitule":"Etablissements financiers, intérêts courus produits à recevoir"},{"numero":"538","intitule":"AUTRES ORGANISMES FINANCIERS"}],"fonctionnement":"Le compte 53 – ETABLISSEMENTS FINANCIERS ET ASSIMILES est débité des\\nmouvements de fonds en faveur des établissements concernés\\n- par le crédit des comptes concernés.\\nLe compte 53 – ETABLISSEMENTS FINANCIERS ET ASSIMILES est crédité des\\nmouvements de fonds diminuant les avoirs de l\'entité dans les établissements\\n- par le débit des comptes concernés.","commentaires":"Il y a lieu de distinguer, pour les opérations avec les chèques postaux, les avoirs en\\nunité monétaire légale du pays, d\'une part, des avoirs en devises, d\'autre part.\\nParmi les premiers, il faudra séparer les avoirs liquides des avoirs soumis à\\nrestriction.\\nLes opérations enregistrées en comptabilité doivent correspondre, sous réserve\\nd\'un décalage dans le temps, aux extraits de comptes envoyés par le Centre de\\nchèques postaux après chaque opération ou après chaque période. Les différences\\néventuelles doivent être recherchées et faire l\'objet d\'écritures de redressement\\nlorsqu\'elles n\'ont pas pour origine un chevauchement de dates.\\nEn fin d\'exercice, les avoirs en monnaies étrangères sont évalués au dernier cours\\nofficiel de change connu à la date du bilan.\\nLes comptes chèques postaux dont le solde apparaît créditeur en fin de période\\ncomptable sont inscrits au passif du bilan sous le poste \\"banques, découverts\\", sans\\ncompensation possible avec ceux des comptes bancaires présentant un solde\\ndébiteur.","exclusions":"Le compte 53 – ETABLISSEMENTS FINANCIERS ET ASSIMILES ne doit pas servir à\\nenregistrer :\\n- les mouvements de fonds relatifs aux opérations avec les banques\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n52 – Banques","controle":"Le compte 53 – ETABLISSEMENTS FINANCIERS ET ASSIMILES peut être contrôlé à\\npartir :\\ndes relevés de chèques postaux ;\\ndes relevés du Trésor ;\\ndes états de rapprochement.","motsCles":["etablissements","financiers","assimiles"]},{"numero":"54","intitule":"Instruments de trésorerie","classe":5,"classeLabel":"Comptes de trésorerie","groupe":"A","contenu":"Les Instruments de trésorerie appartiennent à la catégorie des instruments\\nfinanciers.\\nIls comprennent :\\n- les options de taux ;\\n- les options de change ;\\n- les options sur actions ;\\n- les instruments de trésorerie à terme.\\nLa qualification et la classification de ces différents instruments sont opérées en\\nfonction de la motivation ou de l\'intention de l\'entité.","subdivisions":[{"numero":"541","intitule":"OPTIONS DE TAUX D\'INTERÊT"},{"numero":"542","intitule":"OPTIONS DE TAUX DE CHANGE"},{"numero":"543","intitule":"OPTIONS DE TAUX BOURSIERS"},{"numero":"544","intitule":"INSTRUMENTS DE MARCHES A TERME"},{"numero":"545","intitule":"AVOIRS D\'OR ET AUTRES METAUX PRECIEUX(1)"}],"fonctionnement":"Les montants nominaux des contrats des instruments à terme, qu\'ils aient\\nvocation ou non vocation à être réglés ne sont pas comptabilisés au bilan. Ils\\nsont mentionnés dans les engagements hors bilan.\\nLes primes et soultes ou équivalents sont enregistrés suivant le schéma : débit\\ncompte 54 instruments de trésorerie par le crédit d\'un compte de trésorerie (52\\nou 53).\\nLes appels de marges sont enregistrés comme suit :\\ndans le cas d\'un gain : débit compte de trésorerie (52 ou 53) par le crédit\\ncompte 54 instruments de trésorerie ;\\ndans le cas d\'une perte débit 54 instruments de trésorerie par le crédit\\nd\'un compte de trésorerie (52 ou 53).\\nLes dépôts de garantie sont enregistrés au débit du compte 2758\\nAutres dépôts et cautionnement par le crédit d\'un compte de trésorerie (52 ou 53) ;\\nLes variations de valeurs sont ainsi enregistrées :\\nPour les instruments de couverture :\\nL\'instrument de couverture peut être un instrument ou une proportion\\nd\'instrument financier à terme ferme ou optionnel ou une combinaison\\nd\'instruments à terme fermes ou optionnels quel que soit leur sous- jacent.\\nLes autres actifs et passifs financiers peuvent être qualifiés d\'instruments de\\ncouverture contre le risque de change ou contre d\'autres risques lorsque leur\\nexposition au risque couvert compense l\'exposition de l\'élément couvert.\\nLes opérations qualifiées de couverture sont identifiées et traitées comptablement\\nen tant que telles dès leur origine et conservent cette qualification jusqu\'à leur\\néchéance ou dénouement.\\nL\'élément couvert peut être un élément ou un groupe d\'actifs, de passifs,\\nd\'engagements existants ou de transactions futures non encore matérialisées par\\nun engagement si ces transactions sont définies avec précision et possèdent une\\nprobabilité suffisante de réalisation.\\nUn instrument financier à terme peut être un élément couvert.\\nComptabilisation des instruments de couverture : Les produits et charges (latents\\nou réalisés) relatifs aux instruments de couverture sont reconnus au compte de\\nrésultat de manière symétrique au mode de comptabilisation des produits et\\ncharges sur l\'élément couvert. Les variations de valeur des instruments de\\ncouverture ne sont pas reconnues au bilan, sauf si la reconnaissance en partie ou\\nen totalité de ces variations permet d\'assurer un traitement symétrique avec\\n- l\'élément couvert.\\nDans le cas d\'un gain, le compte 54\\nInstruments de trésorerie est débité par le crédit du compte de la classe 7. Ce gain\\nest étalé au prorata de la comptabilisation des produits ou charge de l\'élément\\ncouvert par le biais du compte 477\\nProduits constatés d\'avance ;\\nDans le cas d\'une perte, le compte\\n54 Instrument de trésorerie est crédité par le débit du compte de la classe 6. Cette perte\\nest étalée au prorata de la comptabilisation des produits et charges de l\'élément couvert\\n- par le biais du compte 476\\nCharges constatées d\'avance.\\nPar symétrie, le résultat de la couverture est présenté dans le même poste ou à\\ndéfaut dans la même rubrique du compte de résultat que celui de l\'élément couvert.\\nCette comptabilité de couverture subsiste même en cas d\'arrêt de la couverture\\ndans les cas suivants :\\nlorsque l\'instrument de couverture est dénoué ou échu alors que l\'élément\\ncouvert est toujours existant,\\nlorsque l\'instrument de couverture ne répond plus aux critères de\\nqualification ou lorsqu\'il est mis fin à une relation de couverture et que\\n- l\'élément couvert est toujours existant.\\nEn revanche lorsque l\'élément couvert ne répond plus en partie ou totalement à la\\nqualification d\'élément couvert éligible et que l\'instrument de couverture est\\nconservé, celui-ci est traité en totalité ou en partie comme un instrument en\\nposition ouverte isolée\\nPrimes d\'option : Les primes d\'options peuvent être étalées dans le compte de\\nrésultat sur la période de couverture. Elles peuvent également être constatées en\\nrésultat au même moment que la transaction couverte ou dans la valeur d\'entrée\\nau bilan de l\'élément couvert lorsqu\'il s\'agit d\'un achat futur d\'actif.\\nReport/déport du change à terme: Le report ou déport des contrats de change à\\nterme doit être étalé dans le compte de résultat, par le biais du comptes 6784\\npertes sur instruments de trésorerie ou du compte 7784 Produits sur instruments\\nde trésorerie selon le sens-, sur la durée de la couverture.\\nPour la position ouverte isolée, c\'est à dire spéculative ou des opérations\\ndont le caractère de couverture ne peut être démontré : la perte latente\\nengendrée par la variation de valeur des opérations doit être constatée en\\nfin d\'exercice par le débit du compte\\n- 6791 charges pour dépréciation sur risques financiers et le crédit du compte 594\\ndépréciations des comptes d\'instruments financiers.\\nLes gains latents n\'interviennent pas dans le résultat en raison du principe de\\nprudence.\\nDécomptabilisation des instruments financiers : Si l\'entité perd le contrôle des\\ndroits attachés à l\'instrument financier, elle doit décomptabiliser le bien et le\\ncompte 54 Instruments de trésorerie. Ce compte d\'instruments de trésorerie peut\\nêtre constaté en résultat au même moment que la transaction couverte ou dans la\\nvaleur d\'entrée au bilan de l\'élément couvert lorsqu\'il s\'agit d\'un achat futur d\'actif.","commentaires":"En fonction des marchés sur lesquels les opérations sont traitées, les règles et\\nméthodes de comptabilisation diffèrent :\\nsur les marchés organisés et assimilés, dotés d\'une parfaite liquidité ; évaluation\\nau prix du marché (règle dite de mark to market) ;\\nsur les autres marchés, évaluation au coût historique (règle de prudence).","exclusions":"Le compte 54 – INSTRUMENTS DE TRESORERIE ne doit pas servir à enregistrer :\\n- les opérations de crédits de trésorerie\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n56 – Banques, crédits de trésorerie et d\'escompte","controle":"Le compte 54 – INSTRUMENTS DE TRESORERIE peut être contrôlé à partir des\\nrelevés et états de rapprochement bancaires.","motsCles":["instruments","tresorerie"]},{"numero":"55","intitule":"Instruments de monnaie électronique","classe":5,"classeLabel":"Comptes de trésorerie","groupe":"A","contenu":"L\'instrument de monnaie électronique est constitué d\'une valeur monétaire stockée\\nsous une forme électronique, y compris magnétique, représentant une créance sur\\n- l\'émetteur, qui est émise contre la remise de fonds aux fins d\'opérations de\\npaiement et qui est acceptée par une personne physique ou morale autre que\\n- l\'émetteur de monnaie électronique;","subdivisions":[{"numero":"551","intitule":"MONNAIE ELECTRONIQUE- CARTE CARBURANT"},{"numero":"552","intitule":"MONNAIE ELECTRONIQUE- TELEPHONE PORTABLE"},{"numero":"553","intitule":"MONNAIE ELECTRONIQUE- CARTE PEAGE"},{"numero":"554","intitule":"PORTE-MONNAIE ELECTRONIQUE"},{"numero":"558","intitule":"AUTRES INSTRUMENTS DE MONNAIE ELECTRONIQUE"}],"fonctionnement":"Le compte 55 – INSTRUMENTS MONNAIE ELECTRONIQUE est débité des montants\\ndes chargements effectués\\n- par le crédit des comptes concernés des comptes 52 ; 53 ; 57.\\nLe compte 55 – INSTRUMENTS MONNAIE ELECTRONIQUE est crédité des\\nrèglements\\n- par le débit des comptes concernés.","commentaires":"Il peut être ouvert autant de sous-comptes en cas de besoin.\\nL\'instrument de monnaie électronique est un moyen de paiement électronique qui\\npermet d\'effectuer les opérations financières suivantes:\\ndépôts et retraits d\'argent ;\\ntransferts d\'argent ;\\npaiement de factures (téléphone, électricité, eau, carburant ...) ;\\nachat de biens et services ;\\nachat de crédits téléphoniques ;\\netc….\\nLes comptes instruments de monnaie électronique sont débités lors du chargement\\net crédités au fur et à mesure des paiements.\\nLe porte-monnaie électronique est un moyen de paiement qui se présente sous\\nforme d\'une carte bancaire alimentée en unités monétaires par le porteur. Le porte-\\nmonnaie électronique se retire dans les banques en général. Il n\'est pas nécessaire\\nd\'avoir un compte bancaire pour pouvoir obtenir un porte-monnaie électronique.\\nLes frais relatifs aux dépôts, retraits et paiements par instruments de monnaie\\nélectronique sont enregistrés au compte\\n- 6317 Frais sur instruments monétaires électroniques.\\nLe solde du compte instruments monétaire électronique ne doit être que débiteur\\nou nul.","exclusions":"Le compte 55 – INSTRUMENTS MONNAIE ELECTRONIQUE ne doit pas servir à\\nenregistrer :\\n- les mouvements de fonds des banques\\n- les opérations de crédit de trésorerie\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n52 – Banques\\n56 – Banques crédits de trésorerie et d\'escompte\\n- les instruments de trésorerie\\n- les paiements effectués par cartes de crédit\\n54 – Instruments de trésorerie\\n- 515 – Cartes de crédit à encaisser","controle":"Le compte 55 – INSTRUMENTS MONNAIE ELECTRONIQUE peut être contrôlé à\\npartir :\\ndes factures de chargement;\\ndu code accès au service de l\'instrument et du code secret du gestionnaire de\\n- l\'instrument.","motsCles":["instruments","monnaie","electronique"]},{"numero":"56","intitule":"Banques, crédits de trésorerie et d\'escompte","classe":5,"classeLabel":"Comptes de trésorerie","groupe":"A","contenu":"Ce compte enregistre, d\'une part, le montant de crédits de trésorerie inscrit au\\ncompte courant de l\'établissement dispensateur de ces concours avec lequel l\'entité\\nest en relation d\'affaires et, d\'autre part, le montant nominal des effets escomptés.","subdivisions":[{"numero":"561","intitule":"CREDITS DE TRESORERIE"},{"numero":"564","intitule":"ESCOMPTE DE CREDITS DE CAMPAGNE"},{"numero":"565","intitule":"ESCOMPTE DE CREDITS ORDINAIRES"},{"numero":"566","intitule":"CREDITS DE TRESORERIE, INTERETS COURUS"}],"fonctionnement":"Le compte 56 – BANQUES, CREDITS DE TRESORERIE ET D\'ESCOMPTE est crédité du\\nmontant des crédits de trésorerie effectivement portés au compte\\n- par le débit du compte 52 – Banques.\\nLe compte 56 – BANQUES, CREDITS DE TRESORERIE ET D\'ESCOMPTE est crédité du\\nmontant nominal des effets escomptés\\n- par le débit du compte 52 – Banques ;\\n- ou par le débit du compte 675 – Escompte des effets de commerce.\\nLe compte 56 – BANQUES, CREDITS DE TRESORERIE ET D\'ESCOMPTE est débité du\\nmontant des remboursements de crédits de trésorerie\\n- par le crédit du compte 52 – Banques.\\nLe compte 56 – BANQUES, CREDITS DE TRESORERIE ET D\'ESCOMPTE est débité du\\nmontant nominal des effets remis à l\'escompte dont l\'échéance est passée et\\n- l\'opération dénouée\\n- par le crédit du compte 415 – Clients, effets escomptés non échus.","commentaires":"Le compte 561 – Crédits de trésorerie sert à enregistrer les concours qu\'accordent\\n- les établissements de crédit sur une durée de deux ans au plus, pour financer\\ngénéralement des besoins généraux.\\nIls peuvent prendre la forme de prêt et être assortis de contrat indiquant la durée\\ndu remboursement, le taux d\'intérêt, les garanties réelles ou personnelles y\\nafférents.\\nIls peuvent tout aussi bien revêtir la forme d\'avances en compte, et être des crédits\\nde courrier, des crédits de campagne, des facilités de caisse, voire des découverts\\n(consentis notamment pour le règlement d\'une dette, un achat massif de\\nmarchandises et autres biens, ou pour honorer des paiements importants).\\nLe compte 564 – Escompte de crédits de campagne sert à enregistrer les opérations\\nd\'escompte des effets représentatifs de crédits de campagne.\\nPar crédit de campagne, il convient d\'entendre les concours consentis de façon\\nexclusive et certaine pour la commercialisation de produits agricoles locaux\\nlorsque :\\ncette commercialisation est effectuée par l\'intermédiaire ou sous la surveillance\\nd\'organismes placés directement ou indirectement sous le contrôle de l\'Etat ;\\n- le dénouement de ces concours intervient normalement dans un délai\\nmaximum de douze mois à compter du début de la campagne.\\nToutefois, le financement des stocks – reports, relatifs aux produits agricoles locaux,\\nau-delà de douze mois – est à rattacher aux crédits de campagne.\\nLe compte 565 – Escompte de crédits ordinaires sert à enregistrer les opérations\\nd\'escompte des effets représentatifs de transactions commerciales. Ces effets sont\\ncréés en contrepartie :\\nd\'une livraison effective de biens ou services, hormis les produits de campagne ;\\nd\'exécution de travaux ;\\nde prestations de services.\\nLe banquier escompteur est censé devenir propriétaire de la créance. Toutefois, la\\ncréance ne disparaît pas du bilan de l\'entité en tant que telle, en raison de\\n- l\'engagement de l\'entité de se substituer au débiteur défaillant.\\nComptabilisation de l\'opération d\'escompte d\'effets : 1 – A la date de remise à\\n- l\'escompte, le compte 415 – Clients, effets escomptés non échus est débité par le\\ncrédit du compte 412 – Clients, effets à recevoir en portefeuille. 2 – A la réception\\ndu décompte bancaire, le compte 52 – Banques est débité pour le montant net\\nobtenu de la banque et le compte 675 – Escompte des effets de commerce, pour le\\nmontant des frais bancaires et d\'intérêts d\'escompte ; en contrepartie le compte\\n- 565 – Escompte de crédits ordinaires est crédité, pour le montant nominal des\\neffets concernés.\\n3 – Après la date d\'échéance, et le dénouement de l\'opération, le compte 565 –\\nEscompte de crédits ordinaires est débité pour le montant nominal de l\'effet par le\\ncrédit du compte 415 – Clients, effets escomptés non échus.","exclusions":"Le compte 56 – BANQUES CREDITS DE TRESORERIE ET D\'ESCOMPTE ne doit pas\\nservir à enregistrer :\\n- les prêts bancaires à plus d\'un an\\n- les découverts bancaires autorisés, tant qu\'ils n\'ont qu\'un caractère\\nd\'engagement de la\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n16 – Emprunts et dettes assimilées\\ncomptes d\'engagements hors bilan banque vis-à-vis de l\'entité et qu\'ils s\'ajustent\\ndonc sur le montant du solde débiteur chez le banquier\\n- les effets remis à l\'encaissement à leur échéance normale\\n51 – Valeurs à encaisser","controle":"Le compte 56 – BANQUES, CREDITS DE TRESORERIE peut être contrôlé à partir :\\ndes attestations de la banque concernant les crédits de trésorerie ;\\ndes relevés bancaires, étant entendu que le crédit de trésorerie doit avoir été\\npositionné au crédit du compte courant ;\\ndes bordereaux de remise des effets à l\'escompte.","motsCles":["banques","credits","tresorerie","escompte"]},{"numero":"57","intitule":"Caisse","classe":5,"classeLabel":"Comptes de trésorerie","groupe":"A","contenu":"Le compte Caisse retrace les opérations d\'encaissement et de paiement effectuées\\nen espèces pour les besoins de l\'entité.","subdivisions":[{"numero":"571","intitule":"CAISSE SIEGE SOCIAL"},{"numero":"5711","intitule":"dans l\'unité monétaires légales des pays (UML)"},{"numero":"5712","intitule":"en devises"},{"numero":"572","intitule":"CAISSE SUCCURSALE A"},{"numero":"5721","intitule":"en UML"},{"numero":"5722","intitule":"en devises"},{"numero":"573","intitule":"CAISSE SUCCURSALE B"},{"numero":"5731","intitule":"en UML"},{"numero":"5732","intitule":"en devises"}],"fonctionnement":"Le compte 57 – CAISSE est débité des versements effectués au profit de la caisse\\n- par le crédit des comptes concernés.\\nLe compte 57 – CAISSE est crédité des règlements effectués par la caisse ou\\n- par le débit des comptes concernés.","commentaires":"Il peut être ouvert autant de sous-comptes en cas de besoin.\\nLe solde du compte caisse doit toujours correspondre exactement à la somme\\ndisponible réellement.\\nLe solde du compte caisse ne doit être que débiteur ou nul.\\nUn solde créditeur du compte caisse signifierait que l\'entité serait parvenue à\\ndébourser davantage d\'espèces qu\'elle n\'en aurait reçu en caisse et qu\'elle ne serait\\npas à même d\'indiquer la manière dont les emplois en dépassement ont été\\ncouverts.\\nEn conséquence, un solde créditeur du compte caisse ou constitue une présomption\\nd\'irrégularité de la comptabilité.","exclusions":"Le compte 57 – CAISSE ne doit pas servir à enregistrer :\\n- les chèques de voyage\\n- les chèques de banque\\n- les timbres fiscaux\\n- les timbres postaux et autres figurines d\'affranchissement\\n- les effets de commerce\\n- les paiements effectués par cartes de crédit\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n- 518 – Autres valeurs à l\'encaissement\\n- 513 – Chèques à encaisser ou 514 – Chèques à l\'encaissement\\n64 – Impôts et taxes\\n- 616 – Transports de plis\\n41 – Clients et comptes rattachés\\n51 – Valeurs à encaisser\\n56 – Banques, crédits de trésorerie et d\'escompte\\n- 515 – Cartes de crédit à encaisser","controle":"Le compte 57 – CAISSE peut être contrôlé à partir :\\ndes procès-verbaux de caisse ;\\ndes états de reddition de la caisse ;\\ndes bordereaux de situation journalière ;","motsCles":["caisse"]},{"numero":"58","intitule":"Régies d\'avances, accréditifs et virements internes","classe":5,"classeLabel":"Comptes de trésorerie","groupe":"A","contenu":"Ce compte enregistre le montant des avances aux régisseurs, le montant des\\naccréditifs ainsi que la régularisation desdites avances et le règlement des\\naccréditifs.","subdivisions":[{"numero":"581","intitule":"REGIES D\'AVANCE"},{"numero":"582","intitule":"ACCREDITIFS"},{"numero":"585","intitule":"VIREMENTS DE FONDS"},{"numero":"588","intitule":"AUTRES VIREMENTS INTERNES"}],"fonctionnement":"Le compte 58 – REGIES D\'AVANCES, ACCREDITIFS ET VIREMENTS INTERNES est\\ndébité du montant des avances aux régisseurs et du montant des accréditifs\\n(comptes 581 et 582)\\n- par le crédit des comptes de trésorerie.\\nLe compte 58 – REGIES D\'AVANCES, ACCREDITIFS ET VIREMENTS INTERNES est\\ndébité, en cours d\'exercice, du montant correspondant à un débit à porter dans un\\ncompte support d\'un journal auxiliaire (comptes 585 et 588)\\n- par le crédit des comptes de trésorerie.\\nLe compte 58 – REGIES D\'AVANCES, ACCREDITIFS ET VIREMENTS INTERNES est\\ncrédité lors de la régularisation des avances et du règlement définitif des accréditifs\\n(comptes 581 et 582)\\n- par le débit des comptes concernés.\\nLe compte 58 – REGIES D\'AVANCES, ACCREDITIFS ET VIREMENTS INTERNES est\\ncrédité, en cours d\'exercice, du montant correspondant à un crédit à porter dans un\\ncompte support d\'un journal auxiliaire (comptes 585 et 588)\\n- par le débit des comptes de trésorerie.","commentaires":"Les comptes 581 et 582 enregistrent, le cas échéant, les opérations relatives :\\naux régies d\'avances : fonds gérés par les régisseurs ou les comptables\\nsubordonnés (sur un chantier forestier ou de travaux publics, par exemple) ;\\naux accréditifs, c\'est-à-dire, les crédits ouverts par un établissement de crédit,\\nrelation d\'affaires de l\'entité, dans sa succursale d\'une ville, d\'un département,\\nd\'une localité, afin de permettre au tiers concerné, généralement le responsable\\nlocal de l\'entité, de couvrir ses besoins de trésorerie.\\nLes comptes 585 et 588, relatifs aux virements internes, sont utilisés pour des\\nraisons techniques dans les comptabilités organisées sur la base de journaux\\nauxiliaires. Ce sont des comptes de passage utiles à la comptabilisation d\'opérations\\ninternes à l\'entité. Leur utilisation a pour but d\'éviter les risques de double emploi\\nau cours de la centralisation des écritures. En tout état de cause ces comptes\\ndoivent être soldés au terme de leur utilisation.","exclusions":"Le compte 58 – REGIES D\'AVANCES, ACCREDITIFS ET VIREMENTS INTERNES ne doit\\npas servir à enregistrer :\\n- les opérations internes de trésorerie, lorsque l\'entité utilise un journal unique\\nIl convient dans le cas d\'espèce d\'utiliser les comptes ci-après :\\n- les autres comptes de la classe 5 concernés","controle":"Le compte 58 – REGIES D\'AVANCES, ACCREDITIFS ET VIREMENTS INTERNES peut\\nêtre contrôlé à partir des relevés bancaires. Il importe de s\'assurer que les comptes\\n- 585 et 588 relatifs aux virements internes sont soldés à la fin de l\'exercice.","motsCles":["regies","avances","accreditifs","virements","internes"]},{"numero":"59","intitule":"Dépréciations et provisions pour risques à court terme (Trésorerie)","classe":5,"classeLabel":"Comptes de trésorerie","groupe":"A","contenu":"Ce compte enregistre l\'amoindrissement de la valeur des titres et valeurs liquides,\\ndes avoirs en banque, et autres éléments financiers résultant de causes précises\\nquant à leur nature, mais dont les effets ne sont pas jugés irréversibles ainsi que les\\nreprises de charges provisionnées s\'y rapportant.\\nIl enregistre également les provisions de caractère financier pour risques à moins\\nd\'un an.","subdivisions":[{"numero":"590","intitule":"DÉPRÉCIATIONS DES TITRES DE PLACEMENT"},{"numero":"591","intitule":"DEPRECIATIONS DES TITRES ET VALEURS A ENCAISSER"},{"numero":"592","intitule":"DEPRECIATIONS DES COMPTES BANQUES"},{"numero":"593","intitule":"DEPRECIATIONS DES COMPTES ETABLISSEMENTS FINANCIERS ET ASSIMILES"},{"numero":"594","intitule":"DEPRECIATIONS DES COMPTES D\'INSTRUMENTS DE TRESORERIE"},{"numero":"599","intitule":"PROVISIONS POUR RISRQUES A COURT TERME A CARACTERE FINANCIER"}],"fonctionnement":"A la clôture de l\'exercice :\\nLe compte 59 – DEPRECIATIONS ET RISQUES PROVISIONNES (TRESORERIE) est\\ncrédité des dépréciations de l\'exercice, constatées sur les éléments d\'actif de la\\nclasse 5, ainsi que des pertes probables de nature financière à moins d\'un an\\n- par le débit du compte 679 – Charges pour dépréciations et provisions pour\\nrisques à court terme financières.\\nLe compte 59 – DEPRECIATIONS ET PROVISIONS POUR RISQUES A COURT TERME\\n(TRESORERIE) est débité des dépréciations et provisions existant à l\'ouverture de\\n- l\'exercice\\n- par le crédit du compte 779 – Reprises de charges pour dépréciations et\\nprovisions pour risques à court terme financières.","commentaires":"Les dépréciations des comptes de trésorerie obéissent aux mêmes règles de\\ncomptabilisation que les dépréciations constatées sur les éléments de l\'actif\\ncirculant (classes 3 et 4).\\nLa dotation est à constituer même si la dépréciation est d\'un montant incertain.\\nLa dépréciation traduit une baisse non définitive et non irréversible de l\'évaluation\\ndes éléments d\'actif par rapport à leur valeur comptable.\\nLes événements générateurs de dépréciations, survenus après la clôture de\\n- l\'exercice, ne sont pas pris en compte dans ledit exercice ; les dépréciations ne\\ndoivent être constituées que pour des dépréciations subies au cours de l\'exercice, et\\nà la clôture de l\'exercice.\\nLa dépréciation doit être constituée même en l\'absence ou en cas d\'insuffisance de\\nbénéfices ; de la sorte, il est donné une image fidèle du patrimoine, de la situation\\nfinancière et du résultat de l\'entité.\\nLorsque, au jour de l\'inventaire, la valeur économique réelle des titres, valeurs\\nliquides et autres avoirs du genre sur banques est inférieure à leur valeur\\ncomptable, les entités doivent constituer des dépréciations qui expriment les moins-\\nvalues constatées sur ces éléments de la trésorerie.\\nLes dépréciations sont portées à l\'actif du bilan, en diminution de la valeur des\\npostes qu\'elles concernent, sous la forme prévue par le modèle de bilan.\\nPour les titres de placement, la constitution de dépréciation s\'appuie sur une\\névaluation des cours à la clôture de l\'exercice, basée sur la valeur de la transaction\\nen Bourse, s\'il s\'agit de titres cotés, ou sur la valeur de négociation potentielle, s\'il\\ns\'agit de titres non cotés.\\nLes provision pour risques à court terme à caractère financier enregistrent les\\npertes probables à moins d\'un an ayant leur origine dans une opération de nature\\nfinancière ; exemple : provisions pour pertes de change.","exclusions":"Le compte 59 – DEPRECIATIONS ET PROVISIONS POUR RISQUES A COURT TERME\\nci-après : (TRESORERIE) ne doit pas servir à enregistrer les provisions pour\\ndépréciations d\'autres éléments du bilan :\\nClasse 1\\nClasse 2\\nClasse 3\\nClasse 4\\nIl convient dans les cas d\'espèce d\'utiliser les comptes\\n19 – Provisions financières pour risques et charges\\n29 – dépréciations\\n39 – Dépréciations des stocks\\n49 – Dépréciations et provisions pour risques à court terme (Tiers)","controle":"Le compte 59 – DEPRECIATIONS ET PROVISIONS POUR RISQUES À COURT TERME\\n(TRESORERIE) peut être contrôlé à partir des cours de Bourse de clôture, des\\névaluations de titres, des cours du change.\\n\\n# CLASSE 6 : COMPTES DE CHARGES DES\\nACTIVITÉS ORDINAIRES\\nLes charges sont des emplois définitifs ou consommations de valeurs décaissées ou\\nà décaisser par l\'entité :\\nsoit en contrepartie de marchandises, approvisionnements, travaux et services\\nconsommés par l\'entité, ainsi que des avantages qui leur ont été consentis ;\\nsoit en vertu d\'une obligation légale que l\'entité doit remplir ;\\nsoit exceptionnellement, sans contrepartie directe.\\nLes charges comprennent également pour\\nLes charges sont distinguées, selon leur nature :\\nen charges des Activités Ordinaires (compte de la classe 6)\\nen charges d\'exploitation ;\\nen charges financières ;\\nou en charges Hors Activités\\nOrdinaires (compte classe 8).\\nLa classe 6 est destinée à enregistrer les charges liées à l\'activité ordinaire de\\n- l\'entité. Ces charges entrent dans la composition des coûts des produits de la\\ndétermination du résultat de l\'exercice : * l\'entité.\\n- les dotations aux amortissements, aux provisions et aux dépréciation;\\nla valeur comptable des éléments d\'actif cédés, détruits ou disparus.\\nLes charges doivent être comptabilisées dans l\'exercice au cours duquel elles ont\\npris naissance. Elles donnent éventuellement lieu à abonnement ou à\\nrégularisation à la clôture de l\'exercice.","motsCles":["depreciations","provisions","risques","court","terme","tresorerie"]},{"numero":"60","intitule":"(sauf 603) Achats","classe":6,"classeLabel":"Comptes de charges des activités ordinaires","groupe":"B","contenu":"Ce compte enregistre, le montant des factures d\'achat et la valeur des retours de\\nmatières, fournitures et marchandises aux fournisseurs ainsi que les rabais,\\nremises et ristournes hors factures obtenus des fournisseurs de biens.","subdivisions":[{"numero":"601","intitule":"ACHATS DE MARCHANDISES (1)"},{"numero":"6011","intitule":"dans la Région"},{"numero":"6012","intitule":"hors Région (1)"},{"numero":"6013","intitule":"aux entités du groupe dans la Région"},{"numero":"6014","intitule":"aux entités du groupe hors Région"},{"numero":"6015","intitule":"Frais sur achats (2)"},{"numero":"6019","intitule":"Rabais, Remises et Ristournes obtenus (non ventilés)"},{"numero":"602","intitule":"ACHATS DE MATIERES PREMIERES ET FOURNITURES LIEES (1)"},{"numero":"6021","intitule":"dans la Région (1)"},{"numero":"6022","intitule":"hors Région"},{"numero":"6023","intitule":"aux entités du groupe dans la Région"},{"numero":"6024","intitule":"aux entités du groupe hors Région"},{"numero":"6025","intitule":"Frais sur Achats (2)"},{"numero":"6029","intitule":"Rabais, Remises et Ristournes obtenus (non ventilés)"},{"numero":"604","intitule":"ACHATS STOCKES DE MATIERES ET FOURNITURES CONSOMMABLES"},{"numero":"6041","intitule":"Matières consommables"},{"numero":"6042","intitule":"Matières combustibles"},{"numero":"6043","intitule":"Produits d\'entretien"},{"numero":"6044","intitule":"Fournitures d\'atelier et d\'usine"},{"numero":"6045","intitule":"Frais sur Achats (2)"},{"numero":"6046","intitule":"Fournitures de magasin"},{"numero":"6047","intitule":"Fournitures de bureau"},{"numero":"6049","intitule":"Rabais, Remises et Ristournes obtenus (non ventilés)"},{"numero":"605","intitule":"AUTRES ACHATS"},{"numero":"6051","intitule":"Fournitures non stockables-Eau"},{"numero":"6052","intitule":"Fournitures non stockables- Electricité"},{"numero":"6053","intitule":"Fournitures non stockables- Autres énergies"},{"numero":"6054","intitule":"Fournitures d\'entretien non stockables"},{"numero":"6055","intitule":"Fournitures de bureau non stockables"},{"numero":"6056","intitule":"Achats de petit matériel et outillage"},{"numero":"6057","intitule":"Achats d\'études et prestations de service"},{"numero":"6058","intitule":"Achats de travaux, matériels et équipements"},{"numero":"6059","intitule":"Rabais, Remises et Ristournes obtenus (non ventilés)"},{"numero":"608","intitule":"ACHATS D\'EMBALLAGES"},{"numero":"6081","intitule":"Emballages perdus"},{"numero":"6082","intitule":"Emballages récupérables non identifiables"},{"numero":"6083","intitule":"Emballages à usage mixte"},{"numero":"6085","intitule":"Frais sur achats (2)"},{"numero":"6089","intitule":"Rabais, Remises et Ristournes obtenus (non ventilés)"}],"fonctionnement":"Le compte 60 – ACHATS est débité du montant des factures d\'achat hors taxes frais\\naccessoires inclus .\\nLe compte 445 – ETAT, TVA RECUPERABLE est débité du montant des taxes, si les\\ntaxes sont récupérables.\\n- par le crédit du compte fournisseur ou d\'un compte de trésorerie.\\nLe compte 60 – ACHATS est crédité, en cours d\'exercice, des retours de matières,\\nfournitures et marchandises hors taxes aux fournisseurs ainsi que les rabais,\\nremises, ristournes obtenus par facture d\'avoir (après première facturation)\\nLe compte 445 – ETAT, TVA RECUPERABLE est crédité du montant des taxes, si les\\ntaxes ont été récupérées.\\n- par le débit des comptes fournisseurs ou de tiers intéressés.\\nLe compte 60 – ACHATS est crédité pour solde à la clôture de l\'exercice\\n- par le débit du compte 13 – Résultat net de l\'exercice.","commentaires":"Les comptes 601, 602, 604, 605 et 608, comme les comptes de stocks\\ncorrespondants, donnent lieu à l\'ouverture de sous-comptes de produits regroupés\\nsuivant la nomenclature des biens et services en usage dans chaque Etat-partie.\\nSous cette réserve, les entités peuvent choisir une nomenclature à leur convenance.\\nLe montant des factures d\'achat à inscrire au compte 60 (sauf 603) s\'entend, le cas\\néchéant, net de taxes récupérables. Les frais accessoires d\'achats peuvent être\\nenregistrés au sous-compte Achats concerné pour le montant net de taxes\\nrécupérables. Les sous comptes frais sur achats peuvent être subdivisés selon qu\'il\\ns\'agit de marchandises, de matières et fournitures liées et de matières et\\nfournitures consommables.\\nLes achats sont comptabilisés, déduction faite des rabais et remises, imputés\\ndirectement sur le montant de la facture.\\nMême lorsqu\'ils sont déduits sur la facture d\'achat, les escomptes de règlement sont\\nportés au compte 773 – Escomptes obtenus.\\nA la clôture de l\'exercice, les biens reçus par l\'entité, avant réception de la facture\\ncorrespondante, sont néanmoins inscrits dans les achats, par le crédit d\'un compte\\ndivisionnaire de fournisseurs (408 – Factures non parvenues). Cette précaution a\\npour but de ne pas fausser les résultats.\\nLes remises, rabais et ristournes sur achats, obtenus des fournisseurs et dont le\\nmontant, non déduit des factures d\'achats, n\'est connu que postérieurement à la\\ncomptabilisation de ces factures, sont enregistrés aux comptes d\'achats concernés.","exclusions":"Le compte 60 – ACHATS ne doit pas servir à enregistrer :\\n- les frais accessoires d\'achats directement rattachables aux immobilisations\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\ncomptes de la classe 2","controle":"Le compte 60 – ACHATS peut être contrôlé à partir :\\ndes factures et avoirs fournisseurs ;\\ndes bons de commande ;\\ndes états d\'inventaire.","motsCles":["603","achats"]},{"numero":"603","intitule":"Variations des stocks de biens achetés","classe":6,"classeLabel":"Comptes de charges des activités ordinaires","groupe":"B","contenu":"Ce compte enregistre les variations de stocks de biens et de marchandises achetés\\nen retraçant les opérations relatives aux entrées en stocks, aux sorties de stocks, et\\naux différences constatées entre l\'inventaire comptable permanent et l\'inventaire\\nphysique.\\nLes variations de stocks sont évaluées différemment selon le système d\'inventaire\\nutilisé.","subdivisions":[{"numero":"6031","intitule":"Variations des stocks de marchandises"},{"numero":"6032","intitule":"Variations des stocks de matières premières et fournitures liées"},{"numero":"6033","intitule":"Variations des stocks d\'autres approvisionnements"}],"fonctionnement":"En cas d\'inventaire intermittent, à la clôture de l\'exercice :\\nLe compte 603 – VARIATIONS DES STOCKS DE BIENS ACHETES est débité de la\\nvaleur du stock initial(1)\\n- par le crédit des comptes de stocks concernés (pour solde des stocks\\ninitiaux).\\n(1) ou de la diminution de l\'exercice (stock initial moins stock final).\\nLe compte 603 – VARIATIONS DES STOCKS DE BIENS ACHETES est crédité de la\\nvaleur du stock final, pour sa valeur d\'inventaire(1)\\n- par le débit des comptes de stocks concernés (constatation des stocks finals).\\nLe compte 603 – VARIATIONS DES STOCKS DE BIENS ACHETES est viré pour solde,\\navec les charges, dans le compte 13 – Résultat net de l\'exercice (montant débiteur\\nou montant créditeur, selon le cas).\\nEn cas d\'inventaire permanent :\\nLe compte 603 – VARIATIONS DES STOCKS DE BIENS ACHETES est crédité, en cours\\nd\'exercice, des entrées en stocks\\n- par le débit des comptes de stocks concernés.\\nLe compte 603 – VARIATIONS DES STOCKS DE BIENS ACHETES est débité, en cours\\nd\'exercice, des sorties de stocks\\n- par le crédit des comptes de stocks concernés.\\nA la clôture de l\'exercice, le compte 603 – VARIATIONS DES STOCKS DE BIENS\\nACHETES est débité des différences en moins constatées entre l\'inventaire\\ncomptable et l\'inventaire physique\\n- par le crédit des stocks concernés.\\nA la clôture de l\'exercice, le compte 603 – VARIATIONS DES STOCKS DE BIENS\\nACHETES est crédité des différences en plus constatées entre l\'inventaire comptable\\net l\'inventaire physique\\n- par le débit des comptes de stocks concernés.\\n(1) ou de l\'augmentation de l\'exercice (stock final moins stock initial).\\nA la clôture de l\'exercice, le compte 603 – VARIATIONS DES STOCKS DE BIENS\\nACHETES est viré (pour solde), avec les charges, dans le compte 13 – Résultat net de\\n- l\'exercice (montant débiteur ou montant créditeur, selon le cas).","commentaires":"Les comptes de variations de stocks peuvent être de solde débiteur ou créditeur.\\nPour la détermination des soldes significatifs de gestion, les variations de stocks\\nsont calculées à partir du prix d\'achat des biens inscrits dans les stocks, tel qu\'il est\\ncomptabilisé dans les comptes d\'achats.\\nLes soldes des sous-comptes du compte\\n- 603 – Variations des stocks de biens achetés donnent la mesure des différences entre la\\nvaleur brute des stocks de biens achetés, telle qu\'elle est constatée à la clôture de\\n- l\'exercice, et la valeur brute correspondante à l\'ouverture de l\'exercice.","exclusions":"Le compte 603 – VARIATIONS DES STOCKS DE BIENS ACHETES ne doit pas servir à\\nenregistrer :\\n- les variations de stocks d\'en-cours ou de produits fabriqués\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n73 – Variations des stocks de biens et de services produits","controle":"Le compte 603 – VARIATIONS DES STOCKS DE BIENS ACHETES peut être contrôlé à\\npartir de l\'inventaire, ou du décompte physique, et de l\'évaluation.","motsCles":["variations","stocks","biens","achetes"]},{"numero":"61","intitule":"Transports","classe":6,"classeLabel":"Comptes de charges des activités ordinaires","groupe":"B","contenu":"Les frais de transport comprennent le montant des charges de port ou transports\\nengagés par l\'entité, à l\'occasion, des ventes, des déplacements de son personnel ou\\nde l\'expédition de plis.","subdivisions":[{"numero":"612","intitule":"TRANSPORTS SUR VENTES"},{"numero":"613","intitule":"TRANSPORTS POUR LE COMPTE DE TIERS"},{"numero":"614","intitule":"TRANSPORTS DU PERSONNEL"},{"numero":"616","intitule":"TRANSPORT DE PLIS"},{"numero":"618","intitule":"AUTRES FRAIS DE TRANSPORT"},{"numero":"6181","intitule":"Voyages et déplacements"},{"numero":"6182","intitule":"Transports entre établissements ou chantiers"},{"numero":"6183","intitule":"Transports entre établissements ou chantiers"}],"fonctionnement":"Le compte 61 – TRANSPORTS est débité des charges de port ou transports engagées\\npar l\'entreprise\\n- par le crédit des comptes de tiers ou de trésorerie concernés.\\nLe compte 61 – TRANSPORTS est crédité, en cours d\'exercice, du montant des\\nfactures d\'avoir représentant des réductions à caractère commercial ou des\\nannulations de factures\\n- par le débit des comptes fournisseurs concernés.\\nLe compte 61 – TRANSPORTS est crédité, à la clôture de l\'exercice\\n- par le débit : du compte 476 – Charges constatées d\'avance, pour\\nrégularisation ou par le débit du compte 13 – Résultat net de l\'exercice\\n(pour solde).","commentaires":"Le compte 616 – Transports de plis peut être débité soit à l\'occasion du paiement\\nd\'un affranchissement, soit à l\'occasion de l\'achat à l\'avance de figurines\\nd\'affranchissement ou de bons de courses, représentatifs de courses par coursier.","exclusions":"Le compte 61 – TRANSPORTS ne doit pas servir à enregistrer :\\n- les consommations intermédiaires de biens et de services, lorsque l\'entité\\neffectue des transports pour son propre compte : carburants, réparations de\\nvéhicules, etc\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\ncomptes de charges appropriés","controle":"Le compte 61 – TRANSPORTS peut être contrôlé à partir :\\ndes factures et avoirs fournisseurs ;\\ndes documents de transport (connaissements, lettres de voiture, etc.);\\nde l\'inventaire des figurines d\'affranchissement ;\\ndes bons de course.","motsCles":["transports"]},{"numero":"62","intitule":"Services extérieurs","classe":6,"classeLabel":"Comptes de charges des activités ordinaires","groupe":"B","contenu":"Ces deux comptes enregistrent le montant des factures, paiements et rémunérations versés aux prestataires extérieurs à l\'entité et les éventuels rabais, remises et ristournes obtenus hors factures sur les services extérieurs consommés.","subdivisions":[{"numero":"621","intitule":"SOUS-TRAITANCE GENERALE"},{"numero":"622","intitule":"LOCATIONS ET CHARGES LOCATIVES"},{"numero":"6221","intitule":"Locations de terrains"},{"numero":"6222","intitule":"Locations de bâtiments"},{"numero":"6223","intitule":"Locations de matériels et outillages"},{"numero":"6224","intitule":"Malis sur emballages"},{"numero":"6225","intitule":"Locations d\'emballages"},{"numero":"6226","intitule":"Fermages et loyers du foncier"},{"numero":"6228","intitule":"Locations et charges locatives diverses"},{"numero":"623","intitule":"REDEVANCES DE LOCATION ACQUISITION"},{"numero":"6232","intitule":"Crédit-bail immobilier"},{"numero":"6233","intitule":"Crédit-bail mobilier"},{"numero":"6234","intitule":"location vente"},{"numero":"6235","intitule":"Autres contrats de location acquisition"},{"numero":"624","intitule":"ENTRETIEN, REPARATIONS ET MAINTENANCE"},{"numero":"6241","intitule":"Entretien et réparations des biens immobiliers"},{"numero":"6242","intitule":"Entretien et réparations des biens mobiliers"},{"numero":"6243","intitule":"Maintenance"},{"numero":"6248","intitule":"Autres entretiens et réparations"},{"numero":"625","intitule":"PRIMES D\'ASSURANCE"},{"numero":"6251","intitule":"Assurances multirisques"},{"numero":"6252","intitule":"Assurances matériel de transport"},{"numero":"6253","intitule":"Assurances risques d\'exploitation"},{"numero":"6254","intitule":"Assurances responsabilité du producteur"},{"numero":"6255","intitule":"Assurances insolvabilité clients"},{"numero":"6257","intitule":"Assurances transports sur ventes"},{"numero":"6258","intitule":"Autres primes d\'assurances"},{"numero":"626","intitule":"ETUDES, RECHERCHES ET DOCUMENTATION"},{"numero":"6261","intitule":"Etudes et recherches"},{"numero":"6265","intitule":"Documentation générale"},{"numero":"6266","intitule":"Documentation technique"},{"numero":"627","intitule":"PUBLICITE, PUBLICATIONS, RELATIONS PUBLIQUES"},{"numero":"6271","intitule":"Annonces, insertions"},{"numero":"6272","intitule":"Catalogues, imprimés publicitaires"},{"numero":"6273","intitule":"Echantillons"},{"numero":"6274","intitule":"Foires et expositions"},{"numero":"6275","intitule":"Publications"},{"numero":"6276","intitule":"Cadeaux à la clientèle"},{"numero":"6277","intitule":"Frais de colloques, séminaires, conférences"},{"numero":"6278","intitule":"Autres charges de publicité et relations publiques"},{"numero":"628","intitule":"FRAIS DE TELECOMMUNICATIONS"},{"numero":"6281","intitule":"Frais de téléphone"},{"numero":"6282","intitule":"Frais de télex"},{"numero":"6283","intitule":"Frais de télécopie"},{"numero":"6288","intitule":"Autres frais de télécommunications"}],"fonctionnement":"Les comptes 62 et 63 – SERVICES EXTERIEURS ET AUTRES SERVICES EXTERIEURS\\nsont débités\\n- par le crédit d\'un compte de tiers ou de trésorerie.\\nLes comptes 62 et 63 – SERVICES EXTERIEURS ET AUTRES SERVICES EXTERIEURS\\nsont crédités\\n- par le débit des comptes Fournisseurs des rabais, remises et ristournes\\néventuellement obtenus hors factures.\\nLes comptes 62 et 63 – SERVICES EXTERIEURS ET AUTRES SERVICES EXTERIEURS\\nsont crédités soit par le débit du compte 476 – Charges constatées d\'avance\\n(régularisation), soit par le débit du compte 13 – Résultat net de l\'exercice, pour\\nsolde à la clôture de l\'exercice.","commentaires":"","exclusions":"","controle":"Les comptes 62 et 63 – SERVICES EXTERIEURS ET AUTRES SERVICES EXTERIEURS\\npeuvent être contrôlés à partir des factures et avoirs fournisseurs ainsi que des\\ndispositions des contrats.","motsCles":["services","exterieurs"]},{"numero":"63","intitule":"Autres services extérieurs","classe":6,"classeLabel":"Comptes de charges des activités ordinaires","groupe":"B","contenu":"Ces deux comptes enregistrent le montant des factures, paiements et rémunérations\\nversés aux prestataires extérieurs à l\'entité et les éventuels rabais, remises et\\nristournes obtenus hors factures sur les services extérieurs consommés.\\n62 SERVICES EXTÉRIEURS\\n- 621 SOUS-TRAITANCE GENERALE\\n- 622 LOCATIONS ET CHARGES LOCATIVES\\n- 6221 Locations de terrains\\n- 6222 Locations de bâtiments\\n- 6223 Locations de matériels et outillages\\n- 6224 Malis sur emballages\\n- 6225 Locations d\'emballages\\n- 6226 Fermages et loyers du foncier\\n- 6228 Locations et charges locatives diverses\\n- 623 REDEVANCES DE LOCATION ACQUISITION\\n- 6232 Crédit-bail immobilier\\n- 6233 Crédit-bail mobilier\\n- 6234 location vente\\n- 6235 Autres contrats de location acquisition\\n- 624 ENTRETIEN, REPARATIONS ET MAINTENANCE\\n- 6241 Entretien et réparations des biens immobiliers\\n- 6242 Entretien et réparations des biens mobiliers\\n- 6243 Maintenance\\n- 6248 Autres entretiens et réparations\\n- 625 PRIMES D\'ASSURANCE\\n- 6251 Assurances multirisques\\n- 6252 Assurances matériel de transport\\n- 6253 Assurances risques d\'exploitation\\n- 6254 Assurances responsabilité du producteur\\n- 6255 Assurances insolvabilité clients\\n- 6257 Assurances transports sur ventes\\n- 6258 Autres primes d\'assurances\\n- 626 ETUDES, RECHERCHES ET DOCUMENTATION\\n- 6261 Etudes et recherches\\n- 6265 Documentation générale\\n- 6266 Documentation technique\\n- 627 PUBLICITE, PUBLICATIONS, RELATIONS PUBLIQUES\\n- 6271 Annonces, insertions\\n- 6272 Catalogues, imprimés publicitaires\\n- 6273 Echantillons\\n- 6274 Foires et expositions\\n- 6275 Publications\\n- 6276 Cadeaux à la clientèle\\n- 6277 Frais de colloques, séminaires, conférences\\n- 6278 Autres charges de publicité et relations publiques\\n- 628 FRAIS DE TELECOMMUNICATIONS\\n- 6281 Frais de téléphone\\n- 6282 Frais de télex\\n- 6283 Frais de télécopie\\n- 6288 Autres frais de télécommunications\\n63 AUTRES SERVICES EXTÉRIEURS\\n- 631 FRAIS BANCAIRES\\n- 6311 Frais sur titres (, vente, garde)\\n- 6312 Frais sur effets\\n- 6313 Location de coffres\\n- 6314 Commissions d\' affacturage\\n- 6315 Commissions sur cartes de crédit\\n- 6316 Frais d\'émission d\'emprunts\\n- 6317 Frais sur instruments monnaie électronique\\n- 6318 Autres frais bancaires\\n- 632 REMUNERATIONS D\'INTERMEDIAIRES ET DE CONSEILS\\n- 6322 Commissions et courtages sur ventes\\n- 6324 Honoraires des professions règlementées\\n- 6325 Frais d\'actes et de contentieux\\n- 6327 Rémunérations des autres prestataires de services\\n- 6328 Divers frais\\n- 633 FRAIS DE FORMATION DU PERSONNEL\\n- 634 REDEVANCES POUR BREVETS, LICENCES, MARQUES, LOGICIELS, SITES,\\nCONCESSIONS ET DROITS ET VALEURS SIMILAIRES\\n- 6342 Redevances pour brevets, licences\\n- 6343 Redevances pour logiciels\\n- 6344 Redevances pour marques\\n- 6345 Redevances pour sites\\n- 6346 Redevances pour concessions, droits et valeurs similaires\\n- 635 COTISATIONS\\n- 6351 Cotisations\\n- 6358 Concours divers\\n- 637 REMUNERATIONS DE PERSONNEL EXTERIEUR A L\'ENTITE\\n- 6371 Personnel intérimaire\\n- 6372 Personnel détaché ou prêté à l\'entité\\n- 638 AUTRES CHARGES EXTERNES\\n- 6381 Frais de recrutement du personnel\\n- 6382 Frais de déménagement\\n- 6383 Réceptions\\n- 6384 Missions","subdivisions":[{"numero":"631","intitule":"FRAIS BANCAIRES"},{"numero":"6311","intitule":"Frais sur titres (, vente, garde)"},{"numero":"6312","intitule":"Frais sur effets"},{"numero":"6313","intitule":"Location de coffres"},{"numero":"6314","intitule":"Commissions d\' affacturage"},{"numero":"6315","intitule":"Commissions sur cartes de crédit"},{"numero":"6316","intitule":"Frais d\'émission d\'emprunts"},{"numero":"6317","intitule":"Frais sur instruments monnaie électronique"},{"numero":"6318","intitule":"Autres frais bancaires"},{"numero":"632","intitule":"REMUNERATIONS D\'INTERMEDIAIRES ET DE CONSEILS"},{"numero":"6322","intitule":"Commissions et courtages sur ventes"},{"numero":"6324","intitule":"Honoraires des professions règlementées"},{"numero":"6325","intitule":"Frais d\'actes et de contentieux"},{"numero":"6327","intitule":"Rémunérations des autres prestataires de services"},{"numero":"6328","intitule":"Divers frais"},{"numero":"633","intitule":"FRAIS DE FORMATION DU PERSONNEL"},{"numero":"634","intitule":"REDEVANCES POUR BREVETS, LICENCES, MARQUES, LOGICIELS, SITES,"},{"numero":"6342","intitule":"Redevances pour brevets, licences"},{"numero":"6343","intitule":"Redevances pour logiciels"},{"numero":"6344","intitule":"Redevances pour marques"},{"numero":"6345","intitule":"Redevances pour sites"},{"numero":"6346","intitule":"Redevances pour concessions, droits et valeurs similaires"},{"numero":"635","intitule":"COTISATIONS"},{"numero":"6351","intitule":"Cotisations"},{"numero":"6358","intitule":"Concours divers"},{"numero":"637","intitule":"REMUNERATIONS DE PERSONNEL EXTERIEUR A L\'ENTITE"},{"numero":"6371","intitule":"Personnel intérimaire"},{"numero":"6372","intitule":"Personnel détaché ou prêté à l\'entité"},{"numero":"638","intitule":"AUTRES CHARGES EXTERNES"},{"numero":"6381","intitule":"Frais de recrutement du personnel"},{"numero":"6382","intitule":"Frais de déménagement"},{"numero":"6383","intitule":"Réceptions"},{"numero":"6384","intitule":"Missions"}],"fonctionnement":"Les comptes 62 et 63 – SERVICES EXTERIEURS ET AUTRES SERVICES EXTERIEURS\\nsont débités\\n- par le crédit d\'un compte de tiers ou de trésorerie.\\nLes comptes 62 et 63 – SERVICES EXTERIEURS ET AUTRES SERVICES EXTERIEURS\\nsont crédités\\n- par le débit des comptes Fournisseurs des rabais, remises et ristournes\\néventuellement obtenus hors factures.\\nLes comptes 62 et 63 – SERVICES EXTERIEURS ET AUTRES SERVICES EXTERIEURS\\nsont crédités soit par le débit du compte 476 – Charges constatées d\'avance\\n(régularisation), soit par le débit du compte 13 – Résultat net de l\'exercice, pour\\nsolde à la clôture de l\'exercice.","commentaires":"Les services sont classés par nature ; leur importance et leur diversité sont telles\\nqu\'il a été nécessaire d\'utiliser deux comptes à deux chiffres (62 et 63), dont le\\nfonctionnement est rigoureusement identique.\\nLa consommation de services est rapportée à la période comptable par le jeu de\\ncomptes d\'abonnements ou de régularisation.\\nLe personnel intérimaire, détaché ou prêté est le personnel salarié d\'une entité qui\\n- le met à la disposition d\'une autre entité utilisatrice des services pour une durée\\ndéterminée. La prestation est facturée comme service extérieur par l\'entité\\nemployeur qui peut être :\\nune entité de travail temporaire ;\\nune autre entité industrielle ou commerciale, appartenant généralement\\nau même groupe.\\nEn vertu du principe de la prééminence de la réalité sur l\'apparence juridique :\\nen cours d\'exercice, l\'entité utilisatrice enregistre les factures reçues de\\n- l\'entité de travail temporaire (ou des autres entités employeurs) au débit\\ndu compte 637\\nRémunérations de personnel extérieur à l\'entité;\\nà la clôture de l\'exercice, le compte 637 est viré, pour solde, au débit du\\ncompte\\n- 667 Rémunération transférée de personnel extérieur.\\nLes rémunérations des autres prestataires de services non-salariés d\'une autre\\nentité, ou non mis à disposition par une autre entité doivent être enregistrées au\\ncompte\\n- 6327 Rémunérations des autres prestataires de services ou au compte 6324 Honoraires\\ndes professions réglementées.\\nNe sont pas considérés comme étant des services consommés et sont en principe\\nclassés dans la même catégorie que les produits dans la fabrication desquels ils sont\\nincorporés :\\n- les travaux à façon : consistent à confier à une personne ou à une entité à qui on\\nfournit les matières premières et éventuellement du matériel pour fabriquer,\\ndes produits semi finis, ou finis suivant des spécifications bien définies.\\n- les sous-traitances industrielles : La sous-traitance est le fait qu\'une entreprise\\ndonnée confie partiellement sa production à une autre dans le cadre d\'un travail\\nde sous-œuvre. La sous- traitance industrielle consiste, pour une entreprise à\\nconfier la réalisation à une entreprise, dite « sous-traitant », d\'une ou de\\nplusieurs opérations de conception, d\'élaboration, de fabrication, de mise en\\nœuvre ou de maintenance du produit. Ces opérations concernent un cycle de\\nproduction déterminé.\\n- les frais de réparation, lorsqu\'ils sont effectués par le fabricant du produit.\\nLorsqu\'ils le sont par un réparateur, ils sont inscrits au compte 63.","exclusions":"","controle":"Les comptes 62 et 63 – SERVICES EXTERIEURS ET AUTRES SERVICES EXTERIEURS\\npeuvent être contrôlés à partir des factures et avoirs fournisseurs ainsi que des\\ndispositions des contrats.","motsCles":["services","exterieurs"]},{"numero":"64","intitule":"Impôts et taxes","classe":6,"classeLabel":"Comptes de charges des activités ordinaires","groupe":"B","contenu":"Ce compte enregistre le montant des charges correspondant à des versements\\nobligatoires à l\'Etat et aux collectivités publiques pour subvenir à des dépenses\\npubliques, ou encore des versements institués par les autorités pour le financement\\nd\'actions d\'intérêt général.","subdivisions":[{"numero":"641","intitule":"IMPÔTS ET TAXES DIRECTS"},{"numero":"6411","intitule":"Impôts fonciers et taxes annexes"},{"numero":"6412","intitule":"Patentes, licences et taxes annexes"},{"numero":"6413","intitule":"Taxes sur appointements et salaires"},{"numero":"6414","intitule":"Taxes d\'apprentissage"},{"numero":"6415","intitule":"Formation professionnelle continue"},{"numero":"6418","intitule":"Autres impôts et taxes directs"},{"numero":"645","intitule":"IMPÔTS ET TAXES INDIRECTS"},{"numero":"646","intitule":"DROITS D\'ENREGISTREMENT"},{"numero":"6461","intitule":"Droits de mutation"},{"numero":"6462","intitule":"Droits de timbre"},{"numero":"6463","intitule":"Taxes sur les véhicules de société"},{"numero":"6464","intitule":"Vignettes"},{"numero":"6468","intitule":"Autres droits"},{"numero":"647","intitule":"PENALITES ET AMENDES FISCALES"},{"numero":"6471","intitule":"Pénalités d\'assiette, impôts directs"},{"numero":"6472","intitule":"Pénalités d\'assiette, impôts indirects"},{"numero":"6473","intitule":"Pénalités de recouvrement, impôts directs"},{"numero":"6474","intitule":"Pénalités de recouvrement, impôts indirects"},{"numero":"6478","intitule":"Autres amendes pénales et fiscales"},{"numero":"648","intitule":"AUTRES IMPÔTS ET TAXES"}],"fonctionnement":"Le compte 64 – IMPÔTS ET TAXES est débité du montant de l\'impôt dû\\n- par le crédit du compte 44 – Etat et Collectivités publiques ou\\n- par le crédit des comptes de trésorerie.\\nLe compte 64 – IMPÔTS ET TAXES est crédité pour solde à la clôture de l\'exercice\\n- par le débit du compte 13 – Résultat net de l\'exercice.","commentaires":"Le compte 64 enregistre tous les impôts et taxes à la charge de l\'entité, à l\'exception\\nde ceux dont l\'assiette est établie sur les résultats qui sont inscrits au débit du\\ncompte 89 – Impôts sur le résultat.\\nLes impôts, qui, payés par l\'entité, doivent être récupérés sur des tiers ou sur le\\nTrésor public, sont enregistrés aux comptes de la classe 4.\\nLes entités comprennent dans le prix d\'achat des marchandises, matières et\\nfournitures, les droits de douane qui peuvent leur être affectés de façon certaine,\\npour obtenir le prix d\'achat rendu frontière.\\nLe compte 6411 – Impôts fonciers et taxes annexes enregistre les versements\\nobligatoires à l\'Etat dont l\'entité propriétaire d\'un immeuble bâti ou non bâti ou\\nd\'un terrain doit s\'acquitter, en application des lois en vigueur dans chacun des\\nEtats-parties.\\nLe compte 6412 – Patentes, licences et taxes annexes enregistre les versements\\nobligatoires à l\'Etat dont l\'entité doit s\'acquitter :\\n(cas de la patente) du fait de l\'exercice d\'un commerce, d\'une industrie ou d\'une\\nprofession. La patente peut, en fonction des dispositions fiscales dans les Etats-\\nparties, comporter un droit fixe unique indépendamment du nombre de\\ncommerces, d\'industries et de professions qu\'il exerce dans le même\\nétablissement et, par ailleurs, un droit proportionnel généralement établi sur la\\nvaleur locative des bureaux, magasins, boutiques, usines, ateliers, hangars,\\nremises, chantiers, terrains de dépôts et autres locaux et emplacements servant\\nà l\'exercice de la profession ;\\n(cas de la licence) du fait de l\'exploitation d\'un brevet. C\'est le cas notamment\\ndes exploitants de débits de boisson, de restaurants.\\nLe compte 6413 – Taxes sur appointements et salaires enregistre les versements\\nobligatoires à l\'Etat dont l\'entité est redevable, en qualité d\'employeur, au titre des\\ntraitements, salaires, indemnités et émoluments versés.\\nLe compte 646 – Droits d\'enregistrement enregistre les versements obligatoires à\\n- l\'Etat dont l\'entité est redevable en raison :\\ndes perceptions requises par la recette des impôts pour l\'accomplissement de\\ncertains actes juridiques, tels que des ventes, des échanges, des mutations, des\\ndonations, des successions, des baux, des constitutions de sociétés ;\\nde timbres afférents à certains actes écrits : timbres de quittances, timbres de\\ncontrats de transport, timbres des affiches, timbres sur les bordereaux d\'achat\\nou de vente en Bourse ;\\ndes taxes sur les véhicules de société et vignettes (autos, motos, bateaux, etc.).\\nLe compte 647 – Pénalités et amendes fiscales enregistre les versements\\nobligatoires à l\'Etat dont l\'entité est redevable en raison de l\'inobservation de\\ndispositions fiscales telles que :\\n- les pénalités d\'assiette consistant en intérêts ou indemnités de retard exigibles\\nen cas d\'inexactitude dans les déclarations, manœuvres frauduleuses, défaut de\\nproduction ou production tardive de documents ;\\n- les pénalités de recouvrement sanctionnant le versement tardif des impôts et\\ntaxes qui sont déductibles.\\nLe compte 648 – Autres impôts et taxes enregistre les autres versements\\nobligatoires à l\'Etat et aux collectivités locales dont l\'entité est redevable, en raison\\ndes activités exercées, et qui ne peuvent pas être imputées aux comptes ci- dessus\\ndéfinis.","exclusions":"Le compte 64 – IMPÔTS ET TAXES ne doit pas servir à enregistrer :\\n- les annuités de remboursement d\'emprunts contractés ou d\'avances consenties\\npar l\'Etat\\n- les droits de douane relatifs aux acquisitions d\'immobilisations\\n- les droits de douane relatifs à des achats de biens importés incorporés au prix\\nd\'achat (prix rendu frontière)\\n- l\'impôt sur les bénéfices\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n16 – Emprunts et dettes assimilées\\nde la classe 2\\n60 – Achats et variations de stocks\\n89 – Impôts sur le résultat","controle":"Le compte 64 – IMPÔTS ET TAXES peut être contrôlé à partir :\\ndes déclarations ;\\ndes avis d\'imposition ;\\ndes règlements à l\'ordre du Trésor.","motsCles":["impots","taxes"]},{"numero":"65","intitule":"Autres charges (sauf 659)","classe":6,"classeLabel":"Comptes de charges des activités ordinaires","groupe":"B","contenu":"Ce compte enregistre le montant des charges, de caractère souvent accessoire, qui\\nentrent dans les consommations de l\'exercice en provenance de tiers pour le calcul\\nde la valeur ajoutée de gestion, dans le cadre des choix opérés par le Système\\nComptable OHADA.","subdivisions":[{"numero":"651","intitule":"PERTES SUR CREANCES CLIENTS ET AUTRES DEBITEURS"},{"numero":"6511","intitule":"Clients"},{"numero":"6515","intitule":"Autres débiteurs"},{"numero":"652","intitule":"QUOTE-PART DE RESULTAT SUR OPERATIONS FAITES EN COMMUN"},{"numero":"6521","intitule":"Quote-part transférée de bénéfices (comptabilité du gérant)"},{"numero":"6525","intitule":"Pertes imputées par transfert (comptabilité des associés non gérants)"},{"numero":"654","intitule":"VALEURS COMPTABLES DES CESSIONS COURANTES D\'IMMOBILISATIONS"},{"numero":"658","intitule":"CHARGES DIVERSES"},{"numero":"6581","intitule":"Indemnités de fonction et autres rémunérations d\'administrateurs"},{"numero":"6582","intitule":"Dons"},{"numero":"6583","intitule":"Mécénat"},{"numero":"6588","intitule":"Autres charges diverses"}],"fonctionnement":"Les comptes 651 à 658 – AUTRES CHARGES (sauf 654) sont débités du montant de\\nla charge\\n- par le crédit d\'un compte de tiers ou de trésorerie\\nLe compte 654 – VALEURS COMPTABLES DES CESSIONS COURANTES\\nD\'IMMOBILISATIONS est débité du montant de la valeur brute et crédité des\\namortissements de l\'immobilisation cédée\\nLes comptes 651 à 658 – AUTRES CHARGES sont crédités pour solde à la clôture de\\n- l\'exercice\\n- par le débit du compte 13 – Résultat net de l\'exercice.","commentaires":"Les créances clients et autres débiteurs irrécouvrables sont enregistrées au débit du\\ncompte 651 pertes sur créances et autres débiteurs.\\nLa quote-part de bénéfice revenant aux associés d\'une société en participation\\n(dont la comptabilité est tenue par un gérant, seul connu des tiers) sera enregistrée\\ndans les livres du gérant de la société en participation au débit du compte\\n- 6521 Quote-part transférée de bénéfice par le crédit du compte 463 Associés, opérations\\nfaites en commun.\\nLa perte imputée aux associés par la société en participation sera enregistrée dans\\nla comptabilité des associés par le compte débit du compte 6525 Pertes imputés\\npar transfert au crédit du compte\\n- 463 Associés, opérations faites en commun.\\nLorsqu\'une entité qui, du fait de la nature de son activité renouvelle de manière\\nfréquente ses immobilisations (loueurs de biens, transporteur,…). La valeur brute et\\n- les amortissements des biens de ces entités, sont enregistrés au compte 654 Valeurs\\ncomptables des cessions courantes d\'immobilisations.\\nLes dispositions de l\'Acte uniforme de l\'OHADA relatif au droit des sociétés\\ncommerciales et du GIE prévoient :\\nune indemnité de fonction fixée par l\'assemblée générale ordinaire pour\\nla rémunération des activités des administrateurs ;\\nune rémunération exceptionnelle pour des missions et mandats confiés\\n- par le conseil d\'administration.\\nCes rémunérations sont enregistrées au débit du compte 6581 Indemnités de\\nfonction et autres rémunérations d\'administrateurs par le crédit du compte\\n- 4715 Rémunérations des administrateurs.\\nLes dons et libéralités de toute nature effectués par l\'entité au profit d\'une autre\\npersonne dans le cadre d\'une politique de mécénat destinée à favoriser le\\ndéveloppement d\'activités humanitaires, civiques, culturelles ou sportives sont\\nenregistrés au débit du compte 6582\\nDons ou 6583 Mécénat.","exclusions":"Le compte 65 – AUTRES CHARGES ne doit pas servir à enregistrer :\\n- les charges H.A.O. constatées\\namoindrissement de la valeur d\'une créance dont les effets ne sont pas jugés\\nirréversibles\\ncessions d\'immobilisations non fréquentes et récurrentes\\nlibéralités et dons à l\'occasion d\'évènements exceptionnels tels les phénomènes\\nnaturels : sécheresse, inondations, tempête, vols de criquets, guerres,\\ntremblement de terre, …..\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n- 831 – Charges H.A.O. constatées\\n- 659 charges pour dépréciations et provisions pour risques à court terme\\n81 Valeurs comptables des cessions d\'immobilisations\\n- 835 Dons et libéralités accordés","controle":"Le compte 65 – AUTRES CHARGES peut être contrôlé à partir :\\ndes factures ;\\ndes notifications de cessation de paiement relevées ou du courrier des avocats ;\\nétats financiers de la société en participation\\n- le procès-verbal de l\'assemblée générale ou du conseil d\'administration","motsCles":["charges","659"]},{"numero":"659","intitule":"Charges pour dépréciations et provisions pour risques a court terme d\'exploitation","classe":6,"classeLabel":"Comptes de charges des activités ordinaires","groupe":"B","contenu":"Ce compte enregistre les dotations pour dépréciation des éléments de l\'actif\\ncirculant ainsi que les dotations aux provisions pour risques à court terme.","subdivisions":[{"numero":"6591","intitule":"sur risques à court terme"},{"numero":"6593","intitule":"sur stocks"},{"numero":"6594","intitule":"sur créances"},{"numero":"6598","intitule":"Autres charges pour dépréciations et provisions pour risques à court terme"}],"fonctionnement":"Le compte 659 – CHARGES POUR DÉPRÉCIATIONS ET PROVISIONS POUR RISQUES\\nA COURT TERME D\'EXPLOITATION est débité\\n- par le crédit des comptes de dépréciation de l\'actif circulant, comptes\\n39 et 49 et du compte 499 – Provisions pour risques à court terme (passif)\\nLe compte 659 – CHARGES POUR DÉPRÉCIATIONS ET PROVISIONS POUR RISQUES\\nA COURT TERME D\'EXPLOITATION est crédité pour solde à la clôture de l\'exercice\\n- par le débit du compte 13 – Résultat net de l\'exercice.","commentaires":"Les charges pour dépréciations et provisions pour risques à court terme répondent\\nà une conception nouvelle du risque. En effet, le\\nSystème Comptable OHADA considère ces dotations comme des décaissements\\nprobables à brève échéance. Elles figurent dans le Compte de résultat comme des\\ncharges externes.","exclusions":"Le compte 659 – CHARGES POUR DÉPRÉCIATIONS ET PROVISIONS POUR RISQUES\\nA COURT TERME D\'EXPLOITATION ne doit pas servir à enregistrer :\\n- les Dépréciations et les provisions pour risques à court terme H.A.O.\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n- 839 – Charges pour dépréciations et provisions pour risques à court terme H.A.O.","controle":"Le compte 659 – CHARGES POUR DÉPRÉCIATIONS ET PROVISIONS POUR RISQUES\\nA COURT TERME D\'EXPLOITATION peut être contrôlé à partir des factures,\\nnotifications de cessation de paiements, relevés, ou des courriers des avocats.","motsCles":["charges","depreciations","provisions","risques","court","terme","exploitation"]},{"numero":"66","intitule":"Charges de personnel","classe":6,"classeLabel":"Comptes de charges des activités ordinaires","groupe":"B","contenu":"Ce compte enregistre l\'ensemble des rémunérations du personnel de l\'entité, qu\'il\\ns\'agisse d\'appointements et salaires, de commissions, de congés payés, de primes, de\\ngratifications, d\'indemnités de logement ou d\'indemnités diverses, et, le cas\\néchéant, les rémunérations de l\'exploitant individuel, en contrepartie du travail\\nfourni. Il enregistre aussi les charges sociales payées par l\'entité au titre des\\nsalaires, ainsi que les avantages en nature.\\nPar ailleurs il est débité en fin d\'exercice des montants facturés à l\'entité au titre du\\nPersonnel extérieur, intérimaire, détaché ou prêté.","subdivisions":[{"numero":"661","intitule":"REMUNERATIONS DIRECTES VERSEES AU PERSONNEL NATIONAL"},{"numero":"6611","intitule":"Appointements, salaires et commissions"},{"numero":"6612","intitule":"Primes et gratifications"},{"numero":"6613","intitule":"Congés payés"},{"numero":"6614","intitule":"Indemnités de préavis, de licenciement et de recherche d\'embauche"},{"numero":"6615","intitule":"Indemnités de maladie versées aux travailleurs"},{"numero":"6616","intitule":"Supplément familial"},{"numero":"6617","intitule":"Avantages en nature"},{"numero":"6618","intitule":"Autres rémunérations directes"},{"numero":"662","intitule":"REMUNERATIONS DIRECTES VERSEES AU PERSONNEL NON NATIONAL"},{"numero":"6621","intitule":"Appointements, salaires et commissions"},{"numero":"6622","intitule":"Primes et gratifications"},{"numero":"6623","intitule":"Congés payés"},{"numero":"6624","intitule":"Indemnités de préavis, de licenciement et de recherche d\'embauche"},{"numero":"6625","intitule":"Indemnités de maladie versées aux travailleurs"},{"numero":"6626","intitule":"Supplément familial"},{"numero":"6627","intitule":"Avantages en nature"},{"numero":"6628","intitule":"Autres rémunérations directes"},{"numero":"663","intitule":"INDEMNITES FORFAITAIRES VERSEES AU PERSONNEL"},{"numero":"6631","intitule":"Indemnités de logement"},{"numero":"6632","intitule":"Indemnités de représentation"},{"numero":"6633","intitule":"Indemnités d\'expatriation"},{"numero":"6638","intitule":"Autres indemnités et avantages divers"},{"numero":"664","intitule":"CHARGES SOCIALES"},{"numero":"6641","intitule":"Charges sociales sur rémunération du personnel national"},{"numero":"6642","intitule":"Charges sociales sur rémunération du personnel non national"},{"numero":"666","intitule":"RÉMUNÉRATION ET CHARGES SOCIALES DE L\'EXPLOITANT INDIVIDUEL"},{"numero":"6661","intitule":"Rémunération du travail de l\'exploitant"},{"numero":"6662","intitule":"Charges sociales"},{"numero":"667","intitule":"REMUNERATION TRANSFEREE DE PERSONNEL EXTERIEUR"},{"numero":"6671","intitule":"Personnel intérimaire"},{"numero":"6672","intitule":"Personnel détaché ou prêté à l\'entité"},{"numero":"668","intitule":"AUTRES CHARGES SOCIALES"},{"numero":"6681","intitule":"Versements aux Syndicats et Comités d\'entreprise, d\'établissement"},{"numero":"6682","intitule":"Versements aux Comités d\'hygiène et de sécurité"},{"numero":"6683","intitule":"Versements aux autres œuvres sociales"},{"numero":"6684","intitule":"Médecine du travail et pharmacie"},{"numero":"6685","intitule":"Assurances et organismes de santé"},{"numero":"6686","intitule":"Assurances retraite et fonds de pension"}],"fonctionnement":"Le compte 66 – CHARGES DE PERSONNEL est débité\\n- par le crédit du compte 422 – Personnel, rémunérations dues ;\\n- ou par le crédit du compte 781 – Transferts de charges d\'exploitation.\\nLe compte 66 – CHARGES DE PERSONNEL est débité des charges afférentes à ces\\nrémunérations\\n- par le crédit du compte 43 – Organismes sociaux ;\\n- ou par le crédit du compte 44 – Etat et Collectivités publiques.\\nLe compte 66 – CHARGES DE PERSONNEL (compte 667) est débité des charges de\\npersonnel extérieur\\n- par le crédit du 78– Transferts de charges des rémunérations de personnel\\nextérieur à l\'entité (en fin d\'exercice).\\nLe compte 66 – CHARGES DE PERSONNEL est crédité pour solde à la clôture de\\n- l\'exercice\\n- par le débit du compte 13 – Résultat net de l\'exercice.","commentaires":"Les charges de personnel comprennent toutes les charges supportées par l\'entité, à\\ntitre obligatoire ou bénévole, qui prennent leur source dans les contrats de travail\\nqu\'elle a conclus et qui bénéficient directement ou indirectement aux salariés.\\nLe compte 66 (sauf 667) est débité de la rémunération brute versée au personnel,\\n- les cotisations sociales mises à la charge des salariés étant débitées au compte 42 –\\nPersonnel par le crédit du compte 43 – Organismes sociaux. Les frais de voyage, de\\nréception, les diverses dépenses exposées par le personnel dans l\'exercice de ses\\nfonctions pour le compte de son employeur et dont le montant lui est soit\\nremboursé, soit compris dans les rémunérations, doivent en principe être\\négalement enregistrés en 62 ou 63.\\nLes avantages en nature dont bénéficie le personnel sont enregistrés par l\'entité\\ndans les différents comptes de charges par nature concernée. Ces avantages en\\nnature sont ensuite transférés dans les frais de personnel. Les entités débitent le\\ncompte\\n66 – Charges de personnel par le crédit du compte 78 – Transferts de charges.\\nLe compte 667 est débité, en fin d\'exercice, du montant des rémunérations du\\npersonnel extérieur enregistrées au compte\\n- 637 durant l\'exercice ; ce virement solde le compte 637.","exclusions":"Le compte 66 – CHARGES DE PERSONNEL ne doit pas servir à enregistrer :\\n- les impôts dont l\'assiette repose sur la rémunération\\n- les charges considérées comme des consommations intermédiaires (dépenses\\nexposées par les salariés pour le compte de l\'entité, notamment)\\n- les rémunérations de toutes natures attribuées à des tiers\\n- les indemnités versées à des tierces personnes qui ne sont pas membres de\\n- l\'entité (honoraires)\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n- 6413 – Taxes sur appointements et salaires\\ncomptes appropriés de la classe 6\\n- 632 – Rémunérations d\'intermédiaires et de conseils","controle":"Le compte 66 – CHARGES DE PERSONNEL peut être contrôlé à partir :\\ndes livres de paie ;\\ndes fiches de paie ;\\ndes déclarations sociales et fiscales.","motsCles":["charges","personnel"]},{"numero":"67","intitule":"Frais financiers et charges assimilées","classe":6,"classeLabel":"Comptes de charges des activités ordinaires","groupe":"B","contenu":"Ce compte enregistre l\'ensemble des charges financières dues à différents tiers\\nintervenant dans le financement de l\'entité (à l\'exclusion de la rémunération des\\ncapitaux propres et à celle des services bancaires).","subdivisions":[{"numero":"671","intitule":"INTERÊTS DES EMPRUNTS"},{"numero":"6711","intitule":"Emprunts obligataires"},{"numero":"6712","intitule":"Emprunts auprès des établissements de crédit"},{"numero":"6713","intitule":"Dettes liées à des participations"},{"numero":"6714","intitule":"Primes de remboursement des obligations"},{"numero":"672","intitule":"INTERÊTS DANS LOYERS DE LOCATION ACQUISITION"},{"numero":"6721","intitule":"Intérêts dans loyers de location acquisition / crédit-bail immobilier"},{"numero":"6722","intitule":"Intérêts dans loyers de location acquisition / crédit-bail mobilier"},{"numero":"6723","intitule":"Intérêts dans loyers de location acquisition / location vente"},{"numero":"6724","intitule":"Intérêts dans loyers des autres contrats"},{"numero":"673","intitule":"ESCOMPTES ACCORDES"},{"numero":"674","intitule":"AUTRES INTERÊTS"},{"numero":"6741","intitule":"Avances reçues et dépôts créditeurs"},{"numero":"6742","intitule":"Comptes courants bloqués"},{"numero":"6743","intitule":"Intérêts sur obligations cautionnées"},{"numero":"6744","intitule":"Intérêts sur dettes commerciales"},{"numero":"6745","intitule":"Intérêts bancaires et sur opérations de trésorerie et d\'escompte"},{"numero":"6748","intitule":"Intérêts sur dettes diverses"},{"numero":"675","intitule":"ESCOMPTES DES EFFETS DE COMMERCE"},{"numero":"676","intitule":"PERTES DE CHANGE"},{"numero":"677","intitule":"PERTES SUR TITRES DE PLACEMENT"},{"numero":"6771","intitule":"Pertes sur cessions de titres de placement"},{"numero":"6772","intitule":"Malis provenant d\'attribution gratuite d\'actions au personnel salarié et aux dirigeants"},{"numero":"678","intitule":"PERTES SUR RISQUES FINANCIERS"},{"numero":"6781","intitule":"sur rentes viagères"},{"numero":"6782","intitule":"sur opérations financières"},{"numero":"6784","intitule":"sur instruments de trésorerie"},{"numero":"679","intitule":"CHARGES POUR DEPRECIATIONS ET PROVISIONS POUR RISQUES A COURT TERME"},{"numero":"6791","intitule":"sur risques financiers"},{"numero":"6795","intitule":"sur titres de placement"},{"numero":"6798","intitule":"Autres charges pour dépréciations et provisions pour risques à court terme"}],"fonctionnement":"Le compte 67 (sauf 679) – FRAIS FINANCIERS ET CHARGES ASSIMILEES est débité\\ndes frais dus et des pertes financières constatées\\n- par le crédit des comptes de tiers concernés ou des comptes de trésorerie.\\nLe compte 679 – CHARGES POUR DÉPRÉCIATIONS ET PROVISIONS POUR RISQUES\\nÀ COURT TERME FINANCIERES est débité des dépréciations à court terme des\\nrisques financiers et des comptes de trésorerie\\n- par le crédit du compte 59 – Dépréciations et provisions pour risques à\\ncourt terme (Trésorerie).\\nLe compte 67 – FRAIS FINANCIERS ET CHARGES ASSIMILEES est crédité pour solde\\nà la clôture de l\'exercice\\n- par le débit du compte 13 – Résultat net de l\'exercice.","commentaires":"Lorsque l\'entreprise considère comme frais à immobiliser les intérêts intercalaires\\ndus sur la période de construction d\'une immobilisation, ces intérêts sont d\'abord\\ncomptabilisés au débit du compte 67 – Frais financiers, puis transférés au débit du\\ncompte d\'immobilisation concerné par le crédit du compte 72 – Production\\nimmobilisée.\\nDes nomenclatures internes à l ‘entité doivent permettre de raccorder les intérêts\\npayés ou dus aux emprunts ou avances reçues auxquels ils se rapportent.\\nLe compte 671 – Intérêts des emprunts enregistre le montant des charges\\nfinancières et assimilées que l ‘entité doit payer, en rémunération de l\'utilisation\\ndes capitaux ou des avances de fonds qui lui ont été consentis par des tiers ou des\\nentités liées.\\nLe compte 672 – Intérêts dans loyers de location acquisition enregistre la quote-\\npart des charges financières dans les redevances versées par l ‘entité locataire (cf.\\ntitre VIII Opérations spécifiques chapitre 8).\\nLe compte 673 – Escomptes accordés enregistre le montant des réductions que l\\n‘entité consent sous forme d\'escompte de règlement aux clients qui s\'acquittent de\\nleurs factures ou règlent leurs créances avant le terme normal d\'exigibilité.\\nLe compte 674 – Autres intérêts enregistre les charges financières versées aux\\nassociés et à divers tiers.\\nLe compte 675 – Escomptes des effets de commerce enregistre, après la remise au\\nbanquier de l\'effet à l\'escompte, lors de la réception du bordereau d\'escompte, le\\nmontant indiqué sur le décompte bancaire, au titre des frais prélevés pour\\n- l\'opération d\'escompte.\\nLe compte 676 – Pertes de change enregistre à son débit les pertes de change\\nsupportées par l ‘entité au cours de l\'exercice. Les écarts de conversion négatifs\\nconstatés à la clôture de l\'exercice sur les disponibilités en devises sont considérés\\ncomme étant des pertes de change supportées. Le compte 676 – Pertes de change\\nne doit pas être confondu avec le compte 478 – Ecarts de conversion-Actif qui\\nn\'enregistre que les pertes probables de change.\\nLe compte 677 – Pertes sur titres de placement enregistre les charges nettes\\neffectivement supportées par l\'entité lorsque cette dernière réalise des pertes sur\\ntitres dont le prix de cession se trouverait inférieur au coût d\'acquisition.\\nDans le cas d\'espèce, la perte subie, à savoir la différence entre la valeur d\'entrée et\\n- le prix de cession, net toutefois des frais de cession, est portée au débit du compte\\n- 677 – Pertes titres de placement. Dans le cas où les frais de cession sont enregistrés\\ndistinctement (décalage de facturations), ils sont également portés au débit du\\ncompte 677.\\nLe compte 6772 Malis provenant d\'attribution gratuite d\'actions au personnel\\nsalarié et aux dirigeants est destiné à solder le compte 5021 actions propres lors de\\n- l\'attribution des actions gratuites au personnel salarié et aux dirigeants (voir Titre\\nVIII opérations spécifiques, chapitre 19).\\nLe compte 678 – Pertes sur risques financiers enregistre les pertes subies sur des\\nopérations financières comportant un risque autre que le risque de perte de\\nchange.\\nExemples : rentes viagères, instruments de trésorerie, primes, options...\\nLe compte 679 – Charges pour dépréciations et provisions pour risques à court\\nterme financières enregistre le montant des charges financières potentielles\\névaluées à l\'arrêté des comptes, nettement précisées quant à leur objet, mais dont\\n- l\'échéance ou le montant est incertain.","exclusions":"Le compte 67 – FRAIS FINANCIERS ET CHARGES ASSIMILEES ne doit pas servir à\\nenregistrer :\\n- les remboursements d\'emprunts contractés ou d\'avances reçues\\n- les intérêts intercalaires d\'emprunts dus au titre de la période de construction et\\nde mise en route des immobilisations\\n- les commissions et courtages bancaires, rémunérations de services\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n16 – Emprunts et dettes assimilées\\ncomptes de la classe 2 concernés\\n- 631 – Frais bancaires","controle":"Le compte 67 – FRAIS FINANCIERS ET CHARGES ASSIMILEES peut être contrôlé à\\npartir des relevés de banque et décomptes d\'intérêt.","motsCles":["frais","financiers","charges","assimilees"]},{"numero":"68","intitule":"Dotations aux amortissements","classe":6,"classeLabel":"Comptes de charges des activités ordinaires","groupe":"B","contenu":"Ce compte enregistre, au titre de l\'exercice, les dotations aux amortissements,\\nd\'exploitation et à caractère financier, dans leur conception économique et\\ncomptable (et non pas fiscale).","subdivisions":[{"numero":"681","intitule":"DOTATIONS AUX AMORTISSEMENTS D\'EXPLOITATION"},{"numero":"6812","intitule":"Dotations aux amortissements des immobilisations incorporelles"},{"numero":"6813","intitule":"Dotations aux amortissements des immobilisations corporelles"},{"numero":"687","intitule":"DOTATIONS AUX AMORTISSEMENTS A CARACTERE FINANCIER"}],"fonctionnement":"Le compte 68 – DOTATIONS AUX AMORTISSEMENTS est débité du montant des\\ndotations de la période\\n- par le crédit des comptes d\'amortissements pour le montant de la\\ndépréciation économique de la période\\nLe compte 68 – DOTATIONS AUX AMORTISSEMENTS est crédité pour solde à la\\nclôture de l\'exercice\\n- par le débit du compte 13 – Résultat net de l\'exercice.","commentaires":"L\'amortissement consiste pour l\'entité à répartir le montant amortissable du bien\\nsur sa durée d\'utilité selon un plan prédéfini.\\nLe montant du bien amortissable s\'entend de la différence entre le coût d\'entrée\\nd\'un actif et sa valeur résiduelle prévisionnelle.\\nLe choix du mode de répartition (linéaire, dégressif, variable...) relève de la\\npolitique et de la gestion de l\'entité, dans le respect des principes comptables\\nretenus.\\nLe compte 68 est destiné à enregistrer, à la clôture de l\'exercice, les charges\\n\\"calculées\\" de la période.\\nLe compte 68 enregistre aussi le complément éventuel d\'amortissement relatif aux\\nimmobilisations cédées, mises hors service ou au rebut.\\nLorsque les dispositions fiscales en vigueur autorisent des méthodes\\nd\'amortissements accélérés (amortissement dégressif, etc.) et imposent la\\ncomptabilisation effective des amortissements fiscaux pratiqués, il importe de faire\\napparaître distinctement l\'amortissement technique et économique normal au\\ncompte 68. Le complément d\'amortissement fiscal autorisé figure au débit du\\ncompte 85 – Dotations H.A.O., par le crédit du compte 151 – Amortissements\\ndérogatoires.","exclusions":"Le compte 68 – DOTATIONS AUX AMORTISSEMENTS ne doit pas servir à enregistrer\\n:\\n- les dotations aux provisions\\n- les charges provisionnées\\n- les dotations aux amortissements H.A.O.\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n69 – Dotations aux provisions et aux dépréciations\\n- 659 – Charges pour dépréciations et provisions pour risques à court terme\\nd\'exploitation\\n- 679 – Charges pour dépréciations et provisions pour risques à court terme\\nfinancières\\n- 852 – Dotations aux amortissements H.A.O.","controle":"Le compte 68 – DOTATIONS AUX AMORTISSEMENTS peut être contrôlé à partir des\\nplans et tableaux d\'amortissement.","motsCles":["dotations","amortissements"]},{"numero":"69","intitule":"Dotations aux provisions et aux dépréciations","classe":6,"classeLabel":"Comptes de charges des activités ordinaires","groupe":"B","contenu":"Ce compte enregistre, au titre de l\'exercice, les dotations aux provisions\\nd\'exploitation et à caractère financier, en couverture de dépréciations, risques,\\ncharges ou pertes à prévoir.","subdivisions":[{"numero":"691","intitule":"DOTATIONS AUX PROVISIONS ET AUX DEPRECIATIONS D\'EXPLOITATION"},{"numero":"6911","intitule":"pour risques et charges"},{"numero":"6913","intitule":"des immobilisations incorporelles"},{"numero":"6914","intitule":"des immobilisations corporelles"},{"numero":"697","intitule":"DOTATIONS AUX PROVISIONS ET AUX DEPRECIATIONS FINANCIERES"},{"numero":"6971","intitule":"pour risques et charges"},{"numero":"6972","intitule":"des immobilisations financières"}],"fonctionnement":"Le compte 69 – DOTATIONS AUX PROVISIONS ET AUX DÉPRÉCIATIONS est débité\\ndu montant des dotations de l\'exercice\\n- par le crédit des comptes de provisions (19 et 29).\\nLe compte 69 – DOTATIONS AUX PROVISIONS ET AUX DÉPRÉCIATIONS est crédité\\n- par le débit du compte 13 – Résultat net de l\'exercice pour solde à la clôture\\nde l\'exercice.","commentaires":"La comptabilisation des provisions se fait selon les règles suivantes :\\n- les provisions sont créées ou ajustées en hausse en débitant le compte 69 –\\nDotations aux provisions et par le crédit du compte de provision concerné (19\\nou 29) ;\\n- les provisions sont ajustées en baisse ou annulées en débitant le compte de\\nprovision (19 ou 29) par le crédit du compte 79 – Reprises de provisions, de\\ndépréciations et autres ;\\nlorsqu\'un risque ou une charge provisionnée se réalise, il est régulièrement\\ncomptabilisé dans un compte approprié de la classe 6 ou 8.\\nEn conséquence, la provision est reprise intégralement (débit : compte 19 ou 29 ;\\ncrédit : compte 79).","exclusions":"Le compte 69 – DOTATIONS AUX PROVISIONS ET AUX DÉPRÉCIATIONS ne doit pas\\nservir à enregistrer :\\n- les dotations aux provisions H.A.O.\\n- les charges à la clôture de l\'exercice correspondant à la dépréciation probable\\nconstatée sur les éléments de l\'actif circulant (stocks, clients)\\n- les charges correspondant à la dépréciation probable constatée sur les éléments\\nde trésorerie\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n85 – Dotations H.A.O.\\n- 659 – Charges pour dépréciations et provisions pour risques à court terme\\nd\'exploitation\\n- 679 – Charges pour dépréciations et provisions pour risques à court terme\\nfinancières","controle":"Le compte 69 – DOTATIONS AUX PROVISIONS ET AUX DEPRECIATIONS peut être\\ncontrôlé à partir de tous documents susceptibles d\'éclairer le jugement sur les\\ncharges à prévoir par suite de dépréciation d\'éléments d\'actif ou les risques\\nattachés à des événements ou opérations intervenus au cours de l\'exercice.\\n\\n# CLASSE 7 : COMPTES DE PRODUITS DES\\nACTIVITÉS ORDINAIRES\\nLes produits sont généralement pris en compte lorsqu\'une augmentation des\\nretombées économiques, liée à une augmentation d\'actif ou à une diminution de\\npassif, s\'est produite et qu\'elle peut être mesurée de façon fiable.\\nLa comptabilisation des produits résultant de contrats avec les clients doit traduire\\n- le transfert à un client du contrôle d\'un bien ou d\'un service pour le montant\\nauquel le vendeur s\'attend à avoir droit. En général,\\nLe transfert est opéré à la date de livraison du bien ou de l\'achèvement de la\\nprestation de service.\\nLes comptes de la classe 7 enregistrent les produits liés à l\'activité ordinaire de\\n- l\'entité. Ils résultent en principe de la vente de biens ou de services, de la\\nproduction de biens ou de services non encore vendus ou livrés à soi-même.\\nDoivent être rattachés à l\'exercice, tous les produits le concernant effectivement et\\nceux-là seulement. A la clôture de l\'exercice, ces produits donnent éventuellement\\nlieu à régularisation.","motsCles":["dotations","provisions","depreciations"]},{"numero":"70","intitule":"Ventes","classe":7,"classeLabel":"Comptes de produits des activités ordinaires","groupe":"B","contenu":"Ce compte enregistre les ressources de l\'entité provenant de la vente des\\nmarchandises, des travaux effectués et des services rendus à des tiers.","subdivisions":[{"numero":"701","intitule":"VENTES DE MARCHANDISES"},{"numero":"7011","intitule":"dans la Région (1)"},{"numero":"7012","intitule":"hors Région (1)"},{"numero":"7013","intitule":"aux entités du groupe dans la Région"},{"numero":"7014","intitule":"aux entités du groupe hors Région"},{"numero":"7015","intitule":"sur internet"},{"numero":"702","intitule":"VENTES DE PRODUITS FINIS"},{"numero":"7021","intitule":"dans la Région (1)"},{"numero":"7022","intitule":"hors Région (1)"},{"numero":"7023","intitule":"aux entités du groupe dans la Région"},{"numero":"7024","intitule":"aux entités du groupe hors Région"},{"numero":"7025","intitule":"sur internet"},{"numero":"703","intitule":"VENTES DE PRODUITS INTERMEDIAIRES"},{"numero":"7031","intitule":"dans la Région (1)"},{"numero":"7032","intitule":"hors Région (1)"},{"numero":"7033","intitule":"aux entités du groupe dans la Région"},{"numero":"7034","intitule":"aux entités du groupe hors Région"},{"numero":"7035","intitule":"sur internet"},{"numero":"704","intitule":"VENTES DE PRODUITS RESIDUELS"},{"numero":"7041","intitule":"dans la Région (1)"},{"numero":"7042","intitule":"hors Région (1)"},{"numero":"7043","intitule":"aux entités du groupe dans la Région"},{"numero":"7044","intitule":"aux entités du groupe hors Région"},{"numero":"7045","intitule":"sur internet"},{"numero":"705","intitule":"TRAVAUX FACTURES"},{"numero":"7051","intitule":"dans la Région (1)"},{"numero":"7052","intitule":"hors Région (1)"},{"numero":"7053","intitule":"aux entités du groupe dans la Région"},{"numero":"7054","intitule":"aux entités du groupe hors Région"},{"numero":"7055","intitule":"sur internet"},{"numero":"706","intitule":"SERVICES VENDUS"},{"numero":"7061","intitule":"dans la Région (1)"},{"numero":"7062","intitule":"hors Région (1)"},{"numero":"7063","intitule":"aux entités du groupe dans la Région"},{"numero":"7064","intitule":"aux entités du groupe hors Région"},{"numero":"7065","intitule":"sur internet"},{"numero":"707","intitule":"PRODUITS ACCESSOIRES"},{"numero":"7071","intitule":"Ports, emballages perdus et autres frais facturés"},{"numero":"7072","intitule":"Commissions et courtages (2)"},{"numero":"7073","intitule":"Locations (2)"},{"numero":"7074","intitule":"Bonis sur reprises et cessions d\'emballage"},{"numero":"7075","intitule":"Mise à disposition de personnel (2)"},{"numero":"7076","intitule":"Redevances pour brevets, logiciels, marques et droits similaires (2)"},{"numero":"7077","intitule":"Services exploités dans l\'intérêt du personnel"},{"numero":"7078","intitule":"Autres produits accessoires"}],"fonctionnement":"Le compte 70 – VENTES est crédité du montant des facturations hors taxes si les\\ntaxes sont facturées.\\nLe compte 443 – VENTES est crédité du montant des taxes si les taxes collectées\\nsont facturées.\\n- par le débit du compte 41 – Clients et comptes rattachés ;\\n- ou par le débit d\'un compte de trésorerie.\\nLe compte 70 – VENTES est débité des retours hors taxes facturées sur ventes et des\\nrabais, remises et ristournes accordés hors factures aux clients\\nLe compte 441 – ETAT TVA FACTUREE est débité des taxes facturées des retours sur\\nventes et des rabais, remises et ristournes accordés hors factures aux clients\\n- par le crédit du compte client 41– Clients et comptes rattachés ;\\n- ou par le crédit du compte 13 – Résultat net de l\'exercice, pour solde du compte\\n70 à la clôture de l\'exercice","commentaires":"Le compte 701 est ouvert par les entités commerciales.\\nLes entités qui ont seulement une activité industrielle utilisent les comptes 702 à\\n705.\\nLes ventes sont comptabilisées dans l\'entité selon une nomenclature compatible\\navec la nomenclature de biens et services en usage dans chacun des Etats-parties.\\nLe prix de vente s\'entend du prix facturé, le cas échéant, net de taxes collectées,\\ndéductions faites des rabais et remises lorsqu\'ils sont déduits sur la facture elle-\\nmême.\\nMême lorsqu\'ils sont déduits sur la facture de vente, les escomptes de règlement\\nsont comptabilisés au débit du compte 673 – Escomptes accordés.","exclusions":"Le compte 70 – VENTES ne doit pas servir à enregistrer :\\n- les subventions d\'exploitation compensatrices d\'insuffisances de tarifs\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n71 – Subventions d\'exploitation","controle":"Le compte 70 – VENTES peut être contrôlé à partir\\ndes factures de ventes ;\\ndes factures d\'avoirs ;\\nde la vérification des marges.","motsCles":["ventes"]},{"numero":"71","intitule":"Subventions d\'exploitation","classe":7,"classeLabel":"Comptes de produits des activités ordinaires","groupe":"B","contenu":"Ce sont des aides financières accordées par l\'Etat, des collectivités publiques ou des\\ntiers, qui ne sont ni des fonds de dotation, ni des subventions d\'investissement. Elles\\nsont destinées à compenser l\'insuffisance du prix de vente administré, ou à faire\\nface à des charges d\'exploitation.","subdivisions":[{"numero":"711","intitule":"SUR PRODUITS A L\'EXPORTATION"},{"numero":"712","intitule":"SUR PRODUITS A L\'IMPORTATION"},{"numero":"713","intitule":"SUR PRODUITS DE PEREQUATION"},{"numero":"718","intitule":"AUTRES SUBVENTIONS D\'EXPLOITATION"},{"numero":"7181","intitule":"Versées par l\'Etat et les collectivités publiques"},{"numero":"7182","intitule":"Versées par les organismes internationaux"},{"numero":"7183","intitule":"Versées par des tiers"}],"fonctionnement":"Le compte 71 – SUBVENTIONS D\'EXPLOITATION est crédité des subventions\\nacquises\\n- par le débit du compte 4495 – Etat, subventions d\'exploitation à recevoir\\n- ou par le débit du compte 4582 – Organismes internationaux, subventions à\\nrecevoir ;\\net par le débit des comptes de trésorerie concernés à la date de l\'encaissement.\\nLe compte 71 – SUBVENTIONS D\'EXPLOITATION est débité pour solde à la clôture\\nde l\'exercice\\n- par le crédit du compte 13 – Résultat net de l\'exercice","commentaires":"Les subventions d\'exploitation ne doivent pas être confondues avec les subventions\\nd\'investissement ou d\'équilibre.\\nElles peuvent être accordées sous des formes variées : primes d\'embauche, primes\\nde création d\'emplois.","exclusions":"Le compte 71- SUBVENTIONS D\'EXPLOITATION ne doit pas servir à enregistrer :\\n- les aides accordées par les collectivités publiques et organismes internationaux\\nayant le caractère de fonds de dotation\\n- les subventions accordées en vue d\'acquérir, de créer, de remplacer et de mettre\\nen l\'état des immobilisations\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n- 102 – Capital par dotation\\n14 – Subventions d\'investissement","controle":"Le compte 71 – SUBVENTIONS D\'EXPLOITATION peut être contrôlé à partir des\\ncourriers d\'octroi des subventions.","motsCles":["subventions","exploitation"]},{"numero":"72","intitule":"Production immobilisée","classe":7,"classeLabel":"Comptes de produits des activités ordinaires","groupe":"B","contenu":"Ce compte enregistre le coût de production des travaux faits par l\'entité pour elle-\\nmême.","subdivisions":[{"numero":"721","intitule":"Immobilisations incorporelles"},{"numero":"722","intitule":"Immobilisations corporelles"},{"numero":"724","intitule":"Production auto-consommée"},{"numero":"726","intitule":"Immobilisations financières (1)"}],"fonctionnement":"Le compte 72 – PRODUCTION IMMOBILISEE est crédité\\n- par le débit du compte 21 – Immobilisations incorporelles\\n- ou par le débit du compte 23 – Bâtiments, installations techniques et\\nagencements ; ou 24 – Matériel, mobilier et actifs biologiques.\\nLe compte 72 – PRODUCTION IMMOBILISEE est débité pour solde à la clôture de\\n- l\'exercice\\n- par le crédit du compte 13 – Résultat net de l\'exercice","commentaires":"Le compte 72 – Production immobilisée enregistre les travaux effectués par l\'entité\\npour elle – même au coût de production déterminé par la comptabilité analytique\\nde gestion ou à défaut par des calculs extra- comptables.\\nLes calculs extra-comptables doivent néanmoins cerner le coût de production des\\nbiens concernés en intégrant tous les intrants, notamment:\\n- le coût d\'acquisition des matériaux consommés pour la production des biens ;\\n- les autres coûts engagés sous forme de charges directes de production et des\\ncharges indirectes rattachables ;\\n- les frais financiers supportés sur les emprunts exclusivement affectés au\\nfinancement de la fabrication des biens concernant la période de fabrication.\\nLa production auto-consommée est constituée par des consommations prélevées\\nsur la production de l\'exploitation, sans contrepartie monétaire, par l\'exploitant, sa\\nfamille, et les salariés.\\nEn raison de son importance, cette autoconsommation est enregistrée au crédit du\\ncompte 724 Production immobilisée et autoconsommée par le débit :\\ndu compte 104 Compte de l\'exploitant;\\ndu compte 6617 et 6627 Avantages en nature dans le cas de consommation des\\nsalariés.","exclusions":"","controle":"Le compte 72 – PRODUCTION IMMOBILISEE peut être contrôlé à partir:\\ndes immobilisations portées à l\'actif ;\\ndes charges saisies par la comptabilité analytique.","motsCles":["production","immobilisee"]},{"numero":"73","intitule":"Variations des stocks de biens et services produits","classe":7,"classeLabel":"Comptes de produits des activités ordinaires","groupe":"B","contenu":"Ce compte enregistre les variations de stocks de biens et de services produits en\\nretraçant les opérations relatives aux entrées en stocks, aux sorties de stocks et aux\\ndifférences constatées à la clôture de l\'exercice entre l\'inventaire comptable\\npermanent et l\'inventaire physique et, dans le cas de l\'inventaire intermittent, le\\nstock initial et le stock final, ou leur différence.","subdivisions":[{"numero":"734","intitule":"VARIATIONS DES STOCKS DE PRODUITS EN COURS"},{"numero":"7341","intitule":"Produits en cours"},{"numero":"7342","intitule":"Travaux en cours"},{"numero":"735","intitule":"VARIATIONS DES EN-COURS DE SERVICES"},{"numero":"7351","intitule":"Etudes en cours"},{"numero":"7352","intitule":"Prestations de services en cours"},{"numero":"736","intitule":"VARIATIONS DES STOCKS DE PRODUITS FINIS"},{"numero":"737","intitule":"VARIATIONS DES STOCKS DE PRODUITS INTERMEDIAIRES ET RESIDUELS"},{"numero":"7371","intitule":"Produits intermédiaires"},{"numero":"7372","intitule":"Produits résiduels"}],"fonctionnement":"En cas de tenue d\'inventaire intermittent :\\nA la clôture de l\'exercice, le compte 73 – VARIATIONS DES STOCKS DE BIENS ET\\nSERVICES PRODUITS est débité de la valeur du stock initial (1) pour solde\\n- par le crédit des comptes de stocks concernés\\n(1) ou de la diminution de l\'exercice (stock initial moins stock final)\\nA la clôture de l\'exercice, le compte 73 – VARIATIONS DES STOCKS DE BIENS ET\\nSERVICES PRODUITS est crédité de la valeur du stock final (1)\\n- par le débit des comptes de stocks concernés\\nA la clôture de l\'exercice, le compte 73 – VARIATIONS DES STOCKS DE BIENS ET\\nSERVICES PRODUITS est viré, pour solde, avec les produits dans le compte 13 –\\nRésultat net de l\'exercice (montant débiteur ou montant créditeur, selon le cas).\\nEn cas d\'inventaire permanent :\\nEn cours d\'exercice, le compte 73 – VARIATIONS DES STOCKS DE BIENS ET\\nSERVICES PRODUITS est crédité, des entrées en stocks (en-cours, produits fabriqués)\\n- par le débit des comptes de stocks concernés\\nEn cours d\'exercice, le compte 73 – VARIATIONS DES STOCKS DE BIENS ET\\nSERVICES PRODUITS est débité des sorties de stocks (virements d\'en-cours en\\nproduits fabriqués ou du fait de ventes)\\n- par le crédit des comptes de stocks concernés\\nA la clôture de l\'exercice, le compte 73 – VARIATIONS DES STOCKS DE BIENS ET\\nSERVICES PRODUITS est crédité des différences en plus constatées entre l\'inventaire\\ncomptable et l\'inventaire physique\\n- par le débit des comptes de stocks.\\n(1) ou de l\'augmentation de l\'exercice (stock final moins stock initial)\\nA la clôture de l\'exercice, le compte 73 – VARIATIONS DES STOCKS DE BIENS ET\\nSERVICES PRODUITS est débité des différences en moins constatées entre\\n- l\'inventaire comptable et l\'inventaire physique\\n- par le crédit des comptes de stocks\\nA la clôture de l\'exercice, le compte 73 – VARIATIONS DES STOCKS DE BIENS ET\\nSERVICES PRODUITS est viré, pour solde, avec les produits.\\ndans le compte 13 – Résultat net de l\'exercice (montant débiteur ou montant\\ncréditeur, selon le cas)","commentaires":"Le compte 73 donne par son solde la variation des stocks de produits fabriqués,\\npour l\'exercice considéré. Créditeur, il représente l\'augmentation globale de ces\\nstocks du début à la fin de l\'exercice ; débiteur, il représente la diminution de ces\\nstocks (déstockage) ; production de l\'entité, stockée au cours de la période.\\nDans ce cas, il est porté en négatif du côté des produits dans le Compte de résultat.","exclusions":"Le compte 73 – VARIATION DE STOCKS DE BIENS ET SERVICES PRODUITS ne doit\\npas servir à enregistrer :\\nla variation de la période, afférente aux stocks de marchandises, de matières, de\\nfournitures et d\'emballages commerciaux\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\ncomptes 603 – Variations des stocks de biens achetés","controle":"Le compte 73 – VARIATIONS DES STOCKS DE BIENS ET SERVICES PRODUITS peut\\nêtre contrôlé à partir:\\ndes fiches d\'inventaire ;\\nde l\'évaluation des stocks ;\\nde la comptabilité analytique.","motsCles":["variations","stocks","biens","services","produits"]},{"numero":"75","intitule":"Autres produits (sauf compte 759)","classe":7,"classeLabel":"Comptes de produits des activités ordinaires","groupe":"B","contenu":"Ce sont tous les produits divers qui ne proviennent pas directement de l\'activité\\nproductrice ou commerciale de l\'entité, ni de son activité financière ou de ses\\nrelations avec l\'Etat (subventions) mais qui relèvent néanmoins de ses activités\\nordinaires.","subdivisions":[{"numero":"752","intitule":"QUOTE-PART DE RESULTAT SUR OPERATIONS FAITES EN COMMUN"},{"numero":"7521","intitule":"Quote-part transférée de pertes (comptabilité du gérant)"},{"numero":"7525","intitule":"Bénéfices attribués par transfert (comptabilité des associés non gérants)"},{"numero":"754","intitule":"PRODUITS DES CESSIONS COURANTES D\'IMMOBILISATIONS"},{"numero":"758","intitule":"PRODUITS DIVERS"},{"numero":"7581","intitule":"Indemnités de fonction et autres rémunérations"},{"numero":"7582","intitule":"Indemnités d\'assurances reçues"},{"numero":"7588","intitule":"Autres produits divers"}],"fonctionnement":"Le compte 75 – AUTRES PRODUITS est crédité du montant des produits\\n- par le débit des comptes de tiers concernés ou des comptes de trésorerie\\nLe compte 75 – AUTRES PRODUITS est débité pour solde à la clôture de l\'exercice\\n- par le crédit du compte 13 – Résultat net de l\'exercice","commentaires":"La quote-part de résultat sur opérations faites en commun est la reprise dans la\\ncomptabilité de l\'entité du résultat obtenu dans le cadre d\'une autre structure\\n(société en participation ... ) à laquelle l\'entité est associée, mais qui est\\njuridiquement transparente.\\nLe compte 752 – Quote-part de résultats sur opérations faites en commun\\nenregistre:\\npour l\'entité non gérante, sa participation aux bénéfices ;\\npour l\'entité gérante, le montant des pertes mises à la charge des associés non\\ngérants.\\nLe compte 754 – Produits des cessions courantes d\'immobilisations enregistre le\\nprix de cession des immobilisations lorsque ces cessions présentent un caractère\\nordinaire en raison des politiques de désinvestissement et de renouvellement des\\nimmobilisations.\\nLe compte 758 – Produits divers enregistre les autres produits non imputables aux\\nautres subdivisions du compte 75.","exclusions":"Le compte 75 – AUTRES PRODUITS (sauf 759) ne doit pas servir à enregistrer :\\n- les rabais, remises et ristournes accordés, hors factures, aux clients\\nIl convient dans les cas d\'espèce d\'utiliser le compte ci-après :\\ncompte 70 – Ventes","controle":"Le compte 75 – AUTRES PRODUITS peut être contrôlé à partir :\\ndes factures,\\ndes avis bancaires ;\\ndes correspondances échangées.","motsCles":["produits","compte","759"]},{"numero":"759","intitule":"Reprises de charges pour dépréciations et provisions pour risques à court terme d\'exploitation","classe":7,"classeLabel":"Comptes de produits des activités ordinaires","groupe":"B","contenu":"Ce compte enregistre les annulations ou les régularisations en baisse des provisions\\nà court terme sur éléments de l\'actif circulant et des risques provisionnés","subdivisions":[{"numero":"7591","intitule":"sur risques à court terme"},{"numero":"7593","intitule":"sur les stocks"},{"numero":"7594","intitule":"sur les créances"},{"numero":"7598","intitule":"sur autres charges pour dépréciations et provisions pour risques à court terme"}],"fonctionnement":"Le compte 759 – REPRISES DE CHARGES POUR DEPRECIATIONS ET PROVISIONS\\nPOUR RISQUES A COURT TERME D\'EXPLOITATION est crédité du montant des\\ndépréciations d\'actif circulant et des risques provisionnés existant à l\'ouverture de\\n- l\'exercice.\\n- par le débit du compte 39 – Dépréciations des stocks et en cours ou par le\\ndébit du compte 49 – Dépréciations et provisions pour risques à court terme\\n(Tiers).\\nLe compte 759 – REPRISES DE CHARGES POUR DEPRECIATIONS ET DE PROVISIONS\\nPOUR RISQUES A COURT TERME D\'EXPLOITATION est débité pour solde à la clôture\\nde l\'exercice\\n- par le crédit du compte 13 – Résultat net de l\'exercice","commentaires":"Le compte 759 reprend en fin d\'exercice tout ou partie des dépréciations et\\nprovisions à court terme devenues sans objet ou pour toute autre cause justifiant la\\nrégularisation en baisse.\\nSymétriquement aux charges correspondant à des décaissements probables à brève\\néchéance, les reprises doivent être traitées comme des encaissements probables.","exclusions":"Le compte 759 – REPRISES DE CHARGES POUR DEPRECIATIONS ET PROVISIONS\\nPOUR RISQUES A COURT TERME D\'EXPLOITATION ne doit pas servir à enregistrer :\\n- les reprises de dépréciations d\'éléments de l\'actif immobilisé\\n- les reprises de dépréciations d\'éléments à caractère financier\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n- 791 Reprises de charges pour dépréciations et provisions pour risques à court\\nterme d\'exploitation\\n- 797 Reprises de charges pour dépréciations et provisions pour risques à court\\nterme financières","controle":"Le compte 759 – REPRISES DE CHARGES POUR DEPRECIATIONS ET PROVISIONS\\nPOUR RISQUES A COURT TERME D\'EXPLOITATION peut être contrôlé à partir du\\nrelevé des décisions de gestion des organes compétents.","motsCles":["reprises","charges","depreciations","provisions","risques","court","terme","exploitation"]},{"numero":"77","intitule":"Revenus financiers et produits assimilés","classe":7,"classeLabel":"Comptes de produits des activités ordinaires","groupe":"B","contenu":"Ce sont les ressources que tire l\'entité de ses activités financières.","subdivisions":[{"numero":"771","intitule":"INTERETS DE PRÊTS ET CREANCES DIVERSES"},{"numero":"7712","intitule":"Intérêts de prêts"},{"numero":"7713","intitule":"Intérêts sur créances diverses"},{"numero":"772","intitule":"REVENUS DE PARTICIPATIONS ET AUTRES CREANCES IMMOBILISES"},{"numero":"7721","intitule":"Revenus des titres de participation"},{"numero":"7722","intitule":"Revenus des autres titres immobilisés"},{"numero":"773","intitule":"ESCOMPTES OBTENUS"},{"numero":"774","intitule":"REVENUS DE PLACEMENT"},{"numero":"7745","intitule":"Revenus des obligations"},{"numero":"7746","intitule":"Revenus des titres de placement"},{"numero":"775","intitule":"INTERETS DANS LOYERS DE LOCATION ACQUISITION"},{"numero":"776","intitule":"GAINS DE CHANGE"},{"numero":"777","intitule":"GAINS SUR CESSIONS DE TITRES DE PLACEMENT"},{"numero":"778","intitule":"GAINS SUR RISQUES FINANCIERS"},{"numero":"7781","intitule":"sur rentes viagères"},{"numero":"7782","intitule":"sur opérations financières"},{"numero":"7784","intitule":"sur instruments de trésorerie"},{"numero":"779","intitule":"REPRISES DE CHARGES POUR DÉPRÉCIATIONS ET PROVISIONS POUR RISQUES À"},{"numero":"7791","intitule":"sur risques financiers"},{"numero":"7795","intitule":"sur titres de placement"},{"numero":"7798","intitule":"sur Autres charges pour dépréciations et provisions pour risques à court terme"}],"fonctionnement":"Le compte 77 (sauf 779) – REVENUS FINANCIERS ET PRODUITS ASSIMILES est\\ncrédité du montant des produits financiers acquis\\n- par le débit des comptes de tiers concernés ou des comptes de trésorerie\\nLe compte 779 – REPRISES DE CHARGES POUR DEPRECIATIONS ET PROVISIONS\\nPOUR RISQUES A COURT TERME FINANCIERES est crédité de la reprise des\\ndépréciations des comptes de trésorerie et des provisions pour risques à court\\nterme à caractère financier sans objet, existant au début de l\'exercice\\n- par le débit du compte 59 – Dépréciations et provisions pour risques à court\\nterme (Trésorerie), pour solde ou pour rajustement.\\nLe compte 77 – REVENUS FINANCIERS ET PRODUITS ASSIMILES est débité\\n- par le crédit du compte 13 – Résultat net de l\'exercice, pour solde du compte\\n77 en fin d\'exercice","commentaires":"Les intérêts et dividendes reçus de l\'étranger sont comptabilisés distinctement de\\nceux acquis dans l\'Etat.\\nLa subdivision utilisée par l\'entité doit permettre de raccorder les revenus\\nfinanciers et produits assimilés aux prêts ou avances et titres auxquels ils se\\nrapportent.","exclusions":"Le compte 77 – REVENUS FINANCIERS ET PRODUITS ASSIMILES ne doit pas servir à\\nenregistrer :\\n- les récupérations de prêts ou d\'avances consenties\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n27 – Autres immobilisations financières","controle":"Le compte 77 – REVENUS FINANCIERS ET PRODUITS ASSIMILES peut être contrôlé\\nà partir:\\nde virements bancaires ;\\nde décompte d\'intérêts ;\\nde factures avec escompte ;\\nde bordereaux de cession de titres ;\\nd\'encaissement des coupons.","motsCles":["revenus","financiers","produits","assimiles"]},{"numero":"78","intitule":"Transferts de charges Ce compte sert à l\'imputation de charges d\'exploitation ou financières qui doivent être, en raison de leur nature, affectées à un compte de bilan, à l\'exception des immobilisations pour lesquelles le compte 72 – Production immobilisée est utilisé. Le transfert peut concerner les stocks, les comptes de tiers. Il sert aussi, exceptionnellement, à des transferts de charges à charges (exemple : avantages en nature).","classe":7,"classeLabel":"Comptes de produits des activités ordinaires","groupe":"B","contenu":"","subdivisions":[{"numero":"781","intitule":"TRANSFERTS DE CHARGES D\'EXPLOITATION"},{"numero":"787","intitule":"TRANSFERTS DE CHARGES FINANCIERES"}],"fonctionnement":"Le compte 78 – TRANSFERTS DE CHARGES est crédité du montant des charges\\nd\'exploitation ou financières à transférer\\n- par le débit des comptes de bilan concernés (autre que les comptes\\nd\'immobilisation)\\n- par le débit des comptes de charges concernés (en cas de transfert de\\ncharges à charges)\\nLe compte 78 – TRANSFERTS DE CHARGES est débité pour solde à la clôture de\\n- l\'exercice\\n- par le crédit du compte 13 – Résultat net de l\'exercice","commentaires":"Les transferts de charges concernent les dépenses de l\'entité mises à la charge de\\ntiers (remboursement de débours et frais divers) et pouvant aussi le cas échéant\\nêtre opérés vers d\'autres comptes de charges (exemple : avantages en nature\\naccordés au personnel).\\nLes transferts de charges sont à mentionner dans les Notes annexes.","exclusions":"Le compte 78 – TRANSFERTS DE CHARGES ne doit pas servir à enregistrer\\n- les transferts de charges en actif immobilisé\\n- les transferts de charges H.A.O\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n72 – Production immobilisée\\n- 848 – Transferts de charges H.A.O.","controle":"Le compte 78 – TRANSFERTS DE CHARGES peut être contrôlé à partir du relevé des\\ndécisions de gestion des organes compétents.","motsCles":["transferts","charges","compte","sert","imputation","exploitation","financieres","qui","doivent","etre","raison","leur","nature","affectees","bilan","exception","immobilisations","lesquelles","production","immobilisee","est","utilise","transfert","peut","concerner","stocks","comptes","tiers","aussi","exceptionnellement","exemple","avantages"]},{"numero":"79","intitule":"Reprises de provisions, dépréciations et autres","classe":7,"classeLabel":"Comptes de produits des activités ordinaires","groupe":"B","contenu":"Ce compte enregistre les annulations et les rajustements en baisse des provisions\\nfinancières pour risques et charges, ainsi que des provisions pour dépréciation des\\néléments de l\'actif immobilisé.","subdivisions":[{"numero":"791","intitule":"REPRISES DE PROVISIONS ET DE DEPRECIATIONS D\'EXPLOITATION"},{"numero":"7911","intitule":"pour risques et charges"},{"numero":"7913","intitule":"des immobilisations incorporelles"},{"numero":"7914","intitule":"des immobilisations corporelles __________________"},{"numero":"797","intitule":"REPRISES DE PROVISIONS ET DÉPRÉCIATIONS FINANCIÈRES"},{"numero":"7971","intitule":"pour risques et charges"},{"numero":"7972","intitule":"des immobilisations financières"},{"numero":"798","intitule":"REPRISES D\'AMORTISSEMENTS (1)"},{"numero":"799","intitule":"REPRISES DE SUBVENTIONS D\'INVESTISSEMENT"}],"fonctionnement":"Le compte 79 (sauf 799) – REPRISES DE PROVISIONS, DE DEPRECIATIONS ET\\nAUTRES est crédité\\n- par le débit des comptes (19, 29) pour le montant des diminutions des\\nprovisions, par suite d\'annulation ou de réduction.\\nLe compte 799 – REPRISES DE SUBVENTION D\'INVESTISSEMENT est crédité du\\nmontant de la subvention d\'investissement reprise au résultat\\n- par le débit du compte 14 – Subventions d\'investissement.\\nLe compte 79 – REPRISES DE PROVISIONS, DE DEPRECIATIONS ET AUTRES est\\ndébité pour solde à la clôture de l\'exercice\\n- par le crédit du compte 13 – Résultat net de l\'exercice","commentaires":"Les reprises de provisions constatent soit la diminution de la provision ramenée à\\nun montant inférieur, soit l\'intégration dans les résultats de l\'entité de la provision\\nexistante par suite de la réalisation ou de l\'annulation de la charge ou de la\\ndisparition du risque. Dans le cas exceptionnel d\'une révision rétroactive du plan\\nd\'amortissement initial, la réduction du cumul des amortissements est opérée par le\\ncrédit du compte 798 – Reprises d\'amortissements\\nLe compte 799 – Reprises de subventions d\'investissement enregistre à son crédit :\\nsoit un montant égal à celui de la dotation de l\'exercice aux comptes\\nd\'amortissements des immobilisations amortissables acquises ou créées au\\nmoyen de ladite subvention, affecté du coefficient résultant du rapport :\\nMontant de la subvention/Montant de l\'investissement correspondant ;\\nsoit une somme déterminée en fonction du nombre d\'années pendant lesquelles\\n- les immobilisations non amortissables créées ou acquises au moyen de ladite\\nsubvention sont inaliénables aux termes du contrat ou, à défaut de clause\\nd\'inaliénabilité dans le contrat, une somme égale au dixième du montant de la\\nsubvention.","exclusions":"Le compte 79 – REPRISES DE PROVISIONS, DE DEPRECIATIONS ET AUTRES ne doit\\npas servir à enregistrer :\\n- les reprises HAO\\n- les reprises de charges provisionnées\\nIl convient dans le cas d\'espèce d\'utiliser les comptes ci-après :\\n86 Reprises HAO\\n- 759 Reprises de charges pour dépréciations et provisions pour risques à court\\nterme d\'exploitation\\n- 779 Reprises de charges pour dépréciations et provisions pour risques à court\\nterme financières\\n- 849 Reprises de charges pour dépréciations et provisions pour risques à court\\nterme HAO","controle":"Le compte 79 – REPRISES DE PROVISIONS, DE DEPRECIATIONS ET AUTRES peut\\nêtre contrôlé à partir du relevé des décisions des organes compétents.\\n\\n# CLASSE 8 : COMPTES DE RESSOURCES\\nDURABLES\\nL\'utilisation de la classe 8 permet d\'enregistrer les charges et les produits\\ncorrespondant à des opérations qui ne se rapportent pas à l\'activité ordinaire de\\n- l\'entité.\\nLes produits et les charges hors activité ordinaire (H.A.O.) sont liés à des\\nchangements de structure (significatifs) ou de stratégie de l\'entité, aux cessions,\\nchangements importants dans l\'environnement (exemple: modification de la\\nlégislation commerciale qui impliquera sans doute un changement de la stratégie et\\ndes investissements de la firme) ou à des événements extraordinaires (tels les\\nphénomènes naturels : sécheresse, inondations, tempêtes, raz-de-marée,\\ntremblements de terre, vols de criquets ...)\\nLes sorties et les prix de cession des d\'immobilisations sont des charges et produits\\nHAO. Par contre, les opérations relativement légères et régulières d\'investissement\\n– financement (renouvellement du « parc » de matériel sans novation profonde) ne\\ndoivent donc pas être traitées en « H.A.O. », mais être «remontées » dans les\\nactivités ordinaires.\\nLes produits et les charges H.A.O. sont des charges et des produits non récurrents,\\nde nature non liés à l\'activité ordinaire de l\'entité. Ces charges et produits HAO ne\\ndoivent pas être définis en termes moraux, d\'opportunité ou exceptionnels.\\nUne charge ou un produit d\'exploitation d\'un montant exceptionnellement élevé\\ndoit rester inscrite dans le niveau «ordinaire » (exemple : grosse perte sur une\\nimportante créance clients). Le niveau significativement élevé de la charge ou du\\nproduit sera signalé, avec ses conséquences, dans les Notes annexes.\\nUne charge ou un produit d\'exploitation omis au cours d\'un exercice antérieur doit\\nêtre comptabilisé dans les charges ou les produits des Activités ordinaires de\\n- l\'exercice de rectification.\\nFigurent également dans cette classe la participation des travailleurs aux bénéfices\\net l\'impôt sur le résultat.","motsCles":["reprises","provisions","depreciations"]},{"numero":"81","intitule":"Valeurs comptables des cessions d\'immobilisations","classe":8,"classeLabel":"Comptes des autres charges et produits (HAO)","groupe":"B","contenu":"Ce compte sert à déterminer la valeur comptable nette des éléments de l\'actif\\nimmobilisé cédés. Pour les biens non amortissables, cette valeur est la valeur\\nd\'entrée, sans déduction des éventuelles dépréciations. Pour les biens\\namortissables, elle est la différence entre la valeur d\'entrée brute des\\nimmobilisations cédées et le cumul des amortissements pratiqués depuis l\'entrée du\\nbien dans le patrimoine de l\'entité jusqu\'à la date de sa cession.","subdivisions":[{"numero":"811","intitule":"IMMOBILISATIONS INCORPORELLES"},{"numero":"812","intitule":"IMMOBILISATIONS CORPORELLES"},{"numero":"816","intitule":"IMMOBILISATIONS FINANCIERES"}],"fonctionnement":"Le compte 81 – VALEURS COMPTABLES DES CESSIONS D\'IMMOBILISATIONS est\\ndébité de la valeur d\'entrée des éléments sortis sous déduction des amortissements\\npratiqués\\n- par le crédit du compte d\'immobilisation concerné (classe 2).\\nLe compte 81 – VALEURS COMPTABLES DES CESSIONS D\'IMMOBILISATIONS est\\ncrédité pour solde à la clôture de l\'exercice\\n- par le débit du compte 13 – Résultat net de l\'exercice.","commentaires":"Par cession, il faut entendre : vente, échange, mise au rebut ou destruction.\\nLa sortie d\'une immobilisation du patrimoine de l\'entité donne lieu à :\\nconstatation de l\'amortissement complémentaire pour la période écoulée entre\\n- l\'ouverture de l\'exercice et la date de cession du bien ;\\nenregistrement de la sortie du bien pour sa valeur nette au compte 81 sous la\\nforme d\'une double écriture :\\nau débit pour la valeur d\'entrée,\\nau crédit pour le montant total des amortissements pratiqués sur ce bien ;\\ncomptabilisation de la valeur de sortie si celle-ci est supérieure à zéro, au\\ncompte 82 – Produits des cessions d\'immobilisations.\\nLes cessions d\'immobilisations considérées comme courantes (fréquentes et\\nrécurrentes) ne sont pas enregistrées à ce niveau H.A.O., mais dans les comptes 654\\n(Valeur comptable) et 754 (Prix de cession) ; exemples : transporteurs ; loueurs de\\nmatériels ...","exclusions":"Le compte 81 – VALEURS COMPTABLES DES CESSIONS D\'IMMOBILISATIONS ne\\ndoit pas servir à enregistrer :\\n- les dépréciations afférentes aux éléments d\'actif immobilisé cédés\\n- les cessions considérées comme courantes, compte tenu de l\'activité de l\'entité\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n29 – Dépréciations\\n- 654 – Valeurs comptables des cessions courantes d\'immobilisations","controle":"Le compte 81 – VALEURS COMPTABLES DES CESSIONS D\'IMMOBILISATIONS peut\\nêtre contrôlé à partir :\\ndes documents attestant de la valeur de sortie de l\'immobilisation :\\nprocès-verbal de mise au rebut ;\\ndes factures de vente ;\\nd\'un procès-verbal de destruction ;\\ndes tableaux d\'amortissement.","motsCles":["valeurs","comptables","cessions","immobilisations"]},{"numero":"82","intitule":"Produits des cessions d\'immobilisations","classe":8,"classeLabel":"Comptes des autres charges et produits (HAO)","groupe":"B","contenu":"Ce compte enregistre le produit net de la cession : dans le cas de vente, prix\\nrésultant de l\'accord entre les cocontractants et figurant sur l\'acte de vente diminué\\ndes commissions et des frais de vente ; dans le cas d\'apport, montant contractuel,\\netc.","subdivisions":[{"numero":"821","intitule":"IMMOBILISATIONS INCORPORELLES"},{"numero":"822","intitule":"IMMOBILISATIONS CORPORELLES"},{"numero":"826","intitule":"IMMOBILISATIONS FINANCIERES"}],"fonctionnement":"Le compte 82 – PRODUITS DES CESSIONS D\'IMMOBILISATIONS est crédité des\\nproduits de cession d\'actif, nets de commissions et des frais de vente\\n- par le débit du compte de tiers 485 – Créances sur cessions\\nd\'immobilisations ou par le débit d\'un compte de trésorerie\\nLe compte 82 – PRODUITS DES CESSIONS D\'IMMOBILISATIONS est crédité de\\n- l\'indemnité d\'assurance perçue pour indemnisation d\'une destruction\\nd\'immobilisation\\n- par le débit du compte de tiers 485 – Créances sur cessions\\nd\'immobilisations ou par le débit d\'un compte de trésorerie\\nLe compte 82 – PRODUITS DES CESSIONS D\'IMMOBILISATIONS est débité pour\\nsolde du compte à la clôture de l\'exercice\\n- par le crédit du compte 13 – Résultat net de l\'exercice","commentaires":"En cas de versement d\'indemnité d\'assurance pour réparation, celle-ci figurera au\\ncrédit du compte 82, même si l\'entité prend la décision de ne pas effectuer de\\nréparation et de mettre l\'immobilisation au rebut ou de la céder en l\'état (le prix de\\nvente net viendrait dans ce cas en complément au crédit du compte 82).\\nL\'indemnité d\'assurance perçue au cas où le bien est détruit est assimilée au prix de\\ncession.\\nLe produit des cessions considérées comme \\"courantes\\" (cf. compte 81) est\\nenregistré au crédit du compte 754 (niveau Exploitation).","exclusions":"Le compte 82 – PRODUITS DES CESSIONS D\'IMMOBILISATIONS ne doit pas servir à\\nenregistrer :\\n- les indemnités d\'assurances autres que celles représentatives de l\'indemnisation\\ndu bien détruit\\n- les produits des cessions courantes d\'immobilisations\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n- 7582 – Indemnités d\'assurances reçues\\n- 754 – Produits des cessions courantes d\'immobilisations","controle":"Le compte 82 – PRODUITS DES CESSIONS D\'IMMOBILISATIONS peut être contrôlé à\\npartir :\\ndes factures de cession d\'immobilisations ;\\ndes commissions et des frais de vente ;","motsCles":["produits","cessions","immobilisations"]},{"numero":"83","intitule":"Charges hors activités ordinaires","classe":8,"classeLabel":"Comptes des autres charges et produits (HAO)","groupe":"B","contenu":"Ce sont les charges qui ne sont pas liées à l\'activité ordinaire de l\'entité et qui, de ce\\nfait, n\'ont généralement pas de caractère récurrent. Elles comprennent des charges\\nconstatées et des charges pour dépréciations et provisions pour risques à court\\nterme.","subdivisions":[{"numero":"831","intitule":"CHARGES H.A.O. CONSTATEES"},{"numero":"833","intitule":"CHARGES LIEES AUX OPERATIONS DE RESTRUCTURATION"},{"numero":"834","intitule":"PERTES SUR CRÉANCES H.A.O."},{"numero":"835","intitule":"DONS ET LIBÉRALITÉS ACCORDÉS"},{"numero":"836","intitule":"ABANDONS DE CREANCES CONSENTIS"},{"numero":"837","intitule":"CHARGES LIEES AUX OPERATIONS DE LIQUIDATION"},{"numero":"839","intitule":"CHARGES POUR DEPRECIATIONS ET PROVISIONS POUR RISQUES A COURT TERME"}],"fonctionnement":"Le compte 83 – CHARGES HORS ACTIVITES ORDINAIRES est débité des charges\\nconstatées ne concernant pas l\'activité ordinaire de l\'entité\\n- par le crédit d\'un compte de tiers ou de trésorerie.\\nLe compte 83 – CHARGES HORS ACTIVITES ORDINAIRES est débité des charges hors\\nactivités ordinaires non encore engagées, mais dont la survenance à moins d\'un an\\nest probable et mesurable\\n- par le crédit du compte 48 – Créances et dettes H.A.O.\\nLe compte 83 – CHARGES HORS ACTIVITES ORDINAIRES est crédité pour solde à la\\nclôture de l\'exercice\\n- par le débit du compte 13 – Résultat net de l\'exercice.","commentaires":"Seules les charges liées à la restructuration de l\'entité ou à des événements\\nextraordinaires (tels les phénomènes naturels : Sécheresse, inondations tempêtes,\\nraz-de-marée, tremblements de terre, vols de criquets ...) doivent être considérées\\ncomme relevant des activités autres que ordinaires.\\nToute autre charge est ordinaire, y compris, par exemple, les amendes fiscales ou\\npénales. Il en est de même des charges sur exercices antérieurs liées aux activités\\ncourantes de l\'entité.\\nLorsque la réalisation de la charge H.A.O., bien qu\'incertaine, est envisagée à court\\nterme, elle constitue une charge provisionnée.\\nLorsque, au contraire, cette charge probable est envisagée à plus d\'un an, elle doit\\nfaire l\'objet d\'une dotation aux provisions.","exclusions":"Le compte 83 – CHARGES HORS ACTIVITES ORDINAIRES ne doit pas servir à\\nenregistrer :\\n- les provisions pour risques et charges hors activités ordinaires à plus d\'un an\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n- 854 – Dotations aux provisions pour risques et charges H.A.O.","controle":"Le compte 83 – CHARGES HORS ACTIVITES ORDINAIRES peut être contrôlé à partir\\n:\\ndes factures ;\\ndes évaluations ;\\ndes tableaux d\'amortissements ;\\ndes calculs de plus-values, notamment.","motsCles":["charges","hors","activites","ordinaires"]},{"numero":"84","intitule":"Produits hors activités ordinaires","classe":8,"classeLabel":"Comptes des autres charges et produits (HAO)","groupe":"B","contenu":"Ce sont des produits qui ne sont pas liés à l\'activité ordinaire de l\'entité et sont donc\\ndépourvus de caractère récurrent. Ils comprennent des produits constatés, des\\nreprises de charges provisionnées et des transferts de charges.","subdivisions":[{"numero":"841","intitule":"PRODUITS H.A.O. CONSTATES"},{"numero":"843","intitule":"PRODUITS LIES AUX OPERATIONS DE RESTRUCTURATION"},{"numero":"845","intitule":"DONS ET LIBÉRALITÉS OBTENUS"},{"numero":"846","intitule":"ABANDONS DE CREANCES OBTENUS"},{"numero":"847","intitule":"PRODUITS LIES AUX OPERATIONS DE LIQUIDATION"},{"numero":"848","intitule":"TRANSFERTS DE CHARGES H.A.O."},{"numero":"849","intitule":"REPRISES DE CHARGES POUR DÉPRÉCIATIONS ET PROVISIONS POUR RISQUES A COURT TERME H.A.O."}],"fonctionnement":"Le compte 84 – PRODUITS HORS ACTIVITES ORDINAIRES est crédité du montant\\ndes produits constatés\\n- par le débit d\'un compte de tiers ou de trésorerie.\\nLe compte 84 – PRODUITS HORS ACTIVITES ORDINAIRES est crédité des reprises de\\ncharges provisionnées\\n- par le débit du compte 4998 – Provisions pour risques à court terme sur\\nopérations H.A.O.\\nLe compte 84 – PRODUITS HORS ACTIVITES ORDINAIRES est débité pour solde du\\ncompte à la clôture de l\'exercice\\n- par le crédit du compte 13 – Résultat net de l\'exercice.","commentaires":"Les produits sont considérés comme\\nH.A.O. lorsqu\'ils relèvent d\'événements extraordinaires, liés notamment à des\\nphénomènes naturels ou à des modifications de structure de l\'entité.","exclusions":"Le compte 84 – PRODUITS HORS ACTIVITES ORDINAIRES ne doit pas servir à\\nenregistrer :\\n- les reprises de provisions H.A.O. antérieurement constituées\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n86 – Reprises H.A.O.","controle":"Le compte 84 – PRODUITS HORS ACTIVITES ORDINAIRES peut être contrôlé à partir\\nde l\'analyse, des factures, des évaluations et des tableaux de provisions.","motsCles":["produits","hors","activites","ordinaires"]},{"numero":"85","intitule":"Dotations hors activités ordinaires","classe":8,"classeLabel":"Comptes des autres charges et produits (HAO)","groupe":"B","contenu":"Ce compte enregistre les dotations aux amortissements et aux provisions qui ne\\nconcernent pas l\'activité ordinaire de l\'entité.","subdivisions":[{"numero":"851","intitule":"DOTATIONS AUX PROVISIONS REGLEMENTEES"},{"numero":"852","intitule":"DOTATIONS AUX AMORTISSEMENTS H.A.O."},{"numero":"853","intitule":"DOTATIONS AUX DEPRECIATIONS H.A.O."},{"numero":"854","intitule":"DOTATIONS AUX PROVISIONS POUR RISQUES ET CHARGES H.A.O."},{"numero":"858","intitule":"AUTRES DOTATIONS H.A.O."}],"fonctionnement":"Le compte 85 – DOTATIONS HORS ACTIVITES ORDINAIRES est débité du montant\\nde la provision pour risques ou charges H.A.O. ou de l\'amortissement\\n- par le crédit du compte 15 – Provisions réglementées et Fonds assimilés ;\\n- par le crédit du compte 19 – Provisions financières pour risques et charges\\nou du compte 29 – Dépréciations ;\\n- par le crédit du compte 28 – Amortissements.\\nLe compte 85 – DOTATIONS HORS ACTIVITES ORDINAIRES est crédité pour solde à\\nla clôture de l\'exercice\\n- par le débit du compte 13 – Résultat net de l\'exercice.","commentaires":"La notion \\"hors activités ordinaires\\" doit être appréhendée de façon restrictive :\\nrestructurations d\'entités par exemple, autres événements (telles les catastrophes\\nnaturelles) par essence non prévisibles, et dépourvus de caractère récurrent. Le\\ncompte 85 est aussi utilisé dans les Etats- parties pour enregistrer les opérations\\nliées à l\'application de dispositions fiscales (provisions réglementées ...).","exclusions":"Le compte 85 – DOTATIONS HORS ACTIVITES ORDINAIRES ne doit pas servir à\\nenregistrer :\\n- les charges calculées H.A.O. à court terme (moins d\'un an)\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n- 839 – Charges pour dépréciations et provisions pour risques à court terme H.A.O.","controle":"Le compte 85 – DOTATIONS HORS ACTIVITES ORDINAIRES peut être contrôlé à\\npartir de l\'évaluation de la provision.","motsCles":["dotations","hors","activites","ordinaires"]},{"numero":"86","intitule":"Reprises hors activités ordinaires","classe":8,"classeLabel":"Comptes des autres charges et produits (HAO)","groupe":"B","contenu":"Ce compte enregistre les annulations et rajustements en baisse des provisions,\\namortissements et subventions qui ne sont pas liés à l\'activité ordinaire de l\'entité.","subdivisions":[{"numero":"861","intitule":"REPRISES DE PROVISIONS REGLEMENTEES"},{"numero":"862","intitule":"REPRISES D\'AMORTISSEMENTS H.A.O."},{"numero":"863","intitule":"REPRISES DE DEPRECIATIONS H.A.O."},{"numero":"864","intitule":"REPRISES DE PROVISIONS POUR RISQUES ET CHARGES H.A.O."},{"numero":"868","intitule":"AUTRES REPRISES H.A.O."}],"fonctionnement":"Le compte 86 – REPRISES HORS ACTIVITES ORDINAIRES est crédité de l\'annulation\\nou de la réduction de la provision concernée\\n- par le débit du compte 15 – Provisions réglementées et Fonds assimilés, du\\ncompte 19 – Provisions financières pour risques et charges ou par le débit\\ndu compte 29 – Dépréciations.\\nLe compte 86 – REPRISES HORS ACTIVITES ORDINAIRES est débité pour solde à la\\nclôture de l\'exercice\\n- par le crédit du compte 13 – Résultat net de l\'exercice.","commentaires":"Toute provision constituée par l\'intermédiaire du compte 85 – Dotations hors\\nactivités ordinaires doit être reprise au cours de l\'un des exercices suivants par le\\ncompte 86 – Reprises de dotations\\nH.A.O. ; cette reprise se produisant l\'année de survenance de la charge, ou l\'année\\noù l\'appréciation en est modifiée.\\nTel est le cas des Provisions réglementées (compte 15) comme des Provisions\\nfinancières pour risques et charges (compte 19).\\nDes circonstances particulières peuvent justifier des mesures dérogatoires à ces\\ndispositions générales.","exclusions":"Le compte 86 – REPRISES HORS ACTIVITES ORDINAIRES ne doit pas servir à\\nenregistrer :\\n- les reprises de dépréciations et provisions pour risques à court terme\\n- les reprises de dépréciations d\'éléments de l\'actif immobilisé\\n- les reprises de dotations à caractère financier\\n- les dotations aux provisions et aux dépréciations d\'exploitation ou à caractère\\nfinancier\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n- 759 – Reprises de charges pour dépréciations et provisions pour risques à court\\nterme d\'exploitation ou\\n- 779 – Reprises de charges pour dépréciations et provisions pour risques à court\\nterme financières\\n- 791 – Reprises de provisions et de dépréciations d\'exploitation\\n- 797 – Reprises de provisions et de dépréciations financières\\n- 691 – Dotations aux provisions et aux dépréciations d\'exploitation ou\\n- 697 – Dotations aux provisions et aux dépréciations financières","controle":"Le compte 86 – REPRISES HORS ACTIVITES ORDINAIRES peut être contrôlé à partir\\n:\\ndes tableaux d\'amortissements ;\\ndes tableaux de reprises des écarts de réévaluation ;\\ndes tableaux de reprises de la plus-value de cession à réinvesti","motsCles":["reprises","hors","activites","ordinaires"]},{"numero":"87","intitule":"Participation des travailleurs","classe":8,"classeLabel":"Comptes des autres charges et produits (HAO)","groupe":"B","contenu":"Ce compte enregistre les montants prélevés sur les bénéfices réalisés et affectés par\\n- l\'entité à un fonds légal ou contractuel à l\'avantage des travailleurs.","subdivisions":[{"numero":"871","intitule":"PARTICIPATION LÉGALE AUX BÉNÉFICES"},{"numero":"872","intitule":"PARTICIPATION CONTRACTUELLE AUX BÉNÉFICES"},{"numero":"878","intitule":"AUTRES PARTICIPATIONS"}],"fonctionnement":"Le compte 87 – PARTICIPATION DES TRAVAILLEURS est débité de la part de\\nbénéfices affectée aux salariés au titre de la participation\\n- par le crédit du compte 426 – Personnel, participation aux bénéfices.\\nLe compte 87 – PARTICIPATION DES TRAVAILLEURS est crédité pour solde de ce\\ncompte à la clôture de l\'exercice\\n- par le débit du compte 13 – Résultat net de l\'exercice.","commentaires":"En raison de son assiette de calcul, la \\"participation\\" n\'est pas considérée comme\\nune \\"charge de personnel\\" mais comme un élément de répartition du résultat.","exclusions":"Le compte 87 – PARTICIPATION DES TRAVAILLEURS ne doit pas servir à enregistrer\\n:\\nla participation du personnel au capital de l\'entité\\n- les rémunérations diverses versées au personnel (intéressement)\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n10 – Capital\\n66 – Charges de personnel","controle":"Le compte 87 – PARTICIPATION DES TRAVAILLEURS peut être contrôlé à partir des\\nconventions, des accords d\'entités.","motsCles":["participation","travailleurs"]},{"numero":"88","intitule":"Subventions d\'équilibre","classe":8,"classeLabel":"Comptes des autres charges et produits (HAO)","groupe":"B","contenu":"Ce compte enregistre le montant des subventions allouées par l\'Etat ou l\'un de ses\\ndémembrements à l\'entité, pour lui permettre de compenser, en totalité ou\\npartiellement, des pertes survenues dans des circonstances exceptionnelles.","subdivisions":[{"numero":"881","intitule":"ETAT"},{"numero":"884","intitule":"COLLECTIVITÉS PUBLIQUES"},{"numero":"886","intitule":"GROUPE"},{"numero":"888","intitule":"AUTRES"}],"fonctionnement":"Le compte 88 – SUBVENTIONS D\'EQUILIBRE est crédité du montant des\\nsubventions d\'équilibre allouées à l\'entité\\n- par le débit d\'un compte de tiers ou de trésorerie.\\nLe compte 88 – SUBVENTIONS D\'EQUILIBRE est débité pour solde de ce compte à la\\nclôture de l\'exercice\\n- par le crédit du compte 13 – Résultat net de l\'exercice.","commentaires":"Il importe, avant tout enregistrement, d\'analyser la subvention pour en définir la\\nfinalité : aide à l\'investissement, à l\'exploitation ou à l\'équilibre.\\nLes subventions d\'équilibre se distinguent des subventions d\'exploitation en ce\\nqu\'elles ne sont pas directement liées à une insuffisance des prix de vente imposés.","exclusions":"Le compte 88 – SUBVENTIONS D\'EQUILIBRE ne doit pas servir à enregistrer :\\n- les subventions d\'investissement\\n- les subventions d\'exploitation\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n14 – Subventions d\'investissement\\n71 – Subventions d\'exploitation","controle":"Le compte 88 – SUBVENTIONS D\'EQUILIBRE peut être contrôlé à partir de décrets\\nou d\'arrêtés ministériels, de décisions de collectivités publiques accordant la\\nsubvention.","motsCles":["subventions","equilibre"]},{"numero":"89","intitule":"Impôts sur le résultat","classe":8,"classeLabel":"Comptes des autres charges et produits (HAO)","groupe":"B","contenu":"C\'est la part de bénéfice affectée obligatoirement à l\'Etat au titre de l\'impôt sur le\\nrésultat","subdivisions":[{"numero":"891","intitule":"IMPÔTS SUR LES BENEFICES DE L\'EXERCICE"},{"numero":"8911","intitule":"Activités exercées dans l\'Etat"},{"numero":"8912","intitule":"Activités exercées dans les autres Etats de la Région"},{"numero":"8913","intitule":"Activités exercées hors Région"},{"numero":"892","intitule":"RAPPELS D\'IMPÔTS SUR RESULTATS ANTERIEURS"},{"numero":"895","intitule":"IMPÔT MINIMUM FORFAITAIRE (I.M.F.)"},{"numero":"899","intitule":"DÉGREVEMENTS ET ANNULATIONS D\'IMPÔTS SUR RÉSULTATS ANTÉRIEURS"},{"numero":"8991","intitule":"Dégrèvements"},{"numero":"8994","intitule":"Annulations pour pertes rétroactives"}],"fonctionnement":"Le compte 89 – IMPÔTS SUR LE RESULTAT est débité de l\'impôt exigible\\n- par le crédit du compte 441 – Etat, impôt sur les bénéfices.\\nLe compte 89 – IMPÔTS SUR LE RESULTAT est crédité pour solde de ce compte à la\\nclôture de l\'exercice\\n- par le débit du compte 13 – Résultat net de l\'exercice.","commentaires":"Le montant de l\'impôt sur le résultat doit être calculé sur la base du résultat\\ncomptable retraité selon les règles fiscales.\\nLe compte 891 doit correspondre au montant total de l\'impôt dû de l\'exercice,\\nquelles que soient les modalités de règlement, éventuellement augmenté des\\nrappels d\'impôts et diminué des dégrèvements et des annulations sur des exercices\\nantérieurs","exclusions":"Le compte 89 – IMPÔTS SUR LE RESULTAT ne doit pas servir à enregistrer :\\n- les impôts et taxes\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n64 – Impôts et taxes","controle":"Le compte 89 – IMPÔTS SUR LE RESULTAT peut être contrôlé à partir :\\nde la liasse fiscale ;\\ndes notifications et rappels d\'impôt de la Direction Générale des Impôts\\n(D.G.I.)\\n\\n# CLASSE 9 : COMPTES DES ENGAGEMENTS\\nHORS BILAN ET COMPTES DE LA\\nCOMPTABILITÉ ANALYTIQUE DE GESTION\\nSous-Section 1 : Comptes des engagements hors bilan (90-91)\\nL\'usage de la classe 9 est facultatif. Toutefois, cette classe permet à l\'entité\\nd\'enregistrer les engagements hors bilan et, à ce titre, facilite la confection des\\nNotes annexes.\\nLes engagements hors bilan représentent les droits et obligations de l\'entité dont les\\neffets chiffrables sur le montant et la consistance du patrimoine sont subordonnés à\\nla réalisation de conditions ou d\'événements ultérieurs.\\nPour être enregistrés, les engagements hors bilan doivent faire obligatoirement\\n- l\'objet d\'une convention écrite.\\nLes engagements hors bilan se distinguent en deux rubriques, engagements\\nobtenus et engagements accordés ; chaque rubrique est subdivisée selon les natures\\nsuivantes : engagements de financement, engagements de garantie, engagements\\nréciproques, autres engagements.\\nLes engagements obtenus, représentatifs de droits, s\'enregistrent par convention et\\npar analogie avec les créances du bilan au débit des comptes 901 à 904.\\nPar analogie avec les dettes du bilan, les engagements accordés, qui constituent des\\nobligations, s\'enregistrent par convention au crédit des comptes 905 à 908.\\nLes comptes de contrepartie des engagements hors bilan (obtenus et accordés)\\nsont:911 à\\n- 914 – Contreparties des comptes 901 à 904 ;\\n- 915 à 918 – Contreparties des Comptes 905 à 908.\\nLes entités doivent répartir par tous moyens techniques adéquats leurs\\nengagements hors bilan, en fonction de la durée initiale ainsi que de la qualité des\\nbénéficiaires ou donneurs d\'ordre.\\nElles doivent également identifier les garanties obtenues couvrant les créances et\\n- les garanties accordées en couverture des dettes figurant au bilan","motsCles":["impots","resultat"]},{"numero":"9011","intitule":"Crédits confirmés obtenus","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Le solde débiteur de ce compte représente la partie non utilisée des crédits qu\'une\\nbanque s\'est engagée, d\'une façon irrévocable, à accorder à l\'entité, y compris les\\ncrédits documentaires import- export confirmés.","subdivisions":[],"fonctionnement":"A la notification du crédit confirmé, le compte 9011 – CRÉDITS CONFIRMÉS\\nOBTENUS est débité\\n- par le crédit du compte de contrepartie 9lll\\nLors de l\'utilisation partielle ou totale du crédit confirmé, le compte 9011 –\\nCRÉDITS CONFIRMES OBTENUS est crédité\\n- par le débit du compte de contrepartie 9111","commentaires":"Le crédit documentaire est une opération de crédit à court terme ayant pour objet\\n- le financement des transactions commerciales internationales. Par l\'intermédiaire\\nde cet instrument financier, l\'acheteur donne l\'ordre à son banquier de verser au\\nbanquier du vendeur la valeur des marchandises en cours de route, contre remise\\nde documents prouvant l\'expédition et la conformité des marchandises.\\nPar l\'ouverture de crédit documentaire, l\'acheteur reçoit de son banquier\\n- l\'engagement de régler au vendeur la valeur des marchandises.","exclusions":"Le compte 9011 – CREDITS CONFIRMES OBTENUS ne doit pas servir à enregistrer :\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après : CREDOC","controle":"Le compte 9011 – CRÉDITS CONFIRMÉS OBTENUS peut être contrôlé à partir des\\nlettres de notification de la banque.","motsCles":["credits","confirmes","obtenus"]},{"numero":"9012","intitule":"Emprunts restant à encaisser","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Ce compte enregistre la partie non encore encaissée des emprunts contractés par\\n- l\'entité auprès des tiers autres que les établissements bancaires, notamment les\\nfiliales et les sociétés – mères.","subdivisions":[],"fonctionnement":"A la signature de la convention,\\nLe compte 9012 – EMPRUNTS RESTANT A ENCAISSER et débité\\n- par le crédit du compte de contrepartie 9112\\nLors de la mobilisation partielle ou totale de l\'emprunt,\\nLe compte 9012 – EMPRUNTS RESTANT A ENCAISSER est crédité\\n- par le débit du compte de contrepartie 9112","commentaires":"","exclusions":"Le compte 9012 – EMPRUNTS RESTANT\\nA ENCAISSER ne doit pas servir à enregistrer :\\n- les crédits bancaires notifiés non encore encaissés\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci – après :\\n- 9011 – Crédits confirmés obtenus","controle":"Le compte 9012 – EMPRUNTS RESTANT A ENCAISSER peut être contrôlé à l\'aide des\\nconventions de prêt.","motsCles":["emprunts","restant","encaisser"]},{"numero":"9013","intitule":"Facilités de financement renouvelables","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"","subdivisions":[],"fonctionnement":"","commentaires":"","exclusions":"","controle":"","motsCles":["facilites","financement","renouvelables"]},{"numero":"9014","intitule":"Facilités d\'émission","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"","subdivisions":[],"fonctionnement":"","commentaires":"","exclusions":"","controle":"","motsCles":["facilites","emission"]},{"numero":"9018","intitule":"Autres engagements de financement obtenus","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Les facilités de financement renouvelables sont des contrats par lesquels un\\nensemble de banques (syndicat bancaire) s\'engage, pour une période donnée,\\nenvers un émetteur de titres (entité industrielle ou commerciale) soit à lui acheter\\ntout ou partie des titres qu\'il pourrait émettre, soit à lui consentir un crédit d\'un\\nmontant équivalent. Dans le cas d\'émission de billets de trésorerie, ces facilités\\nprennent le nom de \\" lignes de substitution \\".\\nLes facilités d\'émission sont des contrats par lesquels un établissement de crédit\\ns\'engage, dans le cadre d\'une émission de titres, à consentir des concours de\\ntrésorerie à la société émettrice, sans pour autant acquérir les titres qui n\'auraient\\npas trouvé de preneurs sur le marché.\\nLes autres engagements de financement obtenus sont des engagements autres que\\n- les facilités de financement renouvelables et les facilités d\'émission.","subdivisions":[],"fonctionnement":"A la signature de la convention, les comptes 9013, 9014 et 9018 sont débités du\\nmontant des engagements obtenus ou de la part non utilisée de ces engagements\\n- par le crédit respectif des comptes de contrepartie 9113, 9114 et 9118.\\nA l\'échéance ou au dénouement des engagements, les comptes 9013, 9014 et 9018\\nsont crédités\\n- par le débit respectif des comptes de contrepartie 9113, 9114 et 9118.","commentaires":"\\" L\'engagement à payer \\" représente, dans le cadre d\'un crédit documentaire\\nconfirmé, l\'engagement pris par la banque (émettrice) de payer l\'exportateur ou la\\nbanque de ce dernier sur simple présentation, à l\'échéance, de l\'acceptation.","exclusions":"Les comptes 9013, 9014 et 9018 ne doivent pas servir à enregistrer :\\n- les crédits confirmés\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci – après :\\n- 9011 – Crédits confirmés obtenus","controle":"Les comptes 9013 – FACILITES DE FINANCEMENT RENOUVELABLES, 9014 –\\nFACILITE D\'EMISSION et 9018 – AUTRES ENGAGEMENTS DE FINANCEMENT\\nOBTENUS peuvent être contrôlés à partir des conventions conclues dans le cadre\\nd\'émission de titre et des effets représentatifs des \\" engagements à payer\\" obtenus","motsCles":["engagements","financement","obtenus"]},{"numero":"9021","intitule":"Avals obtenus","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"L\'avaliseur prend l\'engagement de payer au créancier, à l\'échéance, tout ou partie\\ndu nominal d\'une lettre de change, d\'un billet à ordre ou d\'un chèque, à la place du\\ntiré ou du souscripteur, en cas de défaillance éventuelle de celui-ci.","subdivisions":[],"fonctionnement":"A la conclusion de la transaction,\\nLe compte 9021 – AVALS OBTENUS est débité\\n- par le crédit du compte de contrepartie 9121.\\nA l\'échéance ou au dénouement de la transaction,\\nLe compte 9021 – AVALS OBTENUS est crédité\\n- par le débit du compte de contrepartie 9121.","commentaires":"L\'avaliseur peut être un établissement bancaire ou un autre tiers.","exclusions":"","controle":"Le compte 9021 – AVALS OBTENUS peut être contrôlé à l\'aide des effets avalisés.","motsCles":["avals","obtenus"]},{"numero":"9022","intitule":"Cautions, garanties obtenues","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"La caution s\'engage à payer l\'entité créancière au cas où le débiteur de cette\\ndernière n\'exécuterait pas son obligation.","subdivisions":[],"fonctionnement":"A la conclusion du contrat, le compte 9022 – CAUTIONS, GARANTIES OBTENUES est\\ndébité\\n- par le crédit du compte de contrepartie 9122.\\nA l\'échéance et au dénouement de la transaction, le compte 9022 – CAUTIONS,\\nGARANTIES OBTENUES est crédité\\n- par le débit du compte de contrepartie 9122.","commentaires":"Il convient de distinguer les cautions bancaires et les cautions obtenues des autres\\ntiers.\\nLes cautions bancaires se présentent essentiellement sous forme :\\nde cautions fiscales et de cautions en douane ;\\nde cautions sur marchés.\\nLes cautions fiscales concernent principalement les obligations cautionnées, les\\ncautions pour impositions constatées et les cautions pour paiement différé des\\ndroits d\'enregistrement.\\nLes cautions en douane comprennent notamment les cautions pour admissions\\ntemporaires, les cautions de transit ou acquit-à-caution, les cautions d\'entrepôts, les\\ncautions pour transbordement à destination de l\'étranger, les lettres de garantie\\npour absence de connaissement original, les soumissions pour absence de certificat\\nd\'origine. Les cautions sur marchés, notamment publics, revêtent plusieurs formes\\ndont les plus importantes sont\\n- les cautions de soumission ou cautions provisoires ;\\n- les cautions de bonne fin des travaux ou cautions définitives ;\\n- les cautions de retenue de garantie ;\\n- les cautions de remboursement d\'acomptes ;\\n- les cautions d\'avances de démarrage ;\\n- les cautions pour avances forfaitaires.\\nS\'agissant des cautions obtenues des autres tiers, seules les lettres d\'intention ou\\nlettres de confort assimilables à un cautionnement contiennent de véritables\\nobligations pour le garant. Les autres lettres d\'intention sont de simples\\ndéclarations constitutives tout au plus d\'un engagement moral ou d\'une obligation\\nde moyens, rarement de résultat.","exclusions":"Le compte 9022 – CAUTIONS, GARANTIES OBTENUES ne doit pas servir à\\nenregistrer :\\n- les gages\\n- les nantissements\\n- les antichrèses\\nIl convient dans les cas d\'espèce d\'utiliser le compte ci-après :\\n- 9028 – Autres garanties obtenues","controle":"Le compte 9022 – CAUTIONS, GARANTIES OBTENUES peut être contrôlé à l\'aide des\\nconventions de prêts et de l\'acte constitutif de la caution","motsCles":["cautions","garanties","obtenues"]},{"numero":"9023","intitule":"Hypothèques obtenues","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Lorsque l\'entité reçoit de son débiteur un immeuble en hypothèque, cette dernière\\nlui confère le droit de faire saisir et vendre l\'immeuble en quelques mains qu\'il se\\ntrouve et de se faire payer par préférence sur le prix de la vente.","subdivisions":[],"fonctionnement":"A l\'inscription de l\'hypothèque, le compte 9023 – HYPOTHEQUES OBTENUES est\\ndébité de la valeur de l\'immeuble telle que fixée au début de la transaction\\n- par le crédit du compte de contrepartie 9123.\\nAu dénouement de la créance ou à la réalisation de l\'hypothèque, le compte 9023 –\\nHYPOTHEQUES OBTENUES est crédité\\n- par le débit du compte de contrepartie 9123.","commentaires":"La validité de l\'hypothèque est assurée par son inscription sur un registre légal\\n(cadastre, domaine, registre foncier, etc.).","exclusions":"Le compte 9023 – HYPOTHEQUES OBTENUES ne doit pas servir à enregistrer :\\n- les promesses d\'hypothèques\\n- les gages\\n- les nantissements\\n- les antichrèses\\nIl convient dans les cas d\'espèce d\'utiliser le compte ci-après:\\n- 9028 – Autres garanties obtenues","controle":"Le compte 9023 – HYPOTHEQUES OBTENUES peut être contrôlé à partir des\\nconventions de prêts, des récépissés d\'inscription de l\'hypothèque, des rapports\\nd\'expertise immobilière.","motsCles":["hypotheques","obtenues"]},{"numero":"9024","intitule":"Effets endossés par des tiers","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Dans le cadre de la garantie d\'endossement, l\'endosseur (le débiteur de l\'entité) est,\\nsauf clause contraire, garant de l\'acceptation et du paiement de l\'effet.","subdivisions":[],"fonctionnement":"A la réception de l\'effet endossé, le compte 9024 – EFFETS ENDOSSÉS PAR DES\\nTIERS est débité\\n- par le crédit du compte de contrepartie 9124.\\nA l\'échéance ou au dénouement de l\'opération, le compte 9024 – EFFETS\\nENDOSSÉS PAR DES TIERS est crédité\\n- par le débit du compte de contrepartie 9124.","commentaires":"L\'endossement est le mode de transmission des titres à ordre. Il est réalisé par une\\nsignature apposée au dos du titre par le porteur appelé endosseur. L\'endossataire,\\nbénéficiaire de l\'endossement, peut être désigné ; s\'il ne l\'est pas, l\'endossement\\npeut être au porteur ou en blanc.\\nLes effets de l\'endossement varient selon la nature de l\'endossement : endossement\\nde procuration, endossement pignoratif ou endossement translatif.\\nL\'endossement de procuration emporte pour l\'endossataire l\'obligation de\\nprésenter le titre au paiement pour le compte de l\'endosseur qui lui en a donné\\nmandat.\\nL\'endossement pignoratif confère à l\'endossataire un droit de gage sur le titre remis\\npar l\'endosseur.\\nL\'endossement translatif transfère à l\'endossataire tous les droits résultant du titre\\nendossé.\\nLorsque l\'entité réendosse ou escompte les effets reçus et endossés par des tiers, le\\ncompte 9024 – Effets endossés par des tiers n\'est pas mouvementé. Toutefois,\\n- l\'entité doit enregistrer l\'engagement qu\'elle prend ainsi dans les comptes\\nd\'engagements donnés (effets sous endos ou effets escomptés).","exclusions":"Le compte 9024 – EFFETS ENDOSSÉS PAR DES TIERS ne doit pas servir à\\nenregistrer :\\n- les effets transmis aux tiers par endossement de procuration\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n- 9088 – Divers engagements accordés","controle":"Le compte 9024 – EFFETS ENDOSSÉS PAR DES TIERS peut être contrôlé à partir des\\neffets reçus et des bordereaux d\'escompte.","motsCles":["effets","endosses","tiers"]},{"numero":"9028","intitule":"Autres garanties obtenues","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Les autres garanties obtenues comprennent notamment le gage, le nantissement et\\n- l\'antichrèse pour lesquels l\'engagement porte spécialement sur un ou plusieurs\\nbiens affectés à l\'entité créancière en vue de garantir ses droits.","subdivisions":[],"fonctionnement":"A la constitution de la garantie, le compte 9028 – AUTRES GARANTIES OBTENUES\\nest débité de la valeur des biens reçus en garantie\\n- par le crédit du compte de contrepartie 9128.\\nAu dénouement de la créance ou à la réalisation de la garantie, le compte 9028 –\\nAUTRES GARANTIES OBTENUES est crédité\\n- par le débit du compte de contrepartie 9128.","commentaires":"Figurent également dans ce compte: les promesses d\'hypothèque, les chèques de\\ncaution reçus, les actions reçues en garantie de gestion, les effets transmis aux tiers\\npar endossement de procuration (encaissement). L\'antichrèse représente le\\nnantissement sur un immeuble permettant uniquement d\'en percevoir les fruits.","exclusions":"Le compte 9028 – AUTRES GARANTIES OBTENUES ne doit pas servir à enregistrer :\\n- les avals\\n- les cautions\\n- les hypothèques\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n- 9021 – Avals obtenus\\n- 9022 – Cautions, garanties obtenues\\n- 9023 – Hypothèques obtenues","controle":"Le compte 9028 – AUTRES GARANTIES OBTENUES peut être contrôlé à partir des\\nconventions de prêt, de l\'acte constitutif de la garantie, des chèques et des actions.","motsCles":["garanties","obtenues"]},{"numero":"9031","intitule":"Achats de marchandises à terme","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Pour deux partenaires, les engagements réciproques se décomposent en un\\nengagement donné par l\'entité à son cocontractant en contrepartie d\'un\\nengagement reçu de ce dernier. A ce titre, dans le cadre des achats de marchandises\\nà terme, le fournisseur de l\'entité s\'engage à livrer des marchandises et l\'entité\\ns\'engage à en prendre livraison et à en payer le prix convenu à la date de livraison.","subdivisions":[],"fonctionnement":"A la signature de la transaction, le compte 9031 – ACHATS DE MARCHANDISES A\\nTERME est débité\\n- par le crédit du compte de contrepartie 9131\\nA la livraison du marché, le compte 9031 – ACHATS DE MARCHANDISES A TERME\\nest crédité\\n- par le débit du compte de contrepartie 9131","commentaires":"","exclusions":"","controle":"Le compte 9031 – ACHATS DE MARCHANDISES A TERME peut être contrôlé à partir\\ndes demandes d\'achat, des bons de commande, des bons de livraison et des factures","motsCles":["achats","marchandises","terme"]},{"numero":"9032","intitule":"Achats à terme de devises","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Le cocontractant s\'engage à livrer des devises et réciproquement l\'entité s\'engage à\\nlivrer de la monnaie nationale.","subdivisions":[],"fonctionnement":"A la conclusion de la transaction,\\nLe compte 9032 – ACHATS A TERME DE DEVISES est débité\\n- par le crédit du compte de contrepartie 9132.\\nAu dénouement de la transaction,\\nLe compte 9032 – ACHATS A TERME DE DEVISES est crédité\\n- par le débit du compte de contrepartie 9132.","commentaires":"","exclusions":"","controle":"Le compte 9032 – ACHATS A TERME DE DEVISES peut être contrôlé à partir des\\nordres d\'achat et de l\'avis d\'opéré.","motsCles":["achats","terme","devises"]},{"numero":"9033","intitule":"Autres engagements réciproques","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Les commandes fermes des clients sont les engagements irrévocables pris par un\\nclient de régler le prix des travaux exécutés pour son compte conformément à ses\\nspécifications exprimées sur la base des conditions de vente indiquées par l\'entité\\n(fournisseur) selon le cas dans les catalogues, les devis ou les offres de services.\\nLe compte 9038 enregistre les droits relatifs aux engagements réciproques qui ne\\ntrouvent pas place dans les sous- comptes 9031, 9032 et 9033.","subdivisions":[],"fonctionnement":"A la réception de la commande, le compte 9033 – COMMANDES FERMES DES\\nCLIENTS ou le compte 9038 – AUTRES ENGAGEMENTS RÉCIPROQUES est débité\\n- par le crédit du compte de contrepartie 9133 ou 9138.\\nA l\'exécution de la commande, le compte 9033 – COMMANDES FERMES DES\\nCLIENTS ou le compte 9038 AUTRES ENGAGEMENTS RÉCIPROQUES est crédité\\n- par le débit du compte de contrepartie 9133 et 9138.","commentaires":"","exclusions":"","controle":"Le compte 9033 – COMMANDES FERMES DES CLIENTS et le compte\\n- 9038 AUTRES ENGAGEMENTS RÉCIPROQUES peuvent être contrôlés à partir des bons de\\ncommande, des bons de livraison et des factures.","motsCles":["engagements","reciproques"]},{"numero":"9034","intitule":"Commandes fermes des clients","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"","subdivisions":[],"fonctionnement":"","commentaires":"","exclusions":"","controle":"","motsCles":["commandes","fermes","clients"]},{"numero":"9041","intitule":"Abandons de créances conditionnels","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"La convention d\'abandon de créances assortie d\'une clause de retour à meilleure\\nfortune est caractérisée par l\'extinction de la créance de l\'entité sous condition\\nrésolutoire : l\'entité débitrice retrouve des moyens (gains) financiers suffisants qui\\nrétablissent sa dette originelle.","subdivisions":[],"fonctionnement":"A la conclusion des conventions, le compte 9041 – ABANDONS DE CONDITIONNELS\\nest débité CRÉANCES\\n- par le crédit du compte de contrepartie 9141.\\nA la réalisation de l\'éventualité (retour à bonne fortune), le compte 9041 –\\nABANDONS DE CRÉANCES CONDITIONNELS est crédité\\n- par le débit du compte de contrepartie 9141.","commentaires":"Chez l\'entité qui consent l\'abandon, la créance abandonnée sous condition disparaît\\nde son bilan et est suivie en tant qu\'engagement hors bilan reçu.","exclusions":"","controle":"Le compte 9041 – ABANDONS DE CRÉANCES CONDITIONNELS peut être contrôlé à\\npartir des \\" grosses \\" du jugement et des conventions.","motsCles":["abandons","creances","conditionnels"]},{"numero":"9043","intitule":"Ventes avec clause de réserve de propriété","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"","subdivisions":[],"fonctionnement":"","commentaires":"","exclusions":"","controle":"","motsCles":["ventes","avec","clause","reserve","propriete"]},{"numero":"9048","intitule":"Divers engagements obtenus","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Dans le cadre de la vente avec clause de réserve de propriété, le vendeur demeure\\npropriétaire des actifs vendus jusqu\'à complet paiement du prix.\\nLes divers engagements obtenus comprennent notamment les titres à recevoir dans\\n- le cadre de souscription à l\'émission ainsi que les ventes à réméré par lesquelles le\\nvendeur se réserve le droit de racheter l\'objet de la vente dans un certain délai, en\\nremboursant à l\'acquéreur le prix principal et les frais d\'acquisition.","subdivisions":[],"fonctionnement":"A la cession des actifs ou à la souscription des titres, les comptes 9043 – VENTES\\nAVEC CLAUSE DE RÉSERVE DE PROPRIÉTÉ et 9048 – DIVERS ENGAGEMENTS\\nOBTENUS sont débités\\n- par le crédit des comptes de contrepartie respectifs 9143ou 48\\nAu dénouement de la transaction, les comptes 9043 – VENTES AVEC CLAUSE DE\\nRÉSERVE DE PROPRIÉTÉ et 9048 – DIVERS ENGAGEMENTS OBTENUS sont crédités\\n- par le débit des comptes de contrepartie respectifs 9143 ou 9148","commentaires":"","exclusions":"","controle":"Les comptes 9043 – VENTES AVEC CLAUSE DE RÉSERVE DE PROPRIÉTÉ et 9048 –\\nDIVERS ENGAGEMENTS OBTENUS peuvent être contrôlés à partir des conventions\\nde cession et des bordereaux ou attestations de souscription de titres.","motsCles":["divers","engagements","obtenus"]},{"numero":"9051","intitule":"Crédits accordés non décaissés","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"","subdivisions":[],"fonctionnement":"","commentaires":"","exclusions":"","controle":"","motsCles":["credits","accordes","non","decaisses"]},{"numero":"9058","intitule":"Autres engagements de financement accordés","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Le solde créditeur du compte 9051 représente la partie non décaissée des crédits\\nqu\'une entité s\'est engagée, d\'une façon irrévocable, à accorder à un tiers autre\\nqu\'un établissement de crédit.\\nLes autres engagements de financement accordés comprennent notamment les\\nengagements pris par la société-mère d\'un groupe de combler les éventuels déficits\\nde trésorerie de ses différentes filiales auprès d\'une banque.","subdivisions":[],"fonctionnement":"A la signature de l\'engagement, les comptes 90-51 – CRÉDITS ACCORDÉS NON\\nDÉCAISSÉS et 9058 – AUTRES ENGAGEMENTS DE FINANCEMENT ACCORDÉS sont\\ncrédités\\n- par le débit des comptes de contrepartie 9151et 9158\\nLors du décaissement partiel ou total du crédit, ou lors de la couverture des déficits\\nde trésorerie, les comptes 9051 – CRÉDITS ACCORDÉS NON DÉCAISSÉS et 9058 –\\nAUTRES ENGAGEMENTS DE FINANCEMENT ACCORDÉS sont débités\\n- par le crédit des comptes de contrepartie respectifs\\n- 9151 et 9158","commentaires":"","exclusions":"","controle":"Les comptes 9051 – CRÉDITS ACCORDÉS NON DÉCAISSÉS et 9058 – AUTRES\\nENGAGEMENTS DE FINANCEMENT ACCORDÉS peuvent être contrôlés à partir des\\nlettres de notification de l\'entité , des conventions de crédit et des décisions des\\norganes compétents.","motsCles":["engagements","financement","accordes"]},{"numero":"9061","intitule":"Avals accordés","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Par l\'aval, l\'entité prend l\'engagement de payer au bénéficiaire, et à l\'échéance, tout\\nou partie du nominal d\'une lettre de change, d\'un billet à ordre ou d\'un chèque, à la\\nplace du tiré ou du souscripteur éventuellement défaillant.","subdivisions":[],"fonctionnement":"A la conclusion de la transaction,\\nLe compte 9061 – AVALS ACCORDES est crédité\\n- par le débit du compte de contrepartie 9161\\nA l\'échéance ou au dénouement de la transaction,\\nLe compte 9061 – AVALS ACCORDES est débité\\n- par le crédit du compte de contrepartie 9161","commentaires":"","exclusions":"","controle":"Le compte 9061 – AVALS ACCORDÉS peut être contrôlé à partir des effets avalisés\\net des décisions des organes compétents.","motsCles":["avals","accordes"]},{"numero":"9062","intitule":"Cautions, garanties accordées","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"L\'entité, en tant que caution, promet à un créancier de le payer si le débiteur de ce\\ndernier n\'exécute pas son obligation.","subdivisions":[],"fonctionnement":"A la conclusion de la caution, le compte 9062 – CAUTIONS, GARANTIES\\nACCORDÉES est crédité\\n- par le débit du compte de contrepartie 9162\\nA l\'échéance ou au dénouement de la transaction, le compte 9062 – CAUTIONS,\\nGARANTIES ACCORDÉES est débité\\n- par le crédit du compte de contrepartie 9162","commentaires":"Ce compte enregistre également les lettres d\'intention ou lettres de confort dans\\nlesquelles l\'entité s\'engage sans équivoque, envers un créancier, à satisfaire\\n- l\'obligation du débiteur de ce créancier si ce débiteur n\'y satisfait pas lui-même.","exclusions":"Le compte 9062 – CAUTIONS, GARANTIES ACCORDÉES ne doit pas servir à\\nenregistrer :\\n- les gages\\n- les nantissements\\n- les antichrèses\\nIl convient dans les cas d\'espèce d\'utiliser le compte ci-après :\\n- 9068 – Autres garanties accordées","controle":"Le compte 9062 – CAUTIONS, GARANTIES ACCORDÉES peut être contrôlé à partir\\ndes conventions de prêts, des actes constitutifs de la caution, des lettres d\'intention\\nou lettres de confort, des décisions des organes compétents.","motsCles":["cautions","garanties","accordees"]},{"numero":"9063","intitule":"Hypothèques accordées","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Lorsque l\'entité donne à son créancier un immeuble en hypothèque, cette\\nhypothèque confère à ce créancier le droit de faire saisir et vendre l\'immeuble en\\nquelques mains qu\'il se trouve et de se faire payer par préférence sur le prix de la\\nvente.","subdivisions":[],"fonctionnement":"A l\'inscription de l\'hypothèque, le compte 9063 – HYPOTHEQUES ACCORDÉES est\\ncrédité de la valeur de l\'immeuble telle que fixée\\n- par le débit du compte de contrepartie 9163\\nAu dénouement de la créance ou à la réalisation de l\'hypothèque, le compte 9063 –\\nHYPOTHEQUES ACCORDÉES est débité\\n- par le crédit du compte de contrepartie 9163","commentaires":"La validité de l\'hypothèque est assurée par son inscription sur un registre légal\\n(Cadastre, Domaines, registre foncier, etc.).","exclusions":"Le compte 9063 – HYPOTHEQUES ACCORDÉES ne doit pas servir à enregistrer :\\n- les promesses d\'hypothèques\\n- les gages\\n- les nantissements\\n- les antichrèses\\nIl convient dans les cas d\'espèce d\'utiliser le compte ci-après:\\n- 9068 – Autres garanties accordées","controle":"Le compte 9063 – HYPOTHEQUES ACCORDÉES peut être contrôlé à partir des\\nconventions de prêts, des récépissés d\'inscription de l\'hypothèque, des rapports\\nd\'expertise immobilière.","motsCles":["hypotheques","accordees"]},{"numero":"9064","intitule":"Effets endossés par l\'entité","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Dans le cadre de la garantie d\'endossement, l\'endosseur (l\'entité) est, sauf clause\\ncontraire, garant de l\'acceptation et du paiement de l\'effet.","subdivisions":[],"fonctionnement":"Lors de l\'endossement, le compte 9064 – EFFETS ENDOSSÉS PAR L\'ENTITE est\\ncrédité\\n- par le débit du compte de contrepartie 9164\\nA l\'échéance ou au dénouement de l\'opération, le compte 9064 – EFFETS\\nENDOSSES PAR L\'ENTITE est débité\\n- par le crédit du compte de contrepartie 9164","commentaires":"L\'endossement est le mode de transmission des titres à ordre. Il est réalisé par une\\nsignature apposée au dos du titre par le porteur appelé endosseur.\\nL\'endossataire, bénéficiaire de l\'endossement, peut être désigné ; s\'il ne l\'est pas,\\n- l\'endossement peut être au porteur ou en blanc.\\nLes effets de l\'endossement varient selon la nature de l\'endossement : endossement\\nde procuration, endossement pignoratif ou endossement translatif. L\'endossement\\nde procuration emporte pour l\'endossataire l\'obligation de présenter le titre au\\npaiement pour le compte de l\'endosseur qui lui en a donné mandat.\\nL\'endossement pignoratif confère à l\'endossataire un droit de gage sur le titre remis\\npar l\'endosseur.\\nL\'endossement translatif transfère à l\'endossataire tous les droits résultant du titre\\nendossé.","exclusions":"Le compte 9064 – EFFETS ENDOSSÉS PAR L\'ENTITE ne doit pas servir à enregistrer\\n:\\n- les effets transmis par endossement de procuration\\nIl convient dans le cas d\'espèce d\'utiliser le compte ci-après :\\n- 9048 – Divers engagements obtenus","controle":"Le compte 9064 – EFFETS ENDOSSÉS PAR L\'ENTITE peut être contrôlé à partir des\\neffets.","motsCles":["effets","endosses","entite"]},{"numero":"9068","intitule":"Autres garanties accordées","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Les autres garanties accordées comprennent notamment le gage, le nantissement et\\n- l\'antichrèse pour lesquels l\'engagement porte spécialement sur un ou plusieurs\\nbiens affectés par l\'entité à l\'acquittement de ses obligations.","subdivisions":[],"fonctionnement":"A la constitution de la garantie, le compte 9068 – AUTRES GARANTIES ACCORDÉES\\nest crédité de la valeur des biens donnés en garantie\\n- par le débit du compte de contrepartie 9168\\nAu dénouement de la créance ou à la réalisation de la garantie, le compte 9068 –\\nAUTRES GARANTIES ACCORDÉES est débité\\n- par le crédit du compte de contrepartie 9168","commentaires":"Figurent également dans ce compte :\\n- les promesses d\'hypothèque,\\n- les effets reçus des tiers par endossement de procuration (encaissement).\\nL\'antichrèse représente le nantissement sur un immeuble permettant uniquement\\nd\'en percevoir les fruits.","exclusions":"Le compte 9068 – AUTRES GARANTIES ACCORDEES ne doit pas servir à enregistrer\\n:\\n- les avals\\n- les cautions\\n- les hypothèques\\nIl convient dans les cas d\'espèce d\'utiliser les comptes ci-après :\\n- 9061 – Avals accordés\\n- 9062 – Cautions, garanties accordées\\n- 9063 – Hypothèques accordées","controle":"Le compte 9068 – AUTRES GARANTIES ACCORDÉES peut être contrôlé à partir des\\nconventions de prêt et de l\'acte constitutif de la garantie.","motsCles":["garanties","accordees"]},{"numero":"9071","intitule":"Ventes de marchandises à terme","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Pour deux partenaires, les engagements réciproques se décomposent en un\\nengagement donné par l\'entité à son cocontractant en contrepartie d\'un\\nengagement reçu de ce dernier. A ce titre, dans le cadre des ventes de marchandises\\nà terme, l\'entité s\'engage à livrer des marchandises et son client s\'engage à en\\nprendre livraison et à en payer le prix à la date de livraison.","subdivisions":[],"fonctionnement":"A la signature de la transaction, le compte 9071 – VENTES DE MARCHANDISES A\\nTERME est crédité\\n- par le débit du compte de contrepartie 9171\\nA l\'exécution du marché, le compte 9071 – VENTES DE MARCHANDISES A TERME\\nest débité\\n- par le crédit du compte de contrepartie 9171","commentaires":"","exclusions":"","controle":"Le compte 9071 – VENTES DE MARCHANDISES A TERME peut être contrôlé à partir\\ndes bons de commandes, des bons de livraison et des factures.","motsCles":["ventes","marchandises","terme"]},{"numero":"9072","intitule":"Ventes à terme de devises","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"L\'entité s\'engage à livrer des devises et réciproquement le cocontractant s\'engage à\\nlivrer de la monnaie nationale.","subdivisions":[],"fonctionnement":"A la conclusion de la transaction,\\nLe compte 9072 – VENTES A TERME DE DEVISES est crédité\\n- par le débit du compte de contrepartie 9172\\nAu dénouement de la transaction,\\nLe compte 9072 – VENTES A TERME DE DEVISES est débité\\n- par le crédit du compte de contrepartie 9172","commentaires":"","exclusions":"","controle":"Le compte 9072 – VENTES A TERME DE DEVISES peut être contrôlé à partir des\\nordres d\'achat et de l\'avis d\'opéré.","motsCles":["ventes","terme","devises"]},{"numero":"9073","intitule":"Commandes fermes aux fournisseurs","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Dans le cadre d\'une commande ferme, l\'entité s\'engage de façon irrévocable à payer\\n- le prix des travaux exécutés pour son compte conformément aux spécifications\\ncontenues dans sa commande.","subdivisions":[],"fonctionnement":"A l\'émission du bon de commande,\\nLe compte 9073 – COMMANDES FERMES AUX FOURNISSEURS est crédité\\n- par le débit du compte de contrepartie 9173\\nA la réception des travaux,\\nLe compte 9073 – COMMANDES FERMES FOURNISSEURS est débité AUX\\n- par le crédit du compte de contrepartie 9173","commentaires":"","exclusions":"","controle":"Le compte 9073 – COMMANDES FERMES AUX FOURNISSEURS peut être contrôlé à\\npartir des bons de commande et des factures","motsCles":["commandes","fermes","fournisseurs"]},{"numero":"9078","intitule":"Autres engagements réciproques","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Le compte 9078 enregistre les obligations relatives aux engagements réciproques\\nqui ne trouvent pas leur place dans les sous-comptes 9071, 9072 et 9073.","subdivisions":[],"fonctionnement":"A la signature de la convention,\\nLe compte 9078 – AUTRES ENGAGEMENTS RECIPROQUES est crédité\\n- par le débit du compte de contrepartie 9178\\nA l\'échéance ou au dénouement de la transaction\\nLe compte 9078 – AUTRES ENGAGEMENTS RECIPROQUES est débité\\n- par le crédit du compte de contrepartie 9178","commentaires":"","exclusions":"","controle":"Le compte 9078 – AUTRES ENGAGEMENTS RECIPROQUES peut être contrôlé à\\npartir des conventions.","motsCles":["engagements","reciproques"]},{"numero":"9081","intitule":"Annulations conditionnelles de dettes","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"La convention d\'annulation de dettes assortie d\'une clause de retour à meilleure\\nfortune est caractérisée par l\'extinction de la dette de l\'entité sous condition\\nrésolutoire : l\'entité retrouve des moyens (gains) financiers suffisants qui\\nrétablissent sa dette originelle.","subdivisions":[],"fonctionnement":"A la conclusion de la convention,\\nLe compte 9081 – ANNULATIONS CONDITIONNELLES DE DETTES est crédité\\n- par le débit du compte de contrepartie 9181\\nA la réalisation de l\'éventualité (retour à bonne fortune), le compte 9081 –\\nANNULATIONS CONDITIONNELLES DE DETTES est débité\\n- par le crédit du compte de contrepartie 9181","commentaires":"Chez l\'entité qui bénéficie de l\'annulation, la dette annulée sous condition disparaît\\nde son bilan et est suivie en tant qu\'engagement hors bilan donné.","exclusions":"","controle":"Le compte 9081 – ANNULATIONS CONDITIONNELLES DE DETTES peut être\\ncontrôlé à partir des \\" grosses \\" du jugement, des conventions. et des décisions des\\norganes compétents.","motsCles":["annulations","conditionnelles","dettes"]},{"numero":"9083","intitule":"Achats avec clause de réserve de propriété","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"","subdivisions":[],"fonctionnement":"","commentaires":"","exclusions":"","controle":"","motsCles":["achats","avec","clause","reserve","propriete"]},{"numero":"9088","intitule":"Divers engagements accordés","classe":9,"classeLabel":"Comptes des engagements hors bilan et comptabilité analytique","groupe":"C","contenu":"Dans le cadre d\'achat avec clause de réserve de propriété, l\'entité ne sera\\npropriétaire des biens achetés qu\'au paiement complet du prix.\\nLes divers engagements accordés comprennent notamment les titres à livrer dans\\n- le cadre d\'une émission, ainsi que les achats à réméré par lesquels l\'entité\\n(acheteur) garantit au vendeur la faculté de racheter l\'objet de la vente dans un\\ncertain délai et à un prix convenus d\'avance. Figurent également dans ce compte les\\nsubventions à reverser.","subdivisions":[],"fonctionnement":"A la conclusion de la transaction (achat, souscription), les comptes 9083 – ACHATS\\nAVEC CLAUSE DE RÉSERVE DE PROPRIÉTÉ et 9088 – DIVERS ENGAGEMENTS\\nACCORDÉS sont crédités\\n- par le débit des comptes de contrepartie respectifs\\n- 9183 et 9188\\nAu dénouement de la transaction, les comptes 9083 ACHATS AVEC CLAUSE DE\\nRÉSERVE DE PROPRIÉTÉ et 9088 DIVERS ENGAGEMENTS ACCORDÉS sont débités\\n- par le crédit des comptes de contrepartie respectifs 9181 et 9188","commentaires":"","exclusions":"","controle":"Les comptes 9083 – ACHATS AVEC CLAUSE DE RÉSERVE DE PROPRIÉTÉ et 9088 –\\nDIVERS ENGAGEMENTS ACCORDÉS peuvent être contrôlés à partir des conventions\\nde cession, des bordereaux ou des attestations de souscription de titres, des\\nconventions de subvention, des décisions des organes compétents.\\nSous-section 2 : Comptes de la Comptabilité analytique de gestion (92 – 99)\\nL\'usage des comptes 92 à 99 est laissé à l\'initiative des entités qui utilisent les\\ndécoupages convenant le mieux :\\nà leur structure ;\\nà leur politique des coûts ;\\nà leur organisation.\\nLes comptes à deux chiffres 92 à 99 ci-après rappelés sont de caractère\\nsuffisamment général pour répondre aux besoins de toute entité qui les subdivise à\\nsa convenance.\\n92 COMPTES REFLECHIS\\n93 COMPTES DE RECLASSEMENTS\\n94 COMPTES DE COÛTS\\n95 COMPTES DE STOCKS\\n96 COMPTES D\'ECARTS SUR COÛTS PREETABLIS\\n97 COMPTES DE DIFFERENCES DE TRAITEMENT COMPTABLE\\n98 COMPTES DE RESULTATS\\n99 COMPTES DE LIAISONS INTERNES","motsCles":["divers","engagements","accordes"]}]}')},37842,e=>{"use strict";let t=e.i(88507).default,s=t.comptes;function n(e){return e.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"")}({...t.meta,nbComptes:t.comptes.length}),s.map(e=>e.numero),e.s(["getCompte",0,function(e){return s.find(t=>t.numero===e)},"normalize",0,n,"rechercher",0,function(e){let t=n(e.trim());if(!t)return[];let i=[];for(let e of s){let s=e.numero,r=n(e.intitule),o=-1;s===t?o=100:s.startsWith(t)?o=90:r.startsWith(t)?o=80:r.includes(t)?o=60:e.motsCles.some(e=>e.includes(t))?o=50:e.subdivisions.some(e=>n(e.intitule).includes(t)||e.numero.startsWith(t))?o=45:(n(e.contenu).includes(t)||n(e.fonctionnement).includes(t))&&(o=25),o>=0&&i.push({compte:e,score:o})}return i.sort((e,t)=>t.score!==e.score?t.score-e.score:e.compte.numero<t.compte.numero?-1:1).map(e=>e.compte)}])}]);